+      temperature: 'hot',
+      flavor: 'sweet',
+      url: '/menu/seasonal',
+    },
+    {
+      name: 'Dark Roast Espresso',
+      description: 'Bold, smokey, and perfect for a morning boost.',
+      temperature: 'hot',
+      flavor: 'bold',
+      url: '/menu/espresso',
+    },
+    {
+      name: 'Cold Brew',
+      description: 'Steeped for 18 hours for maximum smoothness.',
+      temperature: 'iced',
+      flavor: 'smooth',
+      url: '/menu/cold-brew',
+    },
+  ];
+
+  const form = document.getElementById('coffee-finder-form');
+  const status = document.getElementById('finder-status');
+  const results = document.getElementById('finder-results');
+
+  function findMatches() {
+    const data = new FormData(form);
+    const temperature = data.get('temperature');
+    const flavor = data.get('flavor');
+
+    // Validate membership as well as native constraints for agent-supplied values.
+    if (!form.checkValidity() || !['any', 'hot', 'iced'].includes(temperature) ||
+        !['any', 'sweet', 'bold', 'smooth'].includes(flavor)) {
+      results.replaceChildren();
+      status.textContent = 'Please choose a temperature and flavor from the available options.';
+      form.reportValidity();
+      return { success: false, message: status.textContent, matches: [] };
+    }
+
+    const matches = coffees.filter((coffee) =>
+      (temperature === 'any' || coffee.temperature === temperature) &&
+      (flavor === 'any' || coffee.flavor === flavor));
+
+    results.replaceChildren(...matches.map((coffee) => {
+      const item = document.createElement('li');
+      const link = document.createElement('a');
+      link.href = coffee.url;
+      link.textContent = coffee.name;
+      const description = document.createElement('p');
+      description.textContent = `${coffee.description} Served ${coffee.temperature}.`;
+      item.append(link, description);
+      return item;
+    }));
+
+    status.textContent = matches.length
+      ? `${matches.length} coffee ${matches.length === 1 ? 'matches' : 'match'} your mood. Explore ${matches.length === 1 ? 'your pick' : 'your picks'} below.`
+      : 'No exact match this time. Try “Either” temperature or “Surprise me” for more options.';
+
+    return { success: true, preferences: { temperature, flavor }, message: status.textContent, matches };
+  }
+
+  form.addEventListener('submit', (event) => {
+    event.preventDefault();
+    const result = findMatches();
+    // Unsupported browsers use the same human-facing form and result rendering.
+    if (event.agentInvoked && typeof event.respondWith === 'function') {
+      event.respondWith(Promise.resolve(result));
+    }
+  });
+
+  form.addEventListener('input', () => {
+    results.replaceChildren();
+    status.textContent = 'Preferences updated. Select Find My Coffee to see your matches.';
+  });
+})();
