+(() => {
+  const coffees = [
+    {
+      id: 'maple-oat-latte', name: 'Maple Oat Latte', temperature: 'hot', flavor: 'sweet',
+      description: 'Creamy oat milk with a hint of Vermont maple syrup.',
+      menuUrl: '/menu/seasonal'
+    },
+    {
+      id: 'dark-roast-espresso', name: 'Dark Roast Espresso', temperature: 'hot', flavor: 'bold',
+      description: 'Bold, smoky espresso for a rich, intense cup.',
+      menuUrl: '/menu/espresso'
+    },
+    {
+      id: 'cold-brew', name: 'Cold Brew', temperature: 'iced', flavor: 'smooth',
+      description: 'Steeped for 18 hours for a smooth, refreshing finish.',
+      menuUrl: '/menu/cold-brew'
+    }
+  ];
+
+  const form = document.getElementById('coffee-finder-form');
+  const output = document.getElementById('coffee-result');
+  const temperatures = new Set(['any', 'hot', 'iced']);
+  const flavors = new Set(['any', 'sweet', 'bold', 'smooth']);
+
+  function showResult(result) {
+    output.className = 'finder-result';
+    if (result.status === 'error') {
+      output.textContent = result.message;
+      return;
+    }
+    const heading = document.createElement('h3');
+    heading.textContent = result.coffee.name;
+    const label = document.createElement('p');
+    label.className = 'eyebrow';
+    label.textContent = result.exactMatch ? 'Your coffee match' : 'Your closest match';
+    const description = document.createElement('p');
+    description.textContent = result.coffee.description;
+    const reason = document.createElement('p');
+    reason.textContent = result.message;
+    const link = document.createElement('a');
+    link.href = result.coffee.menuUrl;
+    link.textContent = 'View menu details →';
+    output.replaceChildren(label, heading, description, reason, link);
+  }
+
+  form.addEventListener('submit', (event) => {
+    event.preventDefault();
+    const data = new FormData(form);
+    const temperature = data.get('temperature');
+    const flavor = data.get('flavor');
+    let result;
+
+    if (!form.checkValidity() || !temperatures.has(temperature) || !flavors.has(flavor)) {
+      result = { status: 'error', message: 'Choose a listed temperature and flavor, then try again.' };
+      form.reportValidity();
+    } else {
+      const candidates = coffees.filter(coffee => temperature === 'any' || coffee.temperature === temperature);
+      const coffee = candidates.find(coffee => flavor === 'any' || coffee.flavor === flavor) || candidates[0];
+      const exactMatch = flavor === 'any' || coffee.flavor === flavor;
+      result = {
+        status: 'success', preferences: { temperature, flavor }, exactMatch,
+        coffee: { ...coffee },
+        message: exactMatch
+          ? `Enjoy it ${coffee.temperature}, with a ${coffee.flavor} flavor profile.`
+          : `Our featured ${temperature} coffees don't include a ${flavor} match. Try this ${coffee.flavor} favorite instead.`
+      };
+    }
+
+    showResult(result);
+    // Declarative WebMCP uses this same handler as a normal form submission.
+    // Feature detection preserves ordinary browser support.
+    if (event.agentInvoked && typeof event.respondWith === 'function') {
+      event.respondWith(Promise.resolve(result));
+    }
+  });
+
+  form.addEventListener('change', () => {
+    output.className = '';
+    output.textContent = 'Preferences updated. Select Find My Match to see your recommendation.';
+  });
+})();
