diff --git a/src/utils/agentForms.ts b/src/utils/agentForms.ts
new file mode 100644
index 0000000..6bae961
--- /dev/null
+++ b/src/utils/agentForms.ts
@@ -0,0 +1,26 @@
+import type { FormEvent } from 'react';
+
+interface AgentSubmitEvent extends SubmitEvent {
+  agentInvoked?: boolean;
+  respondWith?: (result: Promise<unknown>) => void;
+}
+
+interface FormResult {
+  success: boolean;
+  message: string;
+}
+
+/** Use the same submission and result for people and declarative WebMCP tools. */
+export function submitAgentForm(
+  event: FormEvent<HTMLFormElement>,
+  submit: (data: FormData) => Promise<FormResult>,
+): void {
+  event.preventDefault();
+  const result = submit(new FormData(event.currentTarget));
+  const nativeEvent = event.nativeEvent as AgentSubmitEvent;
+
+  // Call synchronously during dispatch, before the submission promise resolves.
+  if (nativeEvent.agentInvoked && typeof nativeEvent.respondWith === 'function') {
+    nativeEvent.respondWith(result);
+  }
+}
diff --git a/tests/agentForms.test.mjs b/tests/agentForms.test.mjs
new file mode 100644
index 0000000..a8bd7b6
--- /dev/null
+++ b/tests/agentForms.test.mjs
@@ -0,0 +1,74 @@
+import assert from 'node:assert/strict';
+import { test } from 'node:test';
+import { submitAgentForm } from '../src/utils/agentForms.ts';
+
+// Supply the browser-only FormData(form) constructor without opening a browser.
+class FormDataFromForm extends FormData {
+  constructor(form) {
+    super();
+    for (const [name, value] of Object.entries(form.fields)) {
+      this.set(name, value);
+    }
+  }
+}
+
+test('agent submissions read form values and respond synchronously with the pending result', async (t) => {
+  t.mock.method(globalThis, 'FormData', FormDataFromForm);
+  let finish;
+  let response;
+  let prevented = false;
+  const event = {
+    currentTarget: { fields: { username: 'agent-user', password: 'secret123' } },
+    preventDefault() { prevented = true; },
+    nativeEvent: {
+      agentInvoked: true,
+      respondWith(promise) {
+        assert.equal(prevented, true);
+        response = promise;
+      },
+    },
+  };
+
+  submitAgentForm(event, (data) => {
+    assert.equal(data.get('username'), 'agent-user');
+    assert.equal(data.get('password'), 'secret123');
+    return new Promise((resolve) => { finish = resolve; });
+  });
+
+  assert.ok(response instanceof Promise);
+  // React's currentTarget is only valid during the event handler.
+  event.currentTarget = null;
+  const result = { success: true, message: 'Login successful!' };
+  finish(result);
+  assert.deepEqual(await response, result);
+});
+
+test('agent submissions return failures as structured results', async (t) => {
+  t.mock.method(globalThis, 'FormData', FormDataFromForm);
+  let response;
+  const result = { success: false, message: 'Registration failed: APP_ERR_1001' };
+  submitAgentForm({
+    currentTarget: { fields: {} },
+    preventDefault() {},
+    nativeEvent: {
+      agentInvoked: true,
+      respondWith(promise) { response = promise; },
+    },
+  }, async () => result);
+  assert.deepEqual(await response, result);
+});
+
+test('normal submissions work without WebMCP event extensions', async (t) => {
+  t.mock.method(globalThis, 'FormData', FormDataFromForm);
+  let submissions = 0;
+  submitAgentForm({
+    currentTarget: { fields: { username: 'human-user' } },
+    preventDefault() {},
+    nativeEvent: {},
+  }, async (data) => {
+    submissions++;
+    assert.equal(data.get('username'), 'human-user');
+    return { success: true, message: 'Login successful!' };
+  });
+  assert.equal(submissions, 1);
+});

