+  <script>
+    const menubar = document.querySelector('.menubar');
+    const triggers = [...menubar.querySelectorAll('.menu-trigger')];
+
+    function closeMenus() {
+      triggers.forEach(trigger => {
+        trigger.setAttribute('aria-expanded', 'false');
+        document.getElementById(trigger.getAttribute('aria-controls')).hidden = true;
+      });
+    }
+
+    function setActiveTrigger(trigger) {
+      triggers.forEach(item => { item.tabIndex = item === trigger ? 0 : -1; });
+    }
+
+    function openMenu(trigger, focusLast = false) {
+      closeMenus();
+      setActiveTrigger(trigger);
+      trigger.setAttribute('aria-expanded', 'true');
+      const menu = document.getElementById(trigger.getAttribute('aria-controls'));
+      menu.hidden = false;
+      const items = [...menu.querySelectorAll('[role="menuitem"]')];
+      items[focusLast ? items.length - 1 : 0].focus();
+    }
+
+    triggers.forEach(trigger => {
+      trigger.addEventListener('focus', () => setActiveTrigger(trigger));
+      trigger.addEventListener('click', () => {
+        if (trigger.getAttribute('aria-expanded') === 'true') {
+          closeMenus();
+        } else {
+          openMenu(trigger);
+        }
+      });
+    });
+
+    menubar.addEventListener('keydown', event => {
+      const root = event.target.closest('.menu-root');
+      if (!root) return;
+      const trigger = root.querySelector('.menu-trigger');
+      const onTrigger = event.target === trigger;
+      const items = [...root.querySelectorAll('.dropdown [role="menuitem"]')];
+      const index = items.indexOf(event.target);
+
+      if (event.key === 'Tab') {
+        // Restore focus before the browser moves to the next tab stop.
+        if (!onTrigger) trigger.focus();
+        closeMenus();
+        return;
+      }
+
+      if (event.key === 'Escape') {
+        closeMenus();
+        trigger.focus();
+      } else if (event.key === 'ArrowLeft' || event.key === 'ArrowRight') {
+        const offset = event.key === 'ArrowRight' ? 1 : -1;
+        const next = triggers[(triggers.indexOf(trigger) + offset + triggers.length) % triggers.length];
+        const wasOpen = trigger.getAttribute('aria-expanded') === 'true';
+        closeMenus();
+        setActiveTrigger(next);
+        if (wasOpen) openMenu(next);
+        else next.focus();
