+        if (onTrigger) openMenu(trigger, event.key === 'ArrowUp');
+        else items[(index + (event.key === 'ArrowDown' ? 1 : -1) + items.length) % items.length].focus();
+      } else if (event.key === 'Home' || event.key === 'End') {
+        const targets = onTrigger ? triggers : items;
+        const target = targets[event.key === 'Home' ? 0 : targets.length - 1];
+        if (onTrigger) closeMenus();
+        target.focus();
+      } else if (!onTrigger && event.key === ' ') {
+        event.target.click();
