+    );
+    pageLabels.set('/menu/seasonal', 'Maple Oat Latte');
+    pageLabels.set('/menu/espresso', 'Dark Roast Espresso');
+    pageLabels.set('/menu/cold-brew', 'Cold Brew');
+
+    const segments = window.location.pathname.split('/').filter(Boolean);
+    // index.html is another address for the home page, not a child page.
+    if (segments.at(-1) === 'index.html') segments.pop();
+    const trail = [{ href: '/', label: 'Home' }];
+    let path = '';
+    for (const segment of segments) {
+      path += '/' + segment;
+      const label = pageLabels.get(path) || segment.replace(/-/g, ' ')
+        .replace(/\b\w/g, (letter) => letter.toUpperCase());
+      trail.push({ href: path, label });
+    }
+
