+  <script>
+    (() => {
+      const timer = document.getElementById('maple-promotion');
+      const status = document.getElementById('promotion-status');
+      const days = document.getElementById('promotion-days');
+      const hours = document.getElementById('promotion-hours');
+      const elapsed = document.getElementById('promotion-elapsed');
+      const hourInMilliseconds = 60 * 60 * 1000;
+
+      function durationParts(milliseconds) {
+        const totalHours = Math.floor(Math.max(0, milliseconds) / hourInMilliseconds);
+        return { days: Math.floor(totalHours / 24), hours: totalHours % 24 };
+      }
+
+      function updatePromotion() {
+        // Component constructors use the visitor's local time zone (months are zero-based).
+        // Assumed promotion start; keep the visible start date above in sync if changed.
+        const start = new Date(2026, 0, 1, 0, 0, 0);
+        const end = new Date(2026, 2, 1, 0, 0, 0);
+        const now = Date.now();
+        const remaining = durationParts(end.getTime() - now);
+        const passed = durationParts(now - start.getTime());
+        const statusText = now >= end.getTime() ? 'Offer ended'
+          : now < start.getTime() ? 'Promotion has not started · time until offer ends'
+          : 'Time left to enjoy';
+        const elapsedText = `Elapsed: ${passed.days} days and ${passed.hours} hours`;
+
+        // Avoid repeated live announcements when the displayed values have not changed.
+        if (status.textContent !== statusText) status.textContent = statusText;
+        if (days.textContent !== String(remaining.days)) days.textContent = remaining.days;
+        if (hours.textContent !== String(remaining.hours)) hours.textContent = remaining.hours;
+        if (elapsed.textContent !== elapsedText) elapsed.textContent = elapsedText;
