+import { ml_kem768 } from '@noble/post-quantum/ml-kem.js';
+import { ml_kem768_x25519 } from '@noble/post-quantum/hybrid.js';
+import { x25519 } from '@noble/curves/ed25519.js';
+
+// The classical adapter is ephemeral X25519 key agreement. HKDF below binds
+// its public keys, suite and encapsulation to the derived encryption key.
+const classical = {
+  keygen: () => x25519.keygen(),
+  encapsulate(publicKey) {
+    const ephemeral = x25519.keygen();
+    try {
+      return { cipherText: ephemeral.publicKey, sharedSecret: x25519.getSharedSecret(ephemeral.secretKey, publicKey) };
+    } finally { ephemeral.secretKey.fill(0); }
+  },
+  decapsulate: (cipherText, secretKey) => x25519.getSharedSecret(secretKey, cipherText),
+};
+export const suites = Object.freeze({
+  hybrid: { kem: ml_kem768_x25519, label: 'X25519 + ML-KEM-768', description: 'Classical + post-quantum protection' },
+  'post-quantum': { kem: ml_kem768, label: 'ML-KEM-768', description: 'Post-quantum key encapsulation' },
+  classical: { kem: classical, label: 'X25519', description: 'Classical elliptic-curve key agreement' },
+});
+const encoder = new TextEncoder();
+const b64 = (bytes) => btoa(String.fromCharCode(...bytes));
+const unb64 = (value) => Uint8Array.from(atob(value), (char) => char.charCodeAt(0));
+const random = (length) => crypto.getRandomValues(new Uint8Array(length));
+function getSuite(id) {
+  if (!Object.hasOwn(suites, id)) throw new Error('Unsupported protection level.');
+  return suites[id];
+}
+export function createRecipient(suite) {
+  // Local preview only: a fresh recipient is held in memory. A deployed service
+  // must provision authenticated recipient PUBLIC keys and hold private keys off-client.
+  return { suite, ...getSuite(suite).kem.keygen() };
+}
+export function destroyRecipient(recipient) { recipient?.secretKey.fill(0); }
+async function fingerprint(publicKey) {
+  return b64(new Uint8Array(await crypto.subtle.digest('SHA-256', publicKey)));
+}
+function aad(header) {
+  // Fixed field order prevents JSON property order from affecting verification.
+  return encoder.encode(JSON.stringify({
+    application: header.application, version: header.version, suite: header.suite,
+    cipher: header.cipher, recipient: header.recipient, encapsulation: header.encapsulation,
+    salt: header.salt, iv: header.iv, createdAt: header.createdAt,
+  }));
+}
+async function deriveKey(sharedSecret, header, usage) {
+  const material = await crypto.subtle.importKey('raw', sharedSecret, 'HKDF', false, ['deriveKey']);
+  const transcriptHash = new Uint8Array(await crypto.subtle.digest('SHA-256', aad(header)));
+  const domain = encoder.encode('daily-grind/delivery-notes/v1/');
+  const info = new Uint8Array(domain.length + transcriptHash.length);
+  info.set(domain);
+  info.set(transcriptHash, domain.length);
+  return crypto.subtle.deriveKey({ name: 'HKDF', hash: 'SHA-256', salt: unb64(header.salt), info,
+  }, material, { name: 'AES-GCM', length: 256 }, false, [usage]);
+}
+export async function encryptNote(note, recipient) {
+  if (typeof note !== 'string' || !note.trim() || note.length > 500) throw new Error('Please write a note between 1 and 500 characters.');
+  const { cipherText, sharedSecret } = getSuite(recipient.suite).kem.encapsulate(recipient.publicKey);
+  const plaintext = encoder.encode(note);
+  try {
+    const header = {
+      application: 'daily-grind/delivery-notes', version: 1, suite: recipient.suite,
+      cipher: 'AES-256-GCM', recipient: await fingerprint(recipient.publicKey),
+      encapsulation: b64(cipherText), salt: b64(random(32)), iv: b64(random(12)),
+      createdAt: new Date().toISOString(),
+    };
+    const key = await deriveKey(sharedSecret, header, 'encrypt');
+    const encrypted = await crypto.subtle.encrypt({ name: 'AES-GCM', iv: unb64(header.iv), additionalData: aad(header), tagLength: 128 }, key, plaintext);
+    return { ...header, ciphertext: b64(new Uint8Array(encrypted)) };
+  } finally { sharedSecret.fill(0); plaintext.fill(0); }
+}
+export async function decryptNote(envelope, recipient) {
+  if (envelope.application !== 'daily-grind/delivery-notes' || envelope.version !== 1 || envelope.cipher !== 'AES-256-GCM' || envelope.suite !== recipient.suite || envelope.recipient !== await fingerprint(recipient.publicKey)) throw new Error('This note does not belong to this recipient.');
+  if (unb64(envelope.iv).length !== 12 || unb64(envelope.salt).length !== 32) throw new Error('Invalid encryption parameters.');
+  const sharedSecret = getSuite(envelope.suite).kem.decapsulate(unb64(envelope.encapsulation), recipient.secretKey);
+  let plaintext;
+  try {
+    const key = await deriveKey(sharedSecret, envelope, 'decrypt');
+    plaintext = new Uint8Array(await crypto.subtle.decrypt({ name: 'AES-GCM', iv: unb64(envelope.iv), additionalData: aad(envelope), tagLength: 128 }, key, unb64(envelope.ciphertext)));
+    return new TextDecoder('utf-8', { fatal: true }).decode(plaintext);
+  } finally { sharedSecret.fill(0); plaintext?.fill(0); }
+}
