diff --git a/tests/crypto.test.js b/tests/crypto.test.js
new file mode 100644
index 0000000..eced1b3
--- /dev/null
+++ b/tests/crypto.test.js
@@ -0,0 +1,43 @@
+import { test } from 'node:test';
+import assert from 'node:assert/strict';
+import { createRecipient, destroyRecipient, encryptNote, decryptNote } from '../src/crypto.js';
+
+for (const suite of ['hybrid', 'post-quantum', 'classical']) {
+  test(`${suite}: authenticated round-trip, fresh randomness, tamper rejection`, async () => {
+    const recipient = createRecipient(suite);
+    const note = 'Side door code: 7392. Please call ☕ — café delivery.';
+    try {
+      const first = await encryptNote(note, recipient);
+      const second = await encryptNote(note, recipient);
+      assert.equal(await decryptNote(first, recipient), note);
+      assert.equal(await decryptNote(JSON.parse(JSON.stringify(second)), recipient), note);
+      assert.notEqual(first.iv, second.iv);
+      assert.notEqual(first.salt, second.salt);
+      assert.notEqual(first.encapsulation, second.encapsulation);
+      assert.notEqual(first.ciphertext, second.ciphertext);
+      assert(!JSON.stringify(first).includes('7392'));
+      for (const field of ['ciphertext', 'encapsulation', 'salt', 'iv']) {
+        const bytes = Buffer.from(first[field], 'base64');
+        bytes[0] ^= 1;
+        await assert.rejects(() => decryptNote({ ...first, [field]: bytes.toString('base64') }, recipient));
+      }
+      for (const [field, value] of Object.entries({ createdAt: 'altered', suite: 'unknown', recipient: 'altered', version: 2, cipher: 'none', application: 'another-app' })) {
+        await assert.rejects(() => decryptNote({ ...first, [field]: value }, recipient));
+      }
+      const otherRecipient = createRecipient(suite);
+      try { await assert.rejects(() => decryptNote(first, otherRecipient)); }
+      finally { destroyRecipient(otherRecipient); }
+    } finally {
+      destroyRecipient(recipient);
+      assert(recipient.secretKey.every((byte) => byte === 0));
+    }
+  });
+}
+test('empty, whitespace and oversized notes are rejected', async () => {
+  const recipient = createRecipient('hybrid');
+  try {
+    for (const value of ['', '   ', 'x'.repeat(501), null]) await assert.rejects(() => encryptNote(value, recipient));
+    assert.equal((await decryptNote(await encryptNote('x'.repeat(500), recipient), recipient)).length, 500);
+    assert.throws(() => createRecipient('__proto__'));
+  } finally { destroyRecipient(recipient); }
+});

