new file mode 100644
index 0000000..8bcbcdf
--- /dev/null
+++ b/src/scripts/page-transitions.ts
@@ -0,0 +1,80 @@
+// Extend the router's stylesheet preparation before it captures either page.
+// A bundled script runs once, so these listeners survive every navigation.
+const unreadyDocuments = new WeakSet<Document>();
+const preparationTimeout = 4000;
+
+async function decodeImage(source: HTMLImageElement, destination: URL) {
+  const image = new Image();
+  // Match the real request, including responsive selection and CORS credentials.
+  if (source.crossOrigin !== null) image.crossOrigin = source.crossOrigin;
+  image.referrerPolicy = source.referrerPolicy;
+  image.sizes = source.sizes;
+  image.srcset = source.srcset;
+  image.src = new URL(source.getAttribute("src")!, destination).href;
+  await image.decode();
+}
+
+async function prepareAssets(
+  incoming: Document,
+  destination: URL,
+  signal: AbortSignal,
+  restoringScroll: boolean,
+) {
+  // Back/forward can restore a viewport anywhere in the page, so prepare lazy
+  // images too in that case. Normal navigation only needs the initial imagery.
+  const images = Array.from(incoming.querySelectorAll<HTMLImageElement>(
+    restoringScroll ? "img" : "img[data-transition-image], img:not([loading='lazy'])",
+  )).filter((image) => image.hasAttribute("src"));
+
+  let timeout: ReturnType<typeof setTimeout> | undefined;
+  let onAbort: () => void = () => {};
+  const interrupted = new Promise<boolean>((resolve) => {
+    onAbort = () => resolve(false);
+    signal.addEventListener("abort", onAbort, { once: true });
+    timeout = setTimeout(() => resolve(false), preparationTimeout);
+  });
+
+  const assets = Promise.allSettled([
+    ...images.map((image) => decodeImage(image, destination)),
+    // All news routes share this stylesheet/font. Explicitly load it even when
+    // the outgoing viewport has not yet needed a brand headline.
+    document.fonts.load('500 32px "Grenze"', incoming.body.textContent || ""),
+    document.fonts.ready,
+  ]).then((results) => results.every((result) => result.status === "fulfilled"));
+
+  try {
+    if (signal.aborted) return false;
+    return await Promise.race([assets, interrupted]);
+  } finally {
+    clearTimeout(timeout);
+    signal.removeEventListener("abort", onAbort);
+  }
+}
+
+document.addEventListener("astro:before-preparation", (event) => {
+  const loader = event.loader;
+  event.loader = async () => {
+    // Astro fetches the complete HTML and preloads its stylesheets first.
+    // Keep the outgoing page visible while the extra assets become ready.
+    await loader();
+    if (event.defaultPrevented || event.signal.aborted) return;
+    if (!await prepareAssets(
+      event.newDocument,
+      event.to,
+      event.signal,
+      event.navigationType === "traverse" || Boolean(event.to.hash),
+    )) {
+      unreadyDocuments.add(event.newDocument);
+    }
+  };
+});
+
+document.addEventListener("astro:before-swap", (event) => {
+  // Broken/slow assets must not block navigation or animate an incomplete page.
+  // This also disables Astro's simulated animation in browsers without the API.
+  if (unreadyDocuments.has(event.newDocument) ||
+      window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
+    event.viewTransition.ready.catch(() => {});
+    event.viewTransition.skipTransition();
+  }
+});
