+  <script>
+    // Use WCAG relative luminance where CSS contrast-color() is unavailable.
+    if (!CSS.supports('color', 'contrast-color(red)')) {
+      const root = document.documentElement;
+      const surfaces = [
+        { element: document.querySelector('nav'), foreground: '--on-primary' },
+        { element: document.querySelector('footer'), foreground: '--on-secondary' }
+      ];
+      const canvas = document.createElement('canvas');
+      canvas.width = canvas.height = 1;
+      const context = canvas.getContext('2d', { willReadFrequently: true });
+
+      function updateContrast() {
+        for (const surface of surfaces) {
+          const background = getComputedStyle(surface.element).backgroundColor;
+          if (background === surface.background) continue;
+          surface.background = background;
+
+          // Let the browser resolve CSS color formats into sRGB channels.
+          context.clearRect(0, 0, 1, 1);
+          context.fillStyle = background;
+          context.fillRect(0, 0, 1, 1);
+          const channels = context.getImageData(0, 0, 1, 1).data;
+          const linear = Array.from(channels).slice(0, 3).map(channel => {
+            const value = channel / 255;
+            return value <= 0.04045 ? value / 12.92 : ((value + 0.055) / 1.055) ** 2.4;
+          });
+          const luminance = linear[0] * 0.2126 + linear[1] * 0.7152 + linear[2] * 0.0722;
+          const blackContrast = (luminance + 0.05) / 0.05;
+          const whiteContrast = 1.05 / (luminance + 0.05);
+          root.style.setProperty(surface.foreground, blackContrast >= whiteContrast ? '#000' : '#fff');
+        }
+
+        // Reading computed backgrounds also catches CSSOM edits and media queries.
+        requestAnimationFrame(updateContrast);
+      }
+
+      updateContrast();
+    }
+  </script>
