+const $ = selector => document.querySelector(selector);
+const canvas = $('#render-canvas');
+const context = canvas.getContext('2d');
+const status = $('#render-status');
+const dot = $('#render-dot');
+const download = $('#download');
+const colorInputs = [...document.querySelectorAll('input[type="color"]')];
+const defaults = colorInputs.map(input => input.value);
+let worker;
+let renderId = 0;
+let timer;
+let currentSamples = 32;
+
+function showError(message) {
+  clearInterval(timer);
+  status.textContent = 'Renderer unavailable';
+  status.title = message;
+  dot.style.background = '#d65b36';
+  $('#download-status').textContent = 'Could not load WebAssembly. Reload to retry.';
+}
+
+function startRender() {
+  if (!worker) return;
+  const id = ++renderId;
+  const width = Number($('#resolution').value);
+  const height = width * 2 / 3;
+  currentSamples = Number($('#samples').value);
+  clearInterval(timer);
+  const started = performance.now();
+  timer = setInterval(() => {
+    $('#time-metric').textContent = `${((performance.now() - started) / 1000).toFixed(1)}s`;
+  }, 100);
+  status.textContent = 'Tracing the light…';
+  dot.style.background = '#d65b36';
+  $('#progress-fill').style.width = '0%';
+  $('#samples-metric').textContent = `0 / ${currentSamples} spp`;
+  $('#resolution-metric').textContent = `${width} × ${height}`;
+  $('#download-status').textContent = '';
+  download.disabled = true;
+  // Keep the last image visible while the first complete pass is computed.
+  worker.postMessage({ id, width, height, samples: currentSamples,
+    seed: crypto.getRandomValues(new Uint32Array(1))[0],
+    colors: colorInputs.map(input => ({ index: Number(input.dataset.sphere),
+      rgb: [1, 3, 5].map(offset => parseInt(input.value.slice(offset, offset + 2), 16) / 255) })) });
+}
+
+function setPalette(colors) {
+  colorInputs.forEach((input, i) => {
+    input.value = colors[i];
+    input.parentElement.style.setProperty('--swatch', colors[i]);
+  });
+}
+
+function hslToHex(h, s, l) {
+  const a = s * Math.min(l, 1 - l);
+  const channel = n => {
+    const k = (n + h / 30) % 12;
+    return Math.round(255 * (l - a * Math.max(-1, Math.min(k - 3, 9 - k, 1))))
+      .toString(16).padStart(2, '0');
+  };
+  return `#${channel(0)}${channel(8)}${channel(4)}`;
+}
+
+$('#randomize').addEventListener('click', () => {
+  const hue = Math.random() * 360;
+  setPalette([
+    hslToHex(hue, .35 + Math.random() * .2, .48),
+    hslToHex((hue + 115 + Math.random() * 80) % 360, .28 + Math.random() * .2, .45),
+    hslToHex((hue + 30 + Math.random() * 60) % 360, .35 + Math.random() * .25, .74),
+    hslToHex((hue + 190 + Math.random() * 50) % 360, .3 + Math.random() * .3, .78),
+  ]);
+  startRender();
+});
+
+$('#reset').addEventListener('click', () => { setPalette(defaults); startRender(); });
+for (const input of colorInputs) {
+  input.addEventListener('input', () => input.parentElement.style.setProperty('--swatch', input.value));
+  input.addEventListener('change', startRender);
+}
+$('#samples').addEventListener('change', startRender);
+$('#resolution').addEventListener('change', startRender);
+
+download.addEventListener('click', () => {
+  canvas.toBlob(blob => {
+    if (!blob) {
+      $('#download-status').textContent = 'Could not export this image. Please retry.';
+      return;
+    }
+    const url = URL.createObjectURL(blob);
+    const link = document.createElement('a');
+    link.href = url;
+    link.download = `smallpt-${canvas.width}x${canvas.height}-${Date.now()}.png`;
+    link.click();
+    setTimeout(() => URL.revokeObjectURL(url), 1000);
+    $('#download-status').textContent = 'Your little light experiment, saved.';
+  }, 'image/png');
+});
+
+const dialog = $('#about-dialog');
+$('#about-button').addEventListener('click', () => dialog.showModal());
+$('#close-about').addEventListener('click', () => dialog.close());
+// Native light dismiss where supported; outside-click fallback elsewhere.
+if (!('closedBy' in HTMLDialogElement.prototype)) {
+  dialog.addEventListener('click', event => {
+    const bounds = dialog.getBoundingClientRect();
+    if (event.target === dialog && (event.clientX < bounds.left || event.clientX > bounds.right ||
+        event.clientY < bounds.top || event.clientY > bounds.bottom)) dialog.close();
+  });
+}
+
+try {
+  if (!context || !('WebAssembly' in window) || !('Worker' in window)) {
+    throw new Error('This browser needs WebAssembly, Canvas, and Web Worker support.');
+  }
+  worker = new Worker(new URL('./render-worker.js', import.meta.url), { type: 'module' });
+  worker.onerror = event => showError(event.message || 'The rendering worker could not start.');
+  worker.onmessage = ({ data }) => {
+    if (data.id !== renderId) return;
+    if (data.type === 'error') { showError(data.message); return; }
+    $('#progress-fill').style.width = `${Math.round(data.progress * 100)}%`;
+    if (data.type === 'frame') {
+      if (canvas.width !== data.width || canvas.height !== data.height) {
+        canvas.width = data.width;
+        canvas.height = data.height;
+      }
+      context.putImageData(new ImageData(data.pixels, data.width, data.height), 0, 0);
+      canvas.style.opacity = '1';
+      $('#preview').hidden = true;
+      $('#samples-metric').textContent = `${data.completedSamples} / ${currentSamples} spp`;
+      download.disabled = false;
+      if (data.done) {
+        clearInterval(timer);
+        status.textContent = 'Render complete';
+        dot.style.background = '#6e8e61';
+        $('#time-metric').textContent = `${(data.elapsed / 1000).toFixed(1)}s`;
+      }
+    }
+  };
+  startRender();
+} catch (error) { showError(error.message); }
