diff --git a/render-worker.js b/render-worker.js
new file mode 100644
index 0000000..2079b52
--- /dev/null
+++ b/render-worker.js
@@ -0,0 +1,47 @@
+import createSmallpt from './public/wasm/smallpt.js';
+
+// No SharedArrayBuffer, pthreads, or special cross-origin headers are needed.
+const ready = createSmallpt();
+let generation = 0;
+
+self.onmessage = async ({ data }) => {
+  const current = ++generation;
+  const { id, width, height, samples, seed, colors } = data;
+  try {
+    const wasm = await ready;
+    if (current !== generation) return;
+    if (![480, 720, 960].includes(width) || height !== width * 2 / 3 ||
+        ![16, 32, 64, 128].includes(samples)) throw new Error('Invalid render settings.');
+
+    wasm._setup(width, height, seed);
+    for (const { index, rgb } of colors) wasm._set_color(index, ...rgb);
+
+    const started = performance.now();
+    const passes = samples / 4;
+    let lastProgress = 0;
+    for (let pass = 0; pass < passes; pass++) {
+      let pointer;
+      for (let row = 0; row < height; row += 8) {
+        if (current !== generation) return;
+        pointer = wasm._render_rows(row, Math.min(8, height - row), pass);
+        const now = performance.now();
+        if (now - lastProgress > 100) {
+          self.postMessage({ type: 'progress', id,
+            progress: (pass + Math.min(row + 8, height) / height) / passes,
+            elapsed: now - started });
+          lastProgress = now;
+        }
+        // Allow a newer render request to cancel this one between row batches.
+        await new Promise(resolve => setTimeout(resolve, 0));
+      }
+      if (current !== generation) return;
+      // Read the current heap after the C++ call, in case memory has grown.
+      const pixels = new Uint8ClampedArray(wasm.HEAPU8.buffer, pointer, width * height * 4).slice();
+      self.postMessage({ type: 'frame', id, pixels, width, height,
+        completedSamples: (pass + 1) * 4, progress: (pass + 1) / passes,
+        elapsed: performance.now() - started, done: pass === passes - 1 }, [pixels.buffer]);
+    }
+  } catch (error) {
+    if (current === generation) self.postMessage({ type: 'error', id, message: error.message });
+  }
+};
