@@ -0,0 +1,20 @@
+"""Convert the native preview's PPM output to PNG with Python's standard library."""
+from pathlib import Path
+import struct
+import zlib
+
+header = Path('/tmp/smallpt-preview.ppm').read_bytes().split(b'\n', 3)
+width, height = map(int, header[1].split())
+rgb = header[3]
+assert len(rgb) == width * height * 3
+
+def chunk(name, data):
+    return struct.pack('>I', len(data)) + name + data + struct.pack('>I', zlib.crc32(name + data))
+
+rows = b''.join(b'\0' + rgb[y * width * 3:(y + 1) * width * 3] for y in range(height))
+png = b'\x89PNG\r\n\x1a\n'
+png += chunk(b'IHDR', struct.pack('>IIBBBBB', width, height, 8, 2, 0, 0, 0))
+png += chunk(b'IDAT', zlib.compress(rows, 9))
+png += chunk(b'IEND', b'')
+Path('public/preview.png').write_bytes(png)
+print(f'Generated native smallpt preview: {width} × {height}')
