--- /dev/null
+++ b/scripts/check-wasm.mjs
@@ -0,0 +1,73 @@
+import assert from 'node:assert/strict';
+import { readFile } from 'node:fs/promises';
+import { Worker } from 'node:worker_threads';
+
+// Exercise the shipped worker-targeted module without a browser or HTTP server.
+const originalFetch = globalThis.fetch;
+globalThis.fetch = async input => {
+  const url = new URL(input);
+  assert.equal(url.protocol, 'file:');
+  return new Response(await readFile(url), { headers: { 'Content-Type': 'application/wasm' } });
+};
+
+try {
+  const { default: createSmallpt } = await import('../public/wasm/smallpt.js');
+  const wasm = await createSmallpt();
+  const width = 96, height = 64, bytes = width * height * 4;
+  const render = color => {
+    wasm._setup(width, height, 42);
+    wasm._set_color(6, ...color);
+    wasm._set_color(7, ...color);
+    let ptr;
+    for (let pass = 0; pass < 4; pass++) {
+      for (let row = 0; row < height; row += 8) ptr = wasm._render_rows(row, 8, pass);
+    }
+    return wasm.HEAPU8.slice(ptr, ptr + bytes);
+  };
+  const red = render([.9, .2, .2]);
+  assert.equal(red.length, bytes);
+  assert.ok(red.some((value, index) => index % 4 !== 3 && value > 0), 'Renderer produces lit pixels');
+  assert.ok(red.every((value, index) => index % 4 !== 3 || value === 255), 'Every pixel is opaque');
+  assert.deepEqual(render([.9, .2, .2]), red, 'Resetting the same scene and seed is deterministic');
+  const green = render([.2, .9, .2]);
+  const changed = green.reduce((sum, value, index) => sum + (value !== red[index]), 0);
+  assert.ok(changed > width * height / 10, 'Changing sphere colors changes rendered pixels');
+
+  // Largest selectable resolution exercises Emscripten heap growth as well.
+  wasm._setup(960, 640, 42);
+  const ptr = wasm._render_rows(0, 8, 0);
+  assert.ok(wasm.HEAPU8[ptr + 3] === 255, 'Rendering survives a resized heap');
+  console.log(`WebAssembly checks passed: nonempty image, alpha, deterministic reset, ${changed} changed channels, memory growth.`);
+} finally {
+  globalThis.fetch = originalFetch;
+}
+
+const worker = new Worker(new URL('./worker-harness.mjs', import.meta.url));
+try {
+  await new Promise((resolve, reject) => {
+    const timeout = setTimeout(() => reject(new Error('Worker render timed out')), 30_000);
+    const frames = [];
+    worker.on('error', error => { clearTimeout(timeout); reject(error); });
+    worker.on('message', data => {
+      try {
+        assert.notEqual(data.type, 'error', data.message);
+        if (data.type !== 'frame') return;
+        assert.equal(data.id, 2, 'A newer render cancels its predecessor');
+        assert.equal(data.pixels.length, 480 * 320 * 4);
+        assert.equal(data.pixels[3], 255);
+        frames.push(data.completedSamples);
+        if (data.done) {
+          assert.deepEqual(frames, [4, 8, 12, 16], 'Worker emits progressive sample passes');
+          assert.equal(data.progress, 1);
+          clearTimeout(timeout);
+          resolve();
+        }
+      } catch (error) { clearTimeout(timeout); reject(error); }
+    });
+    const job = { width: 480, height: 320, samples: 16, seed: 42,
+      colors: [{ index: 6, rgb: [.9, .3, .2] }, { index: 7, rgb: [.3, .9, .6] }] };
+    worker.postMessage({ ...job, id: 1 });
+    worker.postMessage({ ...job, id: 2 });
+  });
+  console.log('Worker checks passed: cancellation, transferable pixel buffers, progressive frames, completion.');
+} finally { await worker.terminate(); }
