+// Node-only adapter for exercising the real browser worker without a web server.
+import { parentPort } from 'node:worker_threads';
+import { readFile } from 'node:fs/promises';
+
+globalThis.self = globalThis;
+globalThis.fetch = async input => new Response(await readFile(new URL(input)), {
+  headers: { 'Content-Type': 'application/wasm' },
+});
+self.postMessage = (message, transfer) => parentPort.postMessage(message, transfer);
+await import('../render-worker.js');
+parentPort.on('message', data => self.onmessage({ data }));
