+const $ = (id) => document.getElementById(id);
+const canvas = $('render');
+const context = canvas.getContext('2d');
+const originalColors = { 0: [.75, .25, .25], 1: [.25, .25, .75], 6: [.999, .999, .999], 7: [.999, .999, .999] };
+let colors = structuredClone(originalColors);
+let samples = 128;
+let worker;
+let scene = 1;
+let hasFrame = false;
+let revision = 0;
+
+function status(text, state = '') {
+  $('status-text').textContent = text;
+  $('status-dot').className = state;
+}
+function stopRender() {
+  if (worker) worker.terminate();
+  worker = null;
+  $('stop').disabled = true;
+}
+function paintPalette() {
+  for (const [id, color] of Object.entries(colors)) {
+    $('swatch-' + id).style.setProperty('--swatch', `rgb(${color.map(v => Math.round(v * 255)).join(',')})`);
+  }
+  $('palette-number').textContent = String(scene).padStart(2, '0');
+  $('scene-label').textContent = scene === 1 ? 'The original scene' : `Color study ${String(scene).padStart(2, '0')}`;
+}
+function startRender() {
+  stopRender();
+  const currentRevision = ++revision;
+  const width = Number($('resolution').value);
+  const height = width * .75;
+  let receivedFrame = false;
+  $('sample-count').textContent = '0';
+  $('elapsed').textContent = '0.0s';
+  $('progress').style.width = '0%';
+  status('Rendering · following the light', 'working');
+  try {
+    worker = new Worker(new URL('./public/render-worker.js', import.meta.url), { type: 'module' });
+    $('stop').disabled = false;
+    worker.onmessage = ({ data }) => {
+      if (currentRevision !== revision) return;
+      if (data.error) { fail(data.error); return; }
+      if (!receivedFrame) {
+        canvas.width = width;
+        canvas.height = height;
+        receivedFrame = true;
+      }
+      context.putImageData(new ImageData(new Uint8ClampedArray(data.pixels.buffer), width, height), 0, 0);
+      hasFrame = true;
+      $('download').disabled = false;
+      $('sample-count').textContent = data.spp;
+      $('elapsed').textContent = data.elapsed.toFixed(1) + 's';
+      $('progress').style.width = `${Math.min(100, data.spp / samples * 100)}%`;
+      if (data.done) {
+        status('Render complete');
+        stopRender();
+      }
+    };
+    worker.onerror = (event) => { if (currentRevision === revision) fail(event.message); };
+    worker.postMessage({ width, height, samples, colors });
+  } catch (error) { fail(error.message); }
+}
+function fail(message) {
+  stopRender();
+  status('Render unavailable. Try reloading the page.', 'error');
+  console.error('smallpt:', message);
+}
+// HSL creates cohesive, saturated palettes while keeping reflectance below one.
+function colorFromHue(hue, saturation, lightness) {
+  const a = saturation * Math.min(lightness, 1 - lightness);
+  return [0, 8, 4].map(n => {
+    const k = (n + hue / 30) % 12;
+    return lightness - a * Math.max(-1, Math.min(k - 3, 9 - k, 1));
+  });
+}
+$('randomize').addEventListener('click', () => {
+  const seed = crypto.getRandomValues(new Uint32Array(4));
+  const hue = seed[0] / 2 ** 32 * 360;
+  colors = {
+    0: colorFromHue(hue, .55, .48),
+    1: colorFromHue((hue + 135 + seed[1] % 90) % 360, .5, .48),
+    6: colorFromHue((hue + 30 + seed[2] % 100) % 360, .4, .68),
+    7: colorFromHue((hue + 210 + seed[3] % 90) % 360, .3, .76),
+  };
+  scene++;
+  paintPalette();
+  startRender();
+});
+$('reset').addEventListener('click', () => {
+  colors = structuredClone(originalColors);
+  scene = 1;
+  paintPalette();
+  startRender();
+});
+$('resolution').addEventListener('change', startRender);
+document.querySelectorAll('[data-samples]').forEach(button => {
+  button.addEventListener('click', () => {
+    samples = Number(button.dataset.samples);
+    document.querySelectorAll('[data-samples]').forEach(item => {
+      const selected = item === button;
+      item.classList.toggle('selected', selected);
+      item.setAttribute('aria-pressed', String(selected));
+    });
+    $('target-samples').textContent = `${samples} samples / pixel`;
+    startRender();
+  });
+});
+$('stop').addEventListener('click', () => {
+  stopRender();
+  revision++;
+  status('Render stopped · image preserved');
+});
+$('download').addEventListener('click', () => {
+  if (!hasFrame) return;
+  canvas.toBlob(blob => {
+    if (!blob) return;
+    const url = URL.createObjectURL(blob);
+    const link = document.createElement('a');
+    link.href = url;
+    link.download = `smallpt-study-${String(scene).padStart(2, '0')}.png`;
+    link.click();
+    setTimeout(() => URL.revokeObjectURL(url), 1000);
+  }, 'image/png');
+});
+$('expand').addEventListener('click', async () => {
+  const viewport = $('viewport');
+  try {
+    if (document.fullscreenElement) await document.exitFullscreen();
+    else if (viewport.requestFullscreen) await viewport.requestFullscreen();
+    else viewport.classList.toggle('expanded');
+  } catch { viewport.classList.toggle('expanded'); }
+});
+document.addEventListener('keydown', event => {
+  if (event.key === 'Escape') $('viewport').classList.remove('expanded');
+});
+// The instant preview was generated by this exact WASM module at build time.
+// A new, client-side render replaces it as soon as its first pass is ready.
+const preview = new Image();
+preview.onload = () => {
+  if (!hasFrame) {
+    context.drawImage(preview, 0, 0, canvas.width, canvas.height);
+    $('download').disabled = false;
+    hasFrame = true;
+  }
+};
+preview.src = new URL('./public/preview.png', import.meta.url).href;
+if (typeof WebAssembly === 'undefined' || typeof Worker === 'undefined') {
+  status('WebAssembly and Web Workers are required to render.', 'error');
+  $('randomize').disabled = true;
+  $('reset').disabled = true;
+} else startRender();
+window.addEventListener('pagehide', stopRender);
