--- /dev/null
+++ b/public/render-worker.js
@@ -0,0 +1,16 @@
+import createSmallpt from './smallpt.mjs';
+self.onmessage = async ({ data }) => {
+  try {
+    const { width, height, samples, colors } = data;
+    const engine = await createSmallpt();
+    const ptr = engine._init(width, height);
+    for (const [id, color] of Object.entries(colors)) engine._set_color(Number(id), ...color);
+    const started = performance.now();
+    for (let spp = 0; spp < samples;) {
+      spp = engine._render_pass();
+      const pixels = engine.HEAPU8.slice(ptr, ptr + width * height * 4);
+      self.postMessage({ pixels, spp, elapsed: (performance.now() - started) / 1000, done: spp >= samples }, [pixels.buffer]);
+    }
+    self.close();
+  } catch (error) { self.postMessage({ error: error.message }); }
+};
