diff --git a/scripts/test-wasm.mjs b/scripts/test-wasm.mjs
new file mode 100644
index 0000000..8f00b0c
--- /dev/null
+++ b/scripts/test-wasm.mjs
@@ -0,0 +1,23 @@
+import assert from 'node:assert/strict';
+import createSmallpt from '../public/smallpt.mjs';
+const engine = await createSmallpt();
+const width = 40, height = 30;
+function render(color) {
+  const ptr = engine._init(width, height);
+  if (color) engine._set_color(6, ...color);
+  assert.equal(engine._render_pass(), 4);
+  assert.equal(engine._render_pass(), 8);
+  return engine.HEAPU8.slice(ptr, ptr + width * height * 4);
+}
+const original = render();
+assert(original.some((value, index) => index % 4 !== 3 && value > 0), 'Rendered image contains light');
+assert(original.every((value, index) => index % 4 !== 3 || value === 255), 'All pixels are opaque');
+const changed = render([.8, .1, .2]);
+assert.notDeepEqual(changed, original, 'Changing sphere color changes the render');
+assert.deepEqual(render(), original, 'Reset restores the original deterministic scene');
+console.log('WASM checks passed: progressive samples, RGBA output, sphere color change, and scene reset.');
+// Exercise real-size recursive paths and framebuffer allocation too.
+const largePtr = engine._init(1024, 768);
+assert.equal(engine._render_pass(), 4);
+assert.equal(engine.HEAPU8[largePtr + 1024 * 768 * 4 - 1], 255);
+console.log('Full-resolution (1024 × 768) render passed.');
diff --git a/scripts/test-worker.mjs b/scripts/test-worker.mjs
new file mode 100644
index 0000000..49ef7f6
--- /dev/null
+++ b/scripts/test-worker.mjs
@@ -0,0 +1,17 @@
+import { Worker } from 'node:worker_threads';
+import assert from 'node:assert/strict';
+const worker = new Worker(new URL('./worker-harness.mjs', import.meta.url));
+let frames = 0;
+await new Promise((resolve, reject) => {
+  worker.on('error', reject);
+  worker.on('message', data => {
+    if (data.ready) { worker.postMessage({ width: 40, height: 30, samples: 8, colors: { 6: [.8, .2, .3] } }); return; }
+    if (data.error) { reject(new Error(data.error)); return; }
+    frames++;
+    assert.equal(data.pixels.length, 40 * 30 * 4);
+    assert.equal(data.spp, frames * 4);
+    if (data.done) { assert.equal(frames, 2); resolve(); }
+  });
+  worker.on('exit', code => { if (code !== 0 || frames !== 2) reject(new Error('Worker exited before finishing')); });
+});
+console.log('Worker passed: actual WASM initialization, progressive frame transfers, and completion.');
