+// Browser buffer adapter for smallpt. Original algorithm: Kevin Beason, 2008.
+#include "smallpt-core.h"
+#include <vector>
+#include <cstdint>
+static std::vector<unsigned char> pixels;
+static int width, height, samples;
+static unsigned int renderSeed;
+extern "C" {
+void init_render(int w, int h, int spp, unsigned int seed) {
+  width=w; height=h; samples=spp/4; renderSeed=seed;
+  pixels.assign(w*h*4, 0);
+}
+void set_color(int id, double r, double g, double b) {
+  if (id==0 || id==1 || id==6 || id==7) spheres[id].c=Vec(r,g,b);
+}
+unsigned char* get_pixels() { return pixels.data(); }
+void render_rows(int start, int count) {
+  Ray cam(Vec(50,52,295.6), Vec(0,-0.042612,-1).norm());
+  Vec cx=Vec(width*.5135/height), cy=(cx%cam.d).norm()*.5135;
+  for (int row=start; row<start+count && row<height; row++) {
+    int y=height-row-1;
+    unsigned short Xi[3]={static_cast<unsigned short>(renderSeed),
+      static_cast<unsigned short>(renderSeed>>16),static_cast<unsigned short>(y*y*y)};
