+  init_render(800,600,256,42); render_rows(0,600);
+  FILE* out=fopen("/tmp/smallpt-preview.ppm","wb");
+  fprintf(out,"P6\n800 600\n255\n");
+  for (int i=0;i<800*600;i++) fwrite(pixels.data()+i*4,1,3,out);
