diff --git a/public/wasm/render-worker.js b/public/wasm/render-worker.js
new file mode 100644
index 0000000..c40de47
--- /dev/null
+++ b/public/wasm/render-worker.js
@@ -0,0 +1,24 @@
+import createSmallpt from './smallpt.js';
+const renderer = createSmallpt();
+let busy = false;
+self.onmessage = async ({ data }) => {
+  if (busy) return;
+  busy = true;
+  try {
+    const wasm = await renderer;
+    const { width, height, samples, seed, colors } = data;
+    wasm._init_render(width, height, samples, seed);
+    for (const [id, color] of Object.entries(colors)) wasm._set_color(Number(id), ...color);
+    const started = performance.now();
+    for (let row = 0; row < height; row += 6) {
+      const rows = Math.min(6, height - row);
+      wasm._render_rows(row, rows);
+      const pointer = wasm._get_pixels() + row * width * 4;
+      const pixels = new Uint8ClampedArray(wasm.HEAPU8.buffer, pointer, rows * width * 4).slice();
+      self.postMessage({ type: 'progress', row, rows, width, height, pixels, elapsed: performance.now() - started }, [pixels.buffer]);
+    }
+    self.postMessage({ type: 'done', elapsed: performance.now() - started });
+  } catch (error) {
+    self.postMessage({ type: 'error', message: error.message || String(error) });
+  } finally { busy = false; }
+};
