+#!/usr/bin/env bash
+set -euo pipefail
+cd "$(dirname "$0")/.."
+mkdir -p public/wasm
+em++ native/renderer.cpp -o public/wasm/smallpt.js \
+  -O3 -flto -fno-exceptions -Wall -Werror --no-entry \
+  -sSTRICT -sEXPORT_ES6 -sENVIRONMENT=worker -sALLOW_MEMORY_GROWTH \
+  -sINCOMING_MODULE_JS_API=wasmBinary -sSTACK_SIZE=1MB -sFILESYSTEM=0 \
+  -sEXPORTED_FUNCTIONS=_init_render,_set_color,_get_pixels,_render_rows \
+  -sEXPORTED_RUNTIME_METHODS=HEAPU8
+cp native/LICENSE.txt public/wasm/LICENSE.txt
