+++ b/scripts/verify-wasm.mjs
@@ -0,0 +1,21 @@
+// Runs the actual worker-targeted Wasm binary in Node, without a web server.
+import { readFileSync } from 'node:fs';
+import assert from 'node:assert/strict';
+import createSmallpt from '../public/wasm/smallpt.js';
+const wasm = await createSmallpt({ wasmBinary: readFileSync(new URL('../public/wasm/smallpt.wasm', import.meta.url)) });
+const width = 32, height = 24, size = width * height * 4;
+const read = () => wasm.HEAPU8.slice(wasm._get_pixels(), wasm._get_pixels() + size);
+wasm._init_render(width, height, 8, 42);
+for (let row = 0; row < height; row += 6) wasm._render_rows(row, 6);
+const original = read();
+assert(original.some((value, i) => i % 4 !== 3 && value > 0), 'Visible RGB output');
+assert(original.every((value, i) => i % 4 !== 3 || value === 255), 'Opaque RGBA pixels');
+wasm._init_render(width, height, 8, 42);
+wasm._render_rows(0, height);
+assert.deepEqual(read(), original, 'Chunked rendering matches a full-frame call');
+wasm._set_color(6, .3, .9, .3);
+wasm._set_color(7, .9, .3, .3);
+wasm._init_render(width, height, 8, 42);
+wasm._render_rows(0, height);
+assert(read().some((value, i) => value !== original[i]), 'Sphere recoloring changes output');
+console.log('PASS: RGBA output, progressive row consistency, deterministic seed, sphere color changes.');
