+const get = <T extends HTMLElement>(id: string) => document.getElementById(id) as T;
+const canvas = get<HTMLCanvasElement>('output');
+const context = canvas.getContext('2d')!;
+const preview = get<HTMLImageElement>('preview');
+const renderButton = get<HTMLButtonElement>('render');
+const randomButton = get<HTMLButtonElement>('randomize');
+const resetButton = get<HTMLButtonElement>('reset');
+const downloadButton = get<HTMLButtonElement>('download');
+const resolution = get<HTMLSelectElement>('resolution');
+const samples = get<HTMLInputElement>('samples');
+const progress = get<HTMLProgressElement>('progress');
+const status = get('status');
+const dot = get('status-dot');
+const colorFields = ['left-wall', 'right-wall', 'mirror', 'glass'].map(id => get<HTMLInputElement>(id));
+const sphereIds = [0, 1, 6, 7];
+const originalColors = ['#bf4040', '#4040bf', '#ffffff', '#ffffff'];
+const sampleOptions = [8, 32, 128, 256];
+const qualityNames = ['Draft', 'Balanced', 'High', 'Ultra'];
+let worker: Worker | undefined;
+let busy = false;
+let didStart = false;
+let hasRender = false;
+let finishedRender = false;
+let requestedHeight = 480;
+function updateSettings() {
+  const width = Number(resolution.value);
+  get('dimensions').textContent = `${width} × ${width * .75}`;
+  get('sample-count').textContent = String(sampleOptions[Number(samples.value)]);
+  get('stat-samples').textContent = `${sampleOptions[Number(samples.value)]} spp`;
+  get('quality-name').textContent = qualityNames[Number(samples.value)];
+  samples.style.background = `linear-gradient(to right, var(--lime) ${Number(samples.value) / 3 * 100}%, #414836 ${Number(samples.value) / 3 * 100}%)`;
+}
+resolution.addEventListener('change', updateSettings);
+samples.addEventListener('input', updateSettings);
+function setBusy(value: boolean) {
+  busy = value;
+  [randomButton, resetButton, resolution, samples, ...colorFields].forEach(element => element.disabled = value);
+  downloadButton.disabled = value;
+  renderButton.innerHTML = value ? '<span aria-hidden="true">□</span> Stop rendering' : '<span aria-hidden="true">▷</span> Render scene';
+  dot.classList.toggle('busy', value);
+  progress.hidden = !value;
+}
+function fail(message: string) {
+  setBusy(false);
+  worker?.terminate(); worker = undefined;
+  dot.classList.add('error');
+  status.textContent = message;
+  if (!finishedRender) { canvas.hidden = true; preview.hidden = false; hasRender = false; }
+}
+function beginRender() {
+  if (busy) return;
+  didStart = true;
+  if (!('WebAssembly' in window) || !('Worker' in window)) {
+    fail('This browser does not support WebAssembly workers.'); return;
+  }
+  dot.classList.remove('error');
+  const width = Number(resolution.value), height = width * .75;
+  requestedHeight = height;
+  // Preserve the last image under incoming rows rather than flashing an empty buffer.
+  const previous = document.createElement('canvas');
+  previous.width = width; previous.height = height;
+  const previousContext = previous.getContext('2d')!;
+  if (hasRender) previousContext.drawImage(canvas, 0, 0, width, height);
+  else if (preview.complete && preview.naturalWidth) previousContext.drawImage(preview, 0, 0, width, height);
+  canvas.width = width; canvas.height = height;
+  context.drawImage(previous, 0, 0);
+  finishedRender = false;
+  progress.value = 0;
+  get('elapsed').textContent = '0.0 s';
+  status.textContent = 'Preparing the light…';
+  setBusy(true);
+  const colors: Record<number, number[]> = {};
+  colorFields.forEach((field, i) => {
+    const hex = field.value.slice(1);
+    colors[sphereIds[i]] = [0, 2, 4].map(offset => Math.min(.999, parseInt(hex.slice(offset, offset + 2), 16) / 255));
+  });
+  try {
+    worker ??= new Worker('/wasm/render-worker.js', { type: 'module' });
+    worker.onmessage = ({ data }) => {
+      if (data.type === 'error') { fail('Render failed. Try a lower resolution.'); return; }
+      get('elapsed').textContent = `${(data.elapsed / 1000).toFixed(1)} s`;
+      if (data.type === 'progress') {
+        if (!hasRender) { preview.hidden = true; canvas.hidden = false; hasRender = true; }
+        context.putImageData(new ImageData(data.pixels, data.width, data.rows), 0, data.row);
+        const percent = Math.round((data.row + data.rows) / requestedHeight * 100);
+        progress.value = percent;
+        // Progress is visual; announce only the start and completion to screen readers.
+        if (data.row === 0) status.textContent = 'Rendering scene…';
+        renderButton.innerHTML = `<span aria-hidden="true">□</span> Stop rendering · ${percent}%`;
+      } else if (data.type === 'done') {
+        finishedRender = true;
+        setBusy(false);
+        status.textContent = 'Render complete';
+      }
+    };
+    worker.onerror = event => { event.preventDefault(); fail('Could not load renderer. Reload to try again.'); };
+    worker.postMessage({ width, height, samples: sampleOptions[Number(samples.value)], seed: crypto.getRandomValues(new Uint32Array(1))[0], colors });
+  } catch { fail('Could not start renderer. Reload to try again.'); }
+}
+renderButton.addEventListener('click', () => {
+  if (busy) {
+    worker?.terminate(); worker = undefined;
+    setBusy(false); status.textContent = 'Render stopped';
+  } else beginRender();
+});
+randomButton.addEventListener('click', () => {
+  const values = crypto.getRandomValues(new Uint8Array(12));
+  colorFields.forEach((field, index) => {
+    // Keep materials bright enough to produce rich reflections and color bleeding.
+    const rgb = Array.from(values.slice(index * 3, index * 3 + 3), n => Math.round(80 + n * .66));
+    field.value = '#' + rgb.map(n => n.toString(16).padStart(2, '0')).join('');
+  });
+  beginRender();
+});
+resetButton.addEventListener('click', () => {
+  colorFields.forEach((field, index) => field.value = originalColors[index]);
+  beginRender();
+});
+colorFields.forEach(field => field.addEventListener('change', () => { status.textContent = 'Colors updated · ready to render'; }));
+downloadButton.addEventListener('click', () => {
+  const link = document.createElement('a');
+  link.download = 'smallpt-render.png';
+  if (!hasRender) { link.href = preview.src; link.click(); return; }
+  canvas.toBlob(blob => {
+    if (!blob) return;
+    const url = URL.createObjectURL(blob);
+    link.href = url; link.click();
+    setTimeout(() => URL.revokeObjectURL(url), 1000);
+  }, 'image/png');
+});
+// The bundled preview comes from this same C++ renderer. Start a fresh local render.
+updateSettings();
+requestAnimationFrame(() => setTimeout(async () => {
+  await preview.decode().catch(() => {});
+  if (!didStart) beginRender();
+}, 250));
+window.addEventListener('pagehide', () => worker?.terminate());
