+// Browser adapter for smallpt by Kevin Beason. See LICENSE.smallpt.
+// The original integrator, camera, materials, and 2x2 tent filter are preserved.
+#define main smallpt_cli_main
+#include "smallpt-original.cpp"
+#undef main
+#include <stdint.h>
+#include <vector>
+
+static int width, height, row, pass;
+static unsigned int sceneSeed;
+static std::vector<Vec> accumulation;
+static std::vector<unsigned char> pixels;
+
+extern "C" {
+void init_render(int w, int h, unsigned int seed, const double* colors) {
+  width=w; height=h; row=0; pass=0; sceneSeed=seed;
+  accumulation.assign(w*h, Vec());
+  pixels.assign(w*h*4, 0);
+  for (int i=0; i<w*h; ++i) pixels[i*4+3]=255;
+  spheres[0].c=Vec(.75,.25,.25); spheres[1].c=Vec(.25,.25,.75);
+  spheres[6].c=Vec(.999,.999,.999); spheres[7].c=Vec(.999,.999,.999);
+  if (colors) {
+    for (int i=0; i<4; ++i) {
+      int index = i<2 ? i : i+4;
+      spheres[index].c=Vec(colors[i*3],colors[i*3+1],colors[i*3+2]);
+    }
+  }
+}
+// Each pass traces four paths per pixel, one per subpixel.
+int render_rows(int count) {
+  Ray cam(Vec(50,52,295.6), Vec(0,-0.042612,-1).norm());
+  Vec cx=Vec(width*.5135/height), cy=(cx%cam.d).norm()*.5135;
+  int end=row+count; if (end>height) end=height;
+  for (; row<end; ++row) {
+    unsigned int hash=sceneSeed ^ (row*747796405u) ^ (pass*2891336453u);
+    unsigned short Xi[3]={(unsigned short)hash,(unsigned short)(hash>>16),(unsigned short)(row*row*row+pass+1)};
+    for (int x=0; x<width; ++x) {
+      Vec sample;
+      for (int sy=0; sy<2; ++sy) for (int sx=0; sx<2; ++sx) {
+        double r1=2*erand48(Xi), dx=r1<1?sqrt(r1)-1:1-sqrt(2-r1);
+        double r2=2*erand48(Xi), dy=r2<1?sqrt(r2)-1:1-sqrt(2-r2);
+        Vec d=cx*(((sx+.5+dx)/2+x)/width-.5)+cy*(((sy+.5+dy)/2+row)/height-.5)+cam.d;
+        sample=sample+radiance(Ray(cam.o+d*140,d.norm()),0,Xi)*.25;
+      }
+      int i=(height-row-1)*width+x;
+      accumulation[i]=accumulation[i]+sample;
+      Vec color=accumulation[i]*(1./(pass+1));
+      pixels[i*4]=toInt(color.x); pixels[i*4+1]=toInt(color.y); pixels[i*4+2]=toInt(color.z);
+    }
+  }
+  if (row==height) { row=0; ++pass; }
+  return pass*height+row;
+}
+unsigned char* get_pixels() { return pixels.data(); }
+}
