diff --git a/public/studio.js b/public/studio.js
new file mode 100644
index 0000000..4424a14
--- /dev/null
+++ b/public/studio.js
@@ -0,0 +1,116 @@
+const $ = id => document.getElementById(id);
+const canvas = $('render-canvas');
+const context = canvas.getContext('2d');
+const randomize = $('randomize');
+const rerender = $('rerender');
+let worker, jobId = 0, seed = 2008, colors = null, rendering = false;
+let lastSamples = 0;
+const iconPlay = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><path d="m9 5 10 7-10 7z"/></svg>';
+function updateState(text, state) {
+  $('status-label').textContent = text;
+  $('status').dataset.state = state;
+}
+function startRender() {
+  try {
+    if (!worker) {
+      worker = new Worker(new URL('./wasm/render-worker.js', import.meta.url), { type: 'module' });
+      worker.onmessage = handleMessage;
+      worker.onerror = () => fail('The WebAssembly renderer could not load. Try reloading the page.');
+    }
+    const [width, height] = $('resolution').value.split('x').map(Number);
+    const samples = Number($('samples').value);
+    jobId++;
+    rendering = true;
+    lastSamples = 0;
+    $('progress-fill').style.width = '0%';
+    $('progress-text').textContent = '0%';
+    $('sample-count').textContent = '0';
+    $('render-time').textContent = '—';
+    $('resolution-label').textContent = `${width} × ${height}`;
+    $('seed-value').textContent = String(seed).padStart(4, '0');
+    $('target-samples').textContent = `${samples} samples / pixel`;
+    updateState('Rendering', 'rendering');
+    rerender.innerHTML = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><path d="M7 5h3v14H7zm7 0h3v14h-3z"/></svg> Stop render';
+    canvas.dataset.width = width;
+    canvas.dataset.height = height;
+    worker.postMessage({ id: jobId, width, height, samples, seed, colors });
+  } catch (error) { fail(error.message); }
+}
+function fail(message) {
+  rendering = false;
+  updateState('Render unavailable', 'error');
+  $('progress-description').textContent = message;
+  rerender.innerHTML = iconPlay + ' Try again';
+  worker?.terminate(); worker = null;
+}
+function handleMessage({ data }) {
+  if (data.id !== jobId) return;
+  if (data.type === 'error') return fail(data.message);
+  if (data.type === 'progress') {
+    const percent = Math.floor(data.progress * 100);
+    $('progress-fill').style.width = `${percent}%`;
+    $('progress-text').textContent = `${percent}%`;
+    return;
+  }
+  if (data.type === 'frame') {
+    canvas.width = Number(canvas.dataset.width);
+    canvas.height = Number(canvas.dataset.height);
+    context.putImageData(new ImageData(new Uint8ClampedArray(data.pixels), canvas.width, canvas.height), 0, 0);
+    $('render-preview').hidden = true;
+    canvas.hidden = false;
+    lastSamples = data.samples;
+    $('sample-count').textContent = data.samples;
+    $('render-time').textContent = `${(data.elapsed / 1000).toFixed(1)}s`;
+    if (data.done) {
+      rendering = false;
+      updateState('Render complete', 'complete');
+      $('progress-fill').style.width = '100%';
+      $('progress-text').textContent = '100%';
+      rerender.innerHTML = iconPlay + ' Render again';
+      $('progress-description').textContent = 'Every pixel, a little more light.';
+    }
+  }
+}
+function hsv(h, s, v) {
+  const f = n => { const k = (n + h * 6) % 6; return v * (1 - s * Math.max(0, Math.min(k, 4 - k, 1))); };
+  return [f(5), f(3), f(1)];
+}
+function updateSwatches() {
+  const values = colors || [.75,.25,.25,.25,.25,.75,.999,.999,.999,.999,.999,.999];
+  document.querySelectorAll('.swatch').forEach((el, i) => {
+    const rgb = values.slice(i * 3, i * 3 + 3).map(v => Math.round(v * 255));
+    el.style.backgroundColor = `rgb(${rgb.join(',')})`;
+    el.title = `RGB ${rgb.join(', ')}`;
+  });
+}
+randomize.addEventListener('click', () => {
+  seed = crypto.getRandomValues(new Uint32Array(1))[0] % 1000000;
+  const hue = Math.random();
+  colors = [hsv(hue, .55, .78), hsv((hue+.45)%1, .55, .78), hsv((hue+.12)%1, .48, .94), hsv((hue+.66)%1, .4, .96)].flat();
+  updateSwatches();
+  $('palette-name').textContent = 'Randomized palette';
+  startRender();
+});
+rerender.addEventListener('click', () => {
+  if (rendering) {
+    worker.terminate(); worker = null; rendering = false; ++jobId;
+    updateState('Render stopped', 'stopped');
+    rerender.innerHTML = iconPlay + ' Render again';
+    $('progress-description').textContent = `Stopped at ${lastSamples} samples per pixel.`;
+  } else startRender();
+});
+$('reset').addEventListener('click', () => {
+  colors = null; seed = 2008; updateSwatches();
+  $('palette-name').textContent = 'The original Cornell box';
+  startRender();
+});
+$('download').addEventListener('click', async () => {
+  if (!canvas.hidden) {
+    const a = document.createElement('a');
+    a.download = `smallpt-${seed}.png`; a.href = canvas.toDataURL('image/png'); a.click();
+  } else {
+    const a = document.createElement('a'); a.download = 'smallpt-original.png'; a.href = $('render-preview').src; a.click();
+  }
+});
+updateSwatches();
+startRender();
