diff --git a/public/wasm/render-worker.js b/public/wasm/render-worker.js
new file mode 100644
index 0000000..75c45c7
--- /dev/null
+++ b/public/wasm/render-worker.js
@@ -0,0 +1,33 @@
+import createSmallpt from './smallpt.js';
+let engine;
+let currentJob = 0;
+const ready = createSmallpt().then(module => engine = module);
+self.onmessage = async ({ data }) => {
+  const job = ++currentJob;
+  try {
+    await ready;
+    if (job !== currentJob) return;
+    const { width, height, samples, seed, colors } = data;
+    let ptr = 0;
+    if (colors) {
+      ptr = engine._malloc(12 * 8);
+      engine.HEAPF64.set(colors, ptr / 8);
+    }
+    engine._init_render(width, height, seed, ptr);
+    if (ptr) engine._free(ptr);
+    let progress = 0;
+    const start = performance.now();
+    while (progress < height * samples / 4 && job === currentJob) {
+      progress = engine._render_rows(4);
+      if (progress % height === 0) {
+        const pixels = engine.HEAPU8.slice(engine._get_pixels(), engine._get_pixels() + width * height * 4);
+        self.postMessage({ type: 'frame', id: data.id, pixels, samples: progress / height * 4, elapsed: performance.now() - start, done: progress >= height * samples / 4 }, [pixels.buffer]);
+      } else {
+        self.postMessage({ type: 'progress', id: data.id, progress: progress / (height * samples / 4) });
+      }
+      await new Promise(resolve => setTimeout(resolve, 0));
+    }
+  } catch (error) {
+    self.postMessage({ type: 'error', id: data.id, message: error.message });
+  }
+};
