+mkdir -p public/wasm
+em++ native/smallpt-web.cpp -O3 -Wno-c++11-narrowing -Wno-dangling-else --no-entry \
+  -s MODULARIZE=1 -s EXPORT_ES6=1 -s ENVIRONMENT=web,worker,node \
+  -s EXPORTED_RUNTIME_METHODS=HEAPU8,HEAPF64 \
+  -s ALLOW_MEMORY_GROWTH=1 -s STACK_SIZE=1048576 -s FILESYSTEM=0 \
+  -s EXPORTED_FUNCTIONS='["_init_render","_render_rows","_get_pixels","_malloc","_free"]' \
+  -o public/wasm/smallpt.js
+cp native/LICENSE.smallpt public/wasm/LICENSE.txt
+cp native/smallpt-original.cpp public/wasm/smallpt-original.cpp
+cp native/smallpt-web.cpp public/wasm/smallpt-web.cpp
diff --git a/scripts/check-wasm.mjs b/scripts/check-wasm.mjs
new file mode 100644
index 0000000..95f7427
--- /dev/null
+++ b/scripts/check-wasm.mjs
@@ -0,0 +1,23 @@
+import assert from 'node:assert/strict';
+import createSmallpt from '../public/wasm/smallpt.js';
+const engine = await createSmallpt();
+const width = 32, height = 24, seed = 2008;
+function render(colors = null) {
+  let ptr = 0;
+  if (colors) { ptr = engine._malloc(96); engine.HEAPF64.set(colors, ptr / 8); }
+  engine._init_render(width, height, seed, ptr);
+  if (ptr) engine._free(ptr);
+  let progress = 0;
+  while (progress < height * 2) progress = engine._render_rows(4);
+  assert.equal(progress, height * 2);
+  const pixels = engine.HEAPU8.slice(engine._get_pixels(), engine._get_pixels() + width * height * 4);
+  assert.equal(pixels.length, width * height * 4);
+  assert(pixels.some((value, index) => index % 4 !== 3 && value > 0), 'render should contain visible light');
+  assert(pixels.every((value, index) => index % 4 !== 3 || value === 255), 'pixels must be opaque');
+  return pixels;
+}
+const original = render();
+const randomized = render([.2,.7,.3,.7,.2,.5,.8,.3,.2,.3,.4,.9]);
+assert.notDeepEqual(original, randomized, 'palette changes must alter the rendered image');
+assert.deepEqual(original, render(), 'reset should restore the original scene reproducibly');
+console.log('WASM checks passed: real pixels, progressive passes, palette changes, and deterministic reset.');
