+        event.viewTransition.skipTransition();
+        return;
+      }
+      const from = new URL(navigation.from.url);
+      const to = new URL(navigation.entry.url);
+      if (from.pathname !== to.pathname || pageNumber(from) === pageNumber(to)) {
+        event.viewTransition.skipTransition();
+        return;
+      }
+      document.documentElement.dataset.direction = pageNumber(to) > pageNumber(from) ? 'next' : 'previous';
+    };
+
+    addEventListener('pageswap', setTransitionDirection);
+    addEventListener('pagereveal', setTransitionDirection);
