+/** An autonomous, progressively enhanced coffee card. */
+export class CoffeeCard extends HTMLElement {
+  static observedAttributes = ['name', 'description', 'href', 'price', 'featured'];
+
+  #heading;
+  #description;
+  #link;
+  #price;
+  #featured;
+
+  constructor() {
+    super();
+    // Attributes and children are read only after connection, including upgrades.
+  }
+
+  get name() { return this.getAttribute('name') ?? ''; }
+  set name(value) { this.#setString('name', value); }
+
+  get description() { return this.getAttribute('description') ?? ''; }
+  set description(value) { this.#setString('description', value); }
+
+  get href() { return this.getAttribute('href') ?? ''; }
+  set href(value) { this.#setString('href', value); }
+
+  // Missing, blank, negative, and non-finite markup prices mean “no price”.
+  get price() {
+    const raw = this.getAttribute('price');
+    if (raw === null || raw.trim() === '') return null;
+    const number = Number(raw);
+    return Number.isFinite(number) && number >= 0 ? number : null;
+  }
+
+  set price(value) {
+    if (value == null) {
+      this.removeAttribute('price');
+      return;
+    }
+    const number = Number(value);
+    if (String(value).trim() === '' || !Number.isFinite(number) || number < 0) {
+      throw new RangeError('price must be a finite, non-negative number or null');
+    }
+    this.setAttribute('price', String(number));
+  }
+
+  get featured() { return this.hasAttribute('featured'); }
+  set featured(value) { this.toggleAttribute('featured', Boolean(value)); }
+
+  connectedCallback() {
+    // Recover properties assigned before customElements.define() upgraded us.
+    for (const property of ['name', 'description', 'href', 'price', 'featured']) {
+      if (Object.hasOwn(this, property)) {
+        const value = this[property];
+        delete this[property];
+        this[property] = value;
+      }
+    }
+
+    // Reuse the static HTML so content and links also work without JavaScript.
+    this.#heading ??= this.querySelector('h3') ?? this.#append('h3');
+    this.#description ??= this.querySelector('p') ?? this.#append('p');
+    this.#link ??= this.querySelector('a') ?? this.#append('a');
+    this.#link.classList.add('btn');
+    this.#link.textContent = 'View Details';
+    this.#price ??= this.#append('p', 'price');
+    this.#featured ??= this.#append('p', 'featured-label');
+    this.#featured.textContent = 'Seasonal favorite';
+    this.#link.addEventListener('click', this.#onSelect);
+    this.#render();
+  }
+
+  disconnectedCallback() {
+    this.#link?.removeEventListener('click', this.#onSelect);
+  }
+
+  attributeChangedCallback(name, oldValue, newValue) {
+    if (oldValue !== newValue && this.isConnected) this.#render();
+  }
+
+  #setString(attribute, value) {
+    if (value == null) this.removeAttribute(attribute);
+    else this.setAttribute(attribute, String(value));
+  }
+
+  #append(tag, className) {
+    const node = this.ownerDocument.createElement(tag);
+    if (className) node.className = className;
+    this.append(node);
+    return node;
+  }
+
+  #render() {
+    if (!this.#heading) return;
+    // Update existing nodes: changing attributes must not discard link focus.
+    this.#heading.textContent = this.name;
+    this.#description.textContent = this.description;
+    // Only allow web URLs; consumer-provided strings never become HTML/script.
+    let safeHref = null;
+    try {
+      const url = new URL(this.href, this.baseURI);
+      if (this.href && ['http:', 'https:'].includes(url.protocol)) safeHref = this.href;
+    } catch { /* Invalid URLs leave the details link inactive. */ }
+    if (safeHref) this.#link.setAttribute('href', safeHref);
+    else this.#link.removeAttribute('href');
+    this.#link.setAttribute('aria-disabled', String(!safeHref));
+    const price = this.price;
+    this.#price.hidden = price === null;
+    this.#price.textContent = price === null ? '' : new Intl.NumberFormat('en-US', {
+      style: 'currency', currency: 'USD',
+    }).format(price);
+    this.#featured.hidden = !this.featured;
+  }
+
+  #onSelect = (event) => {
+    if (!this.#link.hasAttribute('href')) return;
+    const accepted = this.dispatchEvent(new CustomEvent('coffee-card-select', {
+      bubbles: true,
+      composed: true,
+      cancelable: true,
+      detail: { name: this.name, href: this.href, price: this.price, featured: this.featured },
+    }));
+    if (!accepted) event.preventDefault();
+  };
+}
+
+if (!customElements.get('coffee-card')) {
+  customElements.define('coffee-card', CoffeeCard);
+}
