+import assert from 'node:assert/strict';
+import { readFile } from 'node:fs/promises';
+import { after, afterEach, test } from 'node:test';
+import { JSDOM } from 'jsdom';
+
+const dom = new JSDOM('<!doctype html><body></body>', { url: 'https://daily-grind.example/' });
+const { window } = dom;
+globalThis.HTMLElement = window.HTMLElement;
+globalThis.customElements = window.customElements;
+const { document } = window;
+
+// Simulate properties set by a consumer before the component module loads.
+const pending = document.createElement('coffee-card');
+Object.assign(pending, { name: 'Early latte', description: 'Oat milk', href: '/early', price: 4.5, featured: true, disabled: true });
+document.body.append(pending);
+const { CoffeeCard } = await import('./coffee-card.js');
+
+afterEach(() => document.body.replaceChildren());
+after(() => {
+  dom.window.close();
+  delete globalThis.HTMLElement;
+  delete globalThis.customElements;
+});
+
+function card() {
+  const element = document.createElement('coffee-card');
+  document.body.append(element);
+  return element;
+}
+
+test('upgrades elements and reflects properties assigned before registration', () => {
+  assert.ok(pending instanceof CoffeeCard);
+  assert.equal(pending.getAttribute('name'), 'Early latte');
+  assert.equal(pending.getAttribute('description'), 'Oat milk');
+  assert.equal(pending.getAttribute('href'), '/early');
+  assert.equal(pending.getAttribute('price'), '4.5');
+  assert.equal(pending.price, 4.5);
+  assert.equal(pending.featured, true);
+  assert.equal(pending.disabled, true);
+  assert.equal(pending.shadowRoot.querySelector('h3').textContent, 'Early latte');
+});
+
+test('reflects strings in both directions, handles removal and renders text safely', () => {
+  const element = card();
+  for (const property of ['name', 'description', 'href']) {
+    element[property] = 'Coffee';
+    assert.equal(element.getAttribute(property), 'Coffee');
+    element.setAttribute(property, 'Changed');
+    assert.equal(element[property], 'Changed');
+    element[property] = null;
+    assert.equal(element.hasAttribute(property), false);
+    assert.equal(element[property], '');
+  }
+  element.name = '<img src=x onerror=alert(1)>';
+  element.description = '<script>unsafe</script>';
+  assert.equal(element.shadowRoot.querySelector('h3').textContent, element.name);
+  assert.equal(element.shadowRoot.querySelector('.description').textContent, element.description);
+  assert.equal(element.shadowRoot.querySelector('img, script'), null);
+});
+
+test('reflects numeric prices, including zero, updates the view and removes optional prices', () => {
+  const element = card();
+  const price = element.shadowRoot.querySelector('.price');
+  assert.equal(element.price, null);
+  assert.equal(price.hidden, true);
+  element.price = 4.5;
+  assert.equal(element.getAttribute('price'), '4.5');
+  assert.equal(price.textContent, '$4.50');
+  assert.equal(price.hidden, false);
+  element.setAttribute('price', '0');
+  assert.equal(element.price, 0);
+  assert.equal(price.textContent, '$0.00');
+  element.price = null;
+  assert.equal(element.hasAttribute('price'), false);
+  assert.equal(price.hidden, true);
+});
+
+test('invalid numeric attributes hide the price and invalid property assignments reject changes', () => {
+  const element = card();
+  for (const value of ['', ' ', 'NaN', 'Infinity', '-1', 'coffee']) {
+    element.setAttribute('price', value);
+    assert.equal(element.price, null);
+    assert.equal(element.shadowRoot.querySelector('.price').hidden, true);
+  }
+  element.price = 3;
+  for (const value of ['', ' ', NaN, Infinity, -1, 'coffee']) {
+    assert.throws(() => { element.price = value; }, RangeError);
+    assert.equal(element.price, 3);
+  }
+});
+
+test('boolean properties reflect presence, including HTML boolean semantics for false text', () => {
+  const element = card();
+  for (const property of ['featured', 'disabled']) {
+    assert.equal(element[property], false);
+    element[property] = true;
+    assert.equal(element.getAttribute(property), '');
+    element[property] = false;
+    assert.equal(element.hasAttribute(property), false);
+    element.setAttribute(property, 'false');
+    assert.equal(element[property], true);
+    element.removeAttribute(property);
+    assert.equal(element[property], false);
+  }
+});
+
+test('updates navigation and accessibility when disabled, re-enabled or given unsafe URLs', () => {
+  const element = card();
+  const link = element.shadowRoot.querySelector('a');
+  element.name = 'Cold Brew';
+  element.href = '/menu/cold-brew';
+  assert.equal(link.getAttribute('href'), element.href);
+  assert.equal(link.getAttribute('aria-label'), 'View details for Cold Brew');
+  element.disabled = true;
+  assert.equal(link.hasAttribute('href'), false);
+  assert.equal(link.getAttribute('aria-disabled'), 'true');
+  assert.equal(link.getAttribute('tabindex'), '-1');
+  element.disabled = false;
+  assert.equal(link.getAttribute('href'), element.href);
+  assert.equal(link.getAttribute('aria-disabled'), 'false');
+  assert.equal(link.hasAttribute('tabindex'), false);
+  for (const href of ['javascript:alert(1)', 'data:text/html,unsafe', 'http://[', '']) {
+    element.href = href;
+    assert.equal(link.hasAttribute('href'), false);
+  }
+});
+
+test('cleans up listeners on disconnect and restores them on reconnect without replacing DOM', () => {
+  const element = card();
+  element.disabled = true;
+  const link = element.shadowRoot.querySelector('a');
+  const click = () => link.dispatchEvent(new window.MouseEvent('click', { cancelable: true }));
+  assert.equal(click(), false);
+  element.remove();
+  assert.equal(click(), true);
+  element.name = 'Reconnected coffee';
+  document.body.append(element);
+  assert.equal(element.shadowRoot.querySelector('a'), link);
+  assert.equal(element.shadowRoot.querySelector('h3').textContent, 'Reconnected coffee');
+  assert.equal(click(), false);
+  element.remove();
+  assert.equal(click(), true);
+});
+
+test('page uses autonomous elements and retains all original coffee content and links', async () => {
+  const html = await readFile(new URL('./index.html', import.meta.url), 'utf8');
+  document.body.innerHTML = html;
+  const cards = [...document.querySelectorAll('coffee-card')];
+  assert.equal(cards.length, 3);
+  assert.deepEqual(cards.map(element => element.name), ['Maple Oat Latte', 'Dark Roast Espresso', 'Cold Brew']);
+  assert.deepEqual(cards.map(element => element.href), ['/menu/seasonal', '/menu/espresso', '/menu/cold-brew']);
+  for (const element of cards) {
+    assert.equal(element.shadowRoot.querySelector('.description').textContent, element.description);
+    assert.equal(element.shadowRoot.querySelector('a').getAttribute('href'), element.href);
+  }
+  assert.ok(document.querySelector('script[type="module"][src="./coffee-card.js"]'));
+  assert.equal(document.querySelectorAll('.card').length, 0);
+});
