@@ -0,0 +1,276 @@
+import { createSigner, fingerprint, signDocument, verifyDocument, MAX_DOCUMENT_LENGTH } from './signatures.mjs';
+
+const $ = id => document.getElementById(id);
+const coffees = {
+  maple: { name: 'Maple Oat Latte', cents: 550 },
+  espresso: { name: 'Dark Roast Espresso', cents: 350 },
+  coldbrew: { name: 'Cold Brew', cents: 450 },
+};
+const money = cents => new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(cents / 100);
+const suiteName = suite => suite === 'ML-DSA-65' ? 'ML-DSA-65 · quantum-resistant' : 'ECDSA P-256 / SHA-256 · classical';
+let signer = null;
+let signedDocument = null;
+let signing = false;
+let verifyRevision = 0;
+
+function status(id, message, state = '') {
+  $(id).textContent = message;
+  $(id).dataset.state = state;
+}
+
+// IndexedDB structured-clones CryptoKeys without exporting private key material.
+async function savedSigner() {
+  if (!globalThis.crypto?.subtle || !globalThis.isSecureContext) {
+    throw new Error('Signing requires HTTPS and a browser with Web Crypto support.');
+  }
+  if (!globalThis.indexedDB) throw new Error('Browser key storage is unavailable. Allow site storage to sign documents.');
+  const database = await new Promise((resolve, reject) => {
+    const request = indexedDB.open('daily-grind-signatures', 1);
+    request.onupgradeneeded = () => request.result.createObjectStore('keys');
+    request.onsuccess = () => resolve(request.result);
+    request.onerror = () => reject(new Error('Browser key storage is unavailable. Allow site storage to sign documents.'));
+    request.onblocked = () => reject(new Error('Key storage is busy. Close other Daily Grind tabs and reload.'));
+  });
+  const read = () => new Promise((resolve, reject) => {
+    const transaction = database.transaction('keys', 'readonly');
+    const request = transaction.objectStore('keys').get('issuer');
+    transaction.oncomplete = () => resolve(request.result);
+    transaction.onabort = () => reject(transaction.error);
+    transaction.onerror = () => reject(transaction.error);
+  });
+  try {
+    let stored = await read();
+    if (!stored) {
+      const generated = await createSigner();
+      // Recheck in a write transaction so simultaneous tabs keep the same key.
+      stored = await new Promise((resolve, reject) => {
+        const transaction = database.transaction('keys', 'readwrite');
+        const store = transaction.objectStore('keys');
+        const request = store.get('issuer');
+        let selected;
+        request.onsuccess = () => {
+          selected = request.result || generated;
+          if (!request.result) store.add(generated, 'issuer');
+        };
+        transaction.oncomplete = () => resolve(selected);
+        transaction.onabort = () => reject(transaction.error);
+        transaction.onerror = () => reject(transaction.error);
+      });
+    }
+    // Do not silently rotate a damaged key and lose the existing trust anchor.
+    if (!stored?.privateKey || stored.privateKey.extractable !== false || !stored.publicKey) {
+      throw new Error('The saved signing key cannot be read. Existing documents can still be checked, but this browser cannot sign.');
+    }
+    return stored;
+  } finally {
+    database.close();
+  }
+}
+
+function documentType() {
+  return document.querySelector('input[name="documentType"]:checked').value;
+}
+
+function currentDetails() {
+  if (documentType() === 'voucher') {
+    return {
+      description: 'Daily Grind gift voucher',
+      recipient: $('recipient').value.trim(),
+      quantity: 1,
+      amountCents: Math.round(Number($('gift-amount').value) * 100),
+    };
+  }
+  const coffee = coffees[$('coffee').value];
+  const quantity = Number($('quantity').value);
+  return { description: coffee.name, recipient: '', quantity, amountCents: coffee.cents * quantity };
+}
+
+function updatePreview() {
+  const voucher = documentType() === 'voucher';
+  $('receipt-fields').hidden = voucher;
+  $('voucher-fields').hidden = !voucher;
+  for (const id of ['coffee', 'quantity']) $(id).disabled = voucher;
+  for (const id of ['recipient', 'gift-amount']) {
+    $(id).disabled = !voucher;
+    $(id).required = voucher;
+  }
+  const details = currentDetails();
+  $('preview-type').textContent = voucher ? 'GIFT VOUCHER' : 'COFFEE RECEIPT';
+  $('preview-description').textContent = voucher
+    ? `A coffee moment for ${details.recipient || 'someone special'}`
+    : `${details.quantity || '—'} × ${details.description}`;
+  $('preview-amount').textContent = Number.isFinite(details.amountCents) ? money(details.amountCents) : '—';
+  // A prior signature applies only to the exact details that were signed.
+  signedDocument = null;
+  $('download-actions').hidden = true;
+  status('sign-status', '');
+}
+
+function download(filename, value) {
+  const url = URL.createObjectURL(new Blob([JSON.stringify(value, null, 2)], { type: 'application/json' }));
+  const anchor = document.createElement('a');
+  anchor.href = url;
+  anchor.download = filename;
+  document.body.append(anchor);
+  anchor.click();
+  anchor.remove();
+  // Keep the blob alive while the browser starts the download.
+  setTimeout(() => URL.revokeObjectURL(url), 30_000);
+}
+
+function clearVerification() {
+  verifyRevision += 1;
+  $('verification-result').hidden = true;
+  $('result-details').replaceChildren();
+  status('verify-status', '');
+}
+
+function showResult(result) {
+  const container = $('verification-result');
+  container.hidden = false;
+  container.dataset.state = result.trusted ? 'success' : 'warning';
+  $('result-heading').textContent = result.trusted ? '✓ Signature valid · recognized browser key' : '⚠ Signature valid · unrecognized signer';
+  const payload = result.payload;
+  const fields = [
+    ['Document', payload.type === 'voucher' ? 'Gift voucher (sample)' : 'Coffee receipt (sample)'],
+    ['Details', `${payload.quantity} × ${payload.description}`],
+    ...(payload.recipient ? [['For', payload.recipient]] : []),
+    ['Amount', money(payload.amountCents)],
+    ['Issued', new Date(payload.issuedAt).toLocaleString()],
+    ['ID', payload.id],
+    ['Algorithm', suiteName(result.suite)],
+    ['Key SHA-256', result.fingerprint],
+  ];
+  for (const [label, value] of fields) {
+    const dt = document.createElement('dt');
+    const dd = document.createElement('dd');
+    dt.textContent = label;
+    dd.textContent = value;
+    $('result-details').append(dt, dd);
+  }
+}
+
+$('sign-form').addEventListener('input', updatePreview);
+$('sign-form').addEventListener('change', updatePreview);
+$('sign-form').addEventListener('submit', async event => {
+  event.preventDefault();
