+// Versioned, domain-separated documents. Private keys never enter an envelope.
+export const MAX_DOCUMENT_LENGTH = 100_000;
+const encoder = new TextEncoder();
+const suites = {
+  'ECDSA-P256-SHA256': {
+    key: { name: 'ECDSA', namedCurve: 'P-256' },
+    operation: { name: 'ECDSA', hash: 'SHA-256' },
+  },
+  'ML-DSA-65': { key: 'ML-DSA-65', operation: 'ML-DSA-65' },
+};
+
+function exactKeys(value, keys) {
+  return value && typeof value === 'object' && !Array.isArray(value)
+    && Object.keys(value).sort().join('|') === [...keys].sort().join('|');
+}
+
+export function canonical(value) {
+  if (Array.isArray(value)) return `[${value.map(canonical).join(',')}]`;
+  if (value && typeof value === 'object') {
+    return `{${Object.keys(value).sort().map(key => `${JSON.stringify(key)}:${canonical(value[key])}`).join(',')}}`;
+  }
+  return JSON.stringify(value);
+}
+
+function base64(bytes) {
+  return btoa(String.fromCharCode(...new Uint8Array(bytes)));
+}
+
+function unbase64(value, maxLength = 20_000) {
+  if (typeof value !== 'string' || !value.length || value.length > maxLength
+    || !/^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/.test(value)) {
+    throw new Error('Invalid document encoding. Use the original signed JSON file.');
+  }
+  const bytes = Uint8Array.from(atob(value), char => char.charCodeAt(0));
+  if (base64(bytes) !== value) throw new Error('Invalid document encoding.');
+  return bytes;
+}
+
+function validatePayload(payload) {
+  if (!exactKeys(payload, ['type', 'id', 'issuedAt', 'issuer', 'currency', 'amountCents', 'description', 'recipient', 'quantity'])
+    || !['receipt', 'voucher'].includes(payload.type)
+    || payload.issuer !== 'Daily Grind browser signer'
+    || payload.currency !== 'USD'
+    || typeof payload.id !== 'string' || !/^[0-9a-f-]{36}$/i.test(payload.id)
+    || typeof payload.issuedAt !== 'string' || !Number.isFinite(Date.parse(payload.issuedAt))
+    || new Date(payload.issuedAt).toISOString() !== payload.issuedAt
+    || !Number.isSafeInteger(payload.amountCents) || payload.amountCents < 1 || payload.amountCents > 100_000
+    || !Number.isSafeInteger(payload.quantity) || payload.quantity < 1 || payload.quantity > 20
+    || typeof payload.description !== 'string' || !payload.description.trim() || payload.description.length > 200
+    || typeof payload.recipient !== 'string' || payload.recipient.length > 100
+    || (payload.type === 'voucher' && (!payload.recipient.trim() || payload.quantity !== 1))) {
+    throw new Error('Invalid receipt or voucher details. Use a Daily Grind signed document.');
+  }
+}
+
+function signingInput(document) {
+  const { version, suite, publicKey, payload } = document;
+  const context = encoder.encode(`daily-grind:${payload.type}:v1`);
+  const data = encoder.encode(canonical({ version, suite, publicKey, payload }));
+  // Classical algorithms ignore a context option, so frame the domain explicitly.
+  const framed = new Uint8Array(1 + context.length + data.length);
+  framed[0] = context.length;
+  framed.set(context, 1);
+  framed.set(data, context.length + 1);
+  return framed;
+}
+
+export async function createSigner(options = {}) {
+  if (!globalThis.crypto?.subtle) throw new Error('Signing requires HTTPS and a browser with Web Crypto support.');
+  let suite = options.suite;
+  if (!suite) {
+    suite = globalThis.SubtleCrypto?.supports?.('sign', 'ML-DSA-65')
+      && globalThis.SubtleCrypto?.supports?.('verify', 'ML-DSA-65')
+      ? 'ML-DSA-65' : 'ECDSA-P256-SHA256';
+  }
+  if (!Object.hasOwn(suites, suite)) throw new Error('Unsupported signature algorithm.');
+  let keyPair;
+  try {
+    keyPair = await crypto.subtle.generateKey(suites[suite].key, false, ['sign', 'verify']);
+  } catch (error) {
+    if (!options.suite && suite === 'ML-DSA-65' && error.name === 'NotSupportedError') {
+      return createSigner({ suite: 'ECDSA-P256-SHA256' });
+    }
+    throw error;
+  }
+  const publicKey = base64(await crypto.subtle.exportKey('spki', keyPair.publicKey));
+  return { suite, publicKey, privateKey: keyPair.privateKey };
+}
+
+export async function fingerprint(publicKey) {
+  const digest = new Uint8Array(await crypto.subtle.digest('SHA-256', unbase64(publicKey)));
+  return [...digest].map(byte => byte.toString(16).padStart(2, '0')).join(':');
+}
+
+export async function signDocument(payload, signer) {
+  validatePayload(payload);
+  const document = { version: 1, suite: signer.suite, publicKey: signer.publicKey, payload: structuredClone(payload) };
+  const signature = await crypto.subtle.sign(suites[signer.suite].operation, signer.privateKey, signingInput(document));
+  return { ...document, signature: base64(signature) };
+}
+
+export async function verifyDocument(text, trustedPublicKey = null) {
+  if (!globalThis.crypto?.subtle) throw new Error('Verification requires HTTPS and a browser with Web Crypto support.');
+  if (typeof text !== 'string' || !text.trim()) throw new Error('Choose a signed JSON file or paste a signed document first.');
+  if (text.length > MAX_DOCUMENT_LENGTH) throw new Error('This file is too large. Choose a signed JSON file under 100 KB.');
+  let document;
+  try { document = JSON.parse(text); } catch { throw new Error('This is not valid JSON. Use the original signed document.'); }
+  if (!exactKeys(document, ['version', 'suite', 'publicKey', 'payload', 'signature'])
+    || document.version !== 1 || !Object.hasOwn(suites, document.suite)) {
+    throw new Error('Unsupported signed document format or algorithm.');
+  }
+  validatePayload(document.payload);
+  const spec = suites[document.suite];
+  const keyBytes = unbase64(document.publicKey);
+  const signatureBytes = unbase64(document.signature);
+  let publicKey;
+  try {
+    publicKey = await crypto.subtle.importKey('spki', keyBytes, spec.key, false, ['verify']);
+  } catch (error) {
+    if (error.name === 'NotSupportedError') throw new Error('This browser does not support this document’s signature algorithm. Try a compatible browser.');
+    throw new Error('The document contains an invalid public key.');
+  }
+  const valid = await crypto.subtle.verify(spec.operation, publicKey, signatureBytes, signingInput(document));
+  return {
+    valid,
+    trusted: valid && trustedPublicKey !== null && document.publicKey === trustedPublicKey,
+    payload: document.payload,
+    suite: document.suite,
+    fingerprint: await fingerprint(document.publicKey),
+  };
+}
