+import test from 'node:test';
+import assert from 'node:assert/strict';
+import { createSigner, signDocument, verifyDocument, fingerprint } from '../signatures.mjs';
+
+const signer = await createSigner({ suite: 'ECDSA-P256-SHA256' });
+const otherSigner = await createSigner({ suite: 'ECDSA-P256-SHA256' });
+const payload = {
+  type: 'receipt', id: crypto.randomUUID(), issuedAt: new Date().toISOString(),
+  issuer: 'Daily Grind browser signer', currency: 'USD', amountCents: 550,
+  description: 'Maple Oat Latte', recipient: '', quantity: 1,
+};
+const receipt = await signDocument(payload, signer);
+
+test('receipt and voucher round-trip with a non-exportable signing key', async () => {
+  assert.equal(signer.privateKey.extractable, false);
+  await assert.rejects(crypto.subtle.exportKey('pkcs8', signer.privateKey));
+  for (const p of [payload, { ...payload, type: 'voucher', description: 'Daily Grind gift voucher', recipient: 'Ada', amountCents: 2500 }]) {
+    const signed = await signDocument(p, signer);
+    const result = await verifyDocument(JSON.stringify(signed), signer.publicKey);
+    assert.equal(result.valid, true);
+    assert.equal(result.trusted, true);
+    assert.deepEqual(result.payload, p);
+    assert.match(result.fingerprint, /^(?:[a-f0-9]{2}:){31}[a-f0-9]{2}$/);
+  }
+});
+
+test('all signed fields and document purpose are protected against tampering', async () => {
+  const modifications = [
+    { amountCents: 50 }, { description: 'Free coffee for life' }, { recipient: 'Mallory' },
+    { quantity: 10 }, { id: crypto.randomUUID() }, { issuedAt: '2026-01-01T00:00:00.000Z' },
+    { type: 'voucher', recipient: 'Mallory' },
+  ];
+  for (const change of modifications) {
+    const tampered = { ...receipt, payload: { ...receipt.payload, ...change } };
+    assert.equal((await verifyDocument(JSON.stringify(tampered), signer.publicKey)).valid, false);
+  }
+});
+
+test('embedded public keys do not grant issuer trust', async () => {
+  const forged = await signDocument(payload, otherSigner);
+  const result = await verifyDocument(JSON.stringify(forged), signer.publicKey);
+  assert.equal(result.valid, true);
+  assert.equal(result.trusted, false);
+  assert.equal((await verifyDocument(JSON.stringify(receipt))).trusted, false);
+  const replaced = { ...receipt, publicKey: otherSigner.publicKey };
+  assert.equal((await verifyDocument(JSON.stringify(replaced), signer.publicKey)).valid, false);
+});
+
+test('changed signature fails, while JSON formatting and key ordering do not matter', async () => {
+  const bytes = Uint8Array.from(atob(receipt.signature), char => char.charCodeAt(0));
+  bytes[0] ^= 1;
+  const tampered = { ...receipt, signature: btoa(String.fromCharCode(...bytes)) };
+  assert.equal((await verifyDocument(JSON.stringify(tampered))).valid, false);
+  const reordered = Object.fromEntries(Object.entries(receipt).reverse());
+  reordered.payload = Object.fromEntries(Object.entries(receipt.payload).reverse());
+  assert.equal((await verifyDocument(JSON.stringify(reordered, null, 4), signer.publicKey)).trusted, true);
+});
+
+test('malformed, oversized, unsupported, and ambiguous documents fail closed', async () => {
+  const invalid = [
+    '', '{', 'x'.repeat(100_001), 'null', '[]',
+    JSON.stringify({ ...receipt, version: 2 }),
+    JSON.stringify({ ...receipt, suite: '__proto__' }),
+    JSON.stringify({ ...receipt, publicKey: 'invalid' }),
+    JSON.stringify({ ...receipt, signature: '???' }),
+    JSON.stringify({ ...receipt, extraUnsignedField: 'approved' }),
+    JSON.stringify({ ...receipt, payload: { ...payload, merchantApproved: true } }),
+    JSON.stringify({ ...receipt, payload: { ...payload, amountCents: 1.5 } }),
+    JSON.stringify({ ...receipt, payload: { ...payload, currency: 'EUR' } }),
+    JSON.stringify({ ...receipt, payload: { ...payload, issuer: 'Trusted merchant' } }),
+  ];
+  for (const text of invalid) await assert.rejects(verifyDocument(text, signer.publicKey));
+});
+
+test('signing snapshots the payload and rejects invalid values', async () => {
+  const mutable = { ...payload };
+  const signed = await signDocument(mutable, signer);
+  mutable.amountCents = 1;
+  assert.equal(signed.payload.amountCents, 550);
+  await assert.rejects(signDocument({ ...payload, type: 'voucher', recipient: '' }, signer));
+  await assert.rejects(signDocument({ ...payload, quantity: 0 }, signer));
+  assert.equal(await fingerprint(signer.publicKey), await fingerprint(signer.publicKey));
+});
+
+test('default browser algorithm selection produces verifiable signatures', async () => {
+  const automatic = await createSigner();
+  const signed = await signDocument(payload, automatic);
+  assert.equal((await verifyDocument(JSON.stringify(signed), automatic.publicKey)).trusted, true);
+});
+
+test('structured-cloned storage records preserve identity and private-key restrictions', async () => {
+  const restored = structuredClone(signer);
+  assert.equal(restored.privateKey.extractable, false);
+  assert.equal(restored.publicKey, signer.publicKey);
+  const signed = await signDocument(payload, restored);
+  assert.equal((await verifyDocument(JSON.stringify(signed), signer.publicKey)).trusted, true);
+  await assert.rejects(crypto.subtle.exportKey('pkcs8', restored.privateKey));
+});

