+  const raw = await crypto.subtle.exportKey('spki', publicKey);
+  return Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256', raw)), n => n.toString(16).padStart(2, '0')).join('');
+}
+export async function generateIdentity() {
+  const keys = await crypto.subtle.generateKey({ name: 'ECDSA', namedCurve: 'P-256' }, false, ['sign', 'verify']);
+  return { ...keys, id: await keyFingerprint(keys.publicKey) };
+}
+function exactKeys(value, keys) { return value && typeof value === 'object' && !Array.isArray(value) && Object.keys(value).sort().join(',') === keys.sort().join(','); }
+function text(value, max) { return typeof value === 'string' && value.trim().length > 0 && value.length <= max; }
