+  const common = ['type', 'id', 'issuedAt', 'customer', 'reference', 'currency', 'amountCents'];
+  if (!p || !['receipt', 'voucher'].includes(p.type)) throw new Error('Unsupported document type.');
+  const fields = p.type === 'receipt' ? ['coffee', 'quantity', 'unitPriceCents'] : ['sender', 'message'];
+  if (!exactKeys(p, [...common, ...fields]) || !text(p.id, 64) || !text(p.customer, 80) || !text(p.reference, 50) || !text(p.issuedAt, 30) || !Number.isFinite(Date.parse(p.issuedAt)) || p.currency !== 'USD' || !Number.isSafeInteger(p.amountCents) || p.amountCents <= 0) throw new Error('This document has invalid or missing details.');
+  if (p.type === 'receipt') {
