+    if (!Object.hasOwn(prices, p.coffee) || !Number.isInteger(p.quantity) || p.quantity < 1 || p.quantity > 99 || p.unitPriceCents !== prices[p.coffee] || p.amountCents !== p.unitPriceCents * p.quantity) throw new Error('Invalid order details.');
