+  const local = await savedIdentity();
+  if (local?.id === id) return local;
+  const db = await openDatabase();
+  return new Promise((resolve, reject) => {
+    const request = db.transaction('identity').objectStore('identity').get('trusted:' + id);
+    request.onsuccess = () => resolve(request.result);
+    request.onerror = () => reject(new Error('Could not read trusted verification keys.'));
+  });
+}
