+import { test } from 'node:test';
+import assert from 'node:assert/strict';
+import { generateIdentity, signDocument, verifyDocument, exportVerificationKey, parseVerificationKey } from '../signing.js';
+const identity = await generateIdentity();
+const receipt = { type: 'receipt', id: 'test-receipt', issuedAt: '2026-11-19T12:00:00.000Z', customer: 'Alex Morgan', reference: 'DG-1042', currency: 'USD', amountCents: 1100, coffee: 'Maple Oat Latte', quantity: 2, unitPriceCents: 550 };
+const voucher = { type: 'voucher', id: 'test-voucher', issuedAt: receipt.issuedAt, customer: 'Sam', reference: 'GIFT-1042', currency: 'USD', amountCents: 2500, sender: 'Alex', message: 'Enjoy your next coffee ☕' };
+for (const payload of [receipt, voucher]) {
+  test(`${payload.type} signs and verifies after JSON export`, async () => {
+    const doc = JSON.parse(JSON.stringify(await signDocument(payload, identity)));
+    assert.deepEqual(await verifyDocument(doc, identity), payload);
+  });
+}
+test('private key cannot be exported', async () => {
+  assert.equal(identity.privateKey.extractable, false);
+  await assert.rejects(crypto.subtle.exportKey('jwk', identity.privateKey));
+});
+test('each signed detail is protected', async () => {
+  const doc = await signDocument(voucher, identity);
+  for (const [field, value] of Object.entries({ customer: 'Someone else', reference: 'GIFT-9999', amountCents: 5000, sender: 'Mallory', message: 'Changed', issuedAt: '2026-11-20T12:00:00.000Z', id: 'another-id' })) {
+    const changed = structuredClone(doc); changed.payload[field] = value;
+    await assert.rejects(verifyDocument(changed, identity), /Signature invalid/);
+  }
+});
+test('an attacker’s valid signature is not trusted', async () => {
+  const other = await generateIdentity();
+  const doc = await signDocument(receipt, other);
+  await assert.rejects(verifyDocument(doc, identity), /Unknown signing key/);
+  await assert.rejects(verifyDocument(doc, null), /Unknown signing key/);
+  doc.keyId = identity.id;
+  await assert.rejects(verifyDocument(doc, identity), /Signature invalid/);
+});
+test('reordering JSON fields does not invalidate an intact document', async () => {
+  const doc = await signDocument(receipt, identity);
+  doc.payload = Object.fromEntries(Object.entries(doc.payload).reverse());
+  assert.deepEqual(await verifyDocument(doc, identity), receipt);
+});
+test('rejects malformed, unsigned, and unsupported documents', async () => {
+  const signed = await signDocument(receipt, identity);
+  for (const doc of [null, {}, receipt, { ...signed, algorithm: 'none' }, { ...signed, format: 'daily-grind/v2' }, { ...signed, signature: 'garbage' }, { ...signed, extra: 'unsigned' }, { ...signed, payload: { ...receipt, extra: true } }]) await assert.rejects(verifyDocument(doc, identity));
+});
+test('rejects invalid order totals before signing', async () => {
+  for (const changes of [{ amountCents: 1 }, { quantity: -1 }, { quantity: 1.2 }, { quantity: 100 }, { customer: '  ' }, { coffee: 'Unknown' }]) await assert.rejects(signDocument({ ...receipt, ...changes }, identity));
+});
+test('a corrupted signature is rejected', async () => {
+  const doc = await signDocument(receipt, identity);
+  doc.signature = (doc.signature[0] === 'A' ? 'B' : 'A') + doc.signature.slice(1);
+  await assert.rejects(verifyDocument(doc, identity), /Signature invalid/);
+});
+
+test('shared public key verifies without the private key', async () => {
+  const bundle = await exportVerificationKey(identity);
+  const imported = await parseVerificationKey(JSON.parse(JSON.stringify(bundle)));
+  assert.equal(imported.privateKey, undefined);
+  assert.equal(imported.id, identity.id);
+  const doc = await signDocument(voucher, identity);
+  assert.deepEqual(await verifyDocument(doc, imported), voucher);
+});
+test('rejects a public key with a substituted fingerprint or unsupported format', async () => {
+  const bundle = await exportVerificationKey(identity);
+  await assert.rejects(parseVerificationKey({ ...bundle, keyId: '0'.repeat(64) }), /fingerprint/);
+  await assert.rejects(parseVerificationKey({ ...bundle, publicKey: 'invalid' }), /invalid/);
+  await assert.rejects(parseVerificationKey({ ...bundle, format: 'unknown' }));
+});
+test('key pairs survive structured cloning without exposing the private key', async () => {
+  const cloned = structuredClone(identity);
+  assert.equal(cloned.privateKey.extractable, false);
+  const doc = await signDocument(receipt, cloned);
+  assert.deepEqual(await verifyDocument(doc, identity), receipt);
+});

