+            {articles.map((article, index) => (
+                <button type="button" class="story-marker" data-marker aria-label={`Go to story ${index + 1}: ${article.data.title}`} aria-current={index === 0 ? 'true' : undefined}>
+                    <span class="block w-2 h-2 rounded-full bg-current"></span>
+                </button>
