+        .story-track { scroll-behavior: smooth; }
+    }
+</style>
+
+<script>
+    document.querySelectorAll<HTMLElement>('[data-top-stories]').forEach((carousel) => {
+        const track = carousel.querySelector<HTMLElement>('[data-track]')!;
+        const slides = Array.from(track.children) as HTMLElement[];
+        const previous = carousel.querySelector<HTMLButtonElement>('[data-previous]')!;
+        const next = carousel.querySelector<HTMLButtonElement>('[data-next]')!;
+        const markers = Array.from(carousel.querySelectorAll<HTMLButtonElement>('[data-marker]'));
+        const counter = carousel.querySelector<HTMLElement>('[data-counter]')!;
+        const status = carousel.querySelector<HTMLElement>('[data-status]')!;
+        if (slides.length < 2) return;
+
+        carousel.querySelector<HTMLElement>('[data-controls]')!.hidden = false;
+        carousel.querySelector<HTMLElement>('[data-markers]')!.hidden = false;
+        let pending: number | null = null;
+        let settled = 0;
+        let frame = 0;
+        let timer: ReturnType<typeof setTimeout>;
+
+        const nearest = () => {
+            const left = track.getBoundingClientRect().left;
+            return slides.reduce((best, slide, index) =>
+                Math.abs(slide.getBoundingClientRect().left - left) < Math.abs(slides[best].getBoundingClientRect().left - left) ? index : best, 0);
+        };
+
+        const sync = (index: number) => {
+            previous.setAttribute('aria-disabled', String(index === 0));
+            next.setAttribute('aria-disabled', String(index === slides.length - 1));
+            counter.textContent = `${index + 1} / ${slides.length}`;
+            markers.forEach((marker, i) => {
+                if (i === index) marker.setAttribute('aria-current', 'true');
+                else marker.removeAttribute('aria-current');
+            });
+        };
+
+        const settle = () => {
+            const index = nearest();
+            // Ignore a completion event from a scroll superseded by a rapid click.
+            if (pending !== null && index !== pending) return;
+            pending = null;
+            sync(index);
+            if (index !== settled) {
+                status.textContent = `Story ${index + 1} of ${slides.length}: ${slides[index].querySelector('h3')!.textContent}`;
+                settled = index;
+            }
+        };
+
+        const goTo = (index: number) => {
+            if (index < 0 || index >= slides.length) return;
+            pending = index;
+            sync(index);
+            // Only scroll the track; scrolling the page would move the controls.
+            const distance = slides[index].getBoundingClientRect().left - track.getBoundingClientRect().left;
+            track.scrollBy({ left: distance });
+            if (Math.abs(distance) < 1) settle();
+        };
+
+        previous.addEventListener('click', () => goTo((pending ?? nearest()) - 1));
+        next.addEventListener('click', () => goTo((pending ?? nearest()) + 1));
+        markers.forEach((marker, index) => marker.addEventListener('click', () => goTo(index)));
+        // Direct interaction takes precedence over any pending button navigation.
+        track.addEventListener('pointerdown', () => { pending = null; });
+        track.addEventListener('wheel', () => { pending = null; }, { passive: true });
+        track.addEventListener('keydown', () => { pending = null; });
+
+        const hasScrollEnd = 'onscrollend' in track;
+        if (hasScrollEnd) track.addEventListener('scrollend', settle);
+        track.addEventListener('scroll', () => {
+            if (pending === null && !frame) {
+                frame = requestAnimationFrame(() => { sync(nearest()); frame = 0; });
+            }
+            if (!hasScrollEnd) {
+                clearTimeout(timer);
+                timer = setTimeout(settle, 150);
+            }
+        }, { passive: true });
+        sync(0);
+    });
+</script>
