+                        data-slide
+                        role="group"
+                        aria-roledescription="slide"
+                        aria-label={`${index + 1} of ${articles.length}`}
+                        aria-hidden={index !== 0}
+                        inert={index !== 0}
+                    >
+                        <a href={`${import.meta.env.BASE_URL}articles/${article.id}`} class="inline-block font-bold text-gray-900 hover:text-amber-400 focus-visible:outline-2 focus-visible:outline-amber-600 focus-visible:outline-offset-2">
+                            <h3>{article.data.title}</h3>
+                        </a>
+                        <time datetime={article.data.date.toISOString()} class="block text-xs text-gray-500 mt-1">{article.data.date.toLocaleDateString()}</time>
+                    </article>
+                ))}
+            </div>
+            <p data-status class="sr-only" aria-live="polite" aria-atomic="true"></p>
+        </section>
+    </top-stories-carousel>
+)}
+
+<style>
+    .story-slide {
+        grid-area: 1 / 1;
+        min-width: 0;
+        visibility: hidden;
+        padding: 0.25rem;
+    }
+
+    .story-slide.is-active {
+        visibility: visible;
+    }
+
+    .carousel-button {
+        cursor: pointer;
+        border: 1px solid var(--color-gray-300);
+        padding: 0.375rem 0.75rem;
+        font-size: 0.75rem;
+        font-weight: 600;
+        color: var(--color-gray-900);
+        transition: background-color 150ms;
+    }
+
+    .carousel-button:hover { background-color: var(--color-amber-100); }
+    .carousel-button:focus-visible { outline: 2px solid var(--color-amber-600); outline-offset: 2px; }
+    .carousel-button:disabled { cursor: default; opacity: 0.5; }
+</style>
