+    class TopStoriesCarousel extends HTMLElement {
+        connectedCallback() {
+            // Astro's client router can reconnect an existing element.
+            if (this.dataset.initialized) return;
+            this.dataset.initialized = 'true';
+
+            const slides = Array.from(this.querySelectorAll<HTMLElement>('[data-slide]'));
+            const previous = this.querySelector<HTMLButtonElement>('[data-previous]')!;
+            const next = this.querySelector<HTMLButtonElement>('[data-next]')!;
+            const counter = this.querySelector<HTMLElement>('[data-counter]')!;
+            const status = this.querySelector<HTMLElement>('[data-status]')!;
+            let current = 0;
+            let moving = false;
+
+            if (slides.length < 2) return;
+            this.querySelector<HTMLElement>('[data-controls]')!.hidden = false;
+
+            const move = async (direction: number) => {
+                if (moving) return;
+                moving = true;
+                previous.disabled = next.disabled = true;
+
+                const outgoing = slides[current];
+                current = (current + direction + slides.length) % slides.length;
+                const incoming = slides[current];
+                outgoing.inert = true;
+                outgoing.setAttribute('aria-hidden', 'true');
+                incoming.classList.add('is-active');
+
+                if (!window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
+                    const options = { duration: 300, easing: 'ease-in-out' };
+                    await Promise.allSettled([
+                        outgoing.animate([
+                            { transform: 'translateX(0)' },
+                            { transform: `translateX(${-direction * 100}%)` },
+                        ], options).finished,
+                        incoming.animate([
+                            { transform: `translateX(${direction * 100}%)` },
+                            { transform: 'translateX(0)' },
+                        ], options).finished,
+                    ]);
+                }
+
+                outgoing.classList.remove('is-active');
+                incoming.inert = false;
+                incoming.setAttribute('aria-hidden', 'false');
