+                status.textContent = `Story ${current + 1} of ${slides.length}: ${incoming.querySelector('h3')!.textContent}`;
+                previous.disabled = next.disabled = false;
+                moving = false;
+            };
+
+            previous.addEventListener('click', () => void move(-1));
+            next.addEventListener('click', () => void move(1));
+        }
+    }
+
+    if (!customElements.get('top-stories-carousel')) {
+        customElements.define('top-stories-carousel', TopStoriesCarousel);
+    }
+</script>
