+  <script>
+    (() => {
+      const panel = document.querySelector('[data-draggable]');
+      const handle = panel.querySelector('[data-drag-handle]');
+      const body = panel.querySelector('.order-body');
+      const toggle = panel.querySelector('.order-toggle');
+      const status = document.querySelector('#order-move-status');
+      panel.classList.add('enhanced');
+      panel.querySelector('.order-position').style.display = 'block';
+
+      function moveTo(left, top) {
+        const maxLeft = Math.max(0, window.innerWidth - panel.offsetWidth - 12);
+        const maxTop = Math.max(0, window.innerHeight - panel.offsetHeight - 12);
+        panel.style.left = `${Math.max(Math.min(12, maxLeft), Math.min(left, maxLeft))}px`;
+        panel.style.top = `${Math.max(Math.min(12, maxTop), Math.min(top, maxTop))}px`;
+        panel.style.right = 'auto';
+        panel.style.bottom = 'auto';
+      }
+
+      function reclamp() {
+        const rect = panel.getBoundingClientRect();
+        moveTo(rect.left, rect.top);
+      }
+
+      let offsetX = 0;
+      let offsetY = 0;
+      let moved = false;
+      handle.addEventListener('pointerdown', (event) => {
+        if (event.button !== 0 || !event.isPrimary) return;
+        const rect = panel.getBoundingClientRect();
+        offsetX = event.clientX - rect.left;
+        offsetY = event.clientY - rect.top;
+        moved = false;
+        handle.setPointerCapture(event.pointerId);
+      });
+      handle.addEventListener('pointermove', (event) => {
+        if (!handle.hasPointerCapture(event.pointerId)) return;
+        handle.classList.add('dragging');
+        moved = true;
+        moveTo(event.clientX - offsetX, event.clientY - offsetY);
+      });
+      function release(event) {
+        if (handle.hasPointerCapture(event.pointerId)) handle.releasePointerCapture(event.pointerId);
+      }
+      handle.addEventListener('pointerup', release);
+      handle.addEventListener('pointercancel', release);
+      handle.addEventListener('lostpointercapture', () => {
+        handle.classList.remove('dragging');
+        if (moved) status.textContent = 'Quick order panel moved.';
+      });
+      handle.addEventListener('keydown', (event) => {
+        const directions = { ArrowLeft: [-15, 0, 'left'], ArrowRight: [15, 0, 'right'], ArrowUp: [0, -15, 'up'], ArrowDown: [0, 15, 'down'] };
+        const direction = directions[event.key];
+        if (!direction) return;
+        event.preventDefault();
+        const rect = panel.getBoundingClientRect();
+        moveTo(rect.left + direction[0], rect.top + direction[1]);
+        status.textContent = `Quick order panel moved ${direction[2]}.`;
+      });
+      panel.querySelectorAll('[data-dock]').forEach((button) => {
+        button.addEventListener('click', () => {
+          moveTo(button.dataset.dock === 'left' ? 12 : window.innerWidth - panel.offsetWidth - 12, window.innerHeight - panel.offsetHeight - 12);
+          status.textContent = `Quick order panel docked ${button.dataset.dock}.`;
+        });
+      });
+      toggle.addEventListener('click', () => {
+        body.hidden = !body.hidden;
+        toggle.setAttribute('aria-expanded', String(!body.hidden));
+        toggle.setAttribute('aria-label', body.hidden ? 'Expand quick order' : 'Minimize quick order');
+        toggle.textContent = body.hidden ? '+' : '−';
+        reclamp();
+      });
+      window.addEventListener('resize', reclamp);
+      new ResizeObserver(reclamp).observe(panel);
+
+      const form = document.querySelector('#quick-order-form');
+      const drink = document.querySelector('#order-drink');
+      const size = document.querySelector('#order-size');
+      const quantity = document.querySelector('#order-quantity');
+      const minus = document.querySelector('#quantity-minus');
+      const plus = document.querySelector('#quantity-plus');
+      const prices = { 'maple-oat-latte': 550, espresso: 300, 'cold-brew': 450 };
+      const currency = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' });
+      function updateTotal() {
+        const count = quantity.valueAsNumber;
+        const valid = quantity.validity.valid && Number.isInteger(count);
+        document.querySelector('#order-total').textContent = valid
+          ? currency.format((prices[drink.value] + (size.value === 'large' ? 100 : 0)) * count / 100)
+          : '—';
+        minus.disabled = !valid || count <= 1;
+        plus.disabled = !valid || count >= 10;
+      }
+      minus.addEventListener('click', () => { quantity.stepDown(); updateTotal(); });
+      plus.addEventListener('click', () => { quantity.stepUp(); updateTotal(); });
+      form.addEventListener('input', updateTotal);
+      updateTotal();
+    })();
+  </script>
 </body>

 </html>

