+          ? `${count} drink${count === 1 ? '' : 's'} found.`
+          : 'No drinks match your search.';
+      });
+    }
+    if (id === 'account') {
+      view.querySelector('form').addEventListener('submit', (event) => {
+        event.preventDefault();
+        view.querySelector('#account-status').textContent = 'Preferences saved for this visit.';
+      });
+    }
