@@ -0,0 +1,92 @@
+const { test } = require('node:test');
+const assert = require('node:assert/strict');
+const { readFileSync } = require('node:fs');
+const { runInNewContext } = require('node:vm');
+
+// A minimal DOM fixture exercises route lifecycle without a browser or server.
+function setup(hash = '') {
+  function element() {
+    const children = new Map();
+    return {
+      dataset: {}, hidden: false, attributes: {}, listeners: {},
+      setAttribute(key, value) { this.attributes[key] = value; },
+      removeAttribute(key) { delete this.attributes[key]; },
+      addEventListener(event, callback) { this.listeners[event] = callback; },
+      focus() { this.focused = true; },
+      querySelector(selector) {
+        if (!children.has(selector)) children.set(selector, element());
+        return children.get(selector);
+      },
+      querySelectorAll() { return []; }
+    };
+  }
+  const home = element();
+  const mounted = [home];
+  const host = { querySelector: () => home, append: node => mounted.push(node) };
+  const links = ['menu', 'locations', 'rewards', 'account'].map(name => {
+    const link = element();
+    link.dataset.viewLink = name;
+    return link;
+  });
+  const window = {
+    scrollY: 0, listeners: {},
+    addEventListener(event, callback) { this.listeners[event] = callback; },
+    scrollTo({ top }) { this.scrollY = top; }
+  };
+  const context = {
+    document: {
+      getElementById: () => host,
+      querySelectorAll: () => links,
+      createElement: element
+    },
+    window, location: { hash }, history: { scrollRestoration: 'auto' }
+  };
+  runInNewContext(readFileSync(`${__dirname}/app.js`, 'utf8'), context);
+  return {
+    ...context, mounted, links,
+    go(hash) {
+      context.location.hash = hash;
+      window.listeners.hashchange();
+    }
+  };
+}
+
+test('visited views reuse their DOM, inputs, details, listeners, and scroll', () => {
+  const app = setup();
+  app.window.scrollY = 125;
+  app.go('#/account');
+  const account = app.mounted[1];
+  account.querySelector('input').value = 'Alex';
+  const submit = account.querySelector('form').listeners.submit;
+  app.window.scrollY = 260;
+  app.go('#/menu');
+  assert.equal(account.hidden, true);
+  const menu = app.mounted[2];
+  menu.querySelector('details').open = true;
+  app.go('#/account');
+  assert.equal(app.mounted.length, 3);
+  assert.equal(account.hidden, false);
+  assert.equal(menu.hidden, true);
+  assert.equal(account.querySelector('input').value, 'Alex');
+  assert.equal(account.querySelector('form').listeners.submit, submit);
+  assert.equal(app.window.scrollY, 260);
+  assert.equal(app.links[3].attributes['aria-current'], 'page');
+  app.go('#/menu');
+  assert.equal(menu.querySelector('details').open, true);
+  app.go('#/');
+  assert.equal(app.window.scrollY, 125);
+  assert.equal(app.mounted.filter(node => !node.hidden).length, 1);
+});
+
+test('deep links initialize directly, repeated routes do not mount again', () => {
+  for (const name of ['menu', 'locations', 'rewards', 'account']) {
+    const app = setup(`#/${name}`);
+    assert.equal(app.mounted[0].hidden, true);
+    assert.equal(app.mounted[1].dataset.view, name);
+    app.go(`#/${name}`);
+    assert.equal(app.mounted.length, 2);
+    app.go('#/unknown');
+    assert.equal(app.mounted[0].hidden, false);
+    assert.equal(app.mounted[1].hidden, true);
+  }
+});
