index 0000000..d10473a
--- /dev/null
+++ b/src/scripts/section-views.ts
@@ -0,0 +1,131 @@
+import { swapFunctions } from 'astro:transitions/client';
+
+// Keep only section listings, never article, account, or arbitrary detail pages.
+// Map insertion order provides an LRU bound even when categories/queries grow.
+const MAX_VIEWS = 8;
+const hostSelector = 'main[data-section-views]';
+const viewSelector = '[data-section-view]';
+interface CachedView {
+  element: HTMLElement;
+  shell: Document;
+  scroll: [number, number];
+}
+const views = new Map<string, CachedView>();
+let host: HTMLElement | null = null;
+let activeKey = '';
+let pendingFocus: HTMLElement | null = null;
+let pendingScroll: [number, number] | null = null;
+const keyFor = (url: URL) => url.pathname.replace(/\/$/, '') + url.search;
+
+// Cache head metadata, not a second copy of the view's DOM or its islands.
+function shellFor(doc: Document): Document {
+  const shell = document.implementation.createHTMLDocument();
+  for (const { name, value } of doc.documentElement.attributes) {
+    shell.documentElement.setAttribute(name, value);
+  }
+  shell.head.replaceWith(doc.head.cloneNode(true));
+  const marker = doc.querySelector(hostSelector)?.cloneNode(false);
+  if (marker) shell.body.append(marker);
+  return shell;
+}
+
+function initialize() {
+  const currentHost = document.querySelector<HTMLElement>(hostSelector);
+  if (currentHost === host) return;
+  views.clear();
+  host = currentHost;
+  activeKey = keyFor(new URL(location.href));
+  const element = host?.querySelector<HTMLElement>(viewSelector);
+  if (element) {
+    views.set(activeKey, { element, shell: shellFor(document), scroll: [0, 0] });
+  }
+}
+
+function updateNavigation() {
+  const path = location.pathname.replace(/\/$/, '');
+  document.querySelectorAll<HTMLAnchorElement>('[data-section-link]').forEach(link => {
+    if (new URL(link.href).pathname.replace(/\/$/, '') === path) {
+      link.setAttribute('aria-current', 'page');
+    } else {
+      link.removeAttribute('aria-current');
+    }
+  });
+}
+
+// Astro still owns links, history, cancellation, hashes, and network failures.
+// A repeat visit only prepares cached head metadata; it makes no page request.
+document.addEventListener('astro:before-preparation', event => {
+  initialize();
+  const cached = views.get(keyFor(event.to));
+  if (!host || !cached || event.formData) return;
+  event.loader = async () => {
+    event.newDocument = cached.shell.cloneNode(true) as Document;
+  };
+});
+
+document.addEventListener('astro:before-swap', event => {
+  initialize();
+  const incomingHost = event.newDocument.querySelector(hostSelector);
+  const key = keyFor(event.to);
+  const cached = views.get(key);
+  const incoming = event.newDocument.querySelector<HTMLElement>(`${hostSelector} > ${viewSelector}`);
+  if (!host || !incomingHost || (!cached && !incoming)) {
+    // Normal Astro navigation tears down the cache when leaving section views.
+    views.clear();
+    host = null;
+    return;
+  }
+  const sectionHost = host;
+  const shell = cached?.shell ?? shellFor(event.newDocument);
+  event.swap = () => {
+    const previous = views.get(activeKey);
+    if (previous) previous.scroll = [window.scrollX, window.scrollY];
+
+    // The existing body remains connected. Mark its scripts as executed before
+    // Astro's post-swap script runner hydrates any newly appended islands.
+    swapFunctions.deselectScripts(document);
+    document.querySelectorAll('script').forEach(script => { script.dataset.astroExec = ''; });
+    swapFunctions.deselectScripts(event.newDocument);
+    swapFunctions.swapRootAttributes(event.newDocument);
+    swapFunctions.swapHeadElements(event.newDocument);
+
+    const target = cached ?? { element: incoming!, shell, scroll: [0, 0] as [number, number] };
+    if (!cached) sectionHost.append(target.element);
+    for (const view of views.values()) {
+      if (view.element === target.element) continue;
+      view.element.classList.add('inactive');
+      view.element.inert = true;
+      view.element.setAttribute('aria-hidden', 'true');
+    }
+    target.element.classList.remove('inactive');
+    target.element.inert = false;
+    target.element.removeAttribute('aria-hidden');
+    target.element.setAttribute('aria-label', shell.title);
+    // Reinsert the entry at the end to record its most recent use.
+    views.delete(key);
+    views.set(key, target);
+    activeKey = key;
+    while (views.size > MAX_VIEWS) {
+      const oldest = views.keys().next().value!;
+      views.get(oldest)!.element.remove();
+      views.delete(oldest);
+    }
+    pendingFocus = target.element;
+    // Astro restores history-entry scroll for Back/Forward and handles hashes.
+    pendingScroll = cached && event.navigationType !== 'traverse' && !event.to.hash
+      ? target.scroll : null;
+  };
+});
+
+document.addEventListener('astro:after-swap', () => {
+  updateNavigation();
+  if (pendingScroll) window.scrollTo(...pendingScroll);
+  pendingFocus?.focus({ preventScroll: true });
+  pendingFocus = null;
+  pendingScroll = null;
+});
+document.addEventListener('astro:page-load', () => {
+  initialize();
+  updateNavigation();
+});
+initialize();
