new file mode 100644
index 0000000..713c5c4
--- /dev/null
+++ b/src/scripts/section-navigation.ts
@@ -0,0 +1,121 @@
+// Keep section nodes connected: disconnecting Astro islands would unmount their
+// React roots and lose the very state this cache is intended to preserve.
+export function setupSectionNavigation(baseUrl: string) {
+  const host = document.querySelector<HTMLElement>('[data-section-host]');
+  const initialView = host?.querySelector<HTMLElement>('[data-section-view]');
+
+  if (!host || !initialView) return;
+
+  type View = { element: HTMLElement; title: string; x: number; y: number };
+  const base = new URL(baseUrl, location.origin).pathname.replace(/\/$/, '');
+  const key = (url: URL) => url.pathname.replace(/\/$/, '') + url.search;
+  const isSection = (url: URL) => url.origin === location.origin && (
+    url.pathname.replace(/\/$/, '') === base ||
+    [`${base}/multimedia`, `${base}/reports`].includes(url.pathname.replace(/\/$/, '')) ||
+    url.pathname.startsWith(`${base}/category/`)
+  );
+  const views = new Map<string, View>();
+  const pending = new Map<string, Promise<View>>();
+  let active = key(new URL(location.href));
+  let navigation = 0;
+  views.set(active, { element: initialView, title: document.title, x: scrollX, y: scrollY });
+  history.scrollRestoration = 'manual';
+
+  function updateLinks() {
+    document.querySelectorAll<HTMLAnchorElement>('header a[href]').forEach(link => {
+      const url = new URL(link.href);
+      if (isSection(url) && key(url) === active) link.setAttribute('aria-current', 'page');
+      else link.removeAttribute('aria-current');
+    });
+  }
+
+  async function load(url: URL): Promise<View> {
+    const id = key(url);
+    const cached = views.get(id);
+    if (cached) return cached;
+    const inFlight = pending.get(id);
+    if (inFlight) return inFlight;
+    const request = (async () => {
+      const response = await fetch(url.href, { headers: { Accept: 'text/html' } });
+      if (!response.ok || !isSection(new URL(response.url)) || key(new URL(response.url)) !== id) throw new Error('Section unavailable');
+      const page = new DOMParser().parseFromString(await response.text(), 'text/html');
+      const element = page.querySelector<HTMLElement>('[data-section-host] > [data-section-view]');
+      if (!element) throw new Error('Not a section view');
+      // Append once and leave mounted until this document is unloaded.
+      element.hidden = true;
+      element.inert = true;
+      host!.append(element);
+      // DOMParser scripts are inert. Run the section's Astro island bootstrap
+      // scripts so lazily loaded bookmark buttons and ads can hydrate normally.
+      // Scripts inside templates remain inert until Astro consumes the template.
+      element.querySelectorAll('script').forEach(script => {
+        const executable = document.createElement('script');
+        for (const attr of script.attributes) executable.setAttribute(attr.name, attr.value);
+        executable.textContent = script.textContent;
+        script.replaceWith(executable);
+      });
+      const view = { element, title: page.title, x: 0, y: 0 };
+      views.set(id, view);
+      return view;
+    })();
+    pending.set(id, request);
+    try { return await request; }
+    finally { pending.delete(id); }
+  }
+
+  async function navigate(url: URL, push: boolean) {
+    const ticket = ++navigation;
+    const status = document.getElementById('section-status');
+    host!.setAttribute('aria-busy', 'true');
+    if (status) status.textContent = 'Loading section…';
+    try {
+      const view = await load(url);
+      if (ticket !== navigation) return;
+      const previous = views.get(active)!;
+      previous.x = scrollX;
+      previous.y = scrollY;
+      previous.element.hidden = true;
+      previous.element.inert = true;
+      view.element.hidden = false;
+      view.element.inert = false;
+      active = key(url);
+      document.title = view.title;
+      if (push) history.pushState(history.state, '', url.href);
+      updateLinks();
+      host!.focus({ preventScroll: true });
+      const target = url.hash ? document.getElementById(decodeURIComponent(url.hash.slice(1))) : null;
+      if (target && view.element.contains(target)) target.scrollIntoView();
+      else window.scrollTo({ left: view.x, top: view.y, behavior: 'instant' });
+      if (status) status.textContent = `${view.title} loaded`;
+    } catch {
+      // Preserve ordinary link behavior if a section cannot be loaded.
+      if (ticket === navigation) location.assign(url.href);
+    } finally {
+      if (ticket === navigation) host!.removeAttribute('aria-busy');
+    }
+  }
+
+  document.addEventListener('click', event => {
+    if (event.defaultPrevented || event.button !== 0 || event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return;
+    const link = event.target instanceof Element ? event.target.closest<HTMLAnchorElement>('a[href]') : null;
+    if (!link || link.hasAttribute('download') || (link.target && link.target !== '_self') || link.hasAttribute('data-astro-reload')) return;
+    const url = new URL(link.href);
+    if (!isSection(url) || (key(url) === active && url.hash)) return;
+    event.preventDefault();
+    if (key(url) === active) {
+      // Clicking the active section also cancels any slower pending navigation.
+      navigation++;
+      host!.removeAttribute('aria-busy');
+      const status = document.getElementById('section-status');
+      if (status) status.textContent = '';
+      return;
+    }
+    void navigate(url, true);
+  });
+  window.addEventListener('popstate', () => {
+    const url = new URL(location.href);
+    if (isSection(url)) void navigate(url, false);
+    else location.reload();
+  });
+  updateLinks();
+}
