new file mode 100644
index 0000000..d3f3f9e
--- /dev/null
+++ b/tests/section-navigation.test.mjs
@@ -0,0 +1,143 @@
+import { test } from 'node:test';
+import assert from 'node:assert/strict';
+import { Window } from 'happy-dom';
+import { setupSectionNavigation } from '../src/scripts/section-navigation.ts';
+
+function fixture(t, path = '') {
+  const window = new Window({ url: `https://example.com/devtools-times/${path}` });
+  window.document.write(`<title>Top News</title>
+    <header><a href="/devtools-times/">Top News</a>
+    <a href="/devtools-times/category/news">World</a>
+    <a href="/devtools-times/reports">Reports</a></header>
+    <main tabindex="-1" data-section-host><div data-section-view><input value="initial"><button>Control</button></div></main>
+    <p id="section-status" role="status"></p>`);
+  for (const name of ['document', 'location', 'history', 'DOMParser', 'Element']) {
+    globalThis[name] = window[name];
+  }
+  globalThis.window = window;
+  globalThis.scrollX = 0;
+  globalThis.scrollY = 0;
+  window.scrollTo = ({ left, top }) => { globalThis.scrollX = left; globalThis.scrollY = top; };
+  const requests = [];
+  globalThis.fetch = async url => {
+    requests.push(url);
+    return response(url);
+  };
+  t.after(() => window.happyDOM.abort());
+  setupSectionNavigation('/devtools-times/');
+  return { window, requests, click(href, options = {}) {
+    const link = window.document.createElement('a');
+    link.href = href;
+    window.document.body.append(link);
+    const event = new window.MouseEvent('click', { bubbles: true, cancelable: true, button: 0, ...options });
+    link.dispatchEvent(event);
+    return event;
+  } };
+}
+
+function response(url) {
+  return { ok: true, url, text: async () => `<title>${new URL(url).pathname}</title>
+    <main data-section-host><div data-section-view><input value="new"><button>Control</button></div></main>` };
+}
+const settle = () => new Promise(resolve => setImmediate(resolve));
+
+test('revisits reuse connected DOM, form values, listeners, and scroll without another fetch', async t => {
+  const { window, requests, click } = fixture(t);
+  const document = window.document;
+  const original = document.querySelector('[data-section-view]');
+  original.querySelector('input').value = 'unsaved edit';
+  let clicks = 0;
+  original.querySelector('button').addEventListener('click', () => clicks++);
+  globalThis.scrollY = 325;
+  click('/devtools-times/category/news');
+  await settle();
+  assert.equal(original.isConnected, true);
+  assert.equal(original.hidden, true);
+  assert.equal(original.inert, true);
+  const world = document.querySelector('[data-section-view]:not([hidden])');
+  world.querySelector('input').value = 'world edit';
+  globalThis.scrollY = 480;
+  click('/devtools-times/');
+  await settle();
+  assert.equal(document.querySelector('[data-section-view]:not([hidden])'), original);
+  assert.equal(original.querySelector('input').value, 'unsaved edit');
+  original.querySelector('button').click();
+  assert.equal(clicks, 1);
+  assert.equal(globalThis.scrollY, 325);
+  click('/devtools-times/category/news');
+  await settle();
+  assert.equal(document.querySelector('[data-section-view]:not([hidden])'), world);
+  assert.equal(world.querySelector('input').value, 'world edit');
+  assert.equal(globalThis.scrollY, 480);
+  assert.equal(requests.length, 1);
+  assert.equal(document.querySelector('header a[aria-current]').textContent, 'World');
+});
+
+test('Back and Forward select cached views and restore the title', async t => {
+  const { window, requests, click } = fixture(t);
+  click('/devtools-times/reports');
+  await settle();
+  window.history.replaceState(null, '', '/devtools-times/');
+  window.dispatchEvent(new window.PopStateEvent('popstate'));
+  await settle();
+  assert.equal(window.document.title, 'Top News');
+  window.history.replaceState(null, '', '/devtools-times/reports');
+  window.dispatchEvent(new window.PopStateEvent('popstate'));
+  await settle();
+  assert.equal(window.document.title, '/devtools-times/reports');
+  assert.equal(requests.length, 1);
+});
+
+test('modified clicks and article, account, external, and hash links retain native behavior', t => {
+  const { click, requests } = fixture(t);
+  for (const href of ['/devtools-times/articles/example', '/devtools-times/signin', 'https://elsewhere.com/', '#news']) {
+    assert.equal(click(href).defaultPrevented, false);
+  }
+  assert.equal(click('/devtools-times/reports', { ctrlKey: true }).defaultPrevented, false);
+  assert.equal(requests.length, 0);
+});
+
+test('a slower request cannot replace the most recently selected view', async t => {
+  const { window, click } = fixture(t);
+  let finish;
+  globalThis.fetch = url => url.endsWith('/reports')
+    ? new Promise(resolve => { finish = () => resolve(response(url)); })
+    : Promise.resolve(response(url));
+  click('/devtools-times/reports');
+  click('/devtools-times/category/news');
+  await settle();
+  finish();
+  await settle();
+  assert.equal(window.location.pathname, '/devtools-times/category/news');
+  assert.equal(window.document.querySelectorAll('[data-section-view]:not([hidden])').length, 1);
+  assert.equal(window.document.querySelector('[data-section-host]').hasAttribute('aria-busy'), false);
+});
+
+test('direct section entry can load Top News and return to its original DOM', async t => {
+  const { window, requests, click } = fixture(t, 'reports');
+  const initial = window.document.querySelector('[data-section-view]');
+  click('/devtools-times/');
+  await settle();
+  click('/devtools-times/reports');
+  await settle();
+  assert.equal(window.document.querySelector('[data-section-view]:not([hidden])'), initial);
+  assert.equal(requests.length, 1);
+});
+
+test('repeated clicks share a pending request and selecting the current view cancels navigation', async t => {
+  const { window, click } = fixture(t);
+  let finish;
+  let requests = 0;
+  globalThis.fetch = url => {
+    requests++;
+    return new Promise(resolve => { finish = () => resolve(response(url)); });
+  };
+  click('/devtools-times/reports');
+  click('/devtools-times/reports');
+  assert.equal(requests, 1);
+  click('/devtools-times/');
+  finish();
+  await settle();
+  assert.equal(window.location.pathname, '/devtools-times/');
+  assert.equal(window.document.querySelectorAll('[data-section-view]:not([hidden])').length, 1);
+});

