+  } catch {
+    status.textContent = 'Your browser couldn’t save the feedback. Please allow site storage and try again.';
+  }
+});
+
+form.addEventListener('reset', () => {
+  status.textContent = '';
+});
+
+form.addEventListener('input', () => {
+  status.textContent = '';
+});
