+const feedbackForm = document.querySelector('#coffee-feedback');
+const feedbackStatus = document.querySelector('#feedback-status');
+
+feedbackForm.addEventListener('submit', event => {
+  event.preventDefault();
+  // Submission reaches this handler only after native constraint validation.
+  // The custom element contributes its own entry to FormData.
+  const data = Object.fromEntries(new FormData(feedbackForm));
+  try {
+    localStorage.setItem('daily-grind-feedback', JSON.stringify({
+      ...data,
+      savedAt: new Date().toISOString()
