+/** A native form-associated rating control. No hidden input is needed. */
+class StarRating extends HTMLElement {
+  static formAssociated = true;
+  static observedAttributes = ['value', 'required', 'disabled', 'label'];
+
+  #internals;
+  #value = '';
+  #dirty = false;
+  #disabled = false;
+  #showError = false;
+  #buttons;
+  #group;
+  #hint;
+  #error;
+  #descriptions = ['Poor', 'Fair', 'Good', 'Great', 'Excellent'];
+
+  constructor() {
+    super();
+    this.#internals = this.attachInternals();
+    const root = this.attachShadow({ mode: 'open', delegatesFocus: true });
+    root.innerHTML = `
+      <style>
+        :host { display:block; font-family:inherit; }
+        .stars { display:flex; gap:7px; width:fit-content; }
+        button { display:grid; place-items:center; width:44px; height:44px; padding:5px; border:1px solid #e3dfd3; background:#faf8f1; border-radius:5px; cursor:pointer; color:#c7c1b3; transition:background .15s,color .15s; }
+        svg { width:29px; height:29px; fill:transparent; stroke:currentColor; stroke-width:1.3; }
+        button.filled { color:#ba522e; background:#fcf2e8; border-color:#e6c1a6; }
+        button.filled svg { fill:#ba522e; }
+        button:focus-visible { outline:2px solid #ba522e; outline-offset:3px; }
+        button:disabled { cursor:not-allowed; }
+        :host([data-disabled]) { opacity:.45; }
+        .hint { font-size:10px; color:#928b7d; margin:7px 0 0; min-height:16px; }
+        .error { color:#a33c27; font-size:11px; margin:5px 0 0; }
+        .error:empty { display:none; }
+        @media(prefers-reduced-motion:reduce) { button { transition:none; } }
+      </style>
+      <div class="stars" role="radiogroup" aria-describedby="hint error">
+        ${[1, 2, 3, 4, 5].map(number => `<button type="button" role="radio" aria-label="${number} ${number === 1 ? 'star' : 'stars'} — ${this.#descriptions[number - 1]}" aria-checked="false" data-value="${number}" tabindex="-1"><svg viewBox="0 0 32 32" aria-hidden="true"><path d="m16 3.5 3.8 7.7 8.5 1.2-6.2 6 1.5 8.5-7.6-4-7.6 4 1.5-8.5-6.2-6 8.5-1.2Z"/></svg></button>`).join('')}
+      </div>
+      <p class="hint" id="hint">Select a star, from 1 to 5.</p>
+      <p class="error" id="error" aria-live="polite"></p>`;
+    this.#buttons = [...root.querySelectorAll('button')];
+    this.#group = root.querySelector('.stars');
+    this.#hint = root.querySelector('.hint');
+    this.#error = root.querySelector('.error');
+    this.#buttons.forEach(button => {
+      button.addEventListener('click', () => this.#choose(button.dataset.value));
+      button.addEventListener('pointerenter', () => {
+        if (!this.#disabled) this.#paint(Number(button.dataset.value));
+      });
+    });
+    this.#group.addEventListener('pointerleave', () => this.#paint(Number(this.#value)));
+    this.#group.addEventListener('keydown', event => {
+      if (this.#disabled || event.altKey || event.ctrlKey || event.metaKey) return;
+      const current = Number(this.#value) || 1;
+      let next;
+      switch (event.key) {
+        case 'ArrowRight': case 'ArrowDown': next = current === 5 ? 1 : current + 1; break;
+        case 'ArrowLeft': case 'ArrowUp': next = current === 1 ? 5 : current - 1; break;
+        case 'Home': next = 1; break;
+        case 'End': next = 5; break;
+        default: return;
+      }
+      event.preventDefault();
+      this.#choose(String(next));
+      this.#buttons[next - 1].focus();
+    });
