+  }
+
+  #paint(value) {
+    this.#buttons.forEach((button, index) => button.classList.toggle('filled', index < value));
+    this.#hint.textContent = value ? `${value} of 5 — ${this.#descriptions[value - 1]}` : 'Select a star, from 1 to 5.';
+  }
