diff --git a/tests/star-rating.test.cjs b/tests/star-rating.test.cjs
new file mode 100644
index 0000000..ba50354
--- /dev/null
+++ b/tests/star-rating.test.cjs
@@ -0,0 +1,140 @@
+const { test } = require('node:test');
+const assert = require('node:assert/strict');
+const { readFileSync } = require('node:fs');
+const vm = require('node:vm');
+
+// A small platform double checks component logic, not browser implementation.
+function control(attributes = {}) {
+  let Rating;
+  class Node extends EventTarget {
+    constructor() {
+      super();
+      this.attributes = new Map();
+      this.dataset = {};
+      this.classes = new Set();
+      this.classList = { toggle: (name, active) => active ? this.classes.add(name) : this.classes.delete(name) };
+    }
+    getAttribute(name) { return this.attributes.get(name) ?? null; }
+    hasAttribute(name) { return this.attributes.has(name); }
+    setAttribute(name, value) {
+      const old = this.getAttribute(name);
+      this.attributes.set(name, String(value));
+      if (old !== String(value) && Rating?.observedAttributes.includes(name)) this.attributeChangedCallback?.(name, old, String(value));
+    }
+    toggleAttribute(name, force = !this.hasAttribute(name)) {
+      const old = this.getAttribute(name);
+      if (force) this.attributes.set(name, ''); else this.attributes.delete(name);
+      if (old !== this.getAttribute(name) && Rating?.observedAttributes.includes(name)) this.attributeChangedCallback?.(name, old, this.getAttribute(name));
+      return force;
+    }
+    focus() { this.focused = true; }
+    matches() { return this.hasAttribute('disabled') || Boolean(this.fieldsetDisabled); }
+    attachShadow() {
+      this.buttons = Array.from({ length: 5 }, (_, index) => {
+        const button = new Node();
+        button.dataset.value = String(index + 1);
+        return button;
+      });
+      this.nodes = Object.fromEntries(['.stars', '.hint', '.error'].map(key => [key, new Node()]));
+      return { set innerHTML(value) {}, querySelectorAll: () => this.buttons, querySelector: key => this.nodes[key] };
+    }
+    attachInternals() {
+      this.internals = {
+        setFormValue(value, state) { this.value = value; this.state = state; },
+        setValidity(flags, message, anchor) { this.validity = flags; this.validationMessage = message; this.anchor = anchor; },
+        checkValidity() { return !this.validity.valueMissing; },
+        reportValidity() { return this.checkValidity(); }
+      };
+      return this.internals;
+    }
+  }
+  vm.runInNewContext(readFileSync(require.resolve('../star-rating.js'), 'utf8'), {
+    HTMLElement: Node, Event,
+    customElements: { define: (name, component) => { assert.equal(name, 'star-rating'); Rating = component; } }
+  });
+  assert.equal(Rating.formAssociated, true);
+  const rating = new Rating();
+  for (const [name, value] of Object.entries(attributes)) rating.setAttribute(name, value);
+  rating.connectedCallback();
+  return rating;
+}
+
+test('required empty ratings expose valueMissing and a focusable validation anchor', () => {
+  const rating = control({ required: '' });
+  assert.equal(rating.internals.value, null);
+  assert.equal(rating.validity.valueMissing, true);
+  assert.equal(rating.checkValidity(), false);
+  assert.equal(rating.internals.anchor, rating.buttons[0]);
+  rating.dispatchEvent(new Event('invalid'));
+  assert.match(rating.nodes['.error'].textContent, /Please select/);
+  rating.value = 4;
+  assert.equal(rating.checkValidity(), true);
+  assert.equal(rating.internals.value, '4');
+  assert.equal(rating.internals.state, '4');
+  assert.equal(rating.nodes['.error'].textContent, '');
+});
+
+test('reset restores the current default without emitting user input', () => {
+  const rating = control({ value: '2', required: '' });
+  let events = 0;
+  rating.addEventListener('input', () => events++);
+  rating.value = 5;
+  rating.defaultValue = '3';
+  assert.equal(rating.value, '5');
+  rating.formResetCallback();
+  assert.equal(rating.value, '3');
+  assert.equal(rating.buttons[2].getAttribute('aria-checked'), 'true');
+  assert.equal(events, 0);
+  rating.defaultValue = '';
+  assert.equal(rating.value, '');
+  assert.equal(rating.validity.valueMissing, true);
+});
+
+test('disabled fieldset callback disables every button and preserves value', () => {
+  const rating = control({ value: '3' });
+  rating.formDisabledCallback(true);
+  assert.ok(rating.buttons.every(button => button.disabled && button.tabIndex === -1));
+  rating.buttons[4].dispatchEvent(new Event('click'));
+  assert.equal(rating.value, '3');
+  rating.formDisabledCallback(false);
+  assert.equal(rating.buttons[2].tabIndex, 0);
+  rating.buttons[4].dispatchEvent(new Event('click'));
+  assert.equal(rating.value, '5');
+  rating.disabled = true;
+  assert.ok(rating.buttons.every(button => button.disabled));
+});
+
+test('restoration updates submission, selection and keyboard tab stop', () => {
+  const rating = control({ required: '' });
+  rating.formStateRestoreCallback('4', 'restore');
+  assert.equal(rating.internals.value, '4');
+  assert.equal(rating.buttons[3].getAttribute('aria-checked'), 'true');
+  assert.equal(rating.buttons[3].tabIndex, 0);
+  assert.equal(rating.checkValidity(), true);
+  rating.formStateRestoreCallback('2', 'autocomplete');
+  assert.equal(rating.value, '2');
+  for (const invalid of ['0', '6', '1.5', 'bad', null]) {
+    rating.value = invalid;
+    assert.equal(rating.value, '');
+  }
+});
+
+test('keyboard selection wraps, supports Home/End and emits input and change', () => {
+  const rating = control({ value: '5' });
+  const events = [];
+  for (const type of ['input', 'change']) rating.addEventListener(type, () => events.push(type));
+  const press = key => {
+    const event = new Event('keydown', { cancelable: true });
+    Object.defineProperty(event, 'key', { value: key });
+    rating.nodes['.stars'].dispatchEvent(event);
+    assert.equal(event.defaultPrevented, true);
+  };
+  press('ArrowRight');
+  assert.equal(rating.value, '1');
+  assert.equal(rating.buttons[0].focused, true);
+  press('End');
+  assert.equal(rating.value, '5');
+  press('Home');
+  assert.equal(rating.value, '1');
+  assert.deepEqual(events, ['input', 'change', 'input', 'change', 'input', 'change']);
+});

