+    (() => {
+      const triggers = document.querySelectorAll('[data-drink-preview]');
+      let active = null;
+      let openTimer;
+      let closeTimer;
+
+      function positionPreview() {
+        if (!active) return;
+        const { trigger, panel } = active;
+        const anchor = trigger.getBoundingClientRect();
+        const gutter = 12;
+        const gap = 8;
+        const height = panel.offsetHeight;
+        const below = window.innerHeight - anchor.bottom - gutter - gap;
+        const above = anchor.top - gutter - gap;
+        const placeAbove = below < height && above > below;
+        panel.style.maxHeight = `${Math.max(0, placeAbove ? above : below)}px`;
+        panel.style.left = `${Math.max(gutter, Math.min(
+          anchor.left + anchor.width / 2 - panel.offsetWidth / 2,
+          window.innerWidth - panel.offsetWidth - gutter
+        ))}px`;
+        panel.style.top = `${placeAbove
+          ? Math.max(gutter, anchor.top - panel.offsetHeight - gap)
+          : anchor.bottom + gap}px`;
+      }
+
+      function closePreview() {
+        clearTimeout(openTimer);
+        clearTimeout(closeTimer);
+        if (!active) return;
+        active.panel.hidden = true;
+        active.trigger.setAttribute('aria-expanded', 'false');
+        active = null;
+      }
+
+      function openPreview(trigger, panel) {
+        clearTimeout(openTimer);
+        clearTimeout(closeTimer);
+        if (active?.trigger === trigger) return;
+        closePreview();
+        active = { trigger, panel };
+        panel.hidden = false;
+        panel.style.maxHeight = 'calc(100vh - 24px)';
+        trigger.setAttribute('aria-expanded', 'true');
+        positionPreview();
+      }
+
+      triggers.forEach((trigger) => {
+        const panel = document.getElementById(trigger.getAttribute('aria-controls'));
+        const contains = (node) => node && (trigger.contains(node) || panel.contains(node));
+
+        [trigger, panel].forEach((element) => {
+          element.addEventListener('pointerenter', (event) => {
+            if (event.pointerType === 'touch') return;
+            clearTimeout(closeTimer);
+            clearTimeout(openTimer);
+            openTimer = setTimeout(() => openPreview(trigger, panel), 120);
+          });
+          element.addEventListener('pointerleave', () => {
+            clearTimeout(openTimer);
+            closeTimer = setTimeout(() => {
+              if (active?.trigger === trigger && !contains(document.activeElement)) closePreview();
+            }, 200);
+          });
+          element.addEventListener('focusin', () => openPreview(trigger, panel));
+          element.addEventListener('focusout', (event) => {
+            if (!contains(event.relatedTarget)) closePreview();
+          });
+        });
+      });
+
+      document.addEventListener('keydown', (event) => {
+        if (event.key === 'Escape' && active) {
+          const { trigger, panel } = active;
+          if (panel.contains(document.activeElement)) trigger.focus();
+          closePreview();
+        }
+      });
+      document.addEventListener('pointerdown', (event) => {
+        if (active && !active.trigger.contains(event.target) && !active.panel.contains(event.target)) {
+          closePreview();
+        }
+      });
+      window.addEventListener('resize', positionPreview);
+      document.addEventListener('scroll', (event) => {
+        if (active && !active.panel.contains(event.target)) closePreview();
+      }, true);
+    })();
+  </script>
