diff --git a/src/components/Modal.tsx b/src/components/Modal.tsx
new file mode 100644
index 0000000..68a919c
--- /dev/null
+++ b/src/components/Modal.tsx
@@ -0,0 +1,53 @@
+import { useEffect, useId, useRef, type ReactNode } from 'react';
+
+interface Props {
+  title: string;
+  onClose: () => void;
+  children: ReactNode;
+}
+
+export default function Modal({ title, onClose, children }: Props) {
+  const dialogRef = useRef<HTMLDialogElement>(null);
+  const titleId = useId();
+
+  useEffect(() => {
+    const dialog = dialogRef.current!;
+    const trigger = document.activeElement;
+    dialog.showModal();
+    return () => {
+      dialog.close();
+      if (trigger instanceof HTMLElement && trigger.isConnected) trigger.focus();
+    };
+  }, []);
+
+  return (
+    <dialog
+      ref={dialogRef}
+      aria-labelledby={titleId}
+      closedBy="any"
+      className="modal bg-white shadow-xl"
+      onClose={onClose}
+      onClick={event => {
+        // Backdrop dismissal fallback for browsers without closedby support.
+        if (event.target !== event.currentTarget) return;
+        const rect = event.currentTarget.getBoundingClientRect();
+        if (event.clientX < rect.left || event.clientX > rect.right ||
+            event.clientY < rect.top || event.clientY > rect.bottom) {
+          event.currentTarget.close();
+        }
+      }}
+    >
+      <header className="flex items-center justify-between gap-4 border-b border-gray-200 p-4">
+        <h2 id={titleId} className="text-lg font-semibold text-gray-800">{title}</h2>
+        <form method="dialog">
+          <button type="submit" aria-label={`Close ${title.toLowerCase()}`} className="p-2 text-gray-600 hover:text-amber-700">
+            <svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" className="h-6 w-6">
+              <path d="M6 18 18 6M6 6l12 12" />
+            </svg>
+          </button>
+        </form>
+      </header>
+      {children}
+    </dialog>
+  );
+}
