diff --git a/src/components/ModalDialog.tsx b/src/components/ModalDialog.tsx
new file mode 100644
index 0000000..be1fb68
--- /dev/null
+++ b/src/components/ModalDialog.tsx
@@ -0,0 +1,36 @@
+import { useEffect, useRef, type ReactNode } from 'react';
+
+interface Props {
+  id: string;
+  title: string;
+  onClose: () => void;
+  children: ReactNode;
+}
+
+/** Native modality provides focus containment, Escape, and an inert background. */
+export default function ModalDialog({ id, title, onClose, children }: Props) {
+  const dialogRef = useRef<HTMLDialogElement>(null);
+  useEffect(() => {
+    const dialog = dialogRef.current!;
+    const opener = document.activeElement instanceof HTMLElement ? document.activeElement : null;
+    dialog.showModal();
+    return () => {
+      dialog.close();
+      if (opener?.isConnected) opener.focus();
+    };
+  }, []);
+
+  return (
+    <dialog ref={dialogRef} id={id} aria-labelledby={`${id}-title`} className="overlay-dialog bg-white shadow-xl w-full max-w-2xl" onClose={onClose} onClick={event => {
+      if (event.target !== event.currentTarget) return;
+      const bounds = event.currentTarget.getBoundingClientRect();
+      if (event.clientX < bounds.left || event.clientX > bounds.right || event.clientY < bounds.top || event.clientY > bounds.bottom) event.currentTarget.close();
+    }}>
+      <div className="flex items-center justify-between gap-4 p-4 border-b border-gray-200">
+        <h2 id={`${id}-title`} className="text-lg font-semibold">{title}</h2>
+        <button type="button" aria-label={`Close ${title.toLowerCase()}`} onClick={() => dialogRef.current?.close()} className="p-2 text-gray-600 hover:text-amber-800">✕</button>
+      </div>
+      {children}
+    </dialog>
+  );
+}
