diff --git a/src/utils/articleIndex.ts b/src/utils/articleIndex.ts
new file mode 100644
index 0000000..df0ce8e
--- /dev/null
+++ b/src/utils/articleIndex.ts
@@ -0,0 +1,20 @@
+export interface ArticleSummary {
+  slug: string;
+  title: string;
+  summary: string;
+  image?: string;
+}
+
+let articleIndex: Promise<ArticleSummary[]> | undefined;
+
+// Share one on-demand request between the search and reading-list islands.
+export function loadArticleIndex() {
+  return articleIndex ??= fetch(`${import.meta.env.BASE_URL}api/articles.json`)
+    .then(response => {
+      if (!response.ok) throw new Error('Unable to load articles. Please try again.');
+      return response.json() as Promise<ArticleSummary[]>;
+    }).catch(error => {
+      articleIndex = undefined;
+      throw error;
+    });
+}

