+(() => {
+  'use strict';
+
+  // Progressive enhancement: never substitute next-frame timing for async paints.
+  if (window.dailyGrindPerformance) return;
+  const supported = globalThis.PerformanceObserver?.supportedEntryTypes ?? [];
+  const reports = [];
+  const inputs = [];
+  const interactionControls = new Map();
+  const observers = [];
+  const limit = 100;
+  let activeNavigation = null;
+  let largestPaint = null;
+
+  function publish(report) {
+    const snapshot = Object.freeze(report);
+    reports.push(snapshot);
+    if (reports.length > limit) reports.shift();
+    window.dispatchEvent(new CustomEvent('daily-grind:performance', { detail: snapshot }));
+  }
+
+  function controlFor(target) {
+    const control = target?.closest?.('[data-performance-control]');
+    if (!control) return null;
+    const link = target.closest('a');
+    return {
+      control: control.dataset.performanceControl,
+      label: control.dataset.performanceLabel ?? link?.textContent.trim() ?? null,
+      destination: link?.getAttribute('href') ?? null,
+    };
+  }
+
+  function rememberInput(event) {
+    if (!event.isTrusted) return;
+    inputs.push({ startTime: event.timeStamp, control: controlFor(event.target) });
+    if (inputs.length > limit) inputs.shift();
+  }
+
+  function attribution(entry) {
+    // Event Timing provides an exact ID join. Timestamp matching also covers fast
+    // inputs below Event Timing's minimum duration threshold (16 ms).
+    const input = inputs.findLast((item) => Math.abs(item.startTime - entry.startTime) < 1);
+    return interactionControls.get(entry.interactionId) ?? input?.control ?? {
+      control: 'other', label: null, destination: null,
+    };
+  }
+
+  function observe(type, consume, options = {}) {
+    if (!supported.includes(type)) return false;
+    try {
+      const observer = new PerformanceObserver((list) => consume(list.getEntries()));
+      observer.observe({ type, buffered: true, ...options });
+      observers.push({ observer, consume });
+      return true;
+    } catch {
+      // Some browsers advertise experimental entries but reject registration.
+      return false;
+    }
+  }
+
+  function reportNavigation(final, reason) {
+    if (!activeNavigation) return;
+    publish({
+      type: 'soft-navigation',
+      ...attribution(activeNavigation),
+      url: activeNavigation.name,
+      navigationId: activeNavigation.navigationId,
+      interactionId: activeNavigation.interactionId,
+      startTime: activeNavigation.startTime,
+      fcpDuration: activeNavigation.duration,
+      lcpDuration: largestPaint?.duration ?? null,
+      lcpSize: largestPaint?.largestContentfulPaint?.size ?? null,
+      final,
+      reason,
+    });
+  }
+
+  function finalizeNavigation(reason) {
+    reportNavigation(true, reason);
+    activeNavigation = null;
+    largestPaint = null;
+  }
+
+  const capabilities = {};
+  capabilities.eventTiming = observe('event', (entries) => {
+    for (const entry of entries) {
+      if (!entry.interactionId) continue;
+      const control = controlFor(entry.target);
+      if (!control) continue;
+      interactionControls.set(entry.interactionId, control);
+      if (interactionControls.size > limit) {
+        interactionControls.delete(interactionControls.keys().next().value);
+      }
+    }
+  }, { durationThreshold: 16 });
+
+  capabilities.softNavigation = observe('soft-navigation', (entries) => {
+    for (const entry of entries) {
+      finalizeNavigation('next-navigation');
+      activeNavigation = entry;
+      // Includes paints before the URL update, even with the old navigationId.
+      largestPaint = entry.getLargestInteractionContentfulPaint();
+      reportNavigation(false, 'first-paint');
+    }
+  });
+
+  capabilities.interactionPaint = observe('interaction-contentful-paint', (entries) => {
+    for (const entry of entries) {
+      publish({
+        type: 'interaction-paint',
+        ...attribution(entry),
+        interactionId: entry.interactionId,
+        startTime: entry.startTime,
+        duration: entry.duration,
+        paintTime: entry.paintTime,
+        presentationTime: entry.presentationTime,
+        size: entry.largestContentfulPaint?.size ?? null,
+      });
