+      if (activeNavigation?.interactionId === entry.interactionId &&
+          (!largestPaint || entry.presentationTime >= largestPaint.presentationTime)) {
+        largestPaint = entry;
+        reportNavigation(false, 'larger-paint');
+      }
+    }
+  });
