+    // Drain pending records before finalizing, including during page teardown.
+    for (const { observer, consume } of observers) consume(observer.takeRecords());
+    finalizeNavigation(reason);
+  }
+
+  window.dailyGrindPerformance = Object.freeze({
+    capabilities: Object.freeze(capabilities),
+    getReports: () => reports.slice(),
