+const { test } = require('node:test');
+const assert = require('node:assert/strict');
+const { readFileSync } = require('node:fs');
+const { runInNewContext } = require('node:vm');
+
+const script = readFileSync(`${__dirname}/performance-monitor.js`, 'utf8');
+
+function setup(types = ['event', 'soft-navigation', 'interaction-contentful-paint'], reject = false) {
+  const observers = new Map();
+  const listeners = new Map();
+  const emitted = [];
+  function addEventListener(type, callback) {
+    listeners.set(type, [...(listeners.get(type) ?? []), callback]);
+  }
+  class PerformanceObserver {
+    static supportedEntryTypes = types;
+    constructor(callback) { this.callback = callback; this.pending = []; }
+    observe(options) {
+      if (reject) throw new Error('Unsupported experimental API');
+      this.options = options;
+      observers.set(options.type, this);
+    }
+    takeRecords() { return this.pending.splice(0); }
+  }
+  const window = { addEventListener, dispatchEvent: (event) => emitted.push(event.detail) };
+  const document = { addEventListener, visibilityState: 'visible' };
+  const context = { window, document, PerformanceObserver,
+    CustomEvent: class { constructor(type, options) { this.type = type; this.detail = options.detail; } } };
+  runInNewContext(script, context);
+  return {
+    api: window.dailyGrindPerformance, observers, emitted, document,
+    emit(type, entries) { observers.get(type).callback({ getEntries: () => entries }); },
+    fire(type, event) { for (const callback of listeners.get(type) ?? []) callback(event); },
+    rerun() { runInNewContext(script, context); },
+  };
+}
+
+function target(control, label) {
+  const link = { textContent: label, getAttribute: () => '/menu' };
+  return { closest: (selector) => selector === 'a' ? link : {
+    dataset: { performanceControl: control, performanceLabel: label },
+  } };
+}
+
+function paint(interactionId = 1, presentationTime = 180, navigationId = 'old') {
+  return { interactionId, navigationId, startTime: 100,
+    duration: presentationTime - 100, presentationTime, paintTime: presentationTime - 2,
+    largestContentfulPaint: { size: 800 } };
+}
+
+function navigation(id, interactionId = 1, seed = paint()) {
+  return { name: `/view/${id}`, navigationId: id, interactionId, startTime: 100,
+    duration: 40, getLargestInteractionContentfulPaint: () => seed };
+}
+
+test('unsupported and rejected entry types degrade safely; initialization is idempotent', () => {
+  for (const env of [setup([]), setup(undefined, true)]) {
+    assert.equal(env.api.capabilities.interactionPaint, false);
+    assert.equal(env.api.capabilities.softNavigation, false);
+    env.api.flush();
+    assert.equal(env.api.getReports().length, 0);
+    env.rerun();
+  }
+  const env = setup();
+  env.rerun();
+  assert.equal(env.observers.size, 3);
+  for (const observer of env.observers.values()) assert.equal(observer.options.buffered, true);
+});
+
+test('each homepage control is attributed to async paint duration, including fast inputs', () => {
+  const env = setup();
+  for (const control of ['navigation', 'order-now', 'seasonal-favorite']) {
+    env.fire('pointerdown', { isTrusted: true, timeStamp: 100, target: target(control, control) });
+    env.emit('interaction-contentful-paint', [paint()]);
+    const report = env.api.getReports().at(-1);
+    assert.equal(report.control, control);
+    assert.equal(report.duration, 80);
+    assert.equal(report.presentationTime, 180);
+    assert.equal(Object.isFrozen(report), true);
+  }
+  assert.equal(env.emitted.length, 3);
+});
+
+test('Event Timing ID correlation takes precedence over timestamps', () => {
+  const env = setup();
+  env.emit('event', [{ interactionId: 42, target: target('seasonal-favorite', 'Cold Brew') }]);
+  env.emit('interaction-contentful-paint', [paint(42)]);
+  assert.equal(env.api.getReports().at(-1).label, 'Cold Brew');
+});
+
+test('soft navigation seeds pre-URL paints and joins later paints by interaction ID', () => {
+  const env = setup();
+  env.emit('soft-navigation', [navigation('new')]);
+  assert.equal(env.api.getReports().at(-1).lcpDuration, 80);
+  // Correct interaction, old navigation ID: must update.
+  env.emit('interaction-contentful-paint', [paint(1, 220, 'old')]);
+  assert.equal(env.api.getReports().at(-1).lcpDuration, 120);
+  // Same navigation ID, unrelated interaction: must not update.
+  env.emit('interaction-contentful-paint', [paint(2, 900, 'new')]);
+  env.emit('soft-navigation', [navigation('next', 3, null)]);
+  const final = env.api.getReports().find((report) => report.final);
+  assert.equal(final.navigationId, 'new');
+  assert.equal(final.lcpDuration, 120);
+  assert.equal(final.fcpDuration, 40);
+  assert.equal(final.reason, 'next-navigation');
+  assert.equal(env.api.getReports().at(-1).lcpDuration, null);
+});
+
+test('hidden/pagehide flush queued paints once and retain bounded immutable history', () => {
+  const env = setup();
+  env.emit('soft-navigation', [navigation('view')]);
+  env.observers.get('interaction-contentful-paint').pending.push(paint(1, 300));
+  env.document.visibilityState = 'hidden';
+  env.fire('visibilitychange');
