+  env.fire('pagehide');
+  assert.equal(env.api.getReports().filter((report) => report.final).length, 1);
+  env.emit('interaction-contentful-paint', Array.from({ length: 110 }, (_, i) => paint(i)));
+  assert.equal(env.api.getReports().length, 100);
+  env.api.getReports().pop();
+  assert.equal(env.api.getReports().length, 100);
+});
+
