+  runInNewContext(script, { window: {} });
+  const env = setup(['interaction-contentful-paint']);
+  env.emit('interaction-contentful-paint', [paint()]);
+  assert.equal(env.api.getReports().at(-1).control, 'other');
+  assert.equal(env.api.capabilities.softNavigation, false);
+});

