+(() => {
+  'use strict';
+
+  const samples = [];
+  const pending = new Set();
+  const limit = 100;
+  let sequence = 0;
+
+  function cancel(job) {
+    cancelAnimationFrame(job.frame);
+    clearTimeout(job.timer);
+    pending.delete(job);
+  }
+
+  function finish(job, duration, source) {
+    if (!pending.has(job)) return;
+    cancel(job);
+    if (document.visibilityState !== 'visible') return;
+
+    const sample = Object.freeze({
+      id: ++sequence,
+      type: job.type,
+      label: job.label,
+      startTime: job.start,
+      duration: Math.max(0, duration),
+      source,
+    });
+    const name = `daily-grind:${sample.type}:${sample.id}`;
+    try {
+      performance.measure(name, {
+        start: sample.startTime,
+        duration: sample.duration,
+        detail: sample,
+      });
+    } catch {
+      // Monitoring must also work on browsers without User Timing Level 3.
+    }
+    samples.push(sample);
+    if (samples.length > limit) {
+      const oldest = samples.shift();
+      performance.clearMeasures(`daily-grind:${oldest.type}:${oldest.id}`);
+    }
+    window.dispatchEvent(new CustomEvent('daily-grind:performance', { detail: sample }));
+  }
+
+  function begin(type, label, start = performance.now()) {
+    if (document.visibilityState !== 'visible') return null;
+    const job = { type, label, start, frame: 0, timer: 0 };
+    pending.add(job);
+    return job;
+  }
+
+  function afterPaint(job) {
+    if (!job || !pending.has(job)) return;
+    // A second frame gives the browser a painting opportunity after the update.
+    // This is an estimate, not proof that pixels reached the display.
+    job.frame = requestAnimationFrame(() => {
+      job.frame = requestAnimationFrame(() => {
+        if (!pending.has(job)) return;
+        const duration = performance.now() - job.start;
+        // Allow Event Timing's asynchronous observer to supply actual timing.
+        job.timer = setTimeout(() => finish(job, duration, 'animation-frame-estimate'),
+          job.type === 'click' ? 200 : 0);
+      });
+    });
+  }
+
+  document.addEventListener('click', (event) => {
+    if (!(event.target instanceof Element)) return;
+    if (event.button !== 0 || event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return;
+    const target = event.target.closest('nav a, .hero .btn, #seasonal-favorites .card');
+    if (!target) return;
+    const link = event.target.closest('a');
+    if (link && (link.hasAttribute('download') || (link.target && link.target !== '_self'))) return;
+
+    let label;
+    if (target.matches('nav a')) label = `navigation:${target.textContent.trim()}`;
+    else if (target.matches('.hero .btn')) label = 'order-now';
+    else label = `seasonal:${target.querySelector('h3')?.textContent.trim() || 'card'}`;
+
+    // Older browsers use epoch-based event timestamps.
+    const timestamp = event.timeStamp > 1e12
+      ? event.timeStamp - performance.timeOrigin : event.timeStamp;
+    const start = Number.isFinite(timestamp) && timestamp >= 0 && timestamp <= performance.now()
+      ? timestamp : performance.now();
+    afterPaint(begin('click', label, start));
+  }, { capture: true, passive: true });
+
+  // Event Timing measures input delay + event processing + the next paint.
+  // Browsers omit fast events, so every click also has a frame-based fallback.
+  if (typeof PerformanceObserver !== 'undefined' &&
+      PerformanceObserver.supportedEntryTypes?.includes('event')) {
+    try {
+      const observer = new PerformanceObserver((list) => {
+        for (const entry of list.getEntries()) {
+          if (entry.name !== 'click' || entry.duration <= 0) continue;
+          const job = [...pending].find((candidate) => candidate.type === 'click' &&
+            Math.abs(candidate.start - entry.startTime) < 1);
+          if (job) finish(job, entry.duration, 'event-timing');
+        }
+      });
+      observer.observe({ type: 'event', buffered: true, durationThreshold: 16 });
+    } catch {
+      // Frame estimates remain available when Event Timing is unavailable.
+    }
+  }
+
+  for (const method of ['pushState', 'replaceState']) {
+    const original = history[method];
+    history[method] = function (...args) {
+      const job = begin('view-switch', `history:${method}`);
+      try {
+        const result = original.apply(this, args);
+        afterPaint(job);
+        return result;
+      } catch (error) {
+        if (job) cancel(job);
+        throw error;
+      }
+    };
+  }
+  for (const name of ['popstate', 'hashchange']) {
+    window.addEventListener(name, () => afterPaint(begin('view-switch', name)));
+  }
+
+  function cancelPending() {
+    for (const job of pending) cancel(job);
+  }
+  document.addEventListener('visibilitychange', () => {
+    if (document.visibilityState !== 'visible') cancelPending();
+  });
+  window.addEventListener('pagehide', cancelPending);
+
+  window.dailyGrindPerformance = Object.freeze({
+    getSamples: () => samples.slice(),
+    // Resolve update() only after asynchronous rendering has committed to the DOM.
+    async measureViewSwitch(label, update) {
+      const job = begin('view-switch', String(label));
+      try {
+        const result = await update();
+        afterPaint(job);
+        return result;
+      } catch (error) {
+        if (job) cancel(job);
+        throw error;
+      }
+    },
+  });
+})();
diff --git a/tests/performance-monitor.test.cjs b/tests/performance-monitor.test.cjs
new file mode 100644
index 0000000..633bba1
--- /dev/null
+++ b/tests/performance-monitor.test.cjs
@@ -0,0 +1,139 @@
+const { test } = require('node:test');
+const assert = require('node:assert/strict');
+const { readFileSync } = require('node:fs');
+const { runInNewContext } = require('node:vm');
+
+const source = readFileSync(require('node:path').join(__dirname, '../performance-monitor.js'), 'utf8');
+
+function setup() {
+  let now = 100;
+  let id = 0;
+  let observer;
+  const frames = new Map();
+  const timers = new Map();
+  const listeners = {};
+  const measures = new Map();
+  const reports = [];
+  const document = {
+    visibilityState: 'visible',
+    addEventListener: (name, fn) => { listeners[name] = fn; },
+  };
+  const window = {
+    addEventListener: document.addEventListener,
+    dispatchEvent: (event) => reports.push(event.detail),
+  };
+  class Element {
+    textContent = 'Menu';
+    target = '';
+    closest(selector) { return selector === 'a' || selector.includes('nav a') ? this : null; }
+    matches(selector) { return selector === 'nav a'; }
+    hasAttribute() { return false; }
+  }
+  const history = {
+    pushState() { return 'pushed'; },
+    replaceState() { throw new Error('invalid state'); },
+  };
+  runInNewContext(source, {
+    document, window, history, Element,
+    performance: {
+      now: () => now, timeOrigin: 1000000000000,
+      measure: (name, options) => measures.set(name, options),
+      clearMeasures: (name) => measures.delete(name),
+    },
+    requestAnimationFrame: (fn) => { frames.set(++id, fn); return id; },
+    cancelAnimationFrame: (key) => frames.delete(key),
+    setTimeout: (fn) => { timers.set(++id, fn); return id; },
+    clearTimeout: (key) => timers.delete(key),
+    CustomEvent: class { constructor(name, options) { this.detail = options.detail; } },
+    PerformanceObserver: class {
+      static supportedEntryTypes = ['event'];
+      constructor(fn) { observer = fn; }
+      observe() {}
+    },
+  });
+  function frame() {
+    now += 16;
+    const callbacks = [...frames.values()];
+    frames.clear();
+    callbacks.forEach((fn) => fn(now));
+  }
+  return {
+    window, document, listeners, history, reports, measures,
+    click: (extra = {}) => listeners.click({
+      target: new Element(), button: 0, timeStamp: now - 10, ...extra,
+    }),
+    native: (duration) => observer({ getEntries: () => [{ name: 'click', startTime: now - 10, duration }] }),
+    paint() {
+      frame(); frame();
+      const callbacks = [...timers.values()];
+      timers.clear();
+      callbacks.forEach((fn) => fn());
+    },
+  };
+}
+
+test('click estimates include input delay and emit a User Timing measure', () => {
+  const app = setup();
+  app.click(); app.paint();
+  assert.equal(app.reports.length, 1);
+  assert.equal(app.reports[0].duration, 42);
+  assert.equal(app.reports[0].label, 'navigation:Menu');
+  assert.equal(app.reports[0].source, 'animation-frame-estimate');
+  assert.equal(app.measures.size, 1);
+});
+
+test('native Event Timing replaces the estimate without duplicate reporting', () => {
+  const app = setup();
+  app.click(); app.native(24); app.paint();
+  assert.equal(app.reports.length, 1);
+  assert.equal(app.reports[0].duration, 24);
+  assert.equal(app.reports[0].source, 'event-timing');
+});
+
+test('modified clicks and hidden/unloaded measurements are excluded', () => {
+  const app = setup();
+  app.click({ ctrlKey: true }); app.paint();
+  app.click(); app.document.visibilityState = 'hidden';
+  app.listeners.visibilitychange(); app.paint();
+  app.document.visibilityState = 'visible';
+  app.click(); app.listeners.pagehide(); app.paint();
+  assert.equal(app.reports.length, 0);
+});
+
+test('history preserves return values and errors and measures view events', () => {
+  const app = setup();
+  assert.equal(app.history.pushState({}, '', '/menu'), 'pushed');
+  app.paint();
+  assert.throws(() => app.history.replaceState(), /invalid state/);
+  app.paint();
+  app.listeners.popstate(); app.paint();
+  app.listeners.hashchange(); app.paint();
+  assert.deepEqual(app.reports.map((sample) => sample.label), [
+    'history:pushState', 'popstate', 'hashchange',
+  ]);
+});
+
+test('explicit async views wait for DOM work and preserve results and rejection', async () => {
+  const app = setup();
+  let resolve;
+  const work = new Promise((done) => { resolve = done; });
+  const measurement = app.window.dailyGrindPerformance.measureViewSwitch('menu', () => work);
+  app.paint();
+  assert.equal(app.reports.length, 0);
+  resolve('rendered');
+  assert.equal(await measurement, 'rendered');
+  app.paint();
+  assert.equal(app.reports[0].type, 'view-switch');
+  await assert.rejects(app.window.dailyGrindPerformance.measureViewSwitch('failed', () => {
+    throw new Error('render failed');
+  }), /render failed/);
+  app.paint();
+  assert.equal(app.reports.length, 1);
+});
+
+test('samples and User Timing entries are bounded', () => {
+  const app = setup();
+  for (let i = 0; i < 110; i++) { app.click(); app.paint(); }
+  assert.equal(app.window.dailyGrindPerformance.getSamples().length, 100);
+  assert.equal(app.measures.size, 100);
+});

