--- /dev/null
+++ b/media-loading.js
@@ -0,0 +1,41 @@
+// URLs stay in data attributes until intersection, including in browsers whose
+// preload scanner does not understand lazy video/audio or deferred posters.
+const deferredPlayers = document.querySelectorAll('[data-deferred-media]');
+const supportsLazyMedia = Object.hasOwn(HTMLMediaElement.prototype, 'loading');
+
+function loadPlayer(player) {
+  if (!player.hasAttribute('data-deferred-media')) return;
+  player.removeAttribute('data-deferred-media');
+  if (player.dataset.poster) {
+    player.setAttribute('poster', player.dataset.poster);
+    delete player.dataset.poster;
+  }
+  for (const source of player.querySelectorAll('source[data-src]')) {
+    source.src = source.dataset.src;
+    delete source.dataset.src;
+  }
+  // IntersectionObserver supplies the same deferral in browsers without native
+  // lazy media. In supported browsers, retain native lazy-loading as well.
+  player.preload = player.dataset.preload || 'metadata';
+  delete player.dataset.preload;
+  if (!supportsLazyMedia) player.removeAttribute('loading');
+  player.load();
+}
+
+if ('IntersectionObserver' in window) {
+  const observer = new IntersectionObserver((entries) => {
+    for (const entry of entries) {
+      if (!entry.isIntersecting) continue;
+      loadPlayer(entry.target);
+      observer.unobserve(entry.target);
+    }
+  }, { rootMargin: '200px 0px', threshold: 0 });
+
+  for (const player of deferredPlayers) observer.observe(player);
+} else {
+  // Preserve bandwidth on older browsers; load only on keyboard/pointer intent.
+  for (const player of deferredPlayers) {
+    player.addEventListener('focus', () => loadPlayer(player), { once: true });
+    player.addEventListener('pointerdown', () => loadPlayer(player), { once: true });
+  }
+}
