@@ -0,0 +1,49 @@
+(() => {
+  const players = document.querySelectorAll('[data-lazy-media]');
+  const pending = new Set(players);
+  const margin = 200;
+
+  function activate(player) {
+    if (!pending.delete(player)) return;
+
+    // Poster URLs also trigger requests, so keep them inert until this point.
+    if (player.dataset.poster) {
+      player.poster = player.dataset.poster;
+      delete player.dataset.poster;
+    }
+    player.querySelectorAll('source[data-src]').forEach(source => {
+      source.src = source.dataset.src;
+      delete source.dataset.src;
+    });
+    player.preload = 'metadata';
+    player.load();
+  }
+
+  if ('IntersectionObserver' in window) {
+    const observer = new IntersectionObserver(entries => {
+      entries.forEach(entry => {
+        if (!entry.isIntersecting) return;
+        activate(entry.target);
+        observer.unobserve(entry.target);
+      });
+    }, { rootMargin: `${margin}px 0px`, threshold: 0 });
+    players.forEach(player => observer.observe(player));
+  } else {
+    // Older browsers still defer offscreen assets instead of loading all players.
+    const check = () => {
+      pending.forEach(player => {
+        const rect = player.getBoundingClientRect();
+        if (rect.bottom >= -margin && rect.top <= window.innerHeight + margin) {
+          activate(player);
+        }
+      });
+      if (!pending.size) {
+        window.removeEventListener('scroll', check);
+        window.removeEventListener('resize', check);
+      }
+    };
+    window.addEventListener('scroll', check, { passive: true });
+    window.addEventListener('resize', check);
+    check();
+  }
+})();
