@@ -0,0 +1,93 @@
+const { test } = require('node:test');
+const assert = require('node:assert/strict');
+const { readFileSync } = require('node:fs');
+const vm = require('node:vm');
+
+const script = readFileSync('media.js', 'utf8');
+
+function setup(withObserver = true) {
+  const players = [0, 1800, 2800].map((top, index) => ({
+    dataset: index < 2 ? { poster: `poster-${index}.jpg` } : {},
+    source: { dataset: { src: `media-${index}` } },
+    loads: 0,
+    top,
+    querySelectorAll() { return [this.source]; },
+    load() { this.loads++; },
+    getBoundingClientRect() { return { top: this.top, bottom: this.top + 300 }; },
+  }));
+  const listeners = {};
+  let callback;
+  const observed = new Set();
+  const window = {
+    innerHeight: 800,
+    addEventListener(name, fn) { listeners[name] = fn; },
+    removeEventListener(name) { delete listeners[name]; },
+  };
+  class Observer {
+    constructor(fn, options) {
+      callback = fn;
+      assert.equal(options.rootMargin, '200px 0px');
+    }
+    observe(player) { observed.add(player); }
+    unobserve(player) { observed.delete(player); }
+  }
+  if (withObserver) window.IntersectionObserver = Observer;
+  vm.runInNewContext(script, {
+    window, IntersectionObserver: Observer,
+    document: { querySelectorAll: () => players },
+  });
+  return { players, listeners, observed, intersect: entries => callback(entries) };
+}
+
+test('HTML keeps every media source and poster inert, with no preload hints', () => {
+  const html = readFileSync('index.html', 'utf8');
+  const players = html.match(/<(video|audio)\b[^>]*>[\s\S]*?<\/\1>/g);
+  assert.equal(players.length, 3);
+  players.forEach(player => {
+    assert.match(player, /data-lazy-media/);
+    assert.match(player, /preload="none"/);
+    assert.match(player, /data-src=/);
+    assert.doesNotMatch(player, /\s(?:src|poster|autoplay)=/);
+  });
+  assert.doesNotMatch(html, /<link[^>]+rel=["'](?:preload|prefetch)/);
+  assert.doesNotMatch(html, /url\(/);
+});
+
+test('only approaching players receive source, poster and metadata requests', () => {
+  const { players, observed, intersect } = setup();
+  players.forEach(player => {
+    assert.equal(player.source.src, undefined);
+    assert.equal(player.poster, undefined);
+    assert.equal(player.loads, 0);
+  });
+  intersect([{ target: players[1], isIntersecting: false }]);
+  assert.equal(players[1].loads, 0);
+  intersect([{ target: players[0], isIntersecting: true }]);
+  assert.equal(players[0].source.src, 'media-0');
+  assert.equal(players[0].poster, 'poster-0.jpg');
+  assert.equal(players[0].preload, 'metadata');
+  assert.equal(players[0].loads, 1);
+  assert.equal(observed.has(players[0]), false);
+  assert.equal(players[1].source.src, undefined);
+  assert.equal(players[1].poster, undefined);
+  assert.equal(players[2].source.src, undefined);
+  intersect([{ target: players[0], isIntersecting: true }, { target: players[2], isIntersecting: true }]);
+  assert.equal(players[0].loads, 1);
+  assert.equal(players[2].source.src, 'media-2');
+  assert.equal(players[2].loads, 1);
+});
+
+test('fallback also waits for proximity and removes listeners when done', () => {
+  const { players, listeners } = setup(false);
+  assert.equal(players[0].loads, 1);
+  assert.equal(players[1].loads, 0);
+  assert.equal(players[2].loads, 0);
+  players[1].top = 1000;
+  listeners.scroll();
+  assert.equal(players[1].loads, 1);
+  assert.equal(players[2].loads, 0);
+  players[2].top = 900;
+  listeners.resize();
+  assert.equal(players[2].loads, 1);
+  assert.deepEqual(listeners, {});
+});

