new file mode 100644
index 0000000..8822264
--- /dev/null
+++ b/equipment.mjs
@@ -0,0 +1,163 @@
+const configuration = {
+  brewer: { space: 'local', permission: 'local-network', label: 'brewer' },
+  helper: { space: 'loopback', permission: 'loopback-network', label: 'helper' },
+};
+
+// Limit each card to its advertised destination; never scan the network.
+export function validateEndpoint(value, kind) {
+  const url = new URL(value);
+  if (!['http:', 'https:'].includes(url.protocol) || url.username || url.password || url.hash) {
+    throw new Error('Use an HTTP or HTTPS URL without credentials or a fragment.');
+  }
+  const host = url.hostname.toLowerCase();
+  const octets = host.split('.').map(Number);
+  const ipv4 = octets.length === 4 && octets.every(n => Number.isInteger(n) && n >= 0 && n <= 255);
+  const loopback = host === 'localhost' || host.endsWith('.localhost') || host === '[::1]' || (ipv4 && octets[0] === 127);
+  const privateLan = (ipv4 && (octets[0] === 10 ||
+    (octets[0] === 172 && octets[1] >= 16 && octets[1] <= 31) ||
+    (octets[0] === 192 && octets[1] === 168) ||
+    (octets[0] === 169 && octets[1] === 254))) || host.endsWith('.local') ||
+    /^\[(?:f[cd][0-9a-f]{2}:|fe[89ab][0-9a-f]:)/.test(host);
+  if (kind === 'helper' ? !loopback : kind !== 'brewer' || !privateLan) {
+    throw new Error(kind === 'helper'
+      ? 'Use a loopback address such as http://127.0.0.1:45678/health or localhost.'
+      : 'Use a private LAN address such as http://192.168.1.100/api/status or brewer.local.');
+  }
+  return url;
+}
+
+export async function queryNetworkPermission(name, permissions = globalThis.navigator?.permissions) {
+  try {
+    return await permissions.query({ name });
+  } catch {
+    // Unsupported granular permissions still allow a user-initiated attempt.
+    // Never query the legacy combined permission: it crashes older browsers.
+    return null;
+  }
+}
+
+export async function checkEndpoint(url, space, signal, fetcher = globalThis.fetch) {
+  const response = await fetcher(url.href, {
+    method: 'GET', mode: 'cors', targetAddressSpace: space,
+    credentials: 'omit', cache: 'no-store', redirect: 'error',
+    referrerPolicy: 'no-referrer', signal,
+  });
+  // A readable successful response is required; opaque responses prove nothing.
+  if (response.body) await response.body.cancel();
+  if (!response.ok) throw new Error(`Endpoint responded with HTTP ${response.status}. Check the status URL and equipment setup.`);
+}
+
+function mountConnection(form) {
+  const kind = form.dataset.equipment;
+  const config = configuration[kind];
+  const input = form.elements.endpoint;
+  const button = form.querySelector('[type="submit"]');
+  const cancel = form.querySelector('.connection-cancel');
+  const badge = form.querySelector('.connection-status');
+  const feedback = form.querySelector('.connection-feedback');
+  const permissionFeedback = form.querySelector('.permission-feedback');
+  let permissionStatus = null;
+  let activeController = null;
+  let sequence = 0;
+  let permissionBlocked = false;
+
+  function show(state, label, message) {
+    badge.dataset.state = state;
+    badge.textContent = label;
+    feedback.textContent = message;
+  }
+
+  function updatePermission() {
+    const state = permissionStatus?.state;
+    permissionFeedback.textContent = state === 'denied'
+      ? `Access blocked. In browser site settings, allow ${kind === 'brewer' ? 'Local network' : 'Loopback network'}, then retry.`
+      : state === 'granted' ? 'Browser network permission allowed.' : '';
+    if (state === 'denied') {
+      permissionBlocked = true;
+      activeController?.abort();
+      show('error', 'Access blocked', 'Allow access in your browser’s site settings before connecting.');
+    } else if (permissionBlocked) {
+      permissionBlocked = false;
+      show('idle', 'Not connected', 'Permission changed. Connect again to check your equipment.');
+    }
+  }
+
+  async function refreshPermission() {
+    const status = await queryNetworkPermission(config.permission);
+    if (status && status !== permissionStatus) {
+      permissionStatus?.removeEventListener('change', updatePermission);
+      permissionStatus = status;
+      permissionStatus.addEventListener('change', updatePermission);
+    }
+    updatePermission();
+    return permissionStatus?.state ?? 'prompt';
+  }
+
+  void refreshPermission(); // Only inspect permission on load; never contact equipment.
+
+  input.addEventListener('input', () => {
+    input.setCustomValidity('');
+    show('idle', 'Not connected', 'Address changed. Connect to check this endpoint.');
+  });
+
+  cancel.addEventListener('click', () => activeController?.abort());
+
+  form.addEventListener('submit', async event => {
+    event.preventDefault();
+    if (activeController) return;
+    let url;
+    try {
+      url = validateEndpoint(input.value.trim(), kind);
+    } catch (error) {
+      input.setCustomValidity(error instanceof TypeError ? 'Enter a complete HTTP or HTTPS status URL.' : error.message);
+      input.reportValidity();
+      show('error', 'Check address', input.validationMessage);
+      return;
+    }
+    if (!globalThis.isSecureContext) {
+      show('error', 'HTTPS required', 'Open the Daily Grind over HTTPS, or localhost for development, to connect to equipment.');
+      return;
+    }
+
+    const requestNumber = ++sequence;
+    const controller = new AbortController();
+    activeController = controller;
+    button.disabled = true;
+    input.readOnly = true;
+    cancel.hidden = false;
+    show('pending', 'Connecting…', 'If your browser asks, allow access to this equipment.');
+    let timedOut = false;
+    let timeout;
+    try {
+      if (await refreshPermission() === 'denied') return;
+      if (controller.signal.aborted) throw new DOMException('Cancelled', 'AbortError');
+      timeout = setTimeout(() => { timedOut = true; controller.abort(); }, 20000);
+      await checkEndpoint(url, config.space, controller.signal);
+      if (controller.signal.aborted) throw new DOMException('Cancelled', 'AbortError');
+      show('success', 'Connection verified', `Your ${config.label} responded successfully. Last checked at ${new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}.`);
+      button.firstChild.textContent = 'Check again ';
+    } catch (error) {
+      const state = await refreshPermission();
+      if (requestNumber !== sequence || state === 'denied') return;
+      if (controller.signal.aborted) {
+        show(timedOut ? 'error' : 'idle', timedOut ? 'Timed out' : 'Cancelled', timedOut
+          ? 'No response within 20 seconds. Check that the equipment is running and reachable, then retry.'
+          : 'Connection check cancelled. You can try again when ready.');
+      } else {
+        show('error', 'Couldn’t connect', error instanceof TypeError
+          ? `Check ${kind === 'brewer' ? 'that the brewer is powered on and on the same Wi-Fi' : 'that the desktop helper is running on this computer'}, the URL, and browser network permissions. The endpoint must allow this site through CORS. If your browser blocks local HTTP access, use trusted HTTPS on the endpoint or a browser supporting local network access.`
+          : error.message);
+      }
+    } finally {
+      clearTimeout(timeout);
+      activeController = null;
+      button.disabled = false;
+      input.readOnly = false;
+      cancel.hidden = true;
+    }
+  });
+}
+
+if (typeof document !== 'undefined') {
+  document.querySelectorAll('[data-equipment]').forEach(mountConnection);
+}
