@@ -0,0 +1,63 @@
+import test from 'node:test';
+import assert from 'node:assert/strict';
+import { validateEndpoint, queryNetworkPermission, checkEndpoint } from './equipment.mjs';
+
+test('brewer accepts LAN addresses and rejects public or loopback destinations', () => {
+  for (const host of ['192.168.1.100', '10.0.0.2', '172.16.0.2', '172.31.255.254', 'brewer.local', '[fd00::1]']) {
+    assert.equal(validateEndpoint(`http://${host}/api/status`, 'brewer').pathname, '/api/status');
+  }
+  for (const host of ['example.com', '172.32.0.1', '127.0.0.1', '192.169.1.1', 'brewer.local.example.com']) {
+    assert.throws(() => validateEndpoint(`http://${host}/`, 'brewer'));
+  }
+});
+
+test('helper accepts only loopback endpoints, including alternate ports', () => {
+  for (const host of ['127.0.0.1', '127.2.3.4', 'localhost', '[::1]']) {
+    assert.equal(validateEndpoint(`http://${host}:45678/health`, 'helper').port, '45678');
+  }
+  for (const host of ['192.168.1.1', 'example.com', 'localhost.example.com']) {
+    assert.throws(() => validateEndpoint(`http://${host}/health`, 'helper'));
+  }
+});
+
+test('unsafe endpoint schemes and embedded credentials are rejected', () => {
+  for (const value of ['ftp://192.168.1.1/status', 'http://user:pass@192.168.1.1/', 'http://192.168.1.1/#secret', 'not a URL']) {
+    assert.throws(() => validateEndpoint(value, 'brewer'));
+  }
+});
+
+test('permission inspection uses granular names and tolerates unsupported browsers', async () => {
+  for (const name of ['local-network', 'loopback-network']) {
+    const status = { state: 'denied' };
+    assert.equal(await queryNetworkPermission(name, { query: async descriptor => {
+      assert.equal(descriptor.name, name);
+      return status;
+    } }), status);
+    assert.equal(await queryNetworkPermission(name, { query: async () => { throw new TypeError('unsupported'); } }), null);
+    assert.equal(await queryNetworkPermission(name, {}), null);
+  }
+});
+
+test('both connection types make readable CORS requests with matching address spaces', async () => {
+  for (const [kind, space, endpoint] of [
+    ['brewer', 'local', 'http://192.168.1.100/api/status'],
+    ['helper', 'loopback', 'http://127.0.0.1:45678/health'],
+  ]) {
+    const controller = new AbortController();
+    await checkEndpoint(validateEndpoint(endpoint, kind), space, controller.signal, async (url, options) => {
+      assert.equal(url, endpoint);
+      assert.equal(options.targetAddressSpace, space);
+      assert.equal(options.mode, 'cors');
+      assert.equal(options.credentials, 'omit');
+      assert.equal(options.redirect, 'error');
+      assert.equal(options.signal, controller.signal);
+      return new Response(null, { status: 204 });
+    });
+  }
+});
+
+test('HTTP failures and browser network errors never report success', async () => {
+  const url = new URL('http://127.0.0.1:45678/health');
+  await assert.rejects(checkEndpoint(url, 'loopback', undefined, async () => new Response(null, { status: 503 })), /HTTP 503/);
+  await assert.rejects(checkEndpoint(url, 'loopback', undefined, async () => { throw new TypeError('Failed to fetch'); }), /Failed to fetch/);
+});
