+(() => {
+  'use strict';
+
+  function statusUrl(value, device) {
+    const url = new URL(value);
+    if (!['http:', 'https:'].includes(url.protocol) || url.username || url.password || url.hash) {
+      throw new Error('Use an HTTP or HTTPS status URL without a password or fragment.');
+    }
+    const host = url.hostname;
+    const octets = host.split('.').map(Number);
+    const ipv4 = octets.length === 4 && octets.every(n => Number.isInteger(n) && n >= 0 && n <= 255);
+    const privateLan = ipv4 && (octets[0] === 10 ||
+      (octets[0] === 172 && octets[1] >= 16 && octets[1] <= 31) ||
+      (octets[0] === 192 && octets[1] === 168));
+    const loopback = host === 'localhost' || host === '[::1]' || (ipv4 && octets[0] === 127);
+    if (device === 'brewer' && !privateLan) {
+      throw new Error('Enter the brewer’s private LAN IP, such as 192.168.1.100, 10.0.0.20 or 172.16.0.20.');
+    }
+    if (device === 'helper' && !loopback) {
+      throw new Error('Use 127.0.0.1, localhost or [::1] for the helper on this computer.');
+    }
+    return url;
+  }
+
+  for (const form of document.querySelectorAll('.connection-card')) {
+    const device = form.dataset.device;
+    const input = form.querySelector('input');
+    const button = form.querySelector('button');
+    const badge = form.querySelector('.connection-badge');
+    const message = form.querySelector('.connection-message');
+    const refresh = document.createElement('button');
+    refresh.type = 'button';
+    refresh.className = 'refresh-button';
+    refresh.textContent = 'Check again';
+    refresh.hidden = true;
+    button.after(refresh);
+    let activeRequest = null;
+
+    function render(state, detail, invalidAddress = false) {
+      form.dataset.state = state;
+      badge.textContent = { disconnected: 'Not connected', connecting: 'Connecting', connected: 'Connected', error: 'Connection failed' }[state];
+      button.textContent = state === 'connecting' ? 'Cancel connection' : state === 'connected' ? 'Disconnect' : `${state === 'error' ? 'Retry' : 'Connect'} ${device}`;
+      input.disabled = state === 'connecting' || state === 'connected';
+      input.setAttribute('aria-invalid', invalidAddress ? 'true' : 'false');
+      refresh.hidden = state !== 'connected';
+      message.textContent = detail;
+    }
+
+    async function connect() {
+      let url;
+      try {
+        url = statusUrl(input.value.trim(), device);
+      } catch (error) {
+        render('error', error instanceof TypeError ? 'Enter a complete status URL, such as the example above.' : error.message, true);
+        input.focus();
+        return;
+      }
+      const controller = new AbortController();
+      activeRequest = controller;
+      let timedOut = false;
+      render('connecting', 'Waiting for your equipment. Allow browser access if prompted.');
+      const timeout = setTimeout(() => {
+        timedOut = true;
+        controller.abort();
+      }, 15000);
+      try {
+        const response = await fetch(url.href, {
+          method: 'GET',
+          mode: 'cors',
+          credentials: 'omit',
+          cache: 'no-store',
+          redirect: 'error',
+          referrerPolicy: 'no-referrer',
+          targetAddressSpace: device === 'helper' ? 'loopback' : 'local',
+          signal: controller.signal
+        });
+        if (!response.ok) throw new Error(`Equipment returned HTTP ${response.status}. Check the status URL and service, then retry.`);
+        let data;
+        try {
+          data = await response.json();
+        } catch (error) {
+          if (controller.signal.aborted) throw error;
+          throw new Error('This address did not return valid JSON. Check the equipment’s status endpoint.');
+        }
+        if (!data || typeof data !== 'object' || Array.isArray(data)) {
+          throw new Error('Expected a JSON status object. Check the equipment’s status endpoint.');
+        }
+        if (activeRequest !== controller) return;
+        const name = typeof data.name === 'string' ? data.name.slice(0, 80) : device === 'brewer' ? 'Coffee brewer' : 'Desktop helper';
+        const status = typeof data.status === 'string' ? ` Reported status: ${data.status.slice(0, 80)}.` : '';
+        render('connected', `${name} responded at ${new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}.${status}`);
+      } catch (error) {
+        if (activeRequest !== controller) return;
+        const detail = timedOut ? 'No response within 15 seconds. Check the device and browser permissions, then retry.' :
+          error instanceof TypeError ? 'Could not reach this endpoint. Check the address, Wi-Fi or helper app, and browser access permissions. The endpoint must allow this site with CORS; see the help below.' : error.message;
+        render('error', detail);
+      } finally {
+        clearTimeout(timeout);
+        if (activeRequest === controller) activeRequest = null;
+      }
+    }
+
+    form.addEventListener('submit', event => {
+      event.preventDefault();
+      if (form.dataset.state === 'connecting' || form.dataset.state === 'connected') {
+        if (activeRequest) activeRequest.abort();
+        activeRequest = null;
+        render('disconnected', 'Disconnected. You can edit the address and connect again.');
+        return;
+      }
+      void connect();
+    });
+    refresh.addEventListener('click', () => { void connect(); });
+  }
+})();
