@@ -0,0 +1,123 @@
+const { test } = require('node:test');
+const assert = require('node:assert/strict');
+const { readFileSync } = require('node:fs');
+const vm = require('node:vm');
+const source = readFileSync(require('node:path').join(__dirname, '../equipment.js'), 'utf8');
+
+function element() {
+  return {
+    textContent: '', hidden: false, disabled: false, listeners: {},
+    addEventListener(type, callback) { this.listeners[type] = callback; },
+    setAttribute() {}, focus() {}, after(child) { this.next = child; }
+  };
+}
+function setup(fetchImpl) {
+  const requests = [];
+  const forms = ['brewer', 'helper'].map(device => {
+    const input = element();
+    input.value = device === 'brewer' ? 'http://192.168.1.100/api/status' : 'http://127.0.0.1:8080/api/status';
+    const parts = { input, button: element(), '.connection-badge': element(), '.connection-message': element() };
+    return Object.assign(element(), {
+      dataset: { device, state: 'disconnected' }, parts,
+      querySelector(selector) { return parts[selector]; }
+    });
+  });
+  let timeout;
+  vm.runInNewContext(source, {
+    document: { querySelectorAll: () => forms, createElement: element },
+    URL, AbortController, TypeError, Date,
+    setTimeout(callback) { timeout = callback; return 1; }, clearTimeout() {},
+    fetch(url, options) { requests.push({ url, options }); return fetchImpl(url, options); }
+  });
+  return {
+    forms, requests, timeout: () => timeout(),
+    submit(index) { forms[index].listeners.submit({ preventDefault() {} }); }
+  };
+}
+const flush = () => new Promise(resolve => setImmediate(resolve));
+const response = data => ({ ok: true, json: async () => data });
+
+test('connects only after a click, independently, with browser CORS and address-space settings', async () => {
+  const app = setup(async () => response({ name: 'Counter brewer', status: 'idle' }));
+  assert.equal(app.requests.length, 0);
+  app.submit(0);
+  await flush();
+  assert.equal(app.forms[0].dataset.state, 'connected');
+  assert.equal(app.forms[1].dataset.state, 'disconnected');
+  assert.match(app.forms[0].parts['.connection-message'].textContent, /Counter brewer.*idle/);
+  assert.equal(app.requests[0].options.targetAddressSpace, 'local');
+  assert.equal(app.requests[0].options.mode, 'cors');
+  assert.equal(app.requests[0].options.credentials, 'omit');
+  assert.equal(app.requests[0].options.redirect, 'error');
+  app.submit(1);
+  await flush();
+  assert.equal(app.forms[1].dataset.state, 'connected');
+  assert.equal(app.requests[1].options.targetAddressSpace, 'loopback');
+  app.submit(0);
+  assert.equal(app.forms[0].dataset.state, 'disconnected');
+  assert.equal(app.forms[0].parts.input.disabled, false);
+  assert.equal(app.forms[1].dataset.state, 'connected');
+});
+
+test('rejects public addresses, credentials, and a LAN address for the desktop helper', () => {
+  const app = setup(async () => response({}));
+  for (const [index, address] of [[0, 'https://example.com/status'], [0, 'http://user:secret@192.168.1.1/status'], [1, 'http://192.168.1.1/status']]) {
+    app.forms[index].parts.input.value = address;
+    app.submit(index);
+    assert.equal(app.forms[index].dataset.state, 'error');
+  }
+  assert.equal(app.requests.length, 0);
+});
+
+test('handles HTTP failures, blocked requests, invalid JSON and invalid status objects', async () => {
+  for (const implementation of [
+    async () => ({ ok: false, status: 503 }),
+    async () => { throw new TypeError('Failed to fetch'); },
+    async () => ({ ok: true, json: async () => { throw new SyntaxError(); } }),
+    async () => response(null),
+    async () => response([])
+  ]) {
+    const app = setup(implementation);
+    app.submit(0);
+    await flush();
+    assert.equal(app.forms[0].dataset.state, 'error');
+    assert.equal(app.forms[0].parts.input.disabled, false);
+    assert.match(app.forms[0].parts.button.textContent, /Retry/);
+  }
+});
+
+test('cancellation prevents a stale response from reconnecting the device', async () => {
+  let resolve;
+  const app = setup(() => new Promise(done => { resolve = done; }));
+  app.submit(0);
+  assert.equal(app.forms[0].dataset.state, 'connecting');
+  app.submit(0);
+  assert.equal(app.requests[0].options.signal.aborted, true);
+  resolve(response({}));
+  await flush();
+  assert.equal(app.forms[0].dataset.state, 'disconnected');
+});
+
+test('timeouts abort a request and explain how to retry', async () => {
+  const app = setup((url, options) => new Promise((resolve, reject) => {
+    options.signal.addEventListener('abort', () => reject(new Error('Aborted')));
+  }));
+  app.submit(1);
+  app.timeout();
+  await flush();
+  assert.equal(app.forms[1].dataset.state, 'error');
+  assert.match(app.forms[1].parts['.connection-message'].textContent, /15 seconds/);
+});
+
+test('refresh checks status again and renders device text without HTML interpretation', async () => {
+  const app = setup(async () => response({ name: '<img src=x onerror=alert(1)>', status: 'offline' }));
+  app.submit(0);
+  await flush();
+  const refresh = app.forms[0].parts.button.next;
+  assert.equal(refresh.hidden, false);
+  assert.match(app.forms[0].parts['.connection-message'].textContent, /<img.*offline/);
+  refresh.listeners.click();
+  await flush();
+  assert.equal(app.requests.length, 2);
+  assert.equal(app.forms[0].dataset.state, 'connected');
+});

