@@ -0,0 +1,175 @@
+import { useEffect, useId, useRef, useState } from 'react';
+import type { FormEvent } from 'react';
+
+type AddressSpace = 'local' | 'loopback';
+type NetworkRequestInit = RequestInit & { targetAddressSpace: AddressSpace };
+
+function validateEndpoint(value: string, space: AddressSpace): URL {
+  const url = new URL(value);
+  if (!['http:', 'https:'].includes(url.protocol) || url.username || url.password || url.hash) {
+    throw new Error('Use an HTTP or HTTPS URL without credentials or a fragment.');
+  }
+  const host = url.hostname.toLowerCase();
+  const octets = host.split('.').map(Number);
+  const ipv4 = octets.length === 4 && octets.every(n => Number.isInteger(n) && n >= 0 && n <= 255);
+  const loopback = host === 'localhost' || host.endsWith('.localhost') || host === '[::1]' || (ipv4 && octets[0] === 127);
+  const privateHost = (ipv4 && (
+    octets[0] === 10 ||
+    (octets[0] === 172 && octets[1] >= 16 && octets[1] <= 31) ||
+    (octets[0] === 192 && octets[1] === 168) ||
+    (octets[0] === 169 && octets[1] === 254)
+  )) || host.endsWith('.local') || /^\[(?:f[cd][\da-f]{2}:|fe[89ab][\da-f]:)/i.test(host);
+  if (space === 'loopback' ? !loopback : !privateHost) {
+    throw new Error(space === 'loopback'
+      ? 'Use a loopback address such as 127.0.0.1, localhost, or [::1].'
+      : 'Use a private LAN address such as 192.168.1.100 or device.local.');
+  }
+  return url;
+}
+
+function ConnectionCard({ space, title, initialUrl, description }: {
+  space: AddressSpace; title: string; initialUrl: string; description: string;
+}) {
+  const id = useId();
+  const permissionName = space === 'local' ? 'local-network' : 'loopback-network';
+  const [url, setUrl] = useState(initialUrl);
+  const [permission, setPermission] = useState<PermissionState | 'unavailable'>('unavailable');
+  const [secure, setSecure] = useState<boolean | null>(null);
+  const [pending, setPending] = useState(false);
+  const [result, setResult] = useState({ kind: 'idle', message: 'Not connected. No requests sent.' });
+  const [invalid, setInvalid] = useState(false);
+  const requestRef = useRef<AbortController | null>(null);
+
+  useEffect(() => {
+    setSecure(window.isSecureContext);
+    let active = true;
+    let status: PermissionStatus | undefined;
+    const updatePermission = () => {
+      if (!active || !status) return;
+      setPermission(status.state);
+      if (status.state === 'denied') {
+        requestRef.current?.abort();
+        setResult({ kind: 'error', message: 'Access blocked. Allow this network permission in browser site settings, then reconnect.' });
+      }
+    };
+    async function watchPermission() {
+      try {
+        // New permission names may be absent from TypeScript's DOM types or the browser.
+        status = await navigator.permissions.query({ name: permissionName as PermissionName });
+        if (!active) return;
+        updatePermission();
+        status.addEventListener('change', updatePermission);
+      } catch {
+        // Unknown permissions still allow an explicit, user-initiated attempt.
+        if (active) setPermission('unavailable');
+      }
+    }
+    void watchPermission();
+    return () => {
+      active = false;
+      status?.removeEventListener('change', updatePermission);
+      requestRef.current?.abort();
+    };
+  }, [permissionName]);
+
+  async function connect(event: FormEvent<HTMLFormElement>) {
+    event.preventDefault();
+    if (requestRef.current) return;
+    if (!window.isSecureContext) {
+      setResult({ kind: 'error', message: 'Open The DevTools Times over HTTPS to use browser network connections.' });
+      return;
+    }
+    if (permission === 'denied') {
+      setResult({ kind: 'error', message: `Allow ${permissionName} in browser site settings, then reconnect.` });
+      return;
+    }
+    let endpoint: URL;
+    try {
+      endpoint = validateEndpoint(url, space);
+    } catch (error) {
+      setInvalid(true);
+      setResult({ kind: 'error', message: error instanceof TypeError ? 'Enter a complete endpoint URL, including http:// or https://.' : (error as Error).message });
+      event.currentTarget.querySelector('input')?.focus();
+      return;
+    }
+    const controller = new AbortController();
+    requestRef.current = controller;
+    setPending(true);
+    setInvalid(false);
+    setResult({ kind: 'pending', message: 'Connecting… Allow the browser permission prompt if shown.' });
+    let timedOut = false;
+    const timeout = window.setTimeout(() => { timedOut = true; controller.abort(); }, 30000);
+    const started = performance.now();
+    try {
+      const options: NetworkRequestInit = {
+        method: 'GET', mode: 'cors', credentials: 'omit', cache: 'no-store',
+        redirect: 'error', referrerPolicy: 'no-referrer',
+        targetAddressSpace: space, signal: controller.signal,
+      };
+      const response = await fetch(endpoint.href, options);
+      // Only check reachability; never render or retain device response data.
+      if (response.body) void response.body.cancel().catch(() => {});
+      if (!response.ok) throw new Error(`Endpoint responded with HTTP ${response.status}. Check the URL and service health, then retry.`);
+      setResult({ kind: 'success', message: `Connected · HTTP ${response.status} · ${Math.round(performance.now() - started)} ms. Last check: ${new Date().toLocaleTimeString()}.` });
+    } catch (error) {
+      if (controller.signal.aborted) {
+        setResult({ kind: 'error', message: timedOut ? 'Connection timed out after 30 seconds. Check the endpoint and try again.' : 'Connection cancelled. Check browser site permissions before retrying.' });
+      } else {
+        setResult({ kind: 'error', message: error instanceof TypeError
+          ? `Could not connect. ${space === 'local' ? 'Check that the device is powered on and on the same Wi-Fi LAN.' : 'Check that the companion CLI is running on this machine and port.'} Check browser network permissions and endpoint CORS settings. This browser may not support HTTP local connections from HTTPS.`
+          : (error as Error).message });
+      }
+    } finally {
+      window.clearTimeout(timeout);
+      requestRef.current = null;
+      setPending(false);
+    }
+  }
+
+  return (
+    <form aria-labelledby={`${id}-title`} onSubmit={connect} className="min-w-0 rounded-lg border border-gray-300 bg-white p-5">
+      <div className="mb-4 flex flex-wrap items-center justify-between gap-2">
+        <h3 id={`${id}-title`} className="font-bold text-gray-900">{title}</h3>
+        <span className="rounded border border-gray-300 px-2 py-1 font-mono text-xs text-gray-600">{space === 'local' ? 'PRIVATE LAN' : 'THIS MACHINE'}</span>
+      </div>
+      <p id={`${id}-help`} className="mb-4 text-sm text-gray-600">{description}</p>
+      <label htmlFor={`${id}-url`} className="mb-1 block text-sm font-semibold">Status endpoint URL (required)</label>
+      <input id={`${id}-url`} name="endpoint" type="url" required value={url} disabled={pending}
+        autoComplete="off" autoCapitalize="none" autoCorrect="off" spellCheck={false}
+        aria-invalid={invalid} aria-describedby={`${id}-help ${id}-result`}
+        onChange={event => { setUrl(event.target.value); setInvalid(false); setResult({ kind: 'idle', message: 'Endpoint changed. Connect to check this address.' }); }}
+        className="min-h-12 w-full rounded border border-gray-500 bg-white px-3 py-2 font-mono text-base text-gray-900 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-amber-700 disabled:bg-gray-100" />
+      <p className="mt-2 text-xs text-gray-600">Permission: {permission === 'unavailable' ? 'checked by browser when connecting' : permission} · {permissionName}</p>
+      {permission === 'denied' && <p className="mt-2 text-sm text-red-800">Open browser site settings and allow {space === 'local' ? 'Local network' : 'Loopback network'} access, then reconnect.</p>}
+      <div className="mt-4 flex flex-wrap gap-3">
+        <button type="submit" disabled={pending || secure !== true} className="min-h-12 rounded bg-gray-900 px-4 py-2 text-sm font-semibold text-white hover:bg-gray-700 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-amber-700 disabled:cursor-not-allowed disabled:opacity-50">{pending ? 'Connecting…' : 'Connect'}</button>
+        {pending && <button type="button" onClick={() => requestRef.current?.abort()} className="min-h-12 rounded border border-gray-500 px-4 py-2 text-sm font-semibold focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-amber-700">Cancel</button>}
+      </div>
+      <p id={`${id}-result`} role="status" aria-atomic="true" className={`mt-3 break-words text-sm ${result.kind === 'error' ? 'text-red-800' : result.kind === 'success' ? 'text-green-800' : 'text-gray-600'}`}>{result.message}</p>
+      {secure === false && <p className="mt-2 text-sm text-red-800">HTTPS is required. Open this site over HTTPS to connect.</p>}
+    </form>
+  );
+}
+
+export default function DeveloperDiagnostics() {
+  return (
+    <section aria-labelledby="developer-diagnostics" className="mx-4 my-6 border-t-4 border-gray-900 bg-gray-50 p-4 sm:mx-6 sm:p-6">
+      <p className="mb-1 text-xs font-bold uppercase tracking-widest text-amber-800">The developer’s workbench</p>
+      <h2 id="developer-diagnostics" className="font-brand text-3xl text-gray-900">Developer diagnostics</h2>
+      <p className="mt-2 max-w-3xl text-sm leading-6 text-gray-600">Connect your browser to a hardware test device or your local companion CLI. Each button sends one GET request to the status endpoint you choose. Your browser may ask for network access.</p>
+      <div className="mt-5 grid gap-4 lg:grid-cols-2">
+        <ConnectionCard space="local" title="Hardware test device" initialUrl="http://192.168.1.100:8080/api/status" description="Use a device on your private Wi-Fi LAN. Enter its address, port, and read-only status path." />
+        <ConnectionCard space="loopback" title="Companion CLI" initialUrl="http://127.0.0.1:45678/health" description="Start your companion CLI on this computer. Enter its loopback address, port, and health path." />
+      </div>
+      <details className="mt-4 text-sm text-gray-600">
+        <summary className="cursor-pointer py-2 font-semibold text-gray-800 focus-visible:outline-2 focus-visible:outline-amber-700">Connection requirements & troubleshooting</summary>
+        <div className="mt-2 space-y-2 leading-6">
+          <p>Serve this page over HTTPS. Allow Local network access for hardware and Loopback network access for the CLI in browser site settings. Permission support varies by browser; an unavailable permission query still lets you try with Connect.</p>
+          <p>Your device or CLI must expose a read-only HTTP(S) status endpoint and return an Access-Control-Allow-Origin header allowing this site’s origin. Browser permission does not replace CORS. Requests omit credentials and do not follow redirects.</p>
+          <p>The example ports and paths are configurable defaults. A successful check confirms an HTTP response at that moment; it does not maintain a live connection. Requests go directly from your browser to the endpoint.</p>
+        </div>
+      </details>
+      <noscript><p className="mt-4">Enable JavaScript to use developer diagnostics. No connection requests are sent without it.</p></noscript>
+    </section>
+  );
+}
