diff --git a/src/components/DiagnosticsConnections.tsx b/src/components/DiagnosticsConnections.tsx
new file mode 100644
index 0000000..2aa24e2
--- /dev/null
+++ b/src/components/DiagnosticsConnections.tsx
@@ -0,0 +1,149 @@
+import { useEffect, useId, useRef, useState } from 'react';
+import { CommandLineIcon, CpuChipIcon, ArrowUpRightIcon, SignalIcon } from '@heroicons/react/24/outline';
+import './DiagnosticsConnections.css';
+
+type Status = 'idle' | 'checking' | 'connected' | 'error';
+type Target = 'device' | 'cli';
+
+function validateEndpoint(value: string, target: Target): string {
+  const url = new URL(value);
+  if (!['http:', 'https:'].includes(url.protocol) || url.username || url.password || url.hash) {
+    throw new Error('Use an HTTP or HTTPS health URL without credentials or a fragment.');
+  }
+  const host = url.hostname;
+  const octets = host.split('.').map(Number);
+  const ipv4 = /^\d+\.\d+\.\d+\.\d+$/.test(host) && octets.every(n => n >= 0 && n <= 255);
+  const loopback = host === 'localhost' || host === '[::1]' || (ipv4 && octets[0] === 127);
+  const privateLan = ipv4 && (octets[0] === 10 || (octets[0] === 192 && octets[1] === 168) ||
+    (octets[0] === 172 && octets[1] >= 16 && octets[1] <= 31));
+  if (target === 'cli' ? !loopback : !privateLan) {
+    throw new Error(target === 'cli'
+      ? 'Use a loopback address: 127.0.0.1, localhost, or [::1].'
+      : 'Use a private LAN IPv4 address: 192.168.x.x, 10.x.x.x, or 172.16–31.x.x.');
+  }
+  return url.href;
+}
+
+function ConnectionCard({ target }: { target: Target }) {
+  const device = target === 'device';
+  const id = useId();
+  const [endpoint, setEndpoint] = useState(device ? 'http://192.168.1.100:8080/health' : 'http://127.0.0.1:4318/health');
+  const [activeUrl, setActiveUrl] = useState<string | null>(null);
+  const [status, setStatus] = useState<Status>('idle');
+  const [message, setMessage] = useState('Ready when you are.');
+  const [lastCheck, setLastCheck] = useState('');
+  const controller = useRef<AbortController | null>(null);
+
+  useEffect(() => {
+    if (!activeUrl) return;
+    let disposed = false;
+    let nextCheck: ReturnType<typeof setTimeout>;
+    let deadline: ReturnType<typeof setTimeout>;
+    async function check() {
+      const request = new AbortController();
+      controller.current = request;
+      let timedOut = false;
+      deadline = setTimeout(() => { timedOut = true; request.abort(); }, 8000);
+      const started = performance.now();
+      try {
+        const response = await fetch(activeUrl!, {
+          method: 'GET', mode: 'cors', credentials: 'omit', cache: 'no-store',
+          redirect: 'error', signal: request.signal,
+        });
+        // Only the HTTP status is needed; do not retain diagnostic payloads.
+        void response.body?.cancel().catch(() => {});
+        if (!response.ok) throw new Error(`Health endpoint returned HTTP ${response.status}.`);
+        if (disposed) return;
+        setStatus('connected');
+        setMessage(`Endpoint reachable · ${Math.round(performance.now() - started)} ms`);
+        setLastCheck(new Date().toLocaleTimeString());
+        nextCheck = setTimeout(check, 15000);
+      } catch (error) {
+        if (disposed || (request.signal.aborted && !timedOut)) return;
+        setStatus('error');
+        setMessage(timedOut ? 'Timed out after 8 seconds. Check the address and that the service is running.'
+          : error instanceof TypeError ? 'Could not reach the endpoint. Check the service, CORS, browser network permission, and HTTPS settings.'
+          : error instanceof Error ? error.message : 'Connection failed. Try again.');
+        setActiveUrl(null);
+      } finally {
+        clearTimeout(deadline);
+      }
+    }
+    void check();
+    return () => {
+      disposed = true;
+      clearTimeout(nextCheck);
+      clearTimeout(deadline);
+      controller.current?.abort();
+    };
+  }, [activeUrl]);
+
+  function connect(event: React.FormEvent) {
+    event.preventDefault();
+    try {
+      const url = validateEndpoint(endpoint.trim(), target);
+      setStatus('checking');
+      setMessage('Waiting for the health endpoint…');
+      setLastCheck('');
+      setActiveUrl(url);
+    } catch (error) {
+      setStatus('error');
+      setMessage(error instanceof TypeError ? 'Enter a complete URL, including http:// or https://.' : (error as Error).message);
+    }
+  }
+
+  function disconnect() {
+    controller.current?.abort();
+    setActiveUrl(null);
+    setStatus('idle');
+    setMessage('Disconnected. No further requests will be sent.');
+    setLastCheck('');
+  }
+
+  const Icon = device ? CpuChipIcon : CommandLineIcon;
+  const labels = { idle: 'Not connected', checking: 'Connecting', connected: 'Connected', error: 'Connection failed' };
+  return (
+    <article className="diagnostics-card">
+      <div className="diagnostics-card-heading">
+        <span className="diagnostics-icon"><Icon aria-hidden="true" /></span>
+        <span className={`diagnostics-status diagnostics-status-${status}`}><i aria-hidden="true" />{labels[status]}</span>
+      </div>
+      <h3>{device ? 'Hardware test device' : 'Companion CLI'}</h3>
+      <p className="diagnostics-description">{device ? 'Reach a device on the same Wi-Fi network.' : 'Connect to the CLI running on this computer.'}</p>
+      <form onSubmit={connect}>
+        <label htmlFor={id}>{device ? 'Device health URL' : 'CLI health URL'}</label>
+        <input id={id} type="url" value={endpoint} required disabled={!!activeUrl}
+          spellCheck={false} autoCapitalize="none" autoComplete="off" aria-describedby={`${id}-feedback`}
+          onChange={event => setEndpoint(event.target.value)} />
+        {activeUrl ? <button type="button" className="diagnostics-disconnect" onClick={disconnect}>{status === 'checking' ? 'Cancel connection' : 'Disconnect'}</button>
+          : <button type="submit">{status === 'error' ? 'Retry connection' : device ? 'Connect device' : 'Connect CLI'}<ArrowUpRightIcon aria-hidden="true" /></button>}
+      </form>
+      <div id={`${id}-feedback`} className={`diagnostics-feedback ${status === 'error' ? 'diagnostics-feedback-error' : ''}`} role="status" aria-live="polite">
+        {message}{lastCheck && <span>Last checked {lastCheck} · Checks every 15s</span>}
+      </div>
+    </article>
+  );
+}
+
+export default function DiagnosticsConnections() {
+  return (
+    <section className="diagnostics" aria-labelledby="diagnostics-title">
+      <div className="diagnostics-heading">
+        <div><p className="diagnostics-eyebrow"><SignalIcon aria-hidden="true" />THE DEVELOPER WORKBENCH</p>
+          <h2 id="diagnostics-title">Your tools. Connected.</h2></div>
+        <span className="diagnostics-browser-label">BROWSER → LOCAL NETWORK</span>
+      </div>
+      <p className="diagnostics-intro">Bring your test bench into the browser. Connect a hardware device and your local CLI to check that they’re reachable.</p>
+      <div className="diagnostics-grid"><ConnectionCard target="device" /><ConnectionCard target="cli" /></div>
+      <details className="diagnostics-help">
+        <summary>Connection setup & troubleshooting</summary>
+        <div>
+          <p>Use your service’s actual health URL and port; the prefilled addresses are examples. Each endpoint must accept GET and return a successful HTTP status (200–299). No response format is required.</p>
+          <p>For hardware, join the same Wi-Fi network. For the CLI, start your companion service on this computer and use its loopback address.</p>
+          <p>Allow local network access if your browser requests it. Configure each service’s CORS policy to allow this site’s origin. An HTTPS page may require an HTTPS device endpoint with a trusted certificate; your browser may block HTTP requests. Check the browser console for details.</p>
+          <p>Requests go directly from this browser to the address you enter, without cookies or credentials. Addresses stay in this widget for this visit. Disconnect stops health checks.</p>
+        </div>
+      </details>
+    </section>
+  );
+}
