+import { snapshot, restore, sameOrigin } from './settings.js';
+
+async function setup() {
+  const response = await fetch('/migration-config.json', { cache: 'no-store' });
+  // A source-only checkout has no migration target; leave the original page usable.
+  if (!response.ok) return;
+  const config = await response.json();
+  const { oldOrigin, newOrigin, settingsKeys, role } = config;
+  if (!sameOrigin(location.origin, role === 'old' ? oldOrigin : newOrigin)) return;
+  const panel = document.createElement('section');
+  panel.className = 'container migration';
+  panel.setAttribute('aria-label', 'App migration');
+  const heading = document.createElement('h2');
+  heading.textContent = role === 'old' ? 'The Daily Grind is moving' : 'Welcome to our new home';
+  const description = document.createElement('p');
+  description.textContent = role === 'old'
+    ? 'Move your saved preferences to our new address. Keep this window open until the transfer finishes.'
+    : 'Your browser may offer to update your installed app and shortcuts. You can also restore a settings backup here.';
+  const status = document.createElement('p');
+  status.setAttribute('role', 'status');
+  panel.append(heading, description, status);
+  document.querySelector('main').prepend(panel);
+  const button = (label, action) => {
+    const element = document.createElement('button');
+    element.className = 'btn';
+    element.textContent = label;
+    element.addEventListener('click', action);
+    panel.append(element);
+    return element;
+  };
+  const report = action => { try { action(); } catch { status.textContent = 'Settings could not be saved. Keep your backup and try again with browser storage enabled.'; } };
+  button('Download settings backup', () => report(() => {
+    const blob = new Blob([JSON.stringify(snapshot(localStorage, settingsKeys))], { type: 'application/json' });
+    const url = URL.createObjectURL(blob);
+    const link = document.createElement('a');
+    link.href = url;
+    link.download = 'daily-grind-settings.json';
+    link.click();
+    setTimeout(() => URL.revokeObjectURL(url), 1000);
+  }));
+  const label = document.createElement('label');
+  label.textContent = ' Restore settings backup (replaces matching preferences): ';
+  const input = document.createElement('input');
+  input.type = 'file';
+  input.accept = '.json,application/json';
+  input.addEventListener('change', async () => {
+    try {
+      const file = input.files[0];
+      if (!file) return;
+      if (file.size > 1000000) throw new Error('Backup too large');
+      restore(localStorage, settingsKeys, JSON.parse(await file.text()));
+      status.textContent = 'Your settings have been restored.';
+    } catch { status.textContent = 'Unable to restore this backup. Check the file and available browser storage.'; }
+  });
+  label.append(input);
+  panel.append(label);
+
+  if (role === 'old') {
+    let peer, token, expiry;
+    const transfer = button('Transfer settings and open new app', () => {
+      clearTimeout(expiry);
+      token = crypto.randomUUID();
+      const target = new URL('/', newOrigin);
+      target.hash = `migration=${token}`;
+      peer = window.open(target.href, '_blank');
+      status.textContent = peer ? 'Waiting for the new app…' : 'The popup was blocked. Download a backup, open the new address below, and restore it there.';
+      transfer.disabled = Boolean(peer);
+      expiry = setTimeout(() => {
+        peer = null;
+        token = null;
+        transfer.disabled = false;
+        status.textContent = 'Transfer was not confirmed. Retry, or use a settings backup. Your original settings are still here.';
+      }, 60000);
+    });
+    window.addEventListener('message', event => {
+      if (!peer || event.source !== peer || !sameOrigin(event.origin, newOrigin) || event.data?.token !== token) return;
+      if (event.data.type === 'daily-grind:ready') report(() => peer.postMessage({ type: 'daily-grind:settings', token, payload: snapshot(localStorage, settingsKeys) }, newOrigin));
+      if (event.data.type === 'daily-grind:saved') {
+        clearTimeout(expiry);
+        peer = null;
+        token = null;
+        transfer.disabled = false;
+        status.textContent = 'Settings transferred. Continue in the new app. Your original settings are retained here.';
+      }
+    });
+    const link = document.createElement('a');
+    link.href = newOrigin;
+    link.textContent = ` Open the new app at ${newOrigin}`;
+    panel.append(link);
+    const fallback = document.createElement('p');
+    fallback.textContent = 'If your browser does not offer an app update, restore your backup at the new address and install it using the browser menu. Existing shortcuts cannot be moved automatically in unsupported browsers.';
+    panel.append(fallback);
+  } else {
+    const token = new URLSearchParams(location.hash.slice(1)).get('migration');
+    const source = window.opener;
+    if (source && token) {
+      history.replaceState(null, '', location.pathname + location.search);
+      const receive = event => {
+        if (event.source !== source || !sameOrigin(event.origin, oldOrigin) || event.data?.token !== token || event.data?.type !== 'daily-grind:settings') return;
+        report(() => {
+          restore(localStorage, settingsKeys, event.data.payload);
+          source.postMessage({ type: 'daily-grind:saved', token }, oldOrigin);
+          status.textContent = 'Your settings have been transferred successfully.';
+          window.removeEventListener('message', receive);
+        });
+      };
+      window.addEventListener('message', receive);
+      source.postMessage({ type: 'daily-grind:ready', token }, oldOrigin);
+      setTimeout(() => window.removeEventListener('message', receive), 60000);
+    }
+  }
+}
+setup().catch(() => console.warn('App migration is unavailable. The coffee shop remains available.'));
