+import { mkdir, writeFile, copyFile, rm } from 'node:fs/promises';
+import { getDomain } from 'tldts';
+
+export function migrationConfig(env = process.env) {
+  const old = new URL(env.OLD_APP_ORIGIN || 'https://app.dailygrind.example');
+  const next = new URL(env.NEW_APP_ORIGIN || 'https://new.dailygrind.example');
+  for (const url of [old, next]) {
+    if (url.protocol !== 'https:' || url.username || url.password || url.pathname !== '/' || url.search || url.hash) {
+      throw new Error('Migration origins must be bare HTTPS origins.');
+    }
+  }
+  const domain = getDomain(old.hostname, { allowPrivateDomains: true });
+  if (!domain || domain !== getDomain(next.hostname, { allowPrivateDomains: true }) || old.origin === next.origin) {
+    throw new Error('Migration requires distinct origins on the same registrable domain.');
+  }
+  // This app previously had no manifest: its root start URL is its default identity.
+  return { oldOrigin: old.origin, newOrigin: next.origin, settingsKeys: ['daily-grind:settings', 'daily-grind:preferences'] };
+}
+
+export async function build(env = process.env) {
+  const config = migrationConfig(env);
+  await rm('dist', { recursive: true, force: true });
+  const base = { name: 'The Daily Grind', short_name: 'Daily Grind', id: '/', start_url: '/', scope: '/', display: 'standalone', background_color: '#fafafa', theme_color: '#4e342e', icons: [{ src: '/icon.svg', sizes: 'any', type: 'image/svg+xml', purpose: 'any' }] };
+  for (const role of ['old', 'new']) {
+    const directory = `dist/${role}`;
+    await mkdir(`${directory}/.well-known`, { recursive: true });
+    for (const file of ['index.html', 'migration.js', 'settings.js', 'icon.svg']) await copyFile(file, `${directory}/${file}`);
+    const migration = role === 'old'
+      ? { migrate_to: { id: `${config.newOrigin}/`, install_url: `${config.newOrigin}/` } }
+      : { migrate_from: [{ id: `${config.oldOrigin}/` }] };
+    await writeFile(`${directory}/manifest.webmanifest`, JSON.stringify({ ...base, ...migration }, null, 2));
+    await writeFile(`${directory}/migration-config.json`, JSON.stringify({ ...config, role }, null, 2));
+    if (role === 'old') await writeFile(`${directory}/.well-known/web-app-origin-association`, JSON.stringify({ [`${config.newOrigin}/`]: { allow_migration: true } }, null, 2));
+  }
+}
+if (process.argv[1] === new URL(import.meta.url).pathname) await build();
