+export function snapshot(storage, keys) {
+  return { app: 'daily-grind', version: 1, settings: Object.fromEntries(keys.map(key => [key, storage.getItem(key)]).filter(([, value]) => value !== null)) };
+}
+
+export function restore(storage, keys, payload) {
+  if (payload?.app !== 'daily-grind' || payload.version !== 1 || !payload.settings || typeof payload.settings !== 'object' || Array.isArray(payload.settings)) throw new Error('Invalid settings backup.');
+  const entries = Object.entries(payload.settings);
+  if (entries.some(([key, value]) => !keys.includes(key) || typeof value !== 'string') || JSON.stringify(payload).length > 1000000) throw new Error('Invalid settings backup.');
+  const previous = entries.map(([key]) => [key, storage.getItem(key)]);
+  try {
+    for (const [key, value] of entries) storage.setItem(key, value);
+  } catch (error) {
+    for (const [key, value] of previous) {
+      if (value === null) storage.removeItem(key);
+      else storage.setItem(key, value);
+    }
+    throw error;
+  }
+}
+
+export function sameOrigin(candidate, trusted) {
+  try {
+    if ('Origin' in globalThis) return Origin.from(candidate).isSameOrigin(Origin.from(trusted));
+    const url = new URL(candidate);
+    return url.origin !== 'null' && url.origin === new URL(trusted).origin;
+  } catch { return false; }
+}
