+import test from 'node:test';
+import assert from 'node:assert/strict';
+import { readFile } from 'node:fs/promises';
+import { migrationConfig, build } from '../scripts/build.mjs';
+import { snapshot, restore, sameOrigin } from '../settings.js';
+
+const storage = () => {
+  const data = new Map();
+  return { getItem: key => data.get(key) ?? null, setItem: (key, value) => data.set(key, value), removeItem: key => data.delete(key) };
+};
+test('only distinct same-site HTTPS origins can migrate', () => {
+  assert.equal(migrationConfig({ OLD_APP_ORIGIN: 'https://old.example.co.uk', NEW_APP_ORIGIN: 'https://new.example.co.uk:443' }).newOrigin, 'https://new.example.co.uk');
+  for (const [old, next] of [
+    ['https://a.github.io', 'https://b.github.io'],
+    ['https://a.co.uk', 'https://b.co.uk'],
+    ['https://app.example.com', 'https://app.example.com.attacker.com'],
+    ['https://app.example.com', 'http://new.example.com'],
+    ['https://app.example.com', 'https://app.example.com'],
+    ['https://app.example.com/path', 'https://new.example.com'],
+  ]) assert.throws(() => migrationConfig({ OLD_APP_ORIGIN: old, NEW_APP_ORIGIN: next }));
+});
+test('artifacts authorize exactly the destination manifest identity', async () => {
+  const env = { OLD_APP_ORIGIN: 'https://old.example.com', NEW_APP_ORIGIN: 'https://new.example.com' };
+  await build(env);
+  const json = async path => JSON.parse(await readFile(path, 'utf8'));
+  const old = await json('dist/old/manifest.webmanifest');
+  const next = await json('dist/new/manifest.webmanifest');
+  const association = await json('dist/old/.well-known/web-app-origin-association');
+  assert.equal(new URL(next.id, env.NEW_APP_ORIGIN).href, old.migrate_to.id);
+  assert.deepEqual(association[old.migrate_to.id], { allow_migration: true });
+  assert.equal(next.migrate_from[0].id, new URL(old.id, env.OLD_APP_ORIGIN).href);
+});
+test('settings transfer round trips selected keys without removing source', () => {
+  const old = storage(), next = storage();
+  old.setItem('daily-grind:settings', '{"theme":"dark"}');
+  old.setItem('session-token', 'secret');
+  const keys = ['daily-grind:settings'];
+  const data = snapshot(old, keys);
+  restore(next, keys, data);
+  assert.equal(next.getItem(keys[0]), old.getItem(keys[0]));
+  assert.equal(next.getItem('session-token'), null);
+  assert.throws(() => restore(next, keys, { ...data, settings: { 'session-token': 'bad' } }));
+  assert.throws(() => restore(next, keys, { ...data, settings: { [keys[0]]: {} } }));
+});
+test('failed writes roll back changed settings', () => {
+  const target = storage();
+  target.setItem('a', 'original');
+  const write = target.setItem;
+  target.setItem = (key, value) => { if (key === 'b') throw new Error('quota'); write(key, value); };
+  assert.throws(() => restore(target, ['a', 'b'], { app: 'daily-grind', version: 1, settings: { a: 'new', b: 'new' } }));
+  assert.equal(target.getItem('a'), 'original');
+  assert.equal(target.getItem('b'), null);
+});
+test('message origins reject opaque, deceptive and different port senders', () => {
+  assert.equal(sameOrigin('https://new.example.com:443', 'https://new.example.com'), true);
+  for (const value of ['null', 'data:text/plain,hello', 'https://new.example.com.evil.com', 'https://new.example.com:444']) assert.equal(sameOrigin(value, 'https://new.example.com'), false);
+});

