+// Only the declared successor may request the explicitly allowed preferences.
+window.addEventListener('message', event => {
+  if (location.origin !== migrationConfig.oldOrigin ||
+      event.origin !== migrationConfig.newOrigin || event.source !== window.parent ||
+      event.data?.type !== 'daily-grind:request-preferences' ||
+      typeof event.data.nonce !== 'string') return;
+  const response = { type: 'daily-grind:preferences', nonce: event.data.nonce };
+  try {
+    response.values = migrationConfig.keys.map(key => [key, localStorage.getItem(key)]);
+  } catch {
+    response.error = 'Preferences storage is unavailable.';
+  }
+  event.source.postMessage(response, migrationConfig.newOrigin);
+});
