@@ -0,0 +1,68 @@
+(() => {
+  const { oldOrigin, newOrigin, role, keys } = migrationConfig;
+  if (location.origin !== (role === 'old' ? oldOrigin : newOrigin)) return;
+  const banner = document.createElement('aside');
+  banner.setAttribute('aria-live', 'polite');
+  banner.style.cssText = 'padding:14px 5%;background:#fff3df;color:#3e2723;text-align:center;font:14px/1.6 system-ui';
+  document.body.prepend(banner);
+  if (role === 'old') {
+    banner.append('The Daily Grind is moving. ');
+    const link = document.createElement('a');
+    link.href = newOrigin;
+    link.textContent = 'Continue to our new address';
+    banner.append(link, '. Keep this app installed to receive its browser-managed update.');
+    return;
+  }
+  const marker = `daily-grind:migrated:${oldOrigin}`;
+  try {
+    if (localStorage.getItem(marker) === '1') { banner.remove(); return; }
+  } catch { /* Report storage failure through the transfer UI below. */ }
+
+  function transfer() {
+    banner.textContent = 'Restoring your coffee preferences…';
+    const nonce = crypto.randomUUID();
+    const frame = document.createElement('iframe');
+    frame.hidden = true;
+    frame.title = 'Transfer saved preferences';
+    frame.src = `${oldOrigin}/migration-bridge.html`;
+    let timer;
+    function finish(error) {
+      clearTimeout(timer);
+      window.removeEventListener('message', receive);
+      frame.remove();
+      if (!error) { banner.remove(); return; }
+      banner.textContent = 'Your saved preferences could not be transferred. They remain available at the old address. ';
+      const retry = document.createElement('button');
+      retry.type = 'button';
+      retry.textContent = 'Try again';
+      retry.addEventListener('click', transfer, { once: true });
+      const source = document.createElement('a');
+      source.href = oldOrigin;
+      source.textContent = 'Open old address';
+      banner.append(retry, ' ', source);
+    }
+    function receive(event) {
+      if (event.origin !== oldOrigin || event.source !== frame.contentWindow ||
+          event.data?.type !== 'daily-grind:preferences' || event.data.nonce !== nonce) return;
+      if (event.data.error || !Array.isArray(event.data.values)) { finish(true); return; }
+      const values = event.data.values;
+      if (values.length !== keys.length || values.some((entry, index) =>
+        !Array.isArray(entry) || entry.length !== 2 || entry[0] !== keys[index] ||
+        !(entry[1] === null || typeof entry[1] === 'string'))) { finish(true); return; }
+      try {
+        for (const [key, value] of values) {
+          // Existing destination preferences always take precedence. Never delete source data.
+          if (value !== null && localStorage.getItem(key) === null) localStorage.setItem(key, value);
+        }
+        // An empty response may mean iframe storage is partitioned. Allow future retries.
+        if (values.some(([, value]) => value !== null) || keys.length === 0) localStorage.setItem(marker, '1');
+        finish(values.length > 0 && values.every(([, value]) => value === null));
+      } catch { finish(true); }
+    }
+    window.addEventListener('message', receive);
+    frame.addEventListener('load', () => frame.contentWindow.postMessage({ type: 'daily-grind:request-preferences', nonce }, oldOrigin), { once: true });
+    timer = setTimeout(() => finish(true), 8000);
+    document.body.append(frame);
+  }
+  transfer();
+})();
