+import { mkdir, readFile, writeFile } from 'node:fs/promises';
+import { resolve } from 'node:path';
+import { pathToFileURL } from 'node:url';
+
+function origin(value, label) {
+  if (!value) throw new Error(`${label} is required. See README.md.`);
+  const url = new URL(value);
+  if (url.protocol !== 'https:' || url.username || url.password ||
+      url.pathname !== '/' || url.search || url.hash) {
+    throw new Error(`${label} must be an HTTPS origin without a path, credentials, query or fragment.`);
+  }
+  return url.origin;
+}
+
+export function configuration(env) {
+  const oldOrigin = origin(env.OLD_ORIGIN, 'OLD_ORIGIN');
+  const newOrigin = origin(env.NEW_ORIGIN, 'NEW_ORIGIN');
+  if (oldOrigin === newOrigin) throw new Error('Origins must be different.');
+  const oldId = new URL(env.OLD_APP_ID || '/', `${oldOrigin}/`);
+  if (oldId.origin !== oldOrigin || oldId.hash || oldId.username || oldId.password) {
+    throw new Error('OLD_APP_ID must belong to OLD_ORIGIN and have no fragment or credentials.');
+  }
+  const keys = JSON.parse(env.CONFIG_KEYS || '["daily-grind:preferences"]');
+  if (!Array.isArray(keys) || keys.some(key => typeof key !== 'string' || !key)) {
+    throw new Error('CONFIG_KEYS must be a JSON array of nonempty localStorage key names.');
+  }
+  return { oldOrigin, newOrigin, oldId: oldId.href, keys: [...new Set(keys)] };
+}
+
+export function manifests(config) {
+  const base = {
+    name: 'The Daily Grind', short_name: 'Daily Grind',
+    start_url: '/', scope: '/', display: 'standalone',
+    background_color: '#fafafa', theme_color: '#4e342e',
+    icons: [192, 512].map(size => ({ src: `/icon-${size}.png`, sizes: `${size}x${size}`, type: 'image/png' })),
+    shortcuts: [
+      { name: 'Order coffee', url: '/order-online' },
+      { name: 'My account', url: '/account' },
+    ],
+  };
+  return {
+    old: { ...base, id: config.oldId, migrate_to: { id: `${config.newOrigin}/`, install_url: `${config.newOrigin}/` } },
+    new: { ...base, id: '/', migrate_from: [{ id: config.oldId, install_url: `${config.oldOrigin}/migration-install.html`, behavior: 'suggest' }] },
+  };
+}
+
+export async function build(env = process.env, output = resolve('dist')) {
+  const config = configuration(env);
+  const manifest = manifests(config);
+  const html = await readFile(new URL('../index.html', import.meta.url), 'utf8');
+  const script = await readFile(new URL('../migration/client.js', import.meta.url), 'utf8');
+  const bridge = await readFile(new URL('../migration/bridge.js', import.meta.url), 'utf8');
+  const { icon } = await import('./icon.mjs');
+  for (const role of ['old', 'new']) {
+    const root = resolve(output, role);
+    await mkdir(resolve(root, '.well-known'), { recursive: true });
+    const settings = JSON.stringify({ ...config, role });
+    await writeFile(resolve(root, 'index.html'), html);
+    await writeFile(resolve(root, 'manifest.webmanifest'), JSON.stringify(manifest[role], null, 2));
+    await writeFile(resolve(root, 'migration.js'), `const migrationConfig = ${settings};\n${script}`);
+    for (const size of [192, 512]) await writeFile(resolve(root, `icon-${size}.png`), icon(size));
+    if (role === 'old') {
+      await writeFile(resolve(root, '.well-known/web-app-origin-association'), JSON.stringify({ [`${config.newOrigin}/`]: { allow_migration: true } }, null, 2));
+      await writeFile(resolve(root, 'migration-install.html'), html);
+      await writeFile(resolve(root, 'migration-bridge.html'), '<!doctype html><html lang="en"><meta charset="utf-8"><title>Transfer preferences</title><script src="/migration-bridge.js" defer></script></html>');
+      await writeFile(resolve(root, 'migration-bridge.js'), `const migrationConfig = ${settings};\n${bridge}`);
+    }
+  }
+  return config;
+}
+
+if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) {
+  await build();
+  console.log('Built dist/old and dist/new. Deploy as described in README.md.');
+}
