--- /dev/null
+++ b/scripts/icon.mjs
@@ -0,0 +1,40 @@
+import { deflateSync } from 'node:zlib';
+
+// Small, dependency-free coffee cup icon for the static installation bundles.
+export function icon(size) {
+  const crc = bytes => {
+    let value = 0xffffffff;
+    for (const byte of bytes) {
+      value ^= byte;
+      for (let bit = 0; bit < 8; bit++) value = (value >>> 1) ^ (0xedb88320 & -(value & 1));
+    }
+    return (value ^ 0xffffffff) >>> 0;
+  };
+  const chunk = (name, data) => {
+    const body = Buffer.concat([Buffer.from(name), data]);
+    const length = Buffer.alloc(4);
+    length.writeUInt32BE(data.length);
+    const checksum = Buffer.alloc(4);
+    checksum.writeUInt32BE(crc(body));
+    return Buffer.concat([length, body, checksum]);
+  };
+  const header = Buffer.alloc(13);
+  header.writeUInt32BE(size, 0);
+  header.writeUInt32BE(size, 4);
+  header[8] = 8;
+  header[9] = 2;
+  const pixels = Buffer.alloc((size * 3 + 1) * size);
+  for (let y = 0; y < size; y++) {
+    for (let x = 0; x < size; x++) {
+      const u = x / size, v = y / size;
+      const cup = u > .25 && u < .65 && v > .35 && v < .68;
+      const handle = ((u - .66) ** 2 + (v - .48) ** 2 < .11 ** 2) &&
+        ((u - .66) ** 2 + (v - .48) ** 2 > .065 ** 2);
+      const saucer = u > .22 && u < .73 && v > .72 && v < .76;
+      const color = cup || handle || saucer ? [250, 250, 250] : [78, 52, 46];
+      const offset = y * (size * 3 + 1) + 1 + x * 3;
+      pixels.set(color, offset);
+    }
+  }
+  return Buffer.concat([Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]), chunk('IHDR', header), chunk('IDAT', deflateSync(pixels)), chunk('IEND', Buffer.alloc(0))]);
+}
