new file mode 100644
index 0000000..b71b56f
--- /dev/null
+++ b/test/migration.test.mjs
@@ -0,0 +1,110 @@
+import test from 'node:test';
+import assert from 'node:assert/strict';
+import { mkdtemp, readFile, rm } from 'node:fs/promises';
+import { tmpdir } from 'node:os';
+import { join } from 'node:path';
+import vm from 'node:vm';
+import { build, configuration } from '../scripts/build-migration.mjs';
+
+const env = { OLD_ORIGIN: 'https://www.example.com', NEW_ORIGIN: 'https://coffee.example.com', OLD_APP_ID: '/installed-app', CONFIG_KEYS: '["theme","orders"]' };
+
+test('requires explicit HTTPS origins and validates configuration', () => {
+  for (const change of [
+    { OLD_ORIGIN: '' }, { NEW_ORIGIN: 'http://coffee.example.com' },
+    { NEW_ORIGIN: env.OLD_ORIGIN }, { OLD_ORIGIN: `${env.OLD_ORIGIN}/path` },
+    { OLD_APP_ID: 'https://attacker.example/' }, { CONFIG_KEYS: '[42]' },
+  ]) assert.throws(() => configuration({ ...env, ...change }));
+});
+
+test('builds reciprocal identities, authorization, discoverable manifests and real icons', async () => {
+  const output = await mkdtemp(join(tmpdir(), 'daily-grind-'));
+  try {
+    await build(env, output);
+    const json = async path => JSON.parse(await readFile(join(output, path), 'utf8'));
+    const old = await json('old/manifest.webmanifest');
+    const successor = await json('new/manifest.webmanifest');
+    const association = await json('old/.well-known/web-app-origin-association');
+    assert.equal(old.id, `${env.OLD_ORIGIN}/installed-app`);
+    assert.equal(old.migrate_to.id, `${env.NEW_ORIGIN}/`);
+    assert.equal(successor.id, '/');
+    assert.equal(successor.migrate_from[0].id, old.id);
+    assert.equal(successor.migrate_from[0].behavior, 'suggest');
+    assert.deepEqual(association[old.migrate_to.id], { allow_migration: true });
+    assert.match(await readFile(join(output, 'old/migration-install.html'), 'utf8'), /rel="manifest" href="\/manifest.webmanifest"/);
+    assert.match(await readFile(join(output, 'new/index.html'), 'utf8'), /src="\/migration.js"/);
+    const png = await readFile(join(output, 'new/icon-192.png'));
+    assert.equal(png.readUInt32BE(16), 192);
+    assert.equal(png.subarray(1, 4).toString(), 'PNG');
+  } finally { await rm(output, { recursive: true, force: true }); }
+});
+
+test('bridge rejects foreign origins and windows and exports only allowed preferences', async () => {
+  const source = await readFile(new URL('../migration/bridge.js', import.meta.url), 'utf8');
+  let receive;
+  const sent = [];
+  const parent = { postMessage: (...args) => sent.push(args) };
+  vm.runInNewContext(source, {
+    migrationConfig: configuration(env), location: { origin: env.OLD_ORIGIN },
+    window: { parent, addEventListener: (_, fn) => { receive = fn; } },
+    localStorage: { getItem: key => ({ theme: 'dark', orders: '[]', token: 'secret' })[key] ?? null },
+  });
+  const request = { origin: env.NEW_ORIGIN, source: parent, data: { type: 'daily-grind:request-preferences', nonce: 'request-1' } };
+  receive({ ...request, origin: 'https://attacker.example' });
+  receive({ ...request, source: { postMessage() { assert.fail('untrusted window'); } } });
+  assert.equal(sent.length, 0);
+  receive(request);
+  assert.equal(sent[0][1], env.NEW_ORIGIN);
+  assert.deepEqual(JSON.parse(JSON.stringify(sent[0][0])), {
+    type: 'daily-grind:preferences', nonce: 'request-1', values: [['theme', 'dark'], ['orders', '[]']],
+  });
+});
+
+async function clientHarness(initial = {}) {
+  const source = await readFile(new URL('../migration/client.js', import.meta.url), 'utf8');
+  const listeners = new Map();
+  const nodes = [];
+  const storage = new Map(Object.entries(initial));
+  const document = {
+    createElement(tag) {
+      const node = { tag, style: {}, events: {}, contentWindow: { postMessage(message) { node.request = message; } },
+        setAttribute() {}, append() {}, addEventListener(type, fn) { this.events[type] = fn; }, remove() { this.removed = true; } };
+      nodes.push(node);
+      return node;
+    },
+    body: { prepend() {}, append(frame) { frame.events.load(); } },
+  };
+  vm.runInNewContext(source, {
+    migrationConfig: { ...configuration(env), role: 'new' },
+    location: { origin: env.NEW_ORIGIN }, document,
+    crypto: { randomUUID: () => 'fresh-nonce' }, setTimeout: () => 1, clearTimeout() {},
+    localStorage: { getItem: key => storage.get(key) ?? null, setItem: (key, value) => storage.set(key, value) },
+    window: { addEventListener: (type, fn) => listeners.set(type, fn), removeEventListener: type => listeners.delete(type) },
+  });
+  const frame = nodes.find(node => node.tag === 'iframe');
+  return { storage, nodes, reply(values, overrides = {}) {
+    listeners.get('message')?.({ origin: env.OLD_ORIGIN, source: frame.contentWindow,
+      data: { type: 'daily-grind:preferences', nonce: frame.request.nonce, values }, ...overrides });
+  } };
+}
+
+test('destination verifies sender and nonce, preserves newer settings and copies missing values', async () => {
+  const client = await clientHarness({ theme: 'newer-theme' });
+  const values = [['theme', 'old-theme'], ['orders', '["latte"]']];
+  client.reply(values, { origin: 'https://attacker.example' });
+  client.reply(values, { source: {} });
+  client.reply(values, { data: { type: 'daily-grind:preferences', nonce: 'stale', values } });
+  assert.equal(client.storage.has('orders'), false);
+  client.reply(values);
+  assert.equal(client.storage.get('theme'), 'newer-theme');
+  assert.equal(client.storage.get('orders'), '["latte"]');
+  assert.equal(client.storage.get(`daily-grind:migrated:${env.OLD_ORIGIN}`), '1');
+});
+
+test('malformed and empty responses never mark migration complete', async () => {
+  for (const values of [[['token', 'secret']], [['theme', null], ['orders', null]]]) {
+    const client = await clientHarness();
+    client.reply(values);
+    assert.equal(client.storage.size, 0);
+    assert.ok(client.nodes.some(node => node.tag === 'button' && node.textContent === 'Try again'));
+  }
+});

