+    // Other in-page menu editors can dispatch window's "menu-changed" event too.
+    async function fetchHTML(path) {
+      const response = await fetch(path, {
+        headers: { Accept: 'text/html' },
+        credentials: 'same-origin',
+        cache: 'no-store',
+        redirect: 'error'
+      });
+      if (!response.ok) throw new Error(`HTML request failed: ${response.status}`);
+      const type = response.headers.get('content-type') || '';
+      if (type.split(';')[0].trim().toLowerCase() !== 'text/html') {
+        throw new Error('Expected an HTML fragment');
+      }
+      return response.text();
+    }
+
+    // Queue another fetch when a publication arrives during a refresh, so the
+    // final menu always reflects the latest notification, even during a burst.
+    let refreshing = false;
+    let refreshPending = false;
+    async function refreshMenu() {
+      refreshPending = true;
+      if (refreshing) return;
+      refreshing = true;
+      refreshButton.disabled = true;
+      cards.setAttribute('aria-busy', 'true');
+      try {
+        do {
+          refreshPending = false;
+          menuStatus.textContent = 'Refreshing seasonal favorites…';
+          const html = await fetchHTML('/api/menu/seasonal');
+          // Safe setter removes scripts and unsafe attributes, preserving the
+          // grid itself and listeners on the surrounding section.
+          cards.setHTML(html);
+          menuStatus.textContent = 'Seasonal favorites updated.';
+        } while (refreshPending);
+      } catch (error) {
+        menuStatus.textContent = 'We couldn’t refresh the menu. Please try again.';
+        console.error('Seasonal menu refresh failed', error);
+      } finally {
+        refreshing = false;
+        refreshButton.disabled = false;
+        cards.setAttribute('aria-busy', 'false');
+      }
+    }
+
+    if (typeof cards.setHTML === 'function') {
+      refreshButton.addEventListener('click', refreshMenu);
+      window.addEventListener('menu-changed', refreshMenu);
+      if ('EventSource' in window) {
