+        function connectMenuEvents() {
+          menuEvents = new EventSource('/api/menu/events');
+          menuEvents.addEventListener('menu-changed', refreshMenu);
+          // EventSource reconnects automatically after temporary disconnects.
+          menuEvents.addEventListener('open', () => {
+            // Also catch menu changes missed while this connection was offline.
+            void refreshMenu();
+          });
+        }
+        connectMenuEvents();
+        window.addEventListener('pagehide', () => menuEvents.close());
+        window.addEventListener('pageshow', (event) => {
