+      menuStatus.textContent = 'For the latest favorites, visit our full menu.';
+      const menuLink = document.createElement('a');
+      menuLink.href = '/menu';
+      menuLink.textContent = ' Browse menu';
+      menuStatus.append(menuLink);
+    }
+
+    async function loadReviews() {
+      const status = document.getElementById('reviews-status');
+      if (typeof reviews.setHTML !== 'function') {
+        status.textContent = 'Customer reviews are currently unavailable in this browser.';
+        return;
+      }
+      try {
+        // User content always goes through the native sanitizer. Never route it
+        // through the CMS setter, even if it came from our own server.
+        reviews.setHTML(await fetchHTML('/api/reviews/seasonal'));
+        status.textContent = reviews.textContent.trim() ? '' : 'No reviews yet.';
+      } catch (error) {
+        status.textContent = 'Customer reviews are currently unavailable.';
+        console.error('Reviews failed to load', error);
+      }
+    }
+
+    async function loadPromo() {
+      const status = document.getElementById('promo-status');
+      if (typeof promo.setHTMLUnsafe !== 'function') {
+        status.textContent = 'Visit Rewards for our latest offers.';
+        return;
+      }
+      try {
+        // This fixed first-party endpoint is a code trust boundary: its CMS
+        // authors may execute JS with page privileges; this is not a sandbox.
+        // runScripts explicitly opts in to executing the embedded widget script.
+        promo.setHTMLUnsafe(await fetchHTML('/api/cms/seasonal-promo'), {
+          runScripts: true
+        });
+        status.textContent = '';
+      } catch (error) {
+        status.textContent = 'Our latest offer is currently unavailable.';
+        console.error('CMS promo failed to load', error);
+      }
+    }
+
+    void loadReviews();
+    void loadPromo();
