+  $('#status').classList.toggle('error', error);
+}
+function render() {
+  list.replaceChildren();
+  $('#key-count').textContent = account.credentials.length;
+  for (const key of account.credentials) {
+    const row = element('article', 'passkey-row');
+    const device = element('div', 'device-icon');
+    device.append(icon(['laptop', 'phone', 'usb'].includes(key.device) ? key.device : 'key'));
+    const info = element('div', 'passkey-info');
+    const title = element('div', 'passkey-title');
+    title.append(element('h4', '', key.name || 'Unnamed passkey'));
+    info.append(title, element('p', 'provider', key.provider || 'Unknown passkey provider'));
+    const dates = element('div', 'passkey-dates');
+    dates.append(element('span', '', `Added ${date(key.registeredAt) || 'date unavailable'}`), element('span', '', '·'), element('span', '', key.lastUsedAt ? `Last used ${date(key.lastUsedAt) || 'date unavailable'}` : 'Not used yet'));
+    info.append(dates);
