@@ -0,0 +1,76 @@
+// Live mode always uses the signed-in session. Never send a client-selected user ID.
+const STORAGE_KEY = 'daily-grind.passkeys.preview.v1';
+const seed = () => ({
+  profile: { displayName: 'Jamie Davis' },
+  rpId: 'dailygrind.example', userId: 'amFtaWUtZGF2aXM',
+  credentials: [
+    { id: 'bWFjYm9vay1wcmV2aWV3', name: 'MacBook Pro', provider: 'iCloud Keychain', device: 'laptop', registeredAt: 1792627200000, lastUsedAt: 1795046400000 },
+    { id: 'aXBob25lLXByZXZpZXc', name: 'iPhone 15', provider: 'iCloud Keychain', device: 'phone', registeredAt: 1792627200000, lastUsedAt: 1794873600000 },
+    { id: 'eXViaWtleS1wcmV2aWV3', name: 'YubiKey 5C', provider: 'Security key', device: 'usb', registeredAt: 1790985600000, lastUsedAt: 1794268800000 },
+  ],
+});
+export function validateAccount(data) {
+  if (!data || !Array.isArray(data.credentials) || !data.credentials.every(key =>
+    key && typeof key.id === 'string' && key.id.length && typeof key.name === 'string'
+  ) || new Set(data.credentials.map(key => key.id)).size !== data.credentials.length) {
+    throw new Error('We couldn’t read your passkeys. Please try again.');
+  }
+  return data;
+}
+export function createAccountService({ apiBase = '', fetchImpl = globalThis.fetch, storage, csrfToken = '' } = {}) {
+  const preview = !apiBase;
+  let memory = seed();
+  if (preview) {
+    try { const saved = storage?.getItem(STORAGE_KEY); if (saved) memory = validateAccount(JSON.parse(saved)); }
+    catch { /* An unavailable or corrupt preview store must not prevent management. */ }
+  }
+  function persist() { try { storage?.setItem(STORAGE_KEY, JSON.stringify(memory)); } catch { /* Keep this session usable without storage. */ } }
+  async function request(path, method = 'GET', body) {
+    const response = await fetchImpl(`${apiBase.replace(/\/$/, '')}${path}`, {
+      method, credentials: 'same-origin', cache: 'no-store',
+      headers: { Accept: 'application/json', ...(body ? { 'Content-Type': 'application/json' } : {}), ...(csrfToken ? { 'X-CSRF-Token': csrfToken } : {}) },
+      ...(body ? { body: JSON.stringify(body) } : {}),
+    });
+    if (!response.ok) {
+      if (response.status === 401 || response.status === 403) throw new Error('Your session needs attention. Please sign in again.');
+      throw new Error('We couldn’t save that change. Please try again.');
+    }
+    return method === 'GET' ? response.json() : undefined;
+  }
+  return {
+    preview,
+    async list() { return validateAccount(preview ? structuredClone(memory) : await request('/credentials')); },
+    async rename(id, name) {
+      const clean = name.trim();
+      if (!clean || clean.length > 60) throw new Error('Choose a name between 1 and 60 characters.');
+      if (!preview) return request(`/credential/${encodeURIComponent(id)}`, 'PUT', { name: clean });
+      const key = memory.credentials.find(key => key.id === id);
+      if (!key) throw new Error('This passkey is no longer available. Refresh and try again.');
+      key.name = clean; persist();
+    },
+    async remove(id) {
+      if (!preview) return request(`/credential/${encodeURIComponent(id)}`, 'DELETE');
+      memory.credentials = memory.credentials.filter(key => key.id !== id); persist();
+    },
+  };
+}
+export function isBase64Url(value) {
+  return typeof value === 'string' && value.length > 0 && value.length % 4 !== 1 && /^[A-Za-z0-9_-]+$/.test(value);
+}
+export async function syncAcceptedCredentials(account, { preview = false, authenticator = globalThis.PublicKeyCredential } = {}) {
+  // Sample records must never be signaled to a real authenticator.
+  if (preview) return 'preview';
+  if (typeof authenticator?.signalAllAcceptedCredentials !== 'function') return 'unsupported';
+  const ids = account.credentials.map(key => key.id);
+  if (typeof account.rpId !== 'string' || !account.rpId || !isBase64Url(account.userId) || !ids.every(isBase64Url)) {
+    console.warn('Passkey sync skipped: invalid server-provided RP or credential identifiers.');
+    return 'failed';
+  }
+  try {
+    await authenticator.signalAllAcceptedCredentials({ rpId: account.rpId, userId: account.userId, allAcceptedCredentialIds: ids });
+    return 'notified';
+  } catch (error) {
+    console.warn('Passkey provider sync unavailable:', error);
+    return 'failed';
+  }
+}
