diff --git a/tests/passkeys.test.mjs b/tests/passkeys.test.mjs
new file mode 100644
index 0000000..28faaaf
--- /dev/null
+++ b/tests/passkeys.test.mjs
@@ -0,0 +1,87 @@
+import test from 'node:test';
+import assert from 'node:assert/strict';
+import { createAccountService, syncAcceptedCredentials, isBase64Url, validateAccount } from '../assets/passkey-service.mjs';
+const account = { rpId: 'example.com', userId: 'dXNlcg', credentials: [{ id: 'Y3JlZA', name: 'Laptop' }] };
+
+test('preview rename/delete persist across sessions without changing other keys', async () => {
+  const saved = new Map();
+  const storage = { getItem: key => saved.get(key), setItem: (key, value) => saved.set(key, value) };
+  const service = createAccountService({ storage });
+  const initial = await service.list();
+  await service.rename(initial.credentials[0].id, '  My laptop  ');
+  await service.remove(initial.credentials[1].id);
+  const refreshed = await createAccountService({ storage }).list();
+  assert.equal(refreshed.credentials.length, 2);
+  assert.equal(refreshed.credentials[0].name, 'My laptop');
+  assert.equal(refreshed.credentials[1].id, initial.credentials[2].id);
+  assert.equal(initial.credentials[0].name, 'MacBook Pro');
+  await assert.rejects(service.rename(refreshed.credentials[0].id, '   '));
+  await assert.rejects(service.rename(refreshed.credentials[0].id, 'x'.repeat(61)));
+});
+
+test('preview supports empty state and blocked storage', async () => {
+  const service = createAccountService({ storage: { getItem() { throw Error(); }, setItem() { throw Error(); } } });
+  for (const key of (await service.list()).credentials) await service.remove(key.id);
+  assert.deepEqual((await service.list()).credentials, []);
+});
+
+test('API requests use the authenticated session and propagate CSRF tokens', async () => {
+  const calls = [];
+  const service = createAccountService({ apiBase: '/api/account/', csrfToken: 'csrf-value', fetchImpl: async (url, options) => {
+    calls.push({ url, options });
+    return { ok: true, json: async () => account };
+  } });
+  assert.deepEqual(await service.list(), account);
+  await service.rename('Y3JlZA', '  Work  ');
+  await service.remove('Y3JlZA');
+  assert.deepEqual(calls.map(call => [call.url, call.options.method]), [
+    ['/api/account/credentials', 'GET'], ['/api/account/credential/Y3JlZA', 'PUT'], ['/api/account/credential/Y3JlZA', 'DELETE'],
+  ]);
+  assert.equal(calls[1].options.body, JSON.stringify({ name: 'Work' }));
+  for (const { options } of calls) {
+    assert.equal(options.credentials, 'same-origin');
+    assert.equal(options.cache, 'no-store');
+    assert.equal(options.headers['X-CSRF-Token'], 'csrf-value');
+  }
+});
+
+test('failed authorization never falls back to sample data', async () => {
+  const service = createAccountService({ apiBase: '/api/account', fetchImpl: async () => ({ ok: false, status: 401 }) });
+  await assert.rejects(service.list(), /sign in again/);
+  await assert.rejects(service.remove('Y3JlZA'), /sign in again/);
+  assert.equal(service.preview, false);
+});
+
+test('sync uses the complete authoritative list and server RP ID, including empty lists', async () => {
+  const calls = [];
+  const authenticator = { async signalAllAcceptedCredentials(options) { calls.push(options); } };
+  assert.equal(await syncAcceptedCredentials(account, { authenticator }), 'notified');
+  assert.deepEqual(calls[0], { rpId: 'example.com', userId: 'dXNlcg', allAcceptedCredentialIds: ['Y3JlZA'] });
+  await syncAcceptedCredentials({ ...account, credentials: [] }, { authenticator });
+  assert.deepEqual(calls[1].allAcceptedCredentialIds, []);
+});
+
+test('preview never signals a real authenticator and unsupported browsers degrade', async () => {
+  let calls = 0;
+  const authenticator = { async signalAllAcceptedCredentials() { calls++; } };
+  assert.equal(await syncAcceptedCredentials(account, { authenticator, preview: true }), 'preview');
+  assert.equal(calls, 0);
+  assert.equal(await syncAcceptedCredentials(account, { authenticator: {} }), 'unsupported');
+});
+
+test('invalid identifiers and provider failures do not reject management', async t => {
+  t.mock.method(console, 'warn', () => {});
+  let calls = 0;
+  const authenticator = { async signalAllAcceptedCredentials() { calls++; throw new Error('Provider unavailable'); } };
+  assert.equal(await syncAcceptedCredentials({ ...account, userId: 'a' }, { authenticator }), 'failed');
+  assert.equal(calls, 0);
+  assert.equal(await syncAcceptedCredentials(account, { authenticator }), 'failed');
+  assert.equal(calls, 1);
+  for (const value of ['a', 'a=', 'abc+', '', undefined]) assert.equal(isBase64Url(value), false);
+  for (const key of (await createAccountService().list()).credentials) assert.equal(isBase64Url(key.id), true);
+});
+
+test('malformed or duplicate credential data is rejected instead of partially synchronized', () => {
+  assert.throws(() => validateAccount({ credentials: [{ name: 'Missing id' }] }));
+  assert.throws(() => validateAccount({ ...account, credentials: [...account.credentials, ...account.credentials] }));
+});

