+import { useEffect, useRef, useState } from 'react';
+import { ArrowPathIcon, CheckIcon, ChevronRightIcon, ComputerDesktopIcon, FingerPrintIcon, KeyIcon, PencilSquareIcon, PlusIcon, ShieldCheckIcon, TrashIcon } from '@heroicons/react/24/outline';
+import providers from '../data/passkey-providers.json';
+import { AccountError, accountRequest, passkeyCapabilities, passkeyError, signalUnknown, syncPasskeys, type PasskeySnapshot, type PasskeySummary } from '../lib/passkey-client';
+
+const providerRegistry = providers as Record<string, { name: string; icon_light?: string }>;
+function providerFor(key: PasskeySummary) {
+  return key.aaguid === '00000000-0000-0000-0000-000000000000' ? undefined : providerRegistry[key.aaguid.toLowerCase()];
+}
+function keyName(key: PasskeySummary) { return key.name || providerFor(key)?.name || 'Passkey'; }
+function date(value?: number) {
+  return value ? new Intl.DateTimeFormat('en', { month: 'short', day: 'numeric', year: 'numeric', timeZone: 'UTC' }).format(value) : 'Not used yet';
+}
+
+export default function PasskeySettings({ username }: { username: string }) {
+  const [snapshot, setSnapshot] = useState<PasskeySnapshot | null>(null);
+  const [loading, setLoading] = useState(true);
+  const [busy, setBusy] = useState(false);
+  const [supported, setSupported] = useState(false);
+  const [error, setError] = useState('');
+  const [expired, setExpired] = useState(false);
+  const [message, setMessage] = useState('');
+  const [syncState, setSyncState] = useState('');
+  const [editing, setEditing] = useState<string | null>(null);
+  const [removing, setRemoving] = useState<string | null>(null);
+  const [name, setName] = useState('');
+  const actionRefs = useRef(new Map<string, HTMLButtonElement>());
+  const listHeading = useRef<HTMLHeadingElement>(null);
+
+  function showError(err: unknown) {
+    setError(passkeyError(err));
+    if (err instanceof AccountError && err.status === 401) setExpired(true);
+  }
+  async function synchronize(data: PasskeySnapshot) {
+    const result = await syncPasskeys(data);
+    setSyncState(result === 'synced'
+      ? 'Your current passkey list has been shared with this browser’s authenticator. Other password managers may need a manual update.'
+      : result === 'unsupported'
+        ? 'This browser cannot update your authenticator automatically. Remove unused keys from your password manager too.'
+        : 'Your account is up to date. Browser synchronization could not complete; refresh to retry or update your password manager manually.');
+  }
+  async function load(signal?: AbortSignal) {
+    setLoading(true); setError('');
+    try {
+      const data = await accountRequest<PasskeySnapshot>('credentials', 'GET', undefined, signal);
+      if (signal?.aborted) return;
+      setSnapshot(data);
+      await synchronize(data);
+    } catch (err) { if (!signal?.aborted) showError(err); }
+    finally { if (!signal?.aborted) setLoading(false); }
+  }
+  useEffect(() => {
+    const controller = new AbortController();
+    void load(controller.signal);
+    void passkeyCapabilities().then(capabilities => {
+      if (!controller.signal.aborted) setSupported(Boolean(capabilities?.passkeyPlatformAuthenticator));
+    }).catch(() => setSupported(false));
+    return () => controller.abort();
+  }, []);
+
+  function closeEditor(id: string) {
+    setEditing(null); setRemoving(null);
+    requestAnimationFrame(() => actionRefs.current.get(id)?.focus());
+  }
+  async function rename(event: React.FormEvent, key: PasskeySummary) {
+    event.preventDefault(); setBusy(true); setError(''); setMessage('');
+    try {
+      const data = await accountRequest<PasskeySnapshot>(`credentials/${encodeURIComponent(key.id)}`, 'PUT', { name: name.trim() });
+      setSnapshot(data); closeEditor(key.id); setMessage('Passkey name updated.');
