+        throw err;
+      }
+      setSnapshot(data); setMessage('Passkey created. Give it a name to help you recognize it.');
+      await synchronize(data);
+    } catch (err) { showError(err); }
+    finally { setBusy(false); }
+  }
+
+  return <div className="passkey-settings">
+    <div className="settings-section-title"><span className="settings-eyebrow">SIGN-IN & SECURITY</span><span className="private-badge"><ShieldCheckIcon /> Private to you</span></div>
+    <div className="passkey-intro">
+      <div className="intro-icon"><FingerPrintIcon /></div>
+      <div><h2>Less friction. More security.</h2><p>Sign in with your fingerprint, face, or device PIN. Passkeys keep your account protected without another password to remember.</p></div>
+    </div>
+    <section className="passkey-panel" aria-labelledby="passkey-list-heading" aria-busy={loading || busy}>
+      <div className="passkey-panel-header">
+        <div><h2 id="passkey-list-heading" ref={listHeading} tabIndex={-1}>Your passkeys {snapshot && <span className="key-count">{snapshot.credentials.length}</span>}</h2><p>Manage the passkeys you use to access The DevTools Times.</p></div>
+        {supported && <button className="settings-button primary" onClick={create} disabled={busy || loading || expired || !snapshot}><PlusIcon />{busy ? 'Please wait…' : 'Create passkey'}</button>}
+      </div>
+      {error && <div className="settings-alert" role="alert">{error} {expired && <a href={`${import.meta.env.BASE_URL}signin`}>Sign in again <ChevronRightIcon /></a>}</div>}
+      <p className="settings-live" role="status" aria-live="polite">{message}</p>
+      {loading ? <div className="passkey-empty"><ArrowPathIcon className="loading-icon" /><p>Loading your passkeys…</p></div>
+        : !snapshot ? <div className="passkey-empty"><KeyIcon /><h3>We couldn’t load your passkeys</h3><p>Your keys haven’t been changed. Please try again.</p><button className="settings-button secondary" onClick={() => void load()} disabled={busy || expired}>Try again</button></div>
