+        : <ul className="passkey-list">{snapshot.credentials.map(key => {
+          const provider = providerFor(key);
+          return <li key={key.id} className="passkey-row">
+            <div className="key-provider-icon">{provider?.icon_light ? <img src={provider.icon_light} alt="" width={28} height={28} /> : <KeyIcon />}</div>
+            <div className="key-details">
+              {editing === key.id ? <form onSubmit={event => void rename(event, key)} className="rename-form">
+                <label htmlFor={`name-${key.id}`}>Passkey display name</label>
+                <input id={`name-${key.id}`} value={name} onChange={event => setName(event.target.value)} maxLength={80} required autoFocus disabled={busy} />
+                <div className="inline-actions"><button className="settings-button primary small" type="submit" disabled={busy || !name.trim()}><CheckIcon />Save name</button><button className="settings-button secondary small" type="button" onClick={() => closeEditor(key.id)} disabled={busy}>Cancel</button></div>
+              </form> : <><h3>{keyName(key)}</h3><p className="key-provider">{provider?.name || 'Unknown passkey provider'}<span>·</span>{key.deviceType === 'multiDevice' ? 'Synced passkey' : 'Device-bound passkey'}</p><div className="key-dates"><span>Created {date(key.registeredAt)}</span><span>Last used: {date(key.lastUsedAt)}</span></div></>}
+              {removing === key.id && <div className="remove-confirmation"><h4>Remove {keyName(key)}?</h4><p>This passkey will no longer sign you in. Your password and other passkeys will still work.</p>{snapshot.credentials.length === 1 && <p>This is your last passkey. Make sure you know your password before removing it.</p>}<div className="inline-actions"><button className="settings-button danger small" onClick={() => void remove(key)} disabled={busy}>Remove passkey</button><button autoFocus className="settings-button secondary small" onClick={() => closeEditor(key.id)} disabled={busy}>Keep passkey</button></div></div>}
+            </div>
+            {editing !== key.id && removing !== key.id && <div className="key-actions"><button ref={element => { if (element) actionRefs.current.set(key.id, element); else actionRefs.current.delete(key.id); }} className="key-action" aria-label={`Rename ${keyName(key)}`} onClick={() => { setEditing(key.id); setRemoving(null); setName(keyName(key)); setError(''); }} disabled={busy || expired}><PencilSquareIcon /><span>Rename</span></button><button className="key-action remove" aria-label={`Remove ${keyName(key)}`} onClick={() => { setRemoving(key.id); setEditing(null); setError(''); }} disabled={busy || expired}><TrashIcon /><span>Remove</span></button></div>}
+          </li>;
+        })}</ul>}
+      <div className="passkey-panel-footer"><ShieldCheckIcon /><p>{syncState || 'Your passkeys are securely linked to your account.'}</p>{snapshot && <button className="refresh-keys" onClick={() => void load()} disabled={busy || loading || expired} aria-label="Refresh passkeys and retry browser synchronization"><ArrowPathIcon /></button>}</div>
+    </section>
+    <div className="settings-help-grid"><section><div className="help-heading"><ComputerDesktopIcon /><h3>One account. Your devices.</h3></div><p>Passkeys may sync across devices through your password manager, so a single passkey can work in more than one place.</p></section><section><div className="help-heading"><ShieldCheckIcon /><h3>Built around your privacy.</h3></div><p>Your fingerprint and face data stay on your device. The DevTools Times never sees or stores your biometric information.</p></section></div>
+    <div className="settings-account-note"><span>Signed in as <strong>{username}</strong></span><span>Keep a familiar name for every key.</span></div>
+  </div>;
+}
