@@ -0,0 +1,19 @@
+import type { APIContext } from 'astro';
+import { accountById } from './account-store';
+
+export function json(value: unknown, status = 200) {
+  return new Response(JSON.stringify(value), { status, headers: { 'Content-Type': 'application/json', 'Cache-Control': 'no-store' } });
+}
+export function webauthnConfig(url: URL) {
+  const origin = process.env.WEBAUTHN_ORIGIN || url.origin;
+  return { origin, rpId: process.env.WEBAUTHN_RP_ID || new URL(origin).hostname };
+}
+export async function signedInAccount(session: APIContext['session']) {
+  const auth = await session?.get('accountAuth');
+  if (!auth || auth.expiresAt < Date.now()) return undefined;
+  return accountById(auth.accountId);
+}
+export async function signIn(session: NonNullable<APIContext['session']>, accountId: string) {
+  await session.regenerate();
+  session.set('accountAuth', { accountId, expiresAt: Date.now() + 86_400_000 });
+}
