--- /dev/null
+++ b/src/lib/account-store.ts
@@ -0,0 +1,79 @@
+import { DatabaseSync } from 'node:sqlite';
+import { randomBytes, randomUUID } from 'node:crypto';
+import { mkdirSync } from 'node:fs';
+import { dirname, resolve } from 'node:path';
+
+export interface Account { id: string; username: string; userId: string }
+export interface StoredPasskey {
+  id: string;
+  accountId: string;
+  rpId: string;
+  name: string;
+  aaguid: string;
+  publicKey: string;
+  counter: number;
+  transports: string[];
+  registeredAt: number;
+  lastUsedAt?: number;
+  backedUp: boolean;
+  deviceType: string;
+}
+
+// A durable, single-host store. Deployments must mount this directory on persistent storage.
+let database: DatabaseSync;
+function db() {
+  if (!database) {
+    const path = resolve(process.env.ACCOUNT_DB_PATH || '.data/accounts.sqlite');
+    mkdirSync(dirname(path), { recursive: true, mode: 0o700 });
+    database = new DatabaseSync(path);
+    database.exec(`PRAGMA journal_mode = WAL; PRAGMA foreign_keys = ON; PRAGMA busy_timeout = 5000;
+      CREATE TABLE IF NOT EXISTS accounts (id TEXT PRIMARY KEY, username TEXT UNIQUE NOT NULL, userId TEXT UNIQUE NOT NULL);
+      CREATE TABLE IF NOT EXISTS passkeys (id TEXT PRIMARY KEY, accountId TEXT NOT NULL REFERENCES accounts(id), rpId TEXT NOT NULL, record TEXT NOT NULL);
+      CREATE TABLE IF NOT EXISTS challenges (challenge TEXT PRIMARY KEY, expiresAt INTEGER NOT NULL);
+      CREATE INDEX IF NOT EXISTS passkey_owner ON passkeys(accountId, rpId);`);
+  }
+  return database;
+}
+
+export function saveChallenge(challenge: string, expiresAt: number) {
+  db().prepare('DELETE FROM challenges WHERE expiresAt < ?').run(Date.now());
+  db().prepare('INSERT INTO challenges VALUES (?, ?)').run(challenge, expiresAt);
+}
+export function consumeChallenge(challenge: string): boolean {
+  // Atomically consume even when verification requests arrive in parallel.
+  return Boolean(db().prepare('DELETE FROM challenges WHERE challenge = ? AND expiresAt >= ? RETURNING challenge').get(challenge, Date.now()));
+}
+
+export function accountById(id: string): Account | undefined {
+  return db().prepare('SELECT * FROM accounts WHERE id = ?').get(id) as unknown as Account | undefined;
+}
+export function ensureAccount(username: string): Account {
+  db().prepare('INSERT OR IGNORE INTO accounts VALUES (?, ?, ?)').run(randomUUID(), username, randomBytes(32).toString('base64url'));
+  return db().prepare('SELECT * FROM accounts WHERE username = ?').get(username) as unknown as Account;
+}
+export function listPasskeys(accountId: string, rpId: string): StoredPasskey[] {
+  return db().prepare('SELECT record FROM passkeys WHERE accountId = ? AND rpId = ? ORDER BY rowid').all(accountId, rpId)
+    .map(row => JSON.parse(row.record as string));
+}
+export function findPasskey(id: string): StoredPasskey | undefined {
+  const row = db().prepare('SELECT record FROM passkeys WHERE id = ?').get(id);
+  return row ? JSON.parse(row.record as string) : undefined;
+}
+export function addPasskey(key: StoredPasskey) {
+  db().prepare('INSERT INTO passkeys VALUES (?, ?, ?, ?)').run(key.id, key.accountId, key.rpId, JSON.stringify(key));
+}
+export function renamePasskey(id: string, accountId: string, rpId: string, name: string): boolean {
+  return db().prepare("UPDATE passkeys SET record = json_set(record, '$.name', ?) WHERE id = ? AND accountId = ? AND rpId = ?")
+    .run(name, id, accountId, rpId).changes === 1;
+}
+export function removePasskey(id: string, accountId: string, rpId: string): boolean {
+  return db().prepare('DELETE FROM passkeys WHERE id = ? AND accountId = ? AND rpId = ?').run(id, accountId, rpId).changes === 1;
+}
+export function recordPasskeyUse(key: StoredPasskey, counter: number, backedUp: boolean): boolean {
+  // A concurrent rename is preserved; a deleted key is never recreated by a racing sign-in.
+  return db().prepare("UPDATE passkeys SET record = json_set(record, '$.counter', ?, '$.lastUsedAt', ?, '$.backedUp', json(?)) WHERE id = ? AND json_extract(record, '$.counter') = ?")
+    .run(counter, Date.now(), JSON.stringify(backedUp), key.id, key.counter).changes === 1;
+}
+export function publicPasskey({ publicKey, counter, accountId, rpId, ...key }: StoredPasskey) {
+  return key;
+}
diff --git a/src/lib/passkey-client.ts b/src/lib/passkey-client.ts
new file mode 100644
index 0000000..7cc9c19
--- /dev/null
+++ b/src/lib/passkey-client.ts
@@ -0,0 +1,61 @@
+export interface PasskeySummary {
+  id: string;
+  name: string;
+  aaguid: string;
+  registeredAt: number;
+  lastUsedAt?: number;
+  backedUp: boolean;
+  deviceType: string;
+}
+export interface PasskeySnapshot { rpId: string; userId: string; credentials: PasskeySummary[] }
+export class AccountError extends Error {
+  status: number;
+  constructor(message: string, status: number) { super(message); this.status = status; }
+}
+export async function accountRequest<T>(path: string, method = 'GET', body?: unknown, signal?: AbortSignal): Promise<T> {
+  const response = await fetch(`${import.meta.env.BASE_URL}api/account/${path}`, {
+    method, credentials: 'same-origin', cache: 'no-store', signal,
+    headers: body === undefined ? undefined : { 'Content-Type': 'application/json' },
+    body: body === undefined ? undefined : JSON.stringify(body),
+  });
+  const data = await response.json();
+  if (!response.ok) throw new AccountError(data.error || 'Unable to complete this request.', response.status);
+  return data;
+}
+export async function passkeyCapabilities() {
+  if (!window.isSecureContext || !window.PublicKeyCredential) return null;
+  await import('webauthn-polyfills');
+  try { return await PublicKeyCredential.getClientCapabilities(); }
+  catch { return null; }
+}
+export function isBase64Url(value: unknown): value is string {
+  return typeof value === 'string' && value.length > 0 && value.length % 4 !== 1 && /^[A-Za-z0-9_-]+$/.test(value);
+}
+export async function syncPasskeys(snapshot: PasskeySnapshot): Promise<'synced' | 'unsupported' | 'failed'> {
+  if (!window.PublicKeyCredential?.signalAllAcceptedCredentials) return 'unsupported';
+  const ids = snapshot.credentials.map(key => key.id);
+  if (!snapshot.rpId || !isBase64Url(snapshot.userId) || !ids.every(isBase64Url)) {
+    console.warn('Passkey synchronization skipped: invalid server identifiers.');
+    return 'failed';
+  }
+  try {
+    await PublicKeyCredential.signalAllAcceptedCredentials({ rpId: snapshot.rpId, userId: snapshot.userId, allAcceptedCredentialIds: ids });
+    return 'synced';
+  } catch (error) {
+    console.warn('Passkey synchronization could not complete:', error);
+    return 'failed';
+  }
+}
+export async function signalUnknown(rpId: string, credentialId: string) {
+  if (!window.PublicKeyCredential?.signalUnknownCredential || !isBase64Url(credentialId)) return;
+  try { await PublicKeyCredential.signalUnknownCredential({ rpId, credentialId }); }
+  catch (error) { console.warn('Passkey provider update could not complete:', error); }
+}
+export function passkeyError(error: unknown) {
+  if (error instanceof DOMException) {
+    if (error.name === 'NotAllowedError' || error.name === 'AbortError') return 'Passkey request cancelled or timed out. You can try again.';
+    if (error.name === 'InvalidStateError') return 'A passkey for this account already exists in this authenticator.';
+    if (error.name === 'SecurityError') return 'Passkeys require a secure connection and a matching site address.';
+  }
+  return error instanceof Error ? error.message : 'Unable to complete the passkey request. Please try again.';
+}
