diff --git a/src/pages/api/account/[...action].ts b/src/pages/api/account/[...action].ts
new file mode 100644
index 0000000..d320238
--- /dev/null
+++ b/src/pages/api/account/[...action].ts
@@ -0,0 +1,105 @@
+import type { APIRoute } from 'astro';
+import { generateRegistrationOptions, verifyRegistrationResponse, generateAuthenticationOptions, verifyAuthenticationResponse } from '@simplewebauthn/server';
+import { accountById, ensureAccount, listPasskeys, findPasskey, addPasskey, renamePasskey, removePasskey, recordPasskeyUse, publicPasskey, saveChallenge, consumeChallenge } from '../../../lib/account-store';
+import { json, webauthnConfig, signedInAccount, signIn } from '../../../lib/account-http';
+
+export const ALL: APIRoute = async ({ request, url, session, params }) => {
+  if (!session) return json({ error: 'Account sessions are unavailable.' }, 503);
+  const action = params.action;
+  const method = request.method;
+  const config = webauthnConfig(url);
+  if (method !== 'GET' && request.headers.get('origin') !== config.origin) {
+    return json({ error: 'This request must come from this site.' }, 403);
+  }
+  try {
+    if (action === 'login' && method === 'POST') {
+      const { username, password } = await request.json();
+      if (typeof username !== 'string' || !username.trim() || username.length > 200 || typeof password !== 'string' || !password || password.length > 1024) {
+        return json({ error: 'Enter your username and password.' }, 400);
+      }
+      // Keep the existing identity service as the authority for password sign-in.
+      const upstream = await fetch('https://us-central1-web-devrel-apps.cloudfunctions.net/times_cdn/api/login', {
+        method: 'POST', headers: { 'Content-Type': 'application/json' },
+        body: JSON.stringify({ username: username.trim(), password }), signal: AbortSignal.timeout(15000),
+      });
+      if (!upstream.ok) return json({ error: 'Unable to sign in. Check your username and password.' }, upstream.status === 429 ? 429 : 401);
+      const identity = await upstream.json();
+      // Prefer the canonical username returned by the identity service, where available.
+      const canonicalName = identity.user?.username || identity.username || username.trim();
+      if (typeof canonicalName !== 'string' || !canonicalName) return json({ error: 'Invalid identity service response.' }, 502);
+      const account = ensureAccount(canonicalName);
+      await signIn(session, account.id);
+      return json({ success: true });
+    }
+    if (action === 'logout' && method === 'POST') {
+      session.destroy();
+      return json({ success: true });
+    }
+    if (action === 'authenticate/options' && method === 'POST') {
+      const options = await generateAuthenticationOptions({ rpID: config.rpId, allowCredentials: [], userVerification: 'required' });
+      saveChallenge(options.challenge, Date.now() + 300000);
+      session.set('passkeyChallenge', { ...config, challenge: options.challenge, kind: 'authenticate', expiresAt: Date.now() + 300000, userVerification: 'required' });
+      return json(options);
+    }
+    if (action === 'authenticate/verify' && method === 'POST') {
+      const challenge = await session.get('passkeyChallenge');
+      session.delete('passkeyChallenge');
+      if (!challenge || challenge.kind !== 'authenticate' || challenge.expiresAt < Date.now() || challenge.origin !== config.origin || challenge.rpId !== config.rpId || !consumeChallenge(challenge.challenge)) return json({ error: 'Sign-in expired. Please try again.' }, 400);
+      const response = await request.json();
+      const key = typeof response.id === 'string' ? findPasskey(response.id) : undefined;
+      if (!key || key.rpId !== config.rpId) return json({ error: 'This passkey is no longer registered. Sign in with your password.' }, 404);
+      const account = accountById(key.accountId);
+      if (!account || response.response?.userHandle !== account.userId) return json({ error: 'Unable to verify this passkey.' }, 400);
+      const verification = await verifyAuthenticationResponse({ response, expectedChallenge: challenge.challenge, expectedOrigin: challenge.origin, expectedRPID: challenge.rpId,
+        requireUserVerification: challenge.userVerification === 'required',
+        credential: { id: key.id, publicKey: new Uint8Array(Buffer.from(key.publicKey, 'base64url')), counter: key.counter, transports: key.transports },
+      });
+      if (!verification.verified || !recordPasskeyUse(key, verification.authenticationInfo.newCounter, verification.authenticationInfo.credentialBackedUp)) return json({ error: 'Unable to verify this passkey. Please try again.' }, 400);
+      await signIn(session, account.id);
+      return json({ success: true });
+    }
+    const account = await signedInAccount(session);
+    if (!account) return json({ error: 'Please sign in to manage your passkeys.' }, 401);
+    const snapshot = () => ({ rpId: config.rpId, userId: account.userId, credentials: listPasskeys(account.id, config.rpId).map(publicPasskey) });
+    if (action === 'credentials' && method === 'GET') return json(snapshot());
+    if (action?.startsWith('credentials/') && (method === 'PUT' || method === 'DELETE')) {
+      const id = action.slice('credentials/'.length);
+      if (method === 'PUT') {
+        const { name } = await request.json();
+        if (typeof name !== 'string' || !name.trim() || name.trim().length > 80) return json({ error: 'Use a name between 1 and 80 characters.' }, 400);
+        if (!renamePasskey(id, account.id, config.rpId, name.trim())) return json({ error: 'Passkey not found. Refresh the list and try again.' }, 404);
+      } else if (!removePasskey(id, account.id, config.rpId)) return json({ error: 'Passkey not found. Refresh the list and try again.' }, 404);
+      // Return the complete authoritative list, including after the last key is removed.
+      return json(snapshot());
+    }
+    if (action === 'register/options' && method === 'POST') {
+      const options = await generateRegistrationOptions({ rpName: 'The DevTools Times', rpID: config.rpId, userName: account.username,
+        userID: new Uint8Array(Buffer.from(account.userId, 'base64url')), userDisplayName: account.username,
+        attestationType: 'none', authenticatorSelection: { residentKey: 'required', requireResidentKey: true, userVerification: 'required' },
+        excludeCredentials: listPasskeys(account.id, config.rpId).map(key => ({ id: key.id, transports: key.transports })),
+      });
+      saveChallenge(options.challenge, Date.now() + 300000);
+      session.set('passkeyChallenge', { ...config, challenge: options.challenge, kind: 'register', accountId: account.id, expiresAt: Date.now() + 300000, userVerification: 'required' });
+      return json(options);
+    }
+    if (action === 'register/verify' && method === 'POST') {
+      const challenge = await session.get('passkeyChallenge');
+      session.delete('passkeyChallenge');
+      if (!challenge || challenge.kind !== 'register' || challenge.accountId !== account.id || challenge.expiresAt < Date.now() || challenge.origin !== config.origin || challenge.rpId !== config.rpId || !consumeChallenge(challenge.challenge)) return json({ error: 'Registration expired. Please try again.' }, 400);
+      const verification = await verifyRegistrationResponse({ response: await request.json(), expectedChallenge: challenge.challenge, expectedOrigin: challenge.origin, expectedRPID: challenge.rpId, requireUserVerification: true });
+      if (!verification.verified) return json({ error: 'Unable to verify this passkey.' }, 400);
+      const info = verification.registrationInfo;
+      addPasskey({ id: info.credential.id, accountId: account.id, rpId: config.rpId, name: '', aaguid: info.aaguid,
+        publicKey: Buffer.from(info.credential.publicKey).toString('base64url'), counter: info.credential.counter,
+        transports: info.credential.transports || [], registeredAt: Date.now(), backedUp: info.credentialBackedUp, deviceType: info.credentialDeviceType,
+      });
+      return json(snapshot(), 201);
+    }
+    return json({ error: 'Account endpoint not found.' }, 404);
+  } catch (error) {
+    if (error instanceof SyntaxError) return json({ error: 'Invalid request.' }, 400);
+    if (action?.endsWith('/verify')) return json({ error: 'Passkey verification failed. Please try again.' }, 400);
+    console.warn('Account request failed:', error instanceof Error ? error.message : 'Unknown error');
+    return json({ error: 'Unable to complete this request. Please try again.' }, 503);
+  }
+};
