+import { test, after } from 'node:test';
+import assert from 'node:assert/strict';
+import { mkdtempSync, rmSync } from 'node:fs';
+import { tmpdir } from 'node:os';
+import { join } from 'node:path';
+import { DatabaseSync } from 'node:sqlite';
+import { ensureAccount, addPasskey, listPasskeys, findPasskey, renamePasskey, removePasskey, recordPasskeyUse, publicPasskey, saveChallenge, consumeChallenge } from '../src/lib/account-store.ts';
+
+const directory = mkdtempSync(join(tmpdir(), 'times-account-test-'));
+process.env.ACCOUNT_DB_PATH = join(directory, 'accounts.sqlite');
+after(() => rmSync(directory, { recursive: true, force: true }));
+
+test('passkey changes persist and are isolated by account and relying party', () => {
+  const alice = ensureAccount('alice');
+  const bob = ensureAccount('bob');
+  assert.deepEqual(ensureAccount('alice'), alice);
+  assert.match(alice.userId, /^[A-Za-z0-9_-]+$/);
+  const key = { id: Buffer.from('alice-key').toString('base64url'), accountId: alice.id, rpId: 'example.com', name: 'Laptop', aaguid: '00000000-0000-0000-0000-000000000000', publicKey: 'cHVibGljLWtleQ', counter: 0, transports: ['internal'], registeredAt: 1700000000000, backedUp: false, deviceType: 'singleDevice' };
+  addPasskey(key);
+  assert.deepEqual(listPasskeys(bob.id, key.rpId), []);
+  assert.deepEqual(listPasskeys(alice.id, 'different.example'), []);
+  assert.equal(renamePasskey(key.id, bob.id, key.rpId, 'Stolen'), false);
+  assert.equal(removePasskey(key.id, bob.id, key.rpId), false);
+  assert.equal(renamePasskey(key.id, alice.id, 'different.example', 'Wrong RP'), false);
+  assert.equal(removePasskey(key.id, alice.id, 'different.example'), false);
+  assert.equal(renamePasskey(key.id, alice.id, key.rpId, 'Travel laptop'), true);
+  assert.equal(recordPasskeyUse(key, 1, true), true);
+  const updated = findPasskey(key.id);
+  assert.equal(updated.name, 'Travel laptop');
+  assert.equal(updated.counter, 1);
+  assert.equal(updated.backedUp, true);
+  assert.ok(updated.lastUsedAt >= key.registeredAt);
+  assert.equal(recordPasskeyUse(key, 2, true), false, 'stale counter cannot overwrite a newer assertion');
+  const publicRecord = publicPasskey(updated);
+  for (const field of ['publicKey', 'counter', 'accountId', 'rpId']) assert.equal(field in publicRecord, false);
+  const persisted = new DatabaseSync(process.env.ACCOUNT_DB_PATH);
+  assert.equal(JSON.parse(persisted.prepare('SELECT record FROM passkeys WHERE id = ?').get(key.id).record).name, 'Travel laptop');
+  persisted.close();
+  assert.equal(removePasskey(key.id, alice.id, key.rpId), true);
+  assert.deepEqual(listPasskeys(alice.id, key.rpId), [], 'the final key can be removed');
+  assert.equal(recordPasskeyUse(updated, 2, true), false, 'a racing sign-in cannot recreate a deleted key');
+  assert.equal(removePasskey(key.id, alice.id, key.rpId), false);
+});
+
+test('verification challenges expire and are consumed only once', () => {
+  saveChallenge('one-time-challenge', Date.now() + 10000);
+  assert.equal(consumeChallenge('one-time-challenge'), true);
+  assert.equal(consumeChallenge('one-time-challenge'), false);
+  saveChallenge('expired-challenge', Date.now() - 1000);
+  assert.equal(consumeChallenge('expired-challenge'), false);
+});
