+import { test, after } from 'node:test';
+import assert from 'node:assert/strict';
+import { syncPasskeys } from '../src/lib/passkey-client.ts';
+
+after(() => { delete globalThis.window; delete globalThis.PublicKeyCredential; });
+const valid = { rpId: 'example.com', userId: 'dXNlci0x', credentials: [{ id: 'a2V5LTE' }, { id: 'a2V5LTI' }] };
+test('sync uses server RP and encoded IDs, including an empty accepted list after last deletion', async () => {
+  const calls = [];
+  globalThis.PublicKeyCredential = { signalAllAcceptedCredentials: async data => calls.push(data) };
+  globalThis.window = { PublicKeyCredential: globalThis.PublicKeyCredential, location: { hostname: 'accounts.example.com' } };
+  assert.equal(await syncPasskeys(valid), 'synced');
+  assert.deepEqual(calls[0], { rpId: 'example.com', userId: valid.userId, allAcceptedCredentialIds: ['a2V5LTE', 'a2V5LTI'] });
+  assert.equal(await syncPasskeys({ ...valid, credentials: [] }), 'synced');
+  assert.deepEqual(calls[1].allAcceptedCredentialIds, []);
+});
+test('unsupported browsers and malformed IDs safely skip synchronization', async () => {
+  globalThis.window = {};
+  assert.equal(await syncPasskeys(valid), 'unsupported');
+  let calls = 0;
+  globalThis.PublicKeyCredential = { signalAllAcceptedCredentials: async () => { calls++; } };
+  globalThis.window.PublicKeyCredential = globalThis.PublicKeyCredential;
+  const previous = console.warn;
+  const warnings = [];
+  console.warn = (...args) => warnings.push(args);
+  try {
+    for (const invalid of ['invalid=', 'x', '', 'bad:id']) {
+      assert.equal(await syncPasskeys({ ...valid, userId: invalid }), 'failed');
+      assert.equal(await syncPasskeys({ ...valid, credentials: [{ id: invalid }] }), 'failed');
+    }
+    assert.equal(calls, 0);
+    globalThis.PublicKeyCredential.signalAllAcceptedCredentials = async () => { throw new Error('provider unavailable'); };
+    assert.equal(await syncPasskeys(valid), 'failed');
+    assert.ok(warnings.length > 0);
+  } finally { console.warn = previous; }
+});

