diff --git a/src/lib/account-server.ts b/src/lib/account-server.ts
new file mode 100644
index 0000000..c229814
--- /dev/null
+++ b/src/lib/account-server.ts
@@ -0,0 +1,36 @@
+// Keep account credentials on the server, in Astro's session store.
+export interface AccountSession {
+  username: string;
+  token?: string;
+  cookie?: string;
+}
+
+export const accountAPI = () =>
+  (
+    import.meta.env.ACCOUNT_API_URL ||
+    "https://us-central1-web-devrel-apps.cloudfunctions.net/times_cdn/api"
+  ).replace(/\/$/, "");
+
+export function accountHeaders(account: AccountSession) {
+  const headers = new Headers({
+    "Content-Type": "application/json",
+    Accept: "application/json",
+  });
+  if (account.token) headers.set("Authorization", `Bearer ${account.token}`);
+  if (account.cookie) headers.set("Cookie", account.cookie);
+  return headers;
+}
+
+export function json(data: unknown, status = 200) {
+  return new Response(JSON.stringify(data), {
+    status,
+    headers: {
+      "Content-Type": "application/json",
+      "Cache-Control": "no-store",
+    },
+  });
+}
+
+export function sameOrigin(request: Request) {
+  return request.headers.get("Origin") === new URL(request.url).origin;
+}
diff --git a/src/lib/passkeys.ts b/src/lib/passkeys.ts
new file mode 100644
index 0000000..cb7ef37
--- /dev/null
+++ b/src/lib/passkeys.ts
@@ -0,0 +1,122 @@
+export interface Passkey {
+  id: string;
+  displayName: string;
+  provider: string;
+  deviceType: "computer" | "phone" | "security-key";
+  createdAt: string;
+  lastUsedAt: string | null;
+  current?: boolean;
+}
+
+export interface PasskeyAccount {
+  user: { id: string; name: string; displayName: string };
+  rpId: string;
+  passkeys: Passkey[];
+}
+
+// This account is only an interactive preview. Never send its IDs to an authenticator.
+export const sampleAccount: PasskeyAccount = {
+  user: {
+    id: "preview",
+    name: "alex.morgan@example.com",
+    displayName: "Alex Morgan",
+  },
+  rpId: "",
+  passkeys: [
+    {
+      id: "preview-mac",
+      displayName: "MacBook Pro",
+      provider: "iCloud Keychain",
+      deviceType: "computer",
+      createdAt: "2026-09-12T10:00:00Z",
+      lastUsedAt: "2026-11-19T09:42:00Z",
+      current: true,
+    },
+    {
+      id: "preview-phone",
+      displayName: "iPhone 16",
+      provider: "iCloud Keychain",
+      deviceType: "phone",
+      createdAt: "2026-09-12T10:15:00Z",
+      lastUsedAt: "2026-11-17T18:00:00Z",
+    },
+    {
+      id: "preview-key",
+      displayName: "YubiKey 5C NFC",
+      provider: "Security key",
+      deviceType: "security-key",
+      createdAt: "2026-10-04T15:00:00Z",
+      lastUsedAt: "2026-10-28T12:00:00Z",
+    },
+  ],
+};
+
+export function validDisplayName(value: unknown): value is string {
+  return (
+    typeof value === "string" &&
+    value.trim().length > 0 &&
+    value.trim().length <= 64
+  );
+}
+
+export function isPasskeyAccount(value: unknown): value is PasskeyAccount {
+  const account = value as PasskeyAccount | null;
+  return (
+    !!account &&
+    typeof account.rpId === "string" &&
+    !!account.rpId &&
+    typeof account.user?.id === "string" &&
+    /^[A-Za-z0-9_-]+$/.test(account.user.id) &&
+    typeof account.user.name === "string" &&
+    typeof account.user.displayName === "string" &&
+    Array.isArray(account.passkeys) &&
+    account.passkeys.every(
+      (key) =>
+        !!key &&
+        typeof key.id === "string" &&
+        /^[A-Za-z0-9_-]+$/.test(key.id) &&
+        validDisplayName(key.displayName) &&
+        typeof key.provider === "string" &&
+        ["computer", "phone", "security-key"].includes(key.deviceType) &&
+        (key.current === undefined || typeof key.current === "boolean") &&
+        typeof key.createdAt === "string" &&
+        Number.isFinite(Date.parse(key.createdAt)) &&
+        (key.lastUsedAt === null ||
+          (typeof key.lastUsedAt === "string" &&
+            Number.isFinite(Date.parse(key.lastUsedAt)))),
+    ) &&
+    new Set(account.passkeys.map((key) => key.id)).size ===
+      account.passkeys.length
+  );
+}
+
+type SignalAPI = {
+  signalAllAcceptedCredentials?: (options: {
+    rpId: string;
+    userId: string;
+    allAcceptedCredentialIds: string[];
+  }) => Promise<void>;
+};
+
+export async function syncAuthenticator(
+  account: PasskeyAccount,
+): Promise<"sent" | "unsupported" | "failed"> {
+  const api = globalThis.PublicKeyCredential as unknown as
+    SignalAPI | undefined;
+  if (
+    !account.rpId ||
+    !globalThis.isSecureContext ||
+    !api?.signalAllAcceptedCredentials
+  )
+    return "unsupported";
+  try {
+    await api.signalAllAcceptedCredentials({
+      rpId: account.rpId,
+      userId: account.user.id,
+      allAcceptedCredentialIds: account.passkeys.map((key) => key.id),
+    });
+    return "sent";
+  } catch {
+    return "failed";
+  }
+}
