diff --git a/src/pages/api/account/login.ts b/src/pages/api/account/login.ts
new file mode 100644
index 0000000..e0d1782
--- /dev/null
+++ b/src/pages/api/account/login.ts
@@ -0,0 +1,54 @@
+import type { APIRoute } from "astro";
+import { accountAPI, json, sameOrigin } from "../../../lib/account-server";
+
+export const POST: APIRoute = async ({ request, session }) => {
+  if (!sameOrigin(request))
+    return json({ error: "Request origin is not allowed." }, 403);
+  if (!session)
+    return json({ error: "Account sessions are unavailable." }, 503);
+  try {
+    const { username, password } = await request.json();
+    if (
+      typeof username !== "string" ||
+      typeof password !== "string" ||
+      !username ||
+      !password
+    ) {
+      return json({ error: "Enter your username and password." }, 400);
+    }
+    const response = await fetch(`${accountAPI()}/login`, {
+      method: "POST",
+      headers: { "Content-Type": "application/json" },
+      body: JSON.stringify({ username, password }),
+      signal: AbortSignal.timeout(15000),
+    });
+    if (!response.ok)
+      return json(
+        { error: "Unable to sign in. Check your username and password." },
+        response.status === 401 ? 401 : 400,
+      );
+    const data = await response.json();
+    const token = typeof data.token === "string" ? data.token : undefined;
+    const cookie =
+      response.headers
+        .getSetCookie()
+        .map((value) => value.split(";")[0])
+        .join("; ") || undefined;
+    if (!token && !cookie)
+      return json(
+        {
+          error:
+            "The account service did not return a session. Please try again later.",
+        },
+        502,
+      );
+    await session.regenerate();
+    await session.set("account", { username, token, cookie });
+    return json({ success: true });
+  } catch {
+    return json(
+      { error: "The account service is unavailable. Please try again." },
+      502,
+    );
+  }
+};
