+import type { APIRoute } from "astro";
+import {
+  accountAPI,
+  accountHeaders,
+  json,
+  sameOrigin,
+  type AccountSession,
+} from "../../../lib/account-server";
+import { isPasskeyAccount, validDisplayName } from "../../../lib/passkeys";
+
+const handle: APIRoute = async ({ request, session }) => {
+  if (request.method !== "GET" && !sameOrigin(request))
+    return json({ error: "Request origin is not allowed." }, 403);
+  const account = (await session?.get("account")) as AccountSession | undefined;
+  if (!account)
+    return json({ error: "Please sign in to manage your passkeys." }, 401);
+  try {
+    let path = "/passkeys";
+    let body: string | undefined;
+    if (request.method !== "GET") {
+      const input = await request.json();
+      if (typeof input.id !== "string" || !/^[A-Za-z0-9_-]+$/.test(input.id))
+        return json({ error: "Invalid passkey." }, 400);
+      path += `/${encodeURIComponent(input.id)}`;
+      if (request.method === "PATCH") {
+        if (!validDisplayName(input.displayName))
+          return json(
+            { error: "Use a name between 1 and 64 characters." },
+            400,
+          );
+        body = JSON.stringify({ displayName: input.displayName.trim() });
+      }
+    }
+    const response = await fetch(`${accountAPI()}${path}`, {
+      method: request.method,
+      headers: accountHeaders(account),
+      body,
+      signal: AbortSignal.timeout(15000),
+    });
+    if (!response.ok) {
+      if (response.status === 401) await session?.delete("account");
+      return json(
+        {
+          error:
+            response.status === 401
+              ? "Your session expired. Please sign in again."
+              : "Your passkeys could not be updated. Please try again.",
+        },
+        response.status === 401 ? 401 : 502,
+      );
+    }
+    // Reload the authoritative list after every mutation, including an empty list after the last removal.
+    const snapshot =
+      request.method === "GET"
+        ? response
+        : await fetch(`${accountAPI()}/passkeys`, {
+            headers: accountHeaders(account),
+            signal: AbortSignal.timeout(15000),
+          });
+    if (!snapshot.ok)
+      return json(
+        {
+          error:
+            "Your change may have been saved. Reload the list before making another change.",
+        },
+        502,
+      );
+    const data = await snapshot.json();
+    if (!isPasskeyAccount(data))
+      return json(
+        { error: "The account service returned an invalid passkey list." },
+        502,
+      );
+    return json(data);
+  } catch {
+    return json(
+      {
+        error:
+          "We could not reach the account service. Reload your passkeys and try again.",
+      },
+      502,
+    );
+  }
+};
