diff --git a/tests/passkeys.test.ts b/tests/passkeys.test.ts
new file mode 100644
index 0000000..daf222d
--- /dev/null
+++ b/tests/passkeys.test.ts
@@ -0,0 +1,121 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import {
+  isPasskeyAccount,
+  validDisplayName,
+  syncAuthenticator,
+} from "../src/lib/passkeys.ts";
+
+const account = {
+  user: { id: "dXNlcg", name: "reader", displayName: "Reader" },
+  rpId: "example.com",
+  passkeys: [
+    {
+      id: "a2V5",
+      displayName: "Laptop",
+      deviceType: "computer" as const,
+      provider: "Password manager",
+      createdAt: "2026-01-01T00:00:00Z",
+      lastUsedAt: null,
+    },
+  ],
+};
+
+test("rejects invalid names and malformed credential snapshots", () => {
+  assert.equal(validDisplayName("   "), false);
+  assert.equal(validDisplayName("x".repeat(65)), false);
+  assert.equal(validDisplayName("  Laptop  "), true);
+  assert.equal(isPasskeyAccount(account), true);
+  assert.equal(isPasskeyAccount({ ...account, passkeys: [] }), true);
+  assert.equal(isPasskeyAccount({ ...account, passkeys: [null] }), false);
+  assert.equal(
+    isPasskeyAccount({
+      ...account,
+      passkeys: [account.passkeys[0], account.passkeys[0]],
+    }),
+    false,
+  );
+  assert.equal(
+    isPasskeyAccount({
+      ...account,
+      user: { ...account.user, id: "not base64url!" },
+    }),
+    false,
+  );
+  assert.equal(
+    isPasskeyAccount({
+      ...account,
+      passkeys: [{ ...account.passkeys[0], id: "invalid id" }],
+    }),
+    false,
+  );
+  assert.equal(
+    isPasskeyAccount({
+      ...account,
+      passkeys: [{ ...account.passkeys[0], createdAt: "bad-date" }],
+    }),
+    false,
+  );
+});
+
+test("signals the authoritative list, including removal of the last credential", async () => {
+  const originalAPI = Object.getOwnPropertyDescriptor(
+    globalThis,
+    "PublicKeyCredential",
+  );
+  const originalSecure = Object.getOwnPropertyDescriptor(
+    globalThis,
+    "isSecureContext",
+  );
+  const calls: unknown[] = [];
+  try {
+    Object.defineProperty(globalThis, "isSecureContext", {
+      configurable: true,
+      value: true,
+    });
+    Object.defineProperty(globalThis, "PublicKeyCredential", {
+      configurable: true,
+      value: {
+        signalAllAcceptedCredentials: async (value: unknown) => {
+          calls.push(value);
+        },
+      },
+    });
+    assert.equal(await syncAuthenticator(account), "sent");
+    assert.equal(await syncAuthenticator({ ...account, passkeys: [] }), "sent");
+    assert.deepEqual(calls, [
+      {
+        rpId: "example.com",
+        userId: "dXNlcg",
+        allAcceptedCredentialIds: ["a2V5"],
+      },
+      { rpId: "example.com", userId: "dXNlcg", allAcceptedCredentialIds: [] },
+    ]);
+    Object.defineProperty(globalThis, "PublicKeyCredential", {
+      configurable: true,
+      value: {},
+    });
+    assert.equal(await syncAuthenticator(account), "unsupported");
+    Object.defineProperty(globalThis, "PublicKeyCredential", {
+      configurable: true,
+      value: {
+        signalAllAcceptedCredentials: async () => {
+          throw new Error("Authenticator unavailable");
+        },
+      },
+    });
+    assert.equal(await syncAuthenticator(account), "failed");
+    Object.defineProperty(globalThis, "isSecureContext", {
+      configurable: true,
+      value: false,
+    });
+    assert.equal(await syncAuthenticator(account), "unsupported");
+  } finally {
+    if (originalAPI)
+      Object.defineProperty(globalThis, "PublicKeyCredential", originalAPI);
+    else Reflect.deleteProperty(globalThis, "PublicKeyCredential");
+    if (originalSecure)
+      Object.defineProperty(globalThis, "isSecureContext", originalSecure);
+    else Reflect.deleteProperty(globalThis, "isSecureContext");
+  }
+});

