diff --git a/server.mjs b/server.mjs
new file mode 100644
index 0000000..50fd803
--- /dev/null
+++ b/server.mjs
@@ -0,0 +1,32 @@
+import { createServer } from 'node:http';
+import { readFile } from 'node:fs/promises';
+import { existsSync, mkdirSync } from 'node:fs';
+import { resolve, extname, sep } from 'node:path';
+import { createApi, openDatabase } from './src/api.mjs';
+
+const port = Number(process.env.PORT || 11222);
+const origin = process.env.APP_ORIGIN || `http://localhost:${port}`;
+const rpId = process.env.RP_ID || new URL(origin).hostname;
+if (process.env.NODE_ENV === 'production' && !origin.startsWith('https://')) throw Error('APP_ORIGIN must use HTTPS in production.');
+const dataDir = resolve(process.env.DATA_DIR || './data');
+mkdirSync(dataDir, { recursive: true, mode: 0o700 });
+const api = createApi({ db: openDatabase(resolve(dataDir, 'daily-grind.sqlite')), origin, rpId });
+const root = resolve('dist');
+if (!existsSync(resolve(root, 'index.html'))) throw Error('Build the frontend with pnpm build before starting.');
+const mime = { '.html': 'text/html; charset=utf-8', '.js': 'text/javascript; charset=utf-8', '.css': 'text/css; charset=utf-8', '.svg': 'image/svg+xml', '.png': 'image/png', '.ico': 'image/x-icon' };
+createServer(async (req, res) => {
+  res.setHeader('X-Content-Type-Options', 'nosniff');
+  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
+  res.setHeader('Permissions-Policy', 'publickey-credentials-create=(self), publickey-credentials-get=(self)');
+  if (req.url.startsWith('/api/')) return api(req, res);
+  res.setHeader('Content-Security-Policy', "default-src 'self'; script-src 'self'; style-src 'self' https://fonts.googleapis.com; font-src 'self' https://fonts.gstatic.com; img-src 'self' data: https://images.unsplash.com; connect-src 'self'; frame-ancestors 'none'; base-uri 'self'; form-action 'self'");
+  if (!['GET', 'HEAD'].includes(req.method)) { res.writeHead(405); return res.end(); }
+  try {
+    const pathname = decodeURIComponent(new URL(req.url, origin).pathname);
+    const file = resolve(root, pathname === '/' || pathname === '/account' ? 'index.html' : `.${pathname}`);
+    if (!file.startsWith(root + sep)) throw Error();
+    const content = await readFile(file);
+    res.writeHead(200, { 'Content-Type': mime[extname(file)] || 'application/octet-stream', 'Cache-Control': extname(file) === '.html' ? 'no-cache' : 'public, max-age=31536000, immutable' });
+    res.end(req.method === 'HEAD' ? undefined : content);
+  } catch { res.writeHead(404, { 'Content-Type': 'text/plain' }); res.end('Page not found'); }
+}).listen(port, '0.0.0.0', () => console.log(`Daily Grind listening on port ${port}`));
