+import { randomBytes } from 'node:crypto';
+import { DatabaseSync } from 'node:sqlite';
+import { generateRegistrationOptions, verifyRegistrationResponse, generateAuthenticationOptions, verifyAuthenticationResponse } from '@simplewebauthn/server';
+import aaguids from './aaguids.json' with { type: 'json' };
+
+const token = () => randomBytes(32).toString('base64url');
+const fail = (status, message) => { throw Object.assign(new Error(message), { status }); };
+export function openDatabase(path) {
+  const db = new DatabaseSync(path);
+  db.exec(`PRAGMA foreign_keys=ON; PRAGMA journal_mode=WAL;
+    CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY, email TEXT UNIQUE COLLATE NOCASE, name TEXT NOT NULL, createdAt INTEGER NOT NULL);
+    CREATE TABLE IF NOT EXISTS passkeys(id TEXT PRIMARY KEY, userId TEXT NOT NULL REFERENCES users(id), publicKey TEXT NOT NULL, counter INTEGER NOT NULL, transports TEXT NOT NULL, deviceType TEXT, backedUp INTEGER, aaguid TEXT, name TEXT NOT NULL, registeredAt INTEGER NOT NULL, lastUsedAt INTEGER);
+    CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY, userId TEXT REFERENCES users(id), expires INTEGER NOT NULL, verifiedAt INTEGER NOT NULL DEFAULT 0);
+    CREATE TABLE IF NOT EXISTS ceremonies(id TEXT PRIMARY KEY, sessionId TEXT NOT NULL, kind TEXT NOT NULL, challenge TEXT NOT NULL, payload TEXT NOT NULL, expires INTEGER NOT NULL);`);
+  return db;
+}
+export function createApi({ db, origin, rpId, secure = origin.startsWith('https:') }) {
+  const cookieName = secure ? '__Host-dg_session' : 'dg_session';
+  const limits = new Map();
+  const sessionTTL = 7 * 24 * 60 * 60 * 1000;
+  const userKeys = (id) => db.prepare('SELECT * FROM passkeys WHERE userId=? ORDER BY registeredAt DESC').all(id);
+  function publicAccount(user) {
+    return { user: { id: user.id, email: user.email, displayName: user.name, createdAt: user.createdAt }, rpId, userId: user.id,
+      credentials: userKeys(user.id).map(k => ({ id: k.id, name: k.name, registeredAt: k.registeredAt, lastUsedAt: k.lastUsedAt, backedUp: Boolean(k.backedUp), deviceType: k.deviceType, aaguid: k.aaguid, provider: aaguids[k.aaguid]?.name || 'Passkey', providerIcon: aaguids[k.aaguid]?.icon_light })) };
+  }
+  const cookie = (res, id, age = sessionTTL / 1000) => res.setHeader('Set-Cookie', `${cookieName}=${id}; HttpOnly; SameSite=Strict; Path=/; Max-Age=${age}${secure ? '; Secure' : ''}`);
+  function rotate(res, session, userId) {
+    db.prepare('DELETE FROM sessions WHERE id=?').run(session.id);
+    db.prepare('DELETE FROM ceremonies WHERE sessionId=?').run(session.id);
+    const id = token();
+    db.prepare('INSERT INTO sessions(id,userId,expires,verifiedAt) VALUES(?,?,?,0)').run(id, userId, Date.now() + sessionTTL);
+    cookie(res, id);
+  }
+  function ceremony(session, kind, options, payload = {}) {
+    const id = token();
+    db.prepare('INSERT INTO ceremonies VALUES(?,?,?,?,?,?)').run(id, session.id, kind, options.challenge, JSON.stringify(payload), Date.now() + 300000);
+    return { options, ceremonyId: id };
+  }
+  function consume(session, id, kind) {
+    const row = db.prepare('SELECT * FROM ceremonies WHERE id=? AND sessionId=? AND kind=?').get(id || '', session.id, kind);
+    if (!row || row.expires < Date.now()) fail(400, 'This request has expired. Please try again.');
+    db.prepare('DELETE FROM ceremonies WHERE id=?').run(row.id);
+    return { ...row, payload: JSON.parse(row.payload) };
+  }
+  function profile(body) {
+    const name = typeof body.displayName === 'string' ? body.displayName.trim() : '';
+    const email = typeof body.email === 'string' ? body.email.trim().toLowerCase() : '';
+    if (!name || name.length > 80 || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email) || email.length > 254) fail(400, 'Enter your name and a valid email address.');
+    return { name, email };
+  }
+  function requireRecent(session) {
+    if (!session.verifiedAt || Date.now() - session.verifiedAt > 120000) fail(403, 'Please verify your identity with a passkey before making this change.');
+  }
+  async function bodyOf(req) {
+    if (!req.headers['content-type']?.startsWith('application/json')) fail(415, 'Please send JSON.');
+    let raw = '';
+    for await (const chunk of req) { raw += chunk; if (Buffer.byteLength(raw) > 65536) fail(413, 'Request too large.'); }
+    try { const data = JSON.parse(raw || '{}'); if (!data || Array.isArray(data) || typeof data !== 'object') throw Error(); return data; }
+    catch { fail(400, 'Invalid request.'); }
+  }
+  return async function api(req, res) {
+    const send = (status, data) => { res.writeHead(status, { 'Content-Type': 'application/json', 'Cache-Control': 'no-store', 'X-Content-Type-Options': 'nosniff' }); res.end(JSON.stringify(data)); };
+    try {
+      const now = Date.now();
+      db.prepare('DELETE FROM sessions WHERE expires<?').run(now);
+      db.prepare('DELETE FROM ceremonies WHERE expires<?').run(now);
+      const path = new URL(req.url, origin).pathname;
+      const write = req.method !== 'GET';
+      if (write && req.headers.origin !== origin) fail(403, 'Request origin is not allowed.');
+      if (write) {
+        const ip = req.socket.remoteAddress || 'unknown';
+        for (const [key, item] of limits) if (item.reset < now) limits.delete(key);
+        const limit = limits.get(ip) || { count: 0, reset: now + 60000 };
+        limit.count++; limits.set(ip, limit);
+        if (limit.count > 80) fail(429, 'Too many requests. Please try again in a minute.');
+      }
+      const cookies = Object.fromEntries((req.headers.cookie || '').split(';').map(s => s.trim().split('=')));
+      let session = db.prepare('SELECT * FROM sessions WHERE id=?').get(cookies[cookieName] || '');
+      if (!session) {
+        session = { id: token(), userId: null, expires: now + sessionTTL, verifiedAt: 0 };
+        db.prepare('INSERT INTO sessions VALUES(?,?,?,?)').run(session.id, null, session.expires, 0);
+        cookie(res, session.id);
+      }
+      const user = session.userId ? db.prepare('SELECT * FROM users WHERE id=?').get(session.userId) : null;
+      if (req.method === 'GET' && path === '/api/account') return send(200, user ? publicAccount(user) : { user: null });
+      const body = write ? await bodyOf(req) : {};
+      if (path === '/api/logout' && req.method === 'POST') {
+        db.prepare('DELETE FROM sessions WHERE id=?').run(session.id);
+        db.prepare('DELETE FROM ceremonies WHERE sessionId=?').run(session.id);
+        cookie(res, '', 0); return send(200, { ok: true });
+      }
+      if (path === '/api/register/options' && req.method === 'POST') {
+        if (user) fail(409, 'You are already signed in. Add a passkey from your security settings.');
+        const data = profile(body);
+        if (db.prepare('SELECT id FROM users WHERE email=?').get(data.email)) fail(409, 'An account with this email already exists. Sign in with your passkey.');
+        const pendingUser = { id: token(), ...data };
+        const options = await generateRegistrationOptions({ rpName: 'The Daily Grind', rpID: rpId, userID: Buffer.from(pendingUser.id, 'base64url'), userName: data.email, userDisplayName: data.name, attestationType: 'none', authenticatorSelection: { residentKey: 'required', requireResidentKey: true, userVerification: 'required' } });
+        return send(200, ceremony(session, 'register', options, pendingUser));
+      }
+      if ((path === '/api/register/verify' || path === '/api/passkeys/verify') && req.method === 'POST') {
+        const add = path.startsWith('/api/passkeys');
+        if (add && !user) fail(401, 'Please sign in again.');
+        if (add) requireRecent(session);
+        const c = consume(session, body.ceremonyId, add ? 'add' : 'register');
+        const result = await verifyRegistrationResponse({ response: body.credential, expectedChallenge: c.challenge, expectedOrigin: origin, expectedRPID: rpId, requireUserVerification: true });
+        if (!result.verified || !result.registrationInfo) fail(400, 'We could not verify this passkey. Please try again.');
+        const info = result.registrationInfo;
+        const account = add ? user : c.payload;
+        if (add && account.id !== c.payload.id) fail(403, 'This passkey request belongs to a different account.');
+        if (db.prepare('SELECT id FROM passkeys WHERE id=?').get(info.credential.id)) fail(409, 'This passkey is already registered.');
+        if (!add && db.prepare('SELECT id FROM users WHERE email=?').get(account.email)) fail(409, 'An account with this email already exists.');
+        db.exec('BEGIN IMMEDIATE');
+        try {
+          if (!add) db.prepare('INSERT INTO users VALUES(?,?,?,?)').run(account.id, account.email, account.name, now);
+          db.prepare('INSERT INTO passkeys VALUES(?,?,?,?,?,?,?,?,?,?,?)').run(info.credential.id, account.id, Buffer.from(info.credential.publicKey).toString('base64url'), info.credential.counter, JSON.stringify(info.credential.transports || []), info.credentialDeviceType, Number(info.credentialBackedUp), info.aaguid, aaguids[info.aaguid]?.name || 'My passkey', now, null);
+          db.exec('COMMIT');
+        } catch (e) { db.exec('ROLLBACK'); throw e; }
+        if (!add) rotate(res, session, account.id);
+        else db.prepare('UPDATE sessions SET verifiedAt=0 WHERE id=?').run(session.id);
+        return send(200, publicAccount(db.prepare('SELECT * FROM users WHERE id=?').get(account.id)));
+      }
+      if ((path === '/api/login/options' || path === '/api/reauth/options') && req.method === 'POST') {
+        const reauth = path.startsWith('/api/reauth');
+        if (reauth && !user) fail(401, 'Please sign in again.');
+        if (!reauth && user) fail(409, 'You are already signed in.');
+        const allowed = reauth ? userKeys(user.id).map(k => ({ id: k.id, transports: JSON.parse(k.transports) })) : [];
+        if (reauth && !allowed.length) fail(400, 'There are no passkeys available for this account.');
+        const options = await generateAuthenticationOptions({ rpID: rpId, userVerification: 'required', allowCredentials: allowed });
+        return send(200, ceremony(session, reauth ? 'reauth' : 'login', options, { userId: user?.id, email: typeof body.email === 'string' ? body.email.trim().toLowerCase() : '' }));
+      }
+      if ((path === '/api/login/verify' || path === '/api/reauth/verify') && req.method === 'POST') {
+        const reauth = path.startsWith('/api/reauth');
+        if (reauth && !user) fail(401, 'Please sign in again.');
+        const c = consume(session, body.ceremonyId, reauth ? 'reauth' : 'login');
+        const key = db.prepare('SELECT * FROM passkeys WHERE id=?').get(body.credential?.id || '');
+        if (!key) fail(404, 'This passkey is no longer registered. Try another passkey or create an account.');
+        if (reauth && (key.userId !== user.id || key.userId !== c.payload.userId)) fail(403, 'Use a passkey belonging to your signed-in account.');
+        const account = db.prepare('SELECT * FROM users WHERE id=?').get(key.userId);
+        if (!reauth && c.payload.email && c.payload.email !== account.email) fail(400, 'This passkey belongs to another email. Use its account email or leave the email field blank.');
+        if (body.credential.response?.userHandle && body.credential.response.userHandle !== key.userId) fail(403, 'The passkey does not match this account.');
+        const result = await verifyAuthenticationResponse({ response: body.credential, expectedChallenge: c.challenge, expectedOrigin: origin, expectedRPID: rpId, requireUserVerification: true, credential: { id: key.id, publicKey: Buffer.from(key.publicKey, 'base64url'), counter: key.counter, transports: JSON.parse(key.transports) } });
+        if (!result.verified) fail(400, 'We could not verify your identity. Please try again.');
+        // Re-read the counter after async verification to reject competing assertions.
+        const latest = db.prepare('SELECT * FROM passkeys WHERE id=?').get(key.id);
+        if (!latest || latest.counter !== key.counter) fail(409, 'Your passkey changed during sign-in. Please try again.');
+        db.prepare('UPDATE passkeys SET counter=?,lastUsedAt=?,backedUp=? WHERE id=?').run(result.authenticationInfo.newCounter, now, Number(result.authenticationInfo.credentialBackedUp), key.id);
+        if (reauth) db.prepare('UPDATE sessions SET verifiedAt=? WHERE id=?').run(now, session.id);
+        else rotate(res, session, account.id);
+        return send(200, reauth ? { verified: true } : publicAccount(account));
+      }
+      if (!user) fail(401, 'Please sign in to manage your account.');
+      if (path === '/api/passkeys/options' && req.method === 'POST') {
+        requireRecent(session);
+        const options = await generateRegistrationOptions({ rpName: 'The Daily Grind', rpID: rpId, userID: Buffer.from(user.id, 'base64url'), userName: user.email, userDisplayName: user.name, excludeCredentials: userKeys(user.id).map(k => ({ id: k.id, transports: JSON.parse(k.transports) })), attestationType: 'none', authenticatorSelection: { residentKey: 'required', requireResidentKey: true, userVerification: 'required' } });
