+      }
+      if (path === '/api/profile' && req.method === 'PUT') {
+        requireRecent(session);
+        const data = profile(body);
+        const exists = db.prepare('SELECT id FROM users WHERE email=? AND id<>?').get(data.email, user.id);
+        if (exists) fail(409, 'This email is already associated with another account.');
+        db.prepare('UPDATE users SET email=?,name=? WHERE id=?').run(data.email, data.name, user.id);
+        db.prepare('UPDATE sessions SET verifiedAt=0 WHERE id=?').run(session.id);
+        return send(200, publicAccount(db.prepare('SELECT * FROM users WHERE id=?').get(user.id)));
+      }
+      const match = path.match(/^\/api\/passkeys\/([A-Za-z0-9_-]+)$/);
