+        if (!key) fail(404, 'Passkey not found.');
+        if (req.method === 'PUT') {
+          const name = typeof body.name === 'string' ? body.name.trim() : '';
+          if (!name || name.length > 60) fail(400, 'Choose a name between 1 and 60 characters.');
+          db.prepare('UPDATE passkeys SET name=? WHERE id=?').run(name, key.id);
+        } else {
+          requireRecent(session);
+          if (userKeys(user.id).length <= 1) fail(409, 'Add another passkey before removing your last one, so you can still sign in.');
