+const date = (time) => time ? new Intl.DateTimeFormat(undefined, { dateStyle: 'medium' }).format(time) : 'Not used yet';
+const state = { account: null, mode: 'signin', page: 'welcome', busy: false, supported: false, conditional: false, apiReady: false };
+let controller = null;
+let conditionalTask = null;
+let action = null;
+
+function notice(message = '', error = false) {
+  $('#notice').textContent = message;
+  $('#notice').classList.toggle('error', error);
+  $('#notice').hidden = !message;
+}
+async function api(path, body, method = 'POST') {
+  let response;
+  try {
+    response = await fetch(`/api/${path}`, { method, credentials: 'same-origin', headers: method === 'GET' ? {} : { 'Content-Type': 'application/json' }, ...(method !== 'GET' && { body: JSON.stringify(body || {}) }) });
+  } catch { throw new Error('We couldn’t reach your account. Check your connection and try again.'); }
+  let data;
