+import { useEffect, useState } from 'react';
+import { ArrowRightIcon, CheckIcon, EyeIcon, EyeSlashIcon, FingerPrintIcon, LockClosedIcon, ShieldCheckIcon } from '@heroicons/react/24/outline';
+import { accountUrl, authMessage, authRequest, authenticatePasskey, registerPasskey, supportsPasskeys } from '../lib/auth-client';
+
+export default function AuthForm({ signup = false }: { signup?: boolean }) {
+  const [method, setMethod] = useState<'passkey' | 'password'>('passkey');
+  const [username, setUsername] = useState('');
+  const [password, setPassword] = useState('');
+  const [showPassword, setShowPassword] = useState(false);
+  const [supported, setSupported] = useState<boolean | null>(null);
+  const [busy, setBusy] = useState('');
+  const [error, setError] = useState('');
+  useEffect(() => { setSupported(supportsPasskeys()); }, []);
+  async function submit(passkey: boolean) {
+    if (busy) return;
+    setError(''); setBusy(passkey ? 'passkey' : 'password');
+    try {
+      if (passkey) {
+        if (signup) await registerPasskey(username);
+        else await authenticatePasskey();
+      } else await authRequest(signup ? 'register' : 'login', { username, password });
+      window.location.assign(accountUrl);
+    } catch (e) { setError(authMessage(e)); }
+    finally { setBusy(''); }
+  }
+  return <div className="auth-form-wrap">
+    <div className="auth-form-heading">
+      <span className="auth-eyebrow">{signup ? 'BECOME A READER' : 'GOOD TO HAVE YOU BACK'}</span>
+      <h1>{signup ? 'Your next chapter\nstarts here.' : 'Welcome back.'}</h1>
+      <p>{signup ? 'Create your free DevTools Times account.' : 'Sign in to your DevTools Times account.'}</p>
+    </div>
+    {signup && <div className="auth-method-tabs" aria-label="Registration method">
+      <button type="button" className={method === 'passkey' ? 'selected' : ''} onClick={() => { setMethod('passkey'); setError(''); }} disabled={!!busy}><FingerPrintIcon /> With a passkey <span>Recommended</span></button>
+      <button type="button" className={method === 'password' ? 'selected' : ''} onClick={() => { setMethod('password'); setError(''); }} disabled={!!busy}><LockClosedIcon /> With a password</button>
+    </div>}
+    {error && <div className="auth-notice error" role="alert">{error}</div>}
+    {supported === false && <div className="auth-notice" role="status">Passkeys aren’t supported in this browser or connection. You can use a password, or try a supported browser over HTTPS.</div>}
+    {!signup && <>
+      <button className="auth-primary passkey-button" type="button" disabled={!!busy || supported !== true} onClick={() => submit(true)}><FingerPrintIcon />{busy === 'passkey' ? 'Waiting for your passkey…' : 'Sign in with a passkey'}{!busy && <ArrowRightIcon />}</button>
+      <p className="passkey-caption">Use your face, fingerprint, or screen lock.</p>
+      <div className="auth-divider"><span>or continue with a password</span></div>
+    </>}
+    <form onSubmit={e => { e.preventDefault(); submit(signup && method === 'passkey'); }} className="auth-form" aria-busy={!!busy}>
+      <div><label htmlFor="username">Username</label><input id="username" name="username" autoComplete={signup ? 'username' : 'username webauthn'} autoCapitalize="none" spellCheck={false} placeholder="Enter your username" required minLength={3} maxLength={80} pattern="[a-zA-Z0-9_.@+\-]+" title="Letters, numbers, and . _ @ + - only" value={username} onChange={e => setUsername(e.target.value)} disabled={!!busy} /></div>
+      {(!signup || method === 'password') && <div><label htmlFor="password">Password</label><div className="password-field"><input id="password" name="password" type={showPassword ? 'text' : 'password'} autoComplete={signup ? 'new-password' : 'current-password'} placeholder={signup ? 'Create a strong password' : 'Enter your password'} minLength={signup ? 8 : undefined} maxLength={128} pattern={signup ? '(?=.*[0-9]).{8,}' : undefined} required value={password} onChange={e => setPassword(e.target.value)} disabled={!!busy} /><button type="button" aria-label={showPassword ? 'Hide password' : 'Show password'} onClick={() => setShowPassword(!showPassword)}>{showPassword ? <EyeSlashIcon /> : <EyeIcon />}</button></div>{signup && <p className="field-help">At least 8 characters, including one number.</p>}</div>}
+      {signup && method === 'passkey' && <div className="auth-passkey-explainer"><span className="small-icon"><FingerPrintIcon /></span><div><strong>A little less friction. A lot more secure.</strong><p>Create a passkey with your device’s screen lock. No password to create, remember, or reset.</p></div></div>}
+      <button className={signup ? 'auth-primary' : 'auth-secondary'} type="submit" disabled={!!busy || (signup && method === 'passkey' && supported !== true)}>{busy ? (busy === 'passkey' ? 'Waiting for your device…' : signup ? 'Creating your account…' : 'Signing in…') : signup ? (method === 'passkey' ? <><FingerPrintIcon />Create account with a passkey</> : 'Create account') : 'Sign in with password'}{signup && !busy && <ArrowRightIcon />}</button>
+    </form>
+    {signup && <p className="auth-terms">By creating an account, you agree to our <a href={`${import.meta.env.BASE_URL}legal/terms`}>Terms of Service</a> and <a href={`${import.meta.env.BASE_URL}legal/privacy`}>Privacy Policy</a>.</p>}
+    <p className="auth-switch">{signup ? 'Already a reader?' : 'New to The DevTools Times?'} <a href={`${import.meta.env.BASE_URL}${signup ? 'signin' : 'signup'}`}>{signup ? 'Sign in' : 'Create an account'} <span aria-hidden="true">↗</span></a></p>
+    <div className="auth-trust"><ShieldCheckIcon /><span>Your privacy comes first. Always.</span></div>
+    <details className="passkey-faq"><summary>What is a passkey?</summary><p>A passkey is a secure alternative to a password, saved by your device or password manager. Use your fingerprint, face, or device PIN to sign in. Your biometric information stays on your device.</p><ul><li><CheckIcon />Resistant to phishing</li><li><CheckIcon />Works with supported password managers</li><li><CheckIcon />Use another device or security key when prompted</li></ul></details>
+  </div>;
+}
