diff --git a/src/lib/auth-client.ts b/src/lib/auth-client.ts
new file mode 100644
index 0000000..23ec1e4
--- /dev/null
+++ b/src/lib/auth-client.ts
@@ -0,0 +1,33 @@
+import { startRegistration, startAuthentication, browserSupportsWebAuthn } from '@simplewebauthn/browser';
+export class AuthRequestError extends Error {
+  constructor(message: string, public status: number) { super(message); }
+}
+export const accountUrl = `${import.meta.env.BASE_URL}account/settings`;
+export async function authRequest(action: string, data?: unknown) {
+  const response = await fetch(`${import.meta.env.BASE_URL}api/auth/${action}`, { method: data === undefined ? 'GET' : 'POST', headers: { 'Content-Type': 'application/json' }, credentials: 'same-origin', ...(data === undefined ? {} : { body: JSON.stringify(data) }) });
+  const result = await response.json();
+  if (!response.ok) throw new AuthRequestError(result.error || 'Something went wrong. Please try again.', response.status);
+  return result;
+}
+export function supportsPasskeys() { return window.isSecureContext && browserSupportsWebAuthn(); }
+export function authMessage(error: unknown) {
+  if (error instanceof Error) {
+    if (error.name === 'NotAllowedError' || error.message.includes('ceremony was sent an abort signal')) return 'The passkey request was canceled or timed out. You can try again or use your password.';
+    if (error.name === 'InvalidStateError') return 'This device already has a passkey for your account. Try signing in with it.';
+    if (error.name === 'SecurityError') return 'Passkeys require a secure connection. Please use HTTPS or localhost.';
+    if (error.name === 'NotSupportedError') return 'Passkeys aren’t available on this device. Try another device or use your password.';
+    if (error instanceof TypeError) return 'We couldn’t connect. Check your connection and try again.';
+    return error.message;
+  }
+  return 'Something went wrong. Please try again.';
+}
+export async function registerPasskey(username?: string, name?: string) {
+  const optionsJSON = await authRequest('passkeys/registration-options', { signup: !!username, username });
+  const response = await startRegistration({ optionsJSON });
+  await authRequest('passkeys/registration-verify', { response, name });
+}
+export async function authenticatePasskey(reauthenticate = false) {
+  const optionsJSON = await authRequest('passkeys/authentication-options', { reauthenticate });
+  const response = await startAuthentication({ optionsJSON });
+  await authRequest('passkeys/authentication-verify', { response });
+}
diff --git a/src/lib/auth-store.ts b/src/lib/auth-store.ts
new file mode 100644
index 0000000..e6ec4ba
--- /dev/null
+++ b/src/lib/auth-store.ts
@@ -0,0 +1,93 @@
+import { DatabaseSync } from 'node:sqlite';
+import { mkdirSync } from 'node:fs';
+import { dirname, resolve } from 'node:path';
+import { randomBytes, createHash, scrypt as scryptCallback, timingSafeEqual } from 'node:crypto';
+import { promisify } from 'node:util';
+import type { AstroCookies } from 'astro';
+import type { AuthenticatorTransport } from '@simplewebauthn/server';
+
+const path = resolve(process.env.AUTH_DATABASE_PATH || '.data/accounts.sqlite');
+mkdirSync(dirname(path), { recursive: true });
+const db = new DatabaseSync(path);
+db.exec(`PRAGMA journal_mode=WAL; PRAGMA foreign_keys=ON;
+  CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, username TEXT UNIQUE NOT NULL, password TEXT);
+  CREATE TABLE IF NOT EXISTS passkeys (id TEXT PRIMARY KEY, userId TEXT NOT NULL REFERENCES users(id), publicKey TEXT NOT NULL, counter INTEGER NOT NULL, transports TEXT NOT NULL, name TEXT NOT NULL, createdAt TEXT NOT NULL, lastUsedAt TEXT, backedUp INTEGER NOT NULL);
+  CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY, userId TEXT NOT NULL REFERENCES users(id), expires INTEGER NOT NULL, verifiedAt INTEGER NOT NULL);
+  CREATE TABLE IF NOT EXISTS challenges (id TEXT PRIMARY KEY, challenge TEXT NOT NULL, purpose TEXT NOT NULL, userId TEXT, username TEXT, expires INTEGER NOT NULL);
+  CREATE TABLE IF NOT EXISTS attempts (key TEXT PRIMARY KEY, count INTEGER NOT NULL, expires INTEGER NOT NULL);
+`);
+export type User = { id: string; username: string; password: string | null };
+export type Passkey = { id: string; userId: string; publicKey: string; counter: number; transports: string; name: string; createdAt: string; lastUsedAt: string | null; backedUp: number };
+export type Challenge = { challenge: string; purpose: string; userId: string | null; username: string | null };
+export const store = {
+  user: (id: string) => db.prepare('SELECT * FROM users WHERE id=?').get(id) as User | undefined,
+  username: (name: string) => db.prepare('SELECT * FROM users WHERE username=?').get(name) as User | undefined,
+  createUser: (username: string, password: string | null = null, id = randomBytes(24).toString('base64url')) => {
+    db.prepare('INSERT INTO users VALUES (?, ?, ?)').run(id, username, password);
+    return { id, username, password };
+  },
+  keys: (id: string) => db.prepare('SELECT * FROM passkeys WHERE userId=? ORDER BY createdAt DESC').all(id) as Passkey[],
+  key: (id: string) => db.prepare('SELECT * FROM passkeys WHERE id=?').get(id) as Passkey | undefined,
+  addKey: (key: Omit<Passkey, 'createdAt' | 'lastUsedAt'>) => db.prepare('INSERT INTO passkeys VALUES (?, ?, ?, ?, ?, ?, ?, NULL, ?)').run(key.id, key.userId, key.publicKey, key.counter, key.transports, key.name, new Date().toISOString(), key.backedUp),
+  useKey: (id: string, counter: number, backedUp: boolean) => db.prepare('UPDATE passkeys SET counter=?, lastUsedAt=?, backedUp=? WHERE id=?').run(counter, new Date().toISOString(), Number(backedUp), id),
+  renameKey: (id: string, name: string) => db.prepare('UPDATE passkeys SET name=? WHERE id=?').run(name, id),
+  removeKey: (id: string) => db.prepare('DELETE FROM passkeys WHERE id=?').run(id),
+};
+const cookieName = 'times-account';
+const challengeCookie = 'times-challenge';
+const hash = (value: string) => createHash('sha256').update(value).digest('hex');
+const options = (secure: boolean, maxAge: number) => ({ httpOnly: true, secure, sameSite: 'lax' as const, path: import.meta.env.BASE_URL, maxAge });
+export function currentSession(cookies: AstroCookies) {
+  const token = cookies.get(cookieName)?.value;
+  if (!token) return;
+  const row = db.prepare('SELECT * FROM sessions WHERE id=? AND expires>?').get(hash(token), Date.now()) as { id: string; userId: string; verifiedAt: number } | undefined;
+  if (!row) return;
+  const user = store.user(row.userId);
+  if (user) return { ...row, user };
+}
+export function signIn(cookies: AstroCookies, userId: string, secure: boolean) {
+  signOut(cookies);
+  db.prepare('DELETE FROM sessions WHERE expires<?').run(Date.now());
+  const token = randomBytes(32).toString('base64url');
+  db.prepare('INSERT INTO sessions VALUES (?, ?, ?, ?)').run(hash(token), userId, Date.now() + 604800000, Date.now());
+  cookies.set(cookieName, token, options(secure, 604800));
+}
+export function signOut(cookies: AstroCookies) {
+  const token = cookies.get(cookieName)?.value;
+  if (token) db.prepare('DELETE FROM sessions WHERE id=?').run(hash(token));
+  cookies.delete(cookieName, { path: import.meta.env.BASE_URL });
+}
+export function markVerified(id: string) { db.prepare('UPDATE sessions SET verifiedAt=? WHERE id=?').run(Date.now(), id); }
+export function saveChallenge(cookies: AstroCookies, data: Challenge, secure: boolean) {
+  const old = cookies.get(challengeCookie)?.value;
+  if (old) db.prepare('DELETE FROM challenges WHERE id=?').run(hash(old));
+  db.prepare('DELETE FROM challenges WHERE expires<?').run(Date.now());
+  const token = randomBytes(32).toString('base64url');
+  db.prepare('INSERT INTO challenges VALUES (?, ?, ?, ?, ?, ?)').run(hash(token), data.challenge, data.purpose, data.userId, data.username, Date.now() + 300000);
+  cookies.set(challengeCookie, token, options(secure, 300));
+}
+export function takeChallenge(cookies: AstroCookies) {
+  const token = cookies.get(challengeCookie)?.value;
+  cookies.delete(challengeCookie, { path: import.meta.env.BASE_URL });
+  if (!token) return;
+  const row = db.prepare('DELETE FROM challenges WHERE id=? AND expires>? RETURNING *').get(hash(token), Date.now()) as Challenge | undefined;
+  return row;
+}
+export function rateLimit(key: string) {
+  db.prepare('DELETE FROM attempts WHERE expires<?').run(Date.now());
+  const row = db.prepare('INSERT INTO attempts VALUES (?, 1, ?) ON CONFLICT(key) DO UPDATE SET count=count+1 RETURNING count').get(hash(key), Date.now() + 900000) as { count: number };
+  return row.count > 30;
+}
+const scrypt = promisify(scryptCallback);
+export async function passwordHash(password: string) {
+  const salt = randomBytes(16).toString('hex');
+  return `${salt}:${(await scrypt(password, salt, 64) as Buffer).toString('hex')}`;
+}
+export async function checkPassword(password: string, saved: string) {
+  const [salt, digest] = saved.split(':');
+  const actual = await scrypt(password, salt, 64) as Buffer;
+  return timingSafeEqual(actual, Buffer.from(digest, 'hex'));
+}
+export function credential(key: Passkey) {
+  return { id: key.id, publicKey: new Uint8Array(Buffer.from(key.publicKey, 'base64url')), counter: key.counter, transports: JSON.parse(key.transports) as AuthenticatorTransport[] };
+}
