diff --git a/src/pages/api/auth/[...action].ts b/src/pages/api/auth/[...action].ts
new file mode 100644
index 0000000..2e8179b
--- /dev/null
+++ b/src/pages/api/auth/[...action].ts
@@ -0,0 +1,124 @@
+import type { APIRoute } from 'astro';
+import { randomBytes } from 'node:crypto';
+import { generateRegistrationOptions, verifyRegistrationResponse, generateAuthenticationOptions, verifyAuthenticationResponse } from '@simplewebauthn/server';
+import { store, currentSession, signIn, signOut, saveChallenge, takeChallenge, credential, passwordHash, checkPassword, markVerified, rateLimit } from '../../../lib/auth-store';
+
+const json = (data: unknown, status = 200) => new Response(JSON.stringify(data), { status, headers: { 'Content-Type': 'application/json', 'Cache-Control': 'no-store' } });
+class AuthError extends Error { constructor(message: string, public status = 400) { super(message); } }
+const assert: (condition: unknown, message: string, status?: number) => asserts condition = (condition, message, status) => { if (!condition) throw new AuthError(message, status); };
+const validName = (value: unknown) => {
+  assert(typeof value === 'string' && /^[a-zA-Z0-9_.@+-]{3,80}$/.test(value.trim()), 'Use 3–80 letters, numbers, or . _ @ + - for your username.');
+  return value.trim().toLowerCase();
+};
+const validPassword = (value: unknown): value is string => typeof value === 'string' && value.length >= 8 && value.length <= 128 && /\d/.test(value);
+
+export const ALL: APIRoute = async ({ request, cookies, params, url }) => {
+  try {
+    const action = params.action;
+    const session = currentSession(cookies);
+    if (request.method === 'GET' && action === 'account') {
+      if (!session) return json({ signedIn: false });
+      return json({ signedIn: true, username: session.user.username, hasPassword: !!session.user.password, passkeys: store.keys(session.user.id).map(({ id, name, createdAt, lastUsedAt, backedUp }) => ({ id, name, createdAt, lastUsedAt, backedUp: !!backedUp })) });
+    }
+    assert(request.method === 'POST', 'Method not allowed.', 405);
+    const origin = process.env.AUTH_ORIGIN || url.origin;
+    assert(request.headers.get('origin') === origin, 'This request could not be verified. Refresh the page and try again.', 403);
+    assert(request.headers.get('content-type')?.startsWith('application/json'), 'Expected a JSON request.', 415);
+    assert(!rateLimit(`${cookies.get('times-account')?.value || request.headers.get('x-forwarded-for') || 'anonymous'}:${action}`), 'Too many attempts. Please try again in 15 minutes.', 429);
+    const body = await request.json();
+    const secure = new URL(origin).protocol === 'https:';
+    const rpID = new URL(origin).hostname;
+    const requireSession = () => { assert(session, 'Please sign in to continue.', 401); return session; };
+    const requireRecent = () => { const s = requireSession(); assert(Date.now() - s.verifiedAt < 300000, 'Please verify your identity to continue.', 403); return s; };
+    if (action === 'logout') { signOut(cookies); return json({ ok: true }); }
+    if (action === 'register') {
+      const username = validName(body.username);
+      assert(validPassword(body.password), 'Use 8–128 characters, including at least one number.');
+      assert(!store.username(username), 'That username is already taken. Try another or sign in.', 409);
+      const digest = await passwordHash(body.password);
+      assert(!store.username(username), 'That username is already taken.', 409);
+      const user = store.createUser(username, digest);
+      signIn(cookies, user.id, secure);
+      return json({ ok: true });
+    }
+    if (action === 'login' || action === 'reauthenticate/password') {
+      const user = action === 'login' ? store.username(validName(body.username)) : requireSession().user;
+      assert(typeof body.password === 'string' && body.password.length <= 128, 'Enter your password.');
+      // Perform the same expensive hash for unknown accounts to avoid a timing oracle.
+      const digest = user?.password || `${'0'.repeat(32)}:${'0'.repeat(128)}`;
+      const valid = await checkPassword(body.password, digest);
+      assert(user?.password && valid, 'Your username or password is incorrect.', 401);
+      if (action === 'login') signIn(cookies, user.id, secure);
+      else markVerified(requireSession().id);
+      return json({ ok: true });
+    }
+    if (action === 'passkeys/registration-options') {
+      const signup = body.signup === true;
+      const userId = signup ? randomBytes(24).toString('base64url') : requireRecent().user.id;
+      const username = signup ? validName(body.username) : requireSession().user.username;
+      assert(!signup || !store.username(username), 'That username is already taken. Try another or sign in.', 409);
+      const options = await generateRegistrationOptions({ rpName: 'The DevTools Times', rpID, userID: new TextEncoder().encode(userId), userName: username, attestationType: 'none', excludeCredentials: signup ? [] : store.keys(userId).map(key => ({ id: key.id, transports: credential(key).transports })), authenticatorSelection: { residentKey: 'required', userVerification: 'required' } });
+      saveChallenge(cookies, { challenge: options.challenge, purpose: signup ? 'signup' : 'register', userId, username }, secure);
+      return json(options);
+    }
+    if (action === 'passkeys/registration-verify') {
+      const pending = takeChallenge(cookies);
+      assert(pending && ['signup', 'register'].includes(pending.purpose), 'Your request expired. Please try again.');
+      if (pending.purpose === 'register') assert(requireRecent().user.id === pending.userId, 'Please sign in again.', 401);
+      const result = await verifyRegistrationResponse({ response: body.response, expectedChallenge: pending.challenge, expectedOrigin: origin, expectedRPID: rpID, requireUserVerification: true });
+      assert(result.verified && result.registrationInfo, 'Your passkey could not be verified. Please try again.');
+      const { credential: key, credentialBackedUp } = result.registrationInfo;
+      assert(!store.key(key.id), 'This passkey is already registered.');
+      let user = pending.purpose === 'signup' ? undefined : requireSession().user;
+      if (!user) {
+        assert(pending.username && pending.userId && !store.username(pending.username), 'That username is already taken.', 409);
+        user = store.createUser(pending.username, null, pending.userId);
+      }
+      store.addKey({ id: key.id, userId: user.id, publicKey: Buffer.from(key.publicKey).toString('base64url'), counter: key.counter, transports: JSON.stringify(key.transports || []), name: typeof body.name === 'string' && body.name.trim() ? body.name.trim().slice(0, 60) : 'My passkey', backedUp: Number(credentialBackedUp) });
+      if (pending.purpose === 'signup') signIn(cookies, user.id, secure);
+      return json({ ok: true });
+    }
+    if (action === 'passkeys/authentication-options') {
+      const reauth = body.reauthenticate === true;
+      const user = reauth ? requireSession().user : body.username ? store.username(validName(body.username)) : undefined;
+      const keys = user ? store.keys(user.id) : [];
+      const options = await generateAuthenticationOptions({ rpID, userVerification: 'required', ...(reauth ? { allowCredentials: keys.map(key => ({ id: key.id, transports: credential(key).transports })) } : {}) });
+      if (reauth) assert(keys.length, 'There are no passkeys on your account. Verify with your password.');
+      saveChallenge(cookies, { challenge: options.challenge, purpose: reauth ? 'reauthenticate' : 'authenticate', userId: user?.id || null, username: null }, secure);
+      return json(options);
+    }
+    if (action === 'passkeys/authentication-verify') {
+      const pending = takeChallenge(cookies);
+      assert(pending && ['authenticate', 'reauthenticate'].includes(pending.purpose), 'Your request expired. Please try again.');
+      const key = typeof body.response?.id === 'string' ? store.key(body.response.id) : undefined;
+      assert(key && (!pending.userId || pending.userId === key.userId), 'No matching passkey was found. Try another passkey or use your password.', 401);
+      if (pending.purpose === 'reauthenticate') assert(requireSession().user.id === key.userId, 'This passkey belongs to a different account.', 401);
+      const userHandle = body.response?.response?.userHandle;
+      assert(!userHandle || userHandle === Buffer.from(key.userId).toString('base64url'), 'This passkey belongs to a different account.', 401);
+      const result = await verifyAuthenticationResponse({ response: body.response, expectedChallenge: pending.challenge, expectedOrigin: origin, expectedRPID: rpID, credential: credential(key), requireUserVerification: true });
+      assert(result.verified, 'Your identity could not be verified.', 401);
+      store.useKey(key.id, result.authenticationInfo.newCounter, result.authenticationInfo.credentialBackedUp);
+      if (pending.purpose === 'reauthenticate') markVerified(requireSession().id);
+      else signIn(cookies, key.userId, secure);
+      return json({ ok: true });
+    }
+    if (action === 'passkeys/rename' || action === 'passkeys/remove') {
+      const s = requireRecent();
+      const key = typeof body.id === 'string' ? store.key(body.id) : undefined;
+      assert(key && key.userId === s.user.id, 'Passkey not found.', 404);
+      if (action.endsWith('rename')) {
+        assert(typeof body.name === 'string' && body.name.trim().length > 0 && body.name.trim().length <= 60, 'Enter a name between 1 and 60 characters.');
+        store.renameKey(key.id, body.name.trim());
+      } else {
+        assert(s.user.password || store.keys(s.user.id).length > 1, 'Add another passkey before removing your only way to sign in.');
+        store.removeKey(key.id);
+      }
+      return json({ ok: true });
+    }
+    return json({ error: 'Not found.' }, 404);
+  } catch (error) {
+    if (error instanceof AuthError) return json({ error: error.message }, error.status);
+    console.error('Authentication request failed:', error instanceof Error ? error.message : 'Unknown error');
+    return json({ error: 'We couldn’t complete that request. Please try again.' }, 400);
+  }
+};
