+// All content and styles arrive in the HTML response. Upgrade only adds behavior;
+// it never creates a shadow root or replaces the server-rendered children.
+class DrinkCard extends HTMLElement {
+  connectedCallback() {
+    const button = this.querySelector('.favorite-toggle');
+    const label = button?.querySelector('[data-favorite-label]');
+    if (!button || !label || this.favoriteButton) return;
+
+    this.favoriteButton = button;
+    this.toggleFavorite = () => {
+      const favorite = button.getAttribute('aria-pressed') !== 'true';
+      button.setAttribute('aria-pressed', String(favorite));
+      label.textContent = favorite ? 'Added to favorites' : 'Add to favorites';
+    };
+    button.addEventListener('click', this.toggleFavorite);
+    button.disabled = false;
+  }
+
+  disconnectedCallback() {
+    if (!this.favoriteButton) return;
+    this.favoriteButton.removeEventListener('click', this.toggleFavorite);
+    this.favoriteButton.disabled = true;
+    this.favoriteButton = null;
+    this.toggleFavorite = null;
+  }
+}
+
+if (!customElements.get('drink-card')) {
+  customElements.define('drink-card', DrinkCard);
+}
