+const assert = require('node:assert/strict');
+const { readFileSync } = require('node:fs');
+const { test } = require('node:test');
+const vm = require('node:vm');
+
+const source = readFileSync(require.resolve('../drink-card.js'), 'utf8');
+
+function fixture() {
+  const registry = new Map();
+  class ServerCard {
+    constructor() {
+      this.label = { textContent: 'Add to favorites' };
+      this.button = new EventTarget();
+      this.button.disabled = true;
+      const attributes = new Map([['aria-pressed', 'false']]);
+      this.button.getAttribute = (name) => attributes.get(name);
+      this.button.setAttribute = (name, value) => attributes.set(name, value);
+      this.button.querySelector = () => this.label;
+      this.children = [this.button];
+    }
+    querySelector() { return this.button; }
+    set innerHTML(_) { assert.fail('Hydration must not replace server HTML'); }
+    replaceChildren() { assert.fail('Hydration must preserve server children'); }
+    attachShadow() { assert.fail('Content must remain in the styled light DOM'); }
+  }
+  const context = vm.createContext({
+    HTMLElement: ServerCard,
+    customElements: {
+      get: (name) => registry.get(name),
+      define: (name, element) => {
+        assert.equal(registry.has(name), false);
+        registry.set(name, element);
+      },
+    },
+  });
+  vm.runInContext(source, context);
+  return new (registry.get('drink-card'))();
+}
+
+test('upgrade preserves server nodes and toggles only the clicked card', () => {
+  const card = fixture();
+  const other = fixture();
+  const button = card.button;
+  const label = card.label;
+  card.connectedCallback();
+  other.connectedCallback();
+  assert.equal(card.button, button);
+  assert.equal(card.label, label);
+  assert.equal(label.textContent, 'Add to favorites');
+  assert.equal(button.disabled, false);
+  button.dispatchEvent(new Event('click'));
+  assert.equal(button.getAttribute('aria-pressed'), 'true');
+  assert.equal(label.textContent, 'Added to favorites');
+  assert.equal(other.button.getAttribute('aria-pressed'), 'false');
+  button.dispatchEvent(new Event('click'));
+  assert.equal(button.getAttribute('aria-pressed'), 'false');
+  assert.equal(label.textContent, 'Add to favorites');
+});
+
+test('reconnection preserves state and does not duplicate event handlers', () => {
+  const card = fixture();
+  card.connectedCallback();
+  card.connectedCallback();
+  card.button.dispatchEvent(new Event('click'));
+  assert.equal(card.button.getAttribute('aria-pressed'), 'true');
+  card.disconnectedCallback();
+  assert.equal(card.button.disabled, true);
+  card.button.dispatchEvent(new Event('click'));
+  assert.equal(card.button.getAttribute('aria-pressed'), 'true');
+  card.connectedCallback();
+  assert.equal(card.button.disabled, false);
+  assert.equal(card.label.textContent, 'Added to favorites');
+  card.button.dispatchEvent(new Event('click'));
+  assert.equal(card.button.getAttribute('aria-pressed'), 'false');
+});
+
+test('HTML response includes complete styled cards before module execution', () => {
+  const html = readFileSync(require.resolve('../index.html'), 'utf8');
+  const cards = [...html.matchAll(/<drink-card class="card">([\s\S]*?)<\/drink-card>/g)];
+  assert.equal(cards.length, 3);
+  for (const [, content] of cards) {
+    assert.match(content, /<h3>[^<]+<\/h3>/);
+    assert.match(content, /<p>[^<]+<\/p>/);
+    assert.match(content, /<a href="\/menu\/[^" ]+" class="btn">View Details<\/a>/);
+    assert.match(content, /<button type="button"[^>]+aria-pressed="false" disabled>/);
+    assert.match(content, /<span data-favorite-label>Add to favorites<\/span>/);
+  }
+  assert.match(html, /\.card\s*\{\s*display: block;/);
+  assert.match(html, /<script type="module" src="\/drink-card.js"><\/script>/);
+  assert.ok(html.indexOf('<style>') < html.indexOf('<drink-card'));
+});

