+import assert from 'node:assert/strict';
+import { readFile, readdir, stat } from 'node:fs/promises';
+import { fileURLToPath } from 'node:url';
+import { resolve, sep } from 'node:path';
+
+const root = fileURLToPath(new URL('../', import.meta.url));
+const headers = await readFile(new URL('../_headers', import.meta.url), 'utf8');
+assert.match(headers, /^\/\*\n/, 'Headers must cover all routes.');
+const csp = headers.match(/^  Content-Security-Policy: (.+)$/m)?.[1];
+assert.ok(csp, 'An enforced CSP is required.');
+for (const directive of [
+  "default-src 'none'", "script-src 'none'", "script-src-attr 'none'",
+  "style-src 'self'", "style-src-attr 'none'", "img-src 'self'", "font-src 'none'",
+  "connect-src 'none'", "frame-src 'none'", "worker-src 'none'", "object-src 'none'",
+  "base-uri 'none'", "form-action 'none'", "frame-ancestors 'none'",
+  "require-trusted-types-for 'script'", "trusted-types 'none'",
+]) {
+  assert.ok(csp.split('; ').includes(directive), `Missing CSP directive: ${directive}`);
+}
+for (const header of [
+  'Referrer-Policy: no-referrer', 'X-Content-Type-Options: nosniff',
+  'X-Frame-Options: DENY', 'Cross-Origin-Resource-Policy: same-origin',
+  'Cross-Origin-Opener-Policy: same-origin-allow-popups',
+  'Strict-Transport-Security: max-age=300',
+]) assert.ok(headers.includes(`  ${header}\n`), `Missing header: ${header}`);
+for (const feature of ['camera', 'microphone', 'geolocation', 'payment', 'browsing-topics']) {
+  assert.ok(headers.includes(`${feature}=()`), `Disable unused feature: ${feature}`);
+}
+
+async function checkAsset(url) {
+  assert.match(url, /^\/(?!\/)[a-zA-Z0-9/_.-]+$/, `Resource must be local: ${url}`);
+  const path = resolve(root, `.${url}`);
+  assert.ok(path.startsWith(root.endsWith(sep) ? root : `${root}${sep}`));
+  assert.ok((await stat(path)).isFile(), `Missing resource: ${url}`);
+}
+
+async function checkPage(file) {
+  const html = await readFile(new URL(`../${file}`, import.meta.url), 'utf8');
+  assert.doesNotMatch(html, /<(?:script|iframe|object|embed|form|input|style|base)\b/i,
+    `${file}: new active content or collection requires a privacy review.`);
+  assert.doesNotMatch(html, /\s(?:on[\w-]+|style|ping|srcdoc)\s*=|javascript:|data:/i);
+  assert.match(html, /<meta name="referrer" content="no-referrer">/);
+  const meta = html.match(/<meta http-equiv="Content-Security-Policy" content="([^"]+)">/)?.[1];
+  assert.equal(meta, csp.replace("; frame-ancestors 'none'", ''), 'Meta fallback must match HTTP policy.');
+  assert.ok(html.indexOf('http-equiv="Content-Security-Policy"') < html.indexOf('<link'),
+    'Fallback policy must precede resource loading.');
+  for (const match of html.matchAll(/\b(?:src|href)="([^"]+)"/g)) {
+    assert.ok(match[1].startsWith('/') && !match[1].startsWith('//'), `Unexpected external URL: ${match[1]}`);
+    if (match[1].startsWith('/assets/')) await checkAsset(match[1]);
+  }
+}
+
+await checkPage('index.html');
+await checkPage('privacy-policy/index.html');
+for (const name of await readdir(new URL('../assets/', import.meta.url))) {
+  assert.ok(['styles.css', 'coffee.jpg'].includes(name), `Unaudited asset: ${name}`);
+}
+const css = await readFile(new URL('../assets/styles.css', import.meta.url), 'utf8');
+assert.doesNotMatch(css, /@import\b|https?:|\/\/|data:|expression\s*\(/i);
+for (const match of css.matchAll(/url\(['"]?([^)'"\s]+)['"]?\)/g)) await checkAsset(match[1]);
+const photo = await readFile(new URL('../assets/coffee.jpg', import.meta.url));
+assert.equal(photo.subarray(0, 3).toString('hex'), 'ffd8ff', 'Hero must be a local JPEG.');
+assert.match(await readFile(new URL('../index.html', import.meta.url), 'utf8'), /href="\/privacy-policy\/"/);
+console.log('Privacy checks passed: local resources, no client collection or scripts, matching policies and headers.');

