--- /dev/null
+++ b/scripts/privacy.test.mjs
@@ -0,0 +1,57 @@
+import { test } from 'node:test';
+import assert from 'node:assert/strict';
+import { readFile, readdir } from 'node:fs/promises';
+
+const headers = await readFile('_headers', 'utf8');
+const csp = headers.match(/^  Content-Security-Policy: (.+)$/m)?.[1];
+
+test('deployment headers restrict data sharing and browser capabilities', () => {
+  assert.ok(csp);
+  for (const directive of ["default-src 'none'", "script-src 'none'", "connect-src 'none'", "form-action 'none'", "base-uri 'none'", "object-src 'none'", "frame-ancestors 'none'", "style-src 'self'", "img-src 'self'", 'upgrade-insecure-requests']) {
+    assert.ok(csp.split('; ').includes(directive), `Missing CSP directive: ${directive}`);
+  }
+  for (const header of ['Referrer-Policy: no-referrer', 'X-Content-Type-Options: nosniff', 'X-Frame-Options: DENY', 'Strict-Transport-Security: max-age=31536000', 'Cache-Control: no-store', 'Cross-Origin-Resource-Policy: same-origin', 'Cross-Origin-Opener-Policy: same-origin']) {
+    assert.ok(headers.includes(header), `Missing header: ${header}`);
+  }
+  for (const feature of ['camera', 'microphone', 'geolocation', 'payment', 'browsing-topics']) {
+    assert.ok(headers.includes(`${feature}=()`));
+  }
+});
+
+async function filesIn(directory) {
+  const files = [];
+  for (const entry of await readdir(directory, { withFileTypes: true })) {
+    if (['.git', 'node_modules', 'dist'].includes(entry.name)) continue;
+    const path = `${directory}/${entry.name}`;
+    if (entry.isDirectory()) files.push(...await filesIn(path));
+    else files.push(path);
+  }
+  return files;
+}
+
+test('all public markup and styles keep the zero-collection baseline', async () => {
+  const files = await filesIn('.');
+  const publicFiles = files.filter(path => /\.(html|css)$/.test(path));
+  assert.ok(publicFiles.length >= 3);
+  // Any future browser script needs an explicit privacy review and policy change.
+  assert.deepEqual(files.filter(path => !path.startsWith('./scripts/') && /\.(?:[cm]?js|ts|tsx|jsx)$/.test(path)), []);
+  for (const path of publicFiles) {
+    const source = await readFile(path, 'utf8');
+    assert.doesNotMatch(source, /https?:|\/\/|@import/i, `${path}: third-party resource or import requires review`);
+    if (!path.endsWith('.html')) continue;
+    assert.doesNotMatch(source, /<(?:script|iframe|object|embed|form|input|textarea|select)\b/i, `${path}: active content or collection requires review`);
+    assert.doesNotMatch(source, /\s(?:on[\w]+|style|ping|srcdoc)\s*=|(?:javascript|data|blob):/i, `${path}: unsafe inline content`);
+    assert.match(source, /<meta name="referrer" content="no-referrer">/);
+    assert.ok(source.includes(`content="${csp.replace("; frame-ancestors 'none'", '')}"`), `${path}: meta CSP must match header CSP`);
+    for (const [, target] of source.matchAll(/(?:src|href)="([^"]+)"/g)) {
+      assert.match(target, /^\/(?!\/)|^#/, `${path}: only local links and resources allowed`);
+    }
+  }
+  const css = await readFile('assets/styles.css', 'utf8');
+  assert.match(css, /url\('\/assets\/coffee\.jpg'\)/);
+  const image = await readFile('assets/coffee.jpg');
+  assert.equal(image.subarray(0, 3).toString('hex'), 'ffd8ff');
+  const home = await readFile('index.html', 'utf8');
+  assert.match(home, /href="\/privacy-policy"/);
+  assert.doesNotMatch(home, /href="\/logout"/);
+});

