@@ -0,0 +1,39 @@
+const form = document.querySelector('#newsletter-form');
+const status = document.querySelector('#newsletter-status');
+const button = form.querySelector('button');
+
+form.addEventListener('submit', async (event) => {
+  event.preventDefault();
+  if (button.disabled || !form.reportValidity()) return;
+
+  const body = new URLSearchParams(new FormData(form));
+  const controller = new AbortController();
+  const timeout = setTimeout(() => controller.abort(), 12000);
+  button.disabled = true;
+  form.setAttribute('aria-busy', 'true');
+  status.textContent = 'Submitting your signup…';
+
+  try {
+    const response = await fetch(form.action, {
+      method: 'POST',
+      body,
+      headers: { Accept: 'application/json' },
+      credentials: 'same-origin',
+      mode: 'same-origin',
+      redirect: 'error',
+      signal: controller.signal,
+    });
+    if (!response.ok) throw new Error('Signup request failed');
+    const result = await response.json();
+    if (result.ok !== true) throw new Error('Signup was not accepted');
+    status.textContent = 'Thanks! You’re signed up for The Daily Grind newsletter.';
+    form.reset();
+  } catch {
+    // Network failures, policy blocks, timeouts and server errors share a retryable state.
+    status.textContent = 'We couldn’t send your signup. Check your connection and try again. Your email is still here.';
+  } finally {
+    clearTimeout(timeout);
+    button.disabled = false;
+    form.removeAttribute('aria-busy');
+  }
+});
