--- /dev/null
+++ b/server/handler.mjs
@@ -0,0 +1,132 @@
+import { randomBytes } from 'node:crypto';
+import { appendFile, mkdir, readFile } from 'node:fs/promises';
+import { dirname, resolve } from 'node:path';
+import { fileURLToPath } from 'node:url';
+
+const root = new URL('../', import.meta.url);
+const connectionAllowlist = '(response-origin "https://images.unsplash.com"); report-to=security';
+
+async function readBody(req, limit) {
+  let size = 0;
+  const chunks = [];
+  for await (const chunk of req) {
+    size += chunk.length;
+    if (size > limit) throw Object.assign(new Error('Request too large'), { status: 413 });
+    chunks.push(chunk);
+  }
+  return Buffer.concat(chunks).toString('utf8');
+}
+
+export async function createHandler({
+  dataFile = process.env.NEWSLETTER_FILE || new URL('../data/newsletter.jsonl', import.meta.url),
+  publicOrigin = process.env.PUBLIC_ORIGIN,
+  saveEmail,
+  onSecurityReport = (counts) => console.warn('Security policy violations:', counts),
+} = {}) {
+  const [html, css, js] = await Promise.all([
+    readFile(new URL('index.html', root), 'utf8'),
+    readFile(new URL('styles.css', root)),
+    readFile(new URL('newsletter.js', root)),
+  ]);
+  const configuredOrigin = publicOrigin ? new URL(publicOrigin).origin : null;
+  const persist = saveEmail || (async (email) => {
+    const path = dataFile instanceof URL ? fileURLToPath(dataFile) : resolve(dataFile);
+    await mkdir(dirname(path), { recursive: true, mode: 0o700 });
+    await appendFile(path, JSON.stringify({ email, subscribedAt: new Date().toISOString() }) + '\n', { mode: 0o600 });
+  });
+
+  return async (req, res) => {
+    const nonce = randomBytes(18).toString('base64');
+    // Apply to every response, including any response requested as a worker script.
+    res.setHeader('Connection-Allowlist', connectionAllowlist);
+    res.setHeader('Reporting-Endpoints', 'security="/api/security-reports"');
+    res.setHeader('Content-Security-Policy', [
+      "default-src 'none'",
+      `script-src 'nonce-${nonce}' 'report-sample'`,
+      "script-src-attr 'none'",
+      "style-src 'self'",
+      "connect-src 'self'",
+      "img-src 'self' https://images.unsplash.com",
+      "form-action 'self'",
+      "worker-src 'none'",
+      "object-src 'none'",
+      "base-uri 'none'",
+      "frame-ancestors 'none'",
+      "require-trusted-types-for 'script'",
+      "trusted-types 'none'",
+      'report-to security',
+    ].join('; '));
+    res.setHeader('X-Content-Type-Options', 'nosniff');
+    res.setHeader('Referrer-Policy', 'no-referrer');
+    res.setHeader('X-DNS-Prefetch-Control', 'off');
+    res.setHeader('X-Frame-Options', 'DENY');
+    res.setHeader('Cache-Control', 'no-store');
+    res.setHeader('Vary', 'Sec-Fetch-Site');
+
+    const send = (code, body, type = 'text/plain; charset=utf-8') => {
+      res.statusCode = code;
+      res.setHeader('Content-Type', type);
+      res.end(req.method === 'HEAD' ? undefined : body);
+    };
+    const reply = (code, message) => {
+      if (req.headers.accept?.includes('application/json')) {
+        send(code, JSON.stringify({ ok: code < 400, message }), 'application/json; charset=utf-8');
+      } else {
+        // Fixed messages only; never reflect customer input into HTML.
+        send(code, `<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Newsletter | The Daily Grind</title><link rel="stylesheet" href="/styles.css"><main class="container"><h1>Daily Grind newsletter</h1><p>${message}</p><a href="/">Return to the homepage</a></main></html>`, 'text/html; charset=utf-8');
+      }
+    };
+
+    try {
+      const origin = configuredOrigin || `${req.socket.encrypted ? 'https' : 'http'}://${req.headers.host}`;
+      const { pathname } = new URL(req.url, origin);
+      if (req.method === 'POST' && pathname === '/api/newsletter') {
+        // Browser POSTs must be same-origin, including native no-JavaScript submissions.
+        if (req.headers.origin !== origin || (req.headers['sec-fetch-site'] && req.headers['sec-fetch-site'] !== 'same-origin')) {
+          return reply(403, 'We couldn’t accept this signup. Please return to the homepage and try again.');
+        }
+        if (req.headers['content-type']?.split(';')[0].trim() !== 'application/x-www-form-urlencoded') {
+          return reply(415, 'Please submit your email using the newsletter form.');
+        }
+        const fields = new URLSearchParams(await readBody(req, 4096));
+        const email = fields.get('email')?.trim();
+        if (fields.getAll('email').length !== 1 || !email || email.length > 254 || !/^[a-zA-Z0-9.!#$%&'*+/=?^_`{|}~-]+@[a-zA-Z0-9](?:[a-zA-Z0-9-]*[a-zA-Z0-9])?(?:\.[a-zA-Z0-9](?:[a-zA-Z0-9-]*[a-zA-Z0-9])?)*$/.test(email)) {
+          return reply(422, 'Please enter a valid email address and try again.');
+        }
+        await persist(email);
+        return reply(201, 'Thanks! You’re signed up for The Daily Grind newsletter.');
+      }
+      if (req.method === 'POST' && pathname === '/api/security-reports') {
+        if (req.headers['sec-fetch-site'] === 'cross-site') return send(403, 'Forbidden');
+        const reports = JSON.parse(await readBody(req, 65536));
+        if (!Array.isArray(reports)) return send(400, 'Invalid reports');
+        // Retain only aggregate counts: report URLs and samples may contain customer data.
+        const counts = { connectionAllowlist: 0, csp: 0 };
+        for (const report of reports) {
+          if (report?.type === 'connection-allowlist') counts.connectionAllowlist++;
+          if (report?.type === 'csp-violation') counts.csp++;
+        }
+        onSecurityReport(counts);
+        return send(204, '');
+      }
+      const assets = {
+        '/': [html.replace('{{SCRIPT_NONCE}}', nonce), 'text/html; charset=utf-8'],
+        '/index.html': [html.replace('{{SCRIPT_NONCE}}', nonce), 'text/html; charset=utf-8'],
+        '/styles.css': [css, 'text/css; charset=utf-8'],
+        '/newsletter.js': [js, 'text/javascript; charset=utf-8'],
+      };
+      if (req.method !== 'GET' && req.method !== 'HEAD') {
+        res.setHeader('Allow', pathname.startsWith('/api/') ? 'POST' : 'GET, HEAD');
+        return send(405, 'Method not allowed');
+      }
+      // Explicit routes prevent accidental exposure of emails, source code or dotfiles.
+      if (!Object.hasOwn(assets, pathname)) return send(404, 'Page not found');
+      return send(200, ...assets[pathname]);
+    } catch (error) {
+      const code = error.status || (error instanceof SyntaxError ? 400 : 503);
+      return reply(code, code === 413
+        ? 'This request is too large. Please return to the form and try again.'
+        : 'We couldn’t complete your request. Please try again in a moment.');
+    }
+  };
+}
