+import test from 'node:test';
+import assert from 'node:assert/strict';
+import { Readable } from 'node:stream';
+import { mkdtemp, readFile, rm } from 'node:fs/promises';
+import { tmpdir } from 'node:os';
+import { join } from 'node:path';
+import vm from 'node:vm';
+import { createHandler } from '../server/handler.mjs';
+
+async function request(handler, { url = '/', method = 'GET', body = '', headers = {} } = {}) {
+  const req = Readable.from([Buffer.from(body)]);
+  Object.assign(req, { url, method, headers: { host: 'daily.test', ...headers }, socket: {} });
+  const res = {
+    headers: {}, statusCode: 200,
+    setHeader(name, value) { this.headers[name.toLowerCase()] = value; },
+    end(value) { this.body = value?.toString() || ''; },
+  };
+  await handler(req, res);
+  return res;
+}
+const signup = (body = 'email=coffee%40example.com', headers = {}) => ({
+  url: '/api/newsletter', method: 'POST', body,
+  headers: { origin: 'http://daily.test', 'content-type': 'application/x-www-form-urlencoded', accept: 'application/json', ...headers },
+});
+
+test('policies enforce the two allowed origins and authorize only the form script', async () => {
+  const handler = await createHandler();
+  const first = await request(handler);
+  const second = await request(handler);
+  assert.equal(first.headers['connection-allowlist'], '(response-origin "https://images.unsplash.com"); report-to=security');
+  assert.equal(first.headers['reporting-endpoints'], 'security="/api/security-reports"');
+  const nonce = first.body.match(/nonce="([^"]+)"/)[1];
+  assert.ok(first.headers['content-security-policy'].includes(`script-src 'nonce-${nonce}'`));
+  assert.notEqual(nonce, second.body.match(/nonce="([^"]+)"/)[1]);
+  for (const directive of ["connect-src 'self'", "form-action 'self'", "worker-src 'none'", "img-src 'self' https://images.unsplash.com", "base-uri 'none'"]) {
+    assert.ok(first.headers['content-security-policy'].includes(directive));
+  }
+  assert.ok(!first.body.includes('<style>'));
+  assert.ok(!first.headers['content-security-policy'].includes('unsafe-inline'));
+  for (const url of ['/newsletter.js', '/styles.css', '/data/newsletter.jsonl', '/server.mjs', '/.git/config', '/missing']) {
+    const res = await request(handler, { url });
+    assert.equal(res.headers['connection-allowlist'], first.headers['connection-allowlist']);
+    assert.equal(res.statusCode, ['/newsletter.js', '/styles.css'].includes(url) ? 200 : 404);
+  }
+});
+
+test('signup persists email, validates inputs, and handles storage failure', async () => {
+  const directory = await mkdtemp(join(tmpdir(), 'daily-grind-test-'));
+  try {
+    const dataFile = join(directory, 'private', 'emails.jsonl');
+    const handler = await createHandler({ dataFile });
+    assert.equal((await request(handler, signup())).statusCode, 201);
+    assert.equal(JSON.parse(await readFile(dataFile, 'utf8')).email, 'coffee@example.com');
+    for (const body of ['', 'email=invalid', 'email=a%40b.com&email=c%40d.com', 'email=a%0Ab%40example.com']) {
+      assert.equal((await request(handler, signup(body))).statusCode, 422);
+    }
+    assert.equal((await request(handler, signup('email=' + 'a'.repeat(5000)))).statusCode, 413);
+    assert.equal((await request(handler, signup(undefined, { origin: 'https://evil.test' }))).statusCode, 403);
+    assert.equal((await request(handler, signup(undefined, { 'sec-fetch-site': 'cross-site' }))).statusCode, 403);
+    assert.equal((await request(handler, signup(undefined, { 'content-type': 'application/json' }))).statusCode, 415);
+    const broken = await createHandler({ saveEmail: async () => { throw new Error('Disk full'); } });
+    const failed = await request(broken, signup());
+    assert.equal(failed.statusCode, 503);
+    assert.equal(JSON.parse(failed.body).ok, false);
+    const native = await request(handler, signup(undefined, { accept: 'text/html' }));
+    assert.equal(native.statusCode, 201);
+    assert.match(native.body, /You’re signed up/);
