+    await rm(directory, { recursive: true, force: true });
+  }
+});
+
+test('reverse-proxy origin is explicit and reports discard sensitive fields', async () => {
+  let summary;
+  const handler = await createHandler({ publicOrigin: 'https://daily.example', saveEmail: async () => {}, onSecurityReport: (value) => { summary = value; } });
+  assert.equal((await request(handler, signup(undefined, { origin: 'https://daily.example' }))).statusCode, 201);
+  const report = await request(handler, { url: '/api/security-reports', method: 'POST', body: JSON.stringify([{ type: 'connection-allowlist', body: { connection: 'https://evil.test/?email=private' } }]) });
+  assert.equal(report.statusCode, 204);
+  assert.deepEqual(summary, { connectionAllowlist: 1, csp: 0 });
+});
+
+test('client reports rejected requests, HTTP errors, timeouts, and success accessibly', async () => {
+  const script = await readFile(new URL('../newsletter.js', import.meta.url), 'utf8');
+  for (const scenario of ['blocked', 'http-error', 'timeout', 'success']) {
+    let submit;
+    let reset = false;
+    let timeout;
+    const status = { textContent: '' };
+    const button = { disabled: false };
+    const form = {
+      action: 'http://daily.test/api/newsletter',
+      querySelector: () => button,
+      reportValidity: () => true,
+      setAttribute() {}, removeAttribute() {},
+      reset() { reset = true; },
+      addEventListener(_, listener) { submit = listener; },
+    };
+    const context = vm.createContext({
+      document: { querySelector: (id) => id === '#newsletter-form' ? form : status },
+      URLSearchParams, FormData: class { *[Symbol.iterator]() { yield ['email', 'coffee@example.com']; } },
+      AbortController,
+      setTimeout(callback) { timeout = callback; return 1; }, clearTimeout() {},
+      fetch: async (_, options) => {
+        assert.equal(options.redirect, 'error');
+        assert.equal(options.mode, 'same-origin');
+        if (scenario === 'blocked') throw new TypeError('Network access revoked');
+        if (scenario === 'timeout') return new Promise((_, reject) => {
+          options.signal.addEventListener('abort', () => reject(new Error('Aborted')));
+          timeout();
+        });
+        return { ok: scenario !== 'http-error', json: async () => ({ ok: true }) };
+      },
+    });
+    vm.runInContext(script, context);
+    await submit({ preventDefault() {} });
+    assert.equal(button.disabled, false);
+    assert.equal(reset, scenario === 'success');
+    assert.match(status.textContent, scenario === 'success' ? /signed up/ : /couldn’t send your signup/);
+  }
+});

