@@ -0,0 +1,80 @@
+import { readFile, mkdir, appendFile } from 'node:fs/promises';
+import { fileURLToPath } from 'node:url';
+import { join } from 'node:path';
+
+const root = fileURLToPath(new URL('.', import.meta.url));
+export const securityHeaders = {
+  'Content-Security-Policy': "default-src 'none'; script-src 'self'; style-src 'self'; img-src 'self' https://images.unsplash.com; connect-src 'self'; font-src 'self'; form-action 'self'; base-uri 'none'; object-src 'none'; frame-src 'none'; frame-ancestors 'none'; worker-src 'none'; manifest-src 'none'",
+  'X-Content-Type-Options': 'nosniff',
+  'Referrer-Policy': 'no-referrer',
+  'X-Frame-Options': 'DENY',
+  'Cache-Control': 'no-store',
+};
+const assets = new Map([
+  ['/', ['index.html', 'text/html; charset=utf-8']],
+  ['/index.html', ['index.html', 'text/html; charset=utf-8']],
+  ['/styles.css', ['styles.css', 'text/css; charset=utf-8']],
+  ['/newsletter.js', ['newsletter.js', 'text/javascript; charset=utf-8']],
+]);
+
+export function createHandler({ dataDir = process.env.DATA_DIR || join(root, 'data') } = {}) {
+  return async (req, res) => {
+    for (const [name, value] of Object.entries(securityHeaders)) res.setHeader(name, value);
+    const send = (code, body, type = 'application/json; charset=utf-8') => {
+      res.writeHead(code, { 'Content-Type': type });
+      res.end(type.startsWith('application/json') ? JSON.stringify(body) : body);
+    };
+    try {
+      const pathname = new URL(req.url, 'http://localhost').pathname;
+      if (pathname === '/api/newsletter') {
+        if (req.method !== 'POST') {
+          res.setHeader('Allow', 'POST');
+          return send(405, { error: 'Method not allowed.' });
+        }
+        // Reject cross-site submissions. Same-origin forms also work without JS.
+        if (req.headers['sec-fetch-site'] === 'cross-site') {
+          return send(403, { error: 'Cross-site signup is not allowed.' });
+        }
+        const type = (req.headers['content-type'] || '').split(';')[0].trim();
+        if (!['application/json', 'application/x-www-form-urlencoded'].includes(type)) {
+          return send(415, { error: 'Unsupported content type.' });
+        }
+        let size = 0;
+        const chunks = [];
+        for await (const chunk of req) {
+          size += Buffer.byteLength(chunk);
+          if (size > 4096) return send(413, { error: 'Request too large.' });
+          chunks.push(Buffer.from(chunk));
+        }
+        const body = Buffer.concat(chunks).toString('utf8');
+        let fields;
+        try {
+          fields = type === 'application/json' ? JSON.parse(body) : Object.fromEntries(new URLSearchParams(body));
+        } catch {
+          return send(400, { error: 'Invalid signup.' });
+        }
+        const email = typeof fields?.email === 'string' ? fields.email.trim() : '';
+        if (email.length > 254 || !/^[^\s@<>]+@[^\s@<>]+\.[^\s@<>]+$/.test(email)) {
+          return send(400, { error: 'Please enter a valid email address.' });
+        }
+        await mkdir(dataDir, { recursive: true, mode: 0o700 });
+        await appendFile(join(dataDir, 'newsletter.jsonl'), JSON.stringify({ email, subscribedAt: new Date().toISOString() }) + '\n', { mode: 0o600 });
+        if (type === 'application/x-www-form-urlencoded') {
+          return send(201, '<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Thanks for joining</title><p>You’re on the list! Thanks for joining the Daily Grind.</p><a href="/">Back to the homepage</a></html>', 'text/html; charset=utf-8');
+        }
+        return send(201, { ok: true });
+      }
+      const asset = assets.get(pathname);
+      if (!asset) return send(404, { error: 'Page not found.' });
+      if (!['GET', 'HEAD'].includes(req.method)) {
+        res.setHeader('Allow', 'GET, HEAD');
+        return send(405, { error: 'Method not allowed.' });
+      }
+      const content = await readFile(join(root, asset[0]));
+      res.writeHead(200, { 'Content-Type': asset[1] });
+      res.end(req.method === 'HEAD' ? undefined : content);
+    } catch {
+      send(500, { error: 'We couldn’t save your signup. Please try again shortly.' });
+    }
+  };
+}
