+import test from 'node:test';
+import assert from 'node:assert/strict';
+import { Readable } from 'node:stream';
+import { mkdtemp, readFile, rm, stat, writeFile } from 'node:fs/promises';
+import { tmpdir } from 'node:os';
+import { join } from 'node:path';
+import { createHandler, securityHeaders } from './handler.js';
+
+async function request(handler, { url = '/', method = 'GET', body = '', headers = {} } = {}) {
+  const req = Readable.from([Buffer.from(body)]);
+  Object.assign(req, { url, method, headers });
+  const response = { headers: {}, setHeader(key, value) { this.headers[key] = value; },
+    writeHead(code, values) { this.status = code; Object.assign(this.headers, values); },
+    end(value) { this.body = value?.toString() || ''; } };
+  await handler(req, response);
+  assert.equal(response.headers['Content-Security-Policy'], securityHeaders['Content-Security-Policy']);
+  return response;
+}
+
+test('CSP restricts connections and forms to self and allows only the photo host for external images', () => {
+  const directives = Object.fromEntries(securityHeaders['Content-Security-Policy'].split('; ').map(part => {
+    const [name, ...sources] = part.split(' ');
+    return [name, sources];
+  }));
+  assert.deepEqual(directives['connect-src'], ["'self'"]);
+  assert.deepEqual(directives['form-action'], ["'self'"]);
+  assert.deepEqual(directives['img-src'], ["'self'", 'https://images.unsplash.com']);
+  for (const name of ['default-src', 'base-uri', 'object-src', 'frame-ancestors', 'worker-src']) {
+    assert.deepEqual(directives[name], ["'none'"]);
+  }
+  assert.deepEqual(directives['script-src'], ["'self'"]);
+  assert.deepEqual(directives['style-src'], ["'self'"]);
+});
+
+test('homepage assets work with CSP and private paths cannot be read', async () => {
+  const handler = createHandler();
+  const page = await request(handler);
+  assert.equal(page.status, 200);
+  assert.match(page.body, /action="\/api\/newsletter"/);
+  assert.doesNotMatch(page.body, /<style|style=|<script(?![^>]*src=)/);
+  for (const url of ['/styles.css', '/newsletter.js']) {
+    assert.equal((await request(handler, { url })).status, 200);
+    assert.equal((await request(handler, { url, method: 'HEAD' })).body, '');
+  }
+  for (const url of ['/data/newsletter.jsonl', '/handler.js', '/package.json', '/%2e%2e/server.js']) {
+    assert.equal((await request(handler, { url })).status, 404);
+  }
+});
+
+test('signup persists valid JSON and form submissions, rejects invalid requests, and reports storage errors', async () => {
+  const dir = await mkdtemp(join(tmpdir(), 'daily-grind-'));
+  try {
+    const dataDir = join(dir, 'private');
+    const handler = createHandler({ dataDir });
+    const signup = (body, headers = {}) => request(handler, { url: '/api/newsletter', method: 'POST', body,
+      headers: { 'content-type': 'application/json', ...headers } });
+    assert.equal((await signup(JSON.stringify({ email: ' coffee@example.com ' }))).status, 201);
+    const saved = JSON.parse((await readFile(join(dataDir, 'newsletter.jsonl'), 'utf8')).trim());
+    assert.equal(saved.email, 'coffee@example.com');
+    assert.ok(saved.subscribedAt);
+    assert.equal((await stat(join(dataDir, 'newsletter.jsonl'))).mode & 0o777, 0o600);
+    assert.equal((await signup('email=other%40example.com', { 'content-type': 'application/x-www-form-urlencoded' })).status, 201);
+    for (const body of ['{', 'null', '{}', '{"email":"bad"}', JSON.stringify({ email: 'x'.repeat(250) + '@example.com' })]) {
+      assert.equal((await signup(body)).status, 400);
+    }
+    assert.equal((await signup('x'.repeat(4097))).status, 413);
+    assert.equal((await signup('{}', { 'content-type': 'text/plain' })).status, 415);
+    assert.equal((await signup('{}', { 'sec-fetch-site': 'cross-site' })).status, 403);
+    assert.equal((await request(handler, { url: '/api/newsletter' })).status, 405);
+    const blockedDir = join(dir, 'file');
+    await writeFile(blockedDir, 'not a directory');
+    const failure = await request(createHandler({ dataDir: blockedDir }), { url: '/api/newsletter', method: 'POST',
+      body: '{"email":"coffee@example.com"}', headers: { 'content-type': 'application/json' } });
+    assert.equal(failure.status, 500);
+    assert.match(failure.body, /try again/);
+  } finally {
+    await rm(dir, { recursive: true, force: true });
+  }
+});
