--- /dev/null
+++ b/newsletter.js
@@ -0,0 +1,48 @@
+const form = document.querySelector('#newsletter-form');
+const status = document.querySelector('#newsletter-status');
+const button = form.querySelector('button');
+let submitting = false;
+
+document.addEventListener('securitypolicyviolation', (event) => {
+  if (submitting && event.effectiveDirective === 'connect-src') {
+    status.textContent = 'Your request was blocked by our security policy. Please try again.';
+  }
+});
+
+form.addEventListener('submit', async (event) => {
+  event.preventDefault();
+  if (submitting || !form.reportValidity()) return;
+  submitting = true;
+  button.disabled = true;
+  status.textContent = 'Signing you up…';
+  const controller = new AbortController();
+  const timeout = setTimeout(() => controller.abort(), 10000);
+  try {
+    const response = await fetch('/api/newsletter', {
+      method: 'POST',
+      headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
+      body: JSON.stringify({ email: form.elements.email.value.trim() }),
+      mode: 'same-origin',
+      redirect: 'error',
+      signal: controller.signal,
+    });
+    if (!response.ok) {
+      status.textContent = response.status === 400
+        ? 'Please enter a valid email address and try again.'
+        : 'We couldn’t save your signup. Please try again shortly.';
+      return;
+    }
+    const result = await response.json();
+    if (!result.ok) throw new Error('Signup failed');
+    status.textContent = 'You’re on the list! Thanks for joining the Daily Grind.';
+    form.reset();
+  } catch (error) {
+    status.textContent = error.name === 'AbortError'
+      ? 'Your request timed out. Please try again.'
+      : 'We couldn’t send your signup. Check your connection and try again. If it keeps failing, the request may be blocked.';
+  } finally {
+    clearTimeout(timeout);
+    submitting = false;
+    button.disabled = false;
+  }
+});
