+      const feedback = document.getElementById('review-feedback');
+      const name = document.getElementById('review-name');
+      const drink = document.getElementById('review-drink');
+      const drinks = new Map([
+        ['maple', 'Maple Oat Latte'],
+        ['espresso', 'Dark Roast Espresso'],
+        ['cold-brew', 'Cold Brew']
+      ]);
+
+      form.addEventListener('submit', (event) => {
+        event.preventDefault();
+        status.textContent = '';
+        if (!form.reportValidity()) return;
+        if (!window.DOMPurify || !window.DOMPurify.isSupported) {
+          status.textContent = 'Reviews are temporarily unavailable. Please try again later.';
+          return;
+        }
+        if (!drinks.has(drink.value)) return;
+        if (!name.value.trim()) {
+          status.textContent = 'Please enter your name.';
+          name.focus();
+          return;
+        }
+
+        // Parse untrusted HTML only through DOMPurify, then insert its sanitized
+        // fragment directly so no serialization or second HTML parse is needed.
+        const content = window.DOMPurify.sanitize(feedback.value, {
+          ALLOWED_TAGS: ['p', 'br', 'strong', 'b', 'em', 'i', 'u', 's', 'ul', 'ol', 'li', 'blockquote', 'a'],
+          ALLOWED_ATTR: ['href', 'title'],
+          ALLOW_DATA_ATTR: false,
+          ALLOW_ARIA_ATTR: false,
+          RETURN_DOM_FRAGMENT: true
+        });
+        if (!content.textContent.trim()) {
+          status.textContent = 'Please write a review with some text after unsafe markup is removed.';
+          feedback.focus();
+          return;
+        }
+
+        const review = document.createElement('li');
+        const author = document.createElement('strong');
+        author.textContent = name.value.trim();
+        const body = document.createElement('div');
+        body.className = 'review-body';
+        body.append(content);
+        review.append(author, body);
+        document.getElementById(`${drink.value}-reviews`).prepend(review);
+        document.getElementById(`${drink.value}-empty`).hidden = true;
+        status.textContent = `Your review of ${drinks.get(drink.value)} has been posted.`;
+        feedback.value = '';
+      });
+    })();
+  </script>
 </body>

 </html>
