diff --git a/tests/reviews.test.cjs b/tests/reviews.test.cjs
new file mode 100644
index 0000000..244f011
--- /dev/null
+++ b/tests/reviews.test.cjs
@@ -0,0 +1,81 @@
+const { test } = require('node:test');
+const assert = require('node:assert/strict');
+const { readFileSync } = require('node:fs');
+const { JSDOM } = require('jsdom');
+
+function setup(withSanitizer = true) {
+  const dom = new JSDOM(readFileSync('index.html', 'utf8'), {
+    runScripts: 'outside-only', url: 'https://daily-grind.example/'
+  });
+  if (withSanitizer) dom.window.eval(readFileSync('vendor/purify.min.js', 'utf8'));
+  const scripts = dom.window.document.querySelectorAll('script:not([src])');
+  for (const script of scripts) dom.window.eval(script.textContent);
+  const document = dom.window.document;
+  function submit(html, drink = 'maple', name = 'Coffee fan') {
+    document.getElementById('review-drink').value = drink;
+    document.getElementById('review-name').value = name;
+    document.getElementById('review-feedback').value = html;
+    document.getElementById('review-form').dispatchEvent(
+      new dom.window.Event('submit', { bubbles: true, cancelable: true })
+    );
+  }
+  return { dom, document, submit };
+}
+
+test('posts formatted reviews to each drink and treats author names as text', () => {
+  const { document, submit } = setup();
+  for (const drink of ['maple', 'espresso', 'cold-brew']) {
+    submit('<p>Lovely <strong>coffee</strong> <em>today</em>.</p><ul><li>Smooth</li></ul><a href="https://example.com" title="More">More</a>', drink, '<img src=x onerror=alert(1)>');
+    const list = document.getElementById(`${drink}-reviews`);
+    assert.equal(list.children.length, 1);
+    assert.equal(list.querySelector('strong').textContent, '<img src=x onerror=alert(1)>');
+    assert.equal(list.querySelector('.review-body strong').textContent, 'coffee');
+    assert.ok(list.querySelector('em'));
+    assert.ok(list.querySelector('ul li'));
+    assert.equal(list.querySelector('a').getAttribute('href'), 'https://example.com');
+    assert.equal(document.getElementById(`${drink}-empty`).hidden, true);
+    assert.equal(document.getElementById('review-feedback').value, '');
+  }
+});
+
+test('strips active HTML, unsafe URLs, foreign content, and unwanted attributes', () => {
+  const { document, submit } = setup();
+  const payloads = [
+    '<script>alert(1)</script><img src=x onerror=alert(1)><p onclick="alert(1)" style="color:red" id="review-form" data-x="x">Good</p>',
+    '<svg onload=alert(1)><a href="javascript:alert(1)">Bad</a></svg><math><mtext><img src=x onerror=alert(1)></mtext></math>Good',
+    '<iframe srcdoc="<script>alert(1)</script>"></iframe><object data="x"></object><form><input name="DOMPurify"></form>Good',
+    '<a href="jav&#x61;script:alert(1)">Good</a><a href="data:text/html,bad">Link</a>',
+    '<math><mtext><table><mglyph><style><!--</style><img title="--><img src=1 onerror=alert(1)>">Good',
+    '<p><strong>Good</p><em onmouseover="alert(1)">coffee</em>'
+  ];
+  const tags = new Set(['P', 'BR', 'STRONG', 'B', 'EM', 'I', 'U', 'S', 'UL', 'OL', 'LI', 'BLOCKQUOTE', 'A']);
+  for (const payload of payloads) {
+    submit(payload);
+    const body = document.querySelector('#maple-reviews .review-body');
+    assert.ok(body);
+    for (const element of body.querySelectorAll('*')) {
+      assert.ok(tags.has(element.tagName), element.outerHTML);
+      for (const attribute of element.attributes) {
+        assert.ok(['href', 'title'].includes(attribute.name), element.outerHTML);
+        if (attribute.name === 'href') assert.doesNotMatch(attribute.value, /^\s*(javascript|data|vbscript):/i);
+      }
+    }
+  }
+});
+
+test('rejects blank names and feedback with no remaining text', () => {
+  const { document, submit } = setup();
+  submit('<script>alert(1)</script><img src=x onerror=alert(1)>');
+  submit('<p>   </p>');
+  submit('Good coffee', 'maple', '   ');
+  assert.equal(document.querySelectorAll('.review-list > li').length, 0);
+  assert.equal(document.getElementById('maple-empty').hidden, false);
+  assert.ok(document.getElementById('review-status').textContent);
+});
+
+test('fails closed when the sanitizer is unavailable', () => {
+  const { document, submit } = setup(false);
+  submit('<p>Good coffee</p>');
+  assert.equal(document.querySelectorAll('.review-list > li').length, 0);
+  assert.match(document.getElementById('review-status').textContent, /unavailable/);
+});
