+    .operations {
+      margin-top: 48px;
+      padding: clamp(20px, 4vw, 32px);
+      border: 1px solid var(--secondary);
+      border-radius: 12px;
+      background: white;
+    }
+
+    .operations-heading, .queue-summary, .task-meta {
+      display: flex;
+      align-items: center;
+      justify-content: space-between;
