+      font-weight: 700;
+      letter-spacing: 0.12em;
+      text-transform: uppercase;
+    }
+
+    .operations-description { margin: 12px 0 20px; max-width: 70ch; }
+    .queue-indicator { font-size: 0.8rem; border-radius: 20px; background: #f3efed; padding: 5px 12px; }
+    .task-controls { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 12px; }
+    .task-button {
+      font: inherit;
+      color: var(--text);
