+    .task-button:disabled { opacity: 0.6; cursor: wait; }
+    .operations button:focus-visible { outline: 3px solid #a85a00; outline-offset: 3px; }
+    .batch-button { grid-column: 1 / -1; background: var(--primary); color: white; text-align: center; }
