+    .queue-summary { padding: 20px 0 12px; font-size: 0.85rem; border-bottom: 1px solid #eee5e0; }
+    .queue-log { list-style: none; max-height: 320px; overflow-y: auto; padding-right: 6px; }
+    .queue-log li { padding: 14px 0; border-bottom: 1px solid #eee5e0; }
+    .queue-log .empty-queue { color: #735f58; padding: 24px 0; }
+    .task-meta { font-size: 0.85rem; }
+    .task-meta small { color: #735f58; }
+    .task-priority { font-size: 0.75rem; font-weight: 600; }
+    .task-priority[data-priority="user-blocking"] { color: #a0391a; }
+    .task-priority[data-priority="background"] { color: #47644e; }
+    .queue-log progress { display: block; width: 100%; height: 6px; margin-top: 8px; accent-color: var(--primary); }
+    .queue-note { font-size: 0.8rem; color: #735f58; margin-top: 16px; }
