+        taskButtons.forEach(button => { button.disabled = pending.length >= 30; });
+        batch.disabled = pending.length > 27;
+      }
+
+      function schedule() {
+        if (scheduled || !pending.length) return;
+        scheduled = true;
+        // Yield to the browser between bounded work slices, including for new clicks.
+        setTimeout(runSlice, 16);
+      }
+
+      function runSlice() {
+        scheduled = false;
+        pending.sort((a, b) => a.rank - b.rank || a.id - b.id);
+        const job = pending[0];
+        if (!job) return;
+        if (active !== job) {
+          if (active) record(active.name + ' #' + active.id + ' paused for higher-priority work.');
