+      cancelNavigation = () => {
+        cancelAnimationFrame(frame);
+        controller.abort();
+      };
+      const interrupt = () => {
+        cancelNavigation();
+        window.scrollTo({ top: window.scrollY, behavior: 'instant' });
+      };
+      for (const type of ['wheel', 'touchstart', 'pointerdown']) {
+        window.addEventListener(type, interrupt, { passive: true, signal: controller.signal });
+      }
