+      const checkScroll = () => {
+        const currentY = window.scrollY;
+        const atDestination = Math.abs(currentY - destination) <= 1;
+        settledFrames = atDestination && Math.abs(currentY - previousY) < 0.1 ? settledFrames + 1 : 0;
+        previousY = currentY;
+        if (settledFrames < 3) {
