+    let observer;
+
+    function configureStory() {
+      observer?.disconnect();
+      visualContainer.classList.remove('scroll-fallback');
+      visualSteps.forEach(step => step.classList.remove('is-active'));
+      if (nativeTimelines || motionPreference.matches || !('IntersectionObserver' in window)) return;
