+          (visibleHeights.get(step) || 0) > (visibleHeights.get(best) || 0) ? step : best,
+          trackedSteps[0]);
+        visualSteps.forEach((step, index) => step.classList.toggle('is-active', trackedSteps[index] === active));
+      }, { threshold: Array.from({ length: 51 }, (_, index) => index / 50) });
+      trackedSteps.forEach(step => observer.observe(step));
+      visualSteps[0].classList.add('is-active');
