+'use strict';
+
+const fs = require('node:fs');
+const path = require('node:path');
+
+// Only developer-owned files are served. Never resolve a request into a disk path.
+const home = fs.readFileSync(path.join(__dirname, 'index.html'));
+const styles = fs.readFileSync(path.join(__dirname, 'styles.css'));
+const pages = new Set(['/', '/index.html', '/menu', '/locations', '/rewards',
+  '/account', '/order-online', '/menu/seasonal', '/menu/espresso', '/menu/cold-brew',
+  '/about', '/careers', '/contact', '/privacy-policy']);
+const policy = [
+  "default-src 'none'", "script-src 'none'", "script-src-attr 'none'",
+  "style-src 'self'", "style-src-attr 'none'",
+  "img-src 'self' https://images.unsplash.com", "connect-src 'none'",
+  "object-src 'none'", "base-uri 'none'", "frame-ancestors 'none'",
+  "form-action 'self'", "require-trusted-types-for 'script'", "trusted-types 'none'",
+  'report-to security', 'report-uri /security-reports',
+].join('; ');
+
+function documentPage(title, body) {
+  // Arguments must be developer-owned constants, never request data.
+  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>${title} | The Daily Grind</title><link rel="stylesheet" href="/styles.css"></head><body><main class="container"><h1>${title}</h1>${body}</main></body></html>`;
+}
+
+function createHandler({ onReport = () => {}, production = false } = {}) {
+  return async function handle(req, res) {
+    const headers = {
+      'Content-Security-Policy': policy,
+      'Reporting-Endpoints': 'security="/security-reports"',
+      'Cross-Origin-Opener-Policy': 'same-origin-allow-popups',
+      'Cross-Origin-Resource-Policy': 'same-origin',
+      'X-Frame-Options': 'DENY',
+      'X-Content-Type-Options': 'nosniff',
+      'Referrer-Policy': 'no-referrer',
+      'Permissions-Policy': 'camera=(), microphone=(), geolocation=(), payment=(), usb=(), focus-without-user-activation=()',
+      'Cache-Control': 'no-store',
+      'Vary': 'Sec-Fetch-Dest, Sec-Fetch-Mode, Sec-Fetch-Site',
+    };
+    // TLS is terminated by the production reverse proxy. Do not trust forwarded
+    // headers from arbitrary clients or opt all subdomains into HSTS.
+    if (production) headers['Strict-Transport-Security'] = 'max-age=300';
+    const send = (status, body = '', type = 'text/plain; charset=utf-8', extra = {}) => {
+      res.writeHead(status, { ...headers, 'Content-Type': type, ...extra });
+      res.end(req.method === 'HEAD' ? undefined : body);
+    };
+    let url;
+    try {
+      if (!req.url.startsWith('/') || req.url.startsWith('//')) throw new Error();
+      url = new URL(req.url, 'http://localhost');
+    } catch {
+      return send(400, 'Bad request');
+    }
+    const pathname = url.pathname;
+    const site = req.headers['sec-fetch-site'];
+    const crossOrigin = site && !['same-origin', 'none'].includes(site);
+    const navigation = req.method === 'GET' && req.headers['sec-fetch-mode'] === 'navigate'
+      && req.headers['sec-fetch-dest'] === 'document';
+    if (crossOrigin && !navigation) return send(403, 'Forbidden');
+
+    if (pathname === '/security-reports') {
+      if (req.method !== 'POST') return send(405, 'Method not allowed', undefined, { Allow: 'POST' });
+      const type = (req.headers['content-type'] || '').split(';')[0].trim();
+      if (!['application/reports+json', 'application/csp-report'].includes(type)) return send(415, 'Unsupported media type');
+      // Reports are untrusted and may contain URLs, tokens, script samples or PII.
+      // Bound the body and emit only fixed, allowlisted directive names as telemetry.
+      const directives = new Set(['default-src', 'script-src', 'script-src-elem',
+        'script-src-attr', 'style-src', 'style-src-elem', 'style-src-attr', 'img-src',
+        'connect-src', 'object-src', 'base-uri', 'frame-ancestors', 'form-action',
+        'require-trusted-types-for', 'trusted-types']);
+      try {
+        let size = 0;
+        const chunks = [];
+        for await (const chunk of req) {
+          size += chunk.length;
+          if (size > 16384) return send(413, 'Report too large');
+          chunks.push(chunk);
+        }
+        const payload = JSON.parse(Buffer.concat(chunks).toString('utf8'));
+        const reports = Array.isArray(payload) ? payload : [payload];
+        for (const report of reports.slice(0, 20)) {
+          const body = report?.body || report?.['csp-report'];
+          const directive = body?.effectiveDirective || body?.['effective-directive'];
+          if (directives.has(directive)) onReport({ directive });
+        }
+        return send(204);
+      } catch {
+        return send(400, 'Invalid report');
+      }
+    }
+
+    if (pathname === '/logout' || pathname === '/logout/') {
+      if (req.method === 'POST') {
+        // Origin comparison is a fallback for browsers without Fetch Metadata.
+        // The Host comparison never becomes a redirect or reporting URL.
+        if (req.headers.origin) {
+          try {
+            const origin = new URL(req.headers.origin);
+            if (!['http:', 'https:'].includes(origin.protocol) || origin.host !== req.headers.host) return send(403, 'Forbidden');
+          } catch { return send(403, 'Forbidden'); }
+        }
+        const names = new Set(['session', '__Host-session']);
+        for (const cookie of (req.headers.cookie || '').split(';')) {
+          const name = cookie.trim().split('=')[0];
+          if (/^[!#$%&'*+.^_`|~0-9A-Za-z-]+$/.test(name)) names.add(name);
+        }
+        const cookies = [...names].map(name => `${name}=; Max-Age=0; Expires=Thu, 01 Jan 1970 00:00:00 GMT; Path=/; HttpOnly; SameSite=Lax${production || name.startsWith('__Secure-') || name.startsWith('__Host-') ? '; Secure' : ''}`);
+        return send(200, documentPage('Logged out', '<p>You have been signed out on this browser.</p><a href="/" class="btn">Return to home</a>'), 'text/html; charset=utf-8', {
+          'Clear-Site-Data': '"cookies", "storage", "cache"', 'Set-Cookie': cookies,
+        });
+      }
+      if (req.method === 'GET' || req.method === 'HEAD') return send(200,
+        documentPage('Sign out', '<form method="post" action="/logout"><button type="submit" class="btn">Sign out</button></form>'), 'text/html; charset=utf-8');
+      return send(405, 'Method not allowed', undefined, { Allow: 'GET, HEAD, POST' });
+    }
+    if (!['GET', 'HEAD'].includes(req.method)) return send(405, 'Method not allowed', undefined, { Allow: 'GET, HEAD' });
+    if (pathname === '/styles.css') return send(200, styles, 'text/css; charset=utf-8');
+    if (pages.has(pathname)) return send(200, home, 'text/html; charset=utf-8');
+    return send(404, 'Not found');
+  };
+}
+
+module.exports = { createHandler };
