@@ -0,0 +1,98 @@
+'use strict';
+const { test } = require('node:test');
+const assert = require('node:assert/strict');
+const { Readable } = require('node:stream');
+const fs = require('node:fs');
+const path = require('node:path');
+const { createHandler } = require('../request-handler');
+
+async function request(url, { method = 'GET', headers = {}, body = '', ...options } = {}) {
+  const req = Readable.from([Buffer.from(body)]);
+  Object.assign(req, { url, method, headers: { host: 'coffee.example', ...headers } });
+  const response = {};
+  await createHandler(options)(req, {
+    writeHead(status, responseHeaders) { Object.assign(response, { status, headers: responseHeaders }); },
+    end(body) { response.body = body?.toString() || ''; },
+  });
+  return response;
+}
+
+test('page and stylesheet remain compatible with enforced policy', async () => {
+  const page = await request('/');
+  assert.equal(page.status, 200);
+  assert.match(page.headers['Content-Security-Policy'], /script-src 'none'/);
+  assert.match(page.headers['Content-Security-Policy'], /require-trusted-types-for 'script'/);
+  assert.match(page.headers['Content-Security-Policy'], /report-to security/);
+  assert.equal(page.headers['Reporting-Endpoints'], 'security="/security-reports"');
+  assert.equal(page.headers['X-Frame-Options'], 'DENY');
+  assert.equal(page.headers['X-Content-Type-Options'], 'nosniff');
+  assert.equal(page.headers['Cross-Origin-Resource-Policy'], 'same-origin');
+  assert.doesNotMatch(page.body, /<script\b|<style\b|\sstyle\s*=|\son\w+\s*=|javascript:/i);
+  assert.match(page.body, /action="\/logout" method="post"/);
+  const css = await request('/styles.css');
+  assert.match(css.headers['Content-Type'], /^text\/css/);
+  assert.match(css.body, /https:\/\/images\.unsplash\.com\//);
+  for (const file of ['index.html', 'styles.css']) {
+    const source = fs.readFileSync(path.join(__dirname, '..', file), 'utf8');
+    const origins = [...source.matchAll(/https?:\/\/[^/'"\s)]+/g)].map(match => match[0]);
+    assert.ok(origins.every(origin => origin === 'https://images.unsplash.com'));
+  }
+});
+
+test('logout clears data and expires cookies, GET and HEAD have no side effects', async () => {
+  const result = await request('/logout', { method: 'POST', headers: { origin: 'https://coffee.example', cookie: 'session=secret; visitor=123; __Host-session=secret' } });
+  assert.equal(result.status, 200);
+  assert.match(result.body, /Logged out/);
+  assert.equal(result.headers['Clear-Site-Data'], '"cookies", "storage", "cache"');
+  assert.equal(result.headers['Cache-Control'], 'no-store');
+  assert.ok(result.headers['Set-Cookie'].some(cookie => cookie.startsWith('visitor=; Max-Age=0;')));
+  assert.ok(result.headers['Set-Cookie'].find(cookie => cookie.startsWith('__Host-session=')).endsWith('; Secure'));
+  assert.doesNotMatch(result.body, /secret/);
+  for (const method of ['GET', 'HEAD']) {
+    const safe = await request('/logout/', { method });
+    assert.equal(safe.status, 200);
+    assert.equal(safe.headers['Clear-Site-Data'], undefined);
+    assert.equal(safe.headers['Set-Cookie'], undefined);
+    if (method === 'HEAD') assert.equal(safe.body, '');
+  }
+});
+
+test('rejects cross-site mutations, same-site sibling origins and bad origins', async () => {
+  for (const site of ['cross-site', 'same-site']) {
+    const result = await request('/logout', { method: 'POST', headers: { 'sec-fetch-site': site } });
+    assert.equal(result.status, 403);
+    assert.equal(result.headers['Clear-Site-Data'], undefined);
+  }
+  for (const origin of ['https://evil.example', 'null', 'invalid']) {
+    assert.equal((await request('/logout', { method: 'POST', headers: { origin } })).status, 403);
+  }
+  assert.equal((await request('/', { headers: { 'sec-fetch-site': 'cross-site', 'sec-fetch-mode': 'navigate', 'sec-fetch-dest': 'document' } })).status, 200);
+  assert.equal((await request('/styles.css', { headers: { 'sec-fetch-site': 'cross-site' } })).status, 403);
+});
+
+test('report collector bounds input and only emits sanitized directive telemetry', async () => {
+  const reports = [];
+  const options = { method: 'POST', headers: { 'content-type': 'application/csp-report' }, onReport: report => reports.push(report) };
+  assert.equal((await request('/security-reports', { ...options, body: JSON.stringify({ 'csp-report': { 'effective-directive': 'script-src', 'document-uri': 'https://example.com/?token=secret', 'script-sample': 'secret' } }) })).status, 204);
+  assert.deepEqual(reports, [{ directive: 'script-src' }]);
+  assert.equal((await request('/security-reports', { ...options, body: '{' })).status, 400);
+  assert.equal((await request('/security-reports', { ...options, body: 'x'.repeat(16385) })).status, 413);
+  assert.equal((await request('/security-reports', { method: 'POST' })).status, 415);
+  assert.equal((await request('/security-reports')).status, 405);
+  assert.equal((await request('/security-reports', { ...options, headers: { 'content-type': 'application/reports+json' }, body: JSON.stringify([{ type: 'csp-violation', body: { effectiveDirective: 'style-src-attr' } }]) })).status, 204);
+  assert.deepEqual(reports[1], { directive: 'style-src-attr' });
+});
+
+test('routing is explicit, malformed requests safe, headers present on errors', async () => {
+  for (const url of ['/server.js', '/package.json', '/.git/config', '/unknown', '/../../etc/passwd']) {
+    const response = await request(url);
+    assert.equal(response.status, 404);
+    assert.equal(response.headers['X-Content-Type-Options'], 'nosniff');
+  }
+  assert.equal((await request('//evil.example')).status, 400);
+  assert.equal((await request('/', { method: 'POST' })).status, 405);
+  assert.equal((await request('/', { method: 'HEAD' })).body, '');
+  assert.equal((await request('/menu/seasonal')).status, 200);
+  assert.equal((await request('/')).headers['Strict-Transport-Security'], undefined);
+  assert.equal((await request('/', { production: true })).headers['Strict-Transport-Security'], 'max-age=300');
+});

