@@ -0,0 +1,129 @@
+'use strict';
+
+const fs = require('node:fs');
+const path = require('node:path');
+
+const CSP = [
+  "default-src 'none'",
+  "script-src 'none'",
+  "script-src-attr 'none'",
+  "style-src 'self'",
+  "style-src-attr 'none'",
+  "img-src 'self' https://images.unsplash.com",
+  "connect-src 'none'",
+  "object-src 'none'",
+  "base-uri 'none'",
+  "form-action 'self'",
+  "frame-ancestors 'none'",
+  "require-trusted-types-for 'script'",
+  "trusted-types 'none'",
+].join('; ');
+
+// Preserve existing page links; never serve arbitrary filesystem paths.
+const PAGE_PATHS = new Set([
+  '/', '/index.html', '/menu', '/locations', '/rewards', '/account',
+  '/order-online', '/menu/seasonal', '/menu/espresso', '/menu/cold-brew',
+  '/about', '/careers', '/contact', '/privacy-policy',
+]);
+
+function documentPage(title, content) {
+  return `<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>${title} | The Daily Grind</title><link rel="stylesheet" href="/styles.css"></head><body><main class="container"><h1>${title}</h1>${content}</main></body></html>`;
+}
+
+function createHandler({ publicOrigin, reportOnly = false } = {}) {
+  let origin;
+  if (publicOrigin) {
+    const parsed = new URL(publicOrigin);
+    if (!['http:', 'https:'].includes(parsed.protocol) || parsed.username || parsed.password ||
+        parsed.pathname !== '/' || parsed.search || parsed.hash) {
+      throw new Error('PUBLIC_ORIGIN must be an HTTP(S) origin without a path or credentials');
+    }
+    origin = parsed.origin;
+  }
+
+  const homepage = fs.readFileSync(path.join(__dirname, 'index.html'));
+  const stylesheet = fs.readFileSync(path.join(__dirname, 'styles.css'));
+
+  return function handleRequest(req, res) {
+    res.setHeader(reportOnly ? 'Content-Security-Policy-Report-Only' : 'Content-Security-Policy', CSP);
+    res.setHeader('X-Content-Type-Options', 'nosniff');
+    res.setHeader('X-Frame-Options', 'DENY');
+    res.setHeader('Referrer-Policy', 'no-referrer');
+    res.setHeader('Permissions-Policy', 'camera=(), microphone=(), geolocation=(), payment=(), usb=()');
+    res.setHeader('Cross-Origin-Opener-Policy', 'same-origin');
+    res.setHeader('Cross-Origin-Resource-Policy', 'same-origin');
+    res.setHeader('X-DNS-Prefetch-Control', 'off');
+    res.setHeader('Cache-Control', 'no-store');
+    if (origin?.startsWith('https:') || req.socket?.encrypted) {
+      res.setHeader('Strict-Transport-Security', 'max-age=31536000');
+    }
+
+    function send(status, body, type = 'text/html; charset=utf-8') {
+      res.statusCode = status;
+      res.setHeader('Content-Type', type);
+      res.setHeader('Content-Length', Buffer.byteLength(body));
+      res.end(req.method === 'HEAD' ? undefined : body);
+    }
+
+    let pathname;
+    try {
+      // A fixed base avoids using untrusted Host as a URL parser base.
+      if (!req.url?.startsWith('/') || req.url.startsWith('//')) throw new Error('Invalid target');
+      pathname = new URL(req.url, 'http://localhost').pathname;
+    } catch {
+      send(400, 'Bad request', 'text/plain; charset=utf-8');
+      return;
+    }
+
+    if (pathname === '/logout' || pathname === '/logout/') {
+      if (req.method === 'GET' || req.method === 'HEAD') {
+        send(200, documentPage('Sign out', '<p>Sign out of The Daily Grind on this browser.</p><form action="/logout" method="post"><button class="btn" type="submit">Logout</button></form><p><a href="/">Return home</a></p>'));
+        return;
+      }
+      if (req.method !== 'POST') {
+        res.setHeader('Allow', 'GET, HEAD, POST');
+        send(405, 'Method not allowed', 'text/plain; charset=utf-8');
+        return;
+      }
+
+      // Do not trust forwarded headers from arbitrary clients.
+      const expectedOrigin = origin || `${req.socket?.encrypted ? 'https' : 'http'}://${req.headers.host}`;
+      const fetchSite = req.headers['sec-fetch-site'];
+      const sameOrigin = req.headers.origin
+        ? req.headers.origin === expectedOrigin
+        : fetchSite === 'same-origin';
+      const purpose = `${req.headers.purpose || ''} ${req.headers['sec-purpose'] || ''}`;
+      if (!sameOrigin || (fetchSite && fetchSite !== 'same-origin') || /prefetch|prerender/i.test(purpose)) {
+        send(403, 'Forbidden', 'text/plain; charset=utf-8');
+        return;
+      }
+
+      // No session store exists. Revoke server-side sessions here if added.
+      res.setHeader('Clear-Site-Data', '"cache", "cookies", "storage"');
+      // Root-path cookie expiration also works without Clear-Site-Data support.
+      const names = new Set(['session', 'sessionId', 'sid']);
+      for (const cookie of (req.headers.cookie || '').split(';')) {
+        const name = cookie.trim().split('=')[0];
+        if (/^[!#$%&'*+\-.^_`|~0-9A-Za-z]+$/.test(name)) names.add(name);
+      }
+      res.setHeader('Set-Cookie', [...names].map(name =>
+        `${name}=; Path=/; Max-Age=0; Expires=Thu, 01 Jan 1970 00:00:00 GMT; HttpOnly; SameSite=Lax${expectedOrigin.startsWith('https:') ? '; Secure' : ''}`));
+      req.resume();
+      send(200, documentPage('Logged out', '<p>You have signed out on this browser.</p><p><a href="/">Return home</a></p>'));
+      return;
+    }
+
+    if (!['GET', 'HEAD'].includes(req.method)) {
+      res.setHeader('Allow', 'GET, HEAD');
+      send(405, 'Method not allowed', 'text/plain; charset=utf-8');
+    } else if (pathname === '/styles.css') {
+      send(200, stylesheet, 'text/css; charset=utf-8');
+    } else if (PAGE_PATHS.has(pathname)) {
+      send(200, homepage);
+    } else {
+      send(404, documentPage('Page not found', '<p><a href="/">Return home</a></p>'));
+    }
+  };
+}
+
+module.exports = { createHandler };
