index 0000000..6238368
--- /dev/null
+++ b/test/security.test.js
@@ -0,0 +1,104 @@
+'use strict';
+
+const { test } = require('node:test');
+const assert = require('node:assert/strict');
+const fs = require('node:fs');
+const path = require('node:path');
+// This module only exports a handler; no server entrypoint is imported or started.
+const { createHandler } = require('../app');
+
+function request(url = '/', { method = 'GET', headers = {}, options = {} } = {}) {
+  const response = { headers: {}, setHeader(name, value) { this.headers[name.toLowerCase()] = value; }, end(body) { this.body = body?.toString() || ''; } };
+  createHandler(options)({ url, method, headers: { host: 'localhost:11222', ...headers }, socket: {}, resume() {} }, response);
+  return response;
+}
+
+const localOrigin = { origin: 'http://localhost:11222', 'sec-fetch-site': 'same-origin' };
+
+test('homepage has restrictive policies and compatible resources', () => {
+  const res = request();
+  assert.equal(res.statusCode, 200);
+  const csp = res.headers['content-security-policy'];
+  for (const directive of ["default-src 'none'", "script-src 'none'", "style-src 'self'", "base-uri 'none'", "form-action 'self'", "frame-ancestors 'none'", "require-trusted-types-for 'script'"]) {
+    assert.ok(csp.includes(directive));
+  }
+  assert.doesNotMatch(csp, /unsafe-inline|unsafe-eval|\*/);
+  assert.doesNotMatch(res.body, /<script\b|<style\b|\sstyle\s*=|\son\w+\s*=|javascript:/i);
+  assert.match(res.body, /<form action="\/logout" method="post">/);
+  assert.match(res.body, /<link rel="stylesheet" href="\/styles.css">/);
+  const css = request('/styles.css');
+  assert.equal(css.headers['content-type'], 'text/css; charset=utf-8');
+  assert.match(css.body, /https:\/\/images\.unsplash\.com\//);
+  assert.equal(res.headers['x-content-type-options'], 'nosniff');
+  assert.equal(res.headers['x-frame-options'], 'DENY');
+  assert.equal(res.headers['cache-control'], 'no-store');
+  assert.equal(res.headers['referrer-policy'], 'no-referrer');
+  assert.ok(res.headers['permissions-policy'].includes('camera=()'));
+});
+
+test('all existing navigation targets resolve', () => {
+  const html = fs.readFileSync(path.join(__dirname, '../index.html'), 'utf8');
+  for (const [, url] of html.matchAll(/href="(\/[^" ]*)"/g)) assert.equal(request(url).statusCode, 200, url);
+});
+
+test('GET, HEAD, and prefetch never log a visitor out', () => {
+  for (const method of ['GET', 'HEAD']) {
+    const res = request('/logout', { method, headers: { purpose: 'prefetch' } });
+    assert.equal(res.statusCode, 200);
+    assert.equal(res.headers['clear-site-data'], undefined);
+    assert.equal(res.headers['set-cookie'], undefined);
+    if (method === 'HEAD') assert.equal(res.body, '');
+  }
+});
+
+test('same-origin POST clears site data and expires cookies', () => {
+  const res = request('/logout/', { method: 'POST', headers: { ...localOrigin, cookie: 'session=secret; custom=value; invalid name=value' } });
+  assert.equal(res.statusCode, 200);
+  assert.match(res.body, /Logged out/);
+  assert.equal(res.headers['clear-site-data'], '"cache", "cookies", "storage"');
+  const cookies = res.headers['set-cookie'];
+  assert.ok(cookies.some(cookie => cookie.startsWith('custom=;')));
+  assert.ok(cookies.every(cookie => cookie.includes('Max-Age=0')));
+  assert.ok(cookies.every(cookie => !cookie.includes('secret') && !cookie.includes('invalid name')));
+});
+
+test('logout rejects cross-site, unverified, and speculative POST requests', () => {
+  for (const headers of [{}, { origin: 'https://attacker.example' }, { ...localOrigin, 'sec-fetch-site': 'cross-site' }, { ...localOrigin, purpose: 'prefetch' }, { ...localOrigin, 'sec-purpose': 'prefetch;prerender' }, { origin: 'null' }]) {
+    const res = request('/logout', { method: 'POST', headers });
+    assert.equal(res.statusCode, 403);
+    assert.equal(res.headers['clear-site-data'], undefined);
+    assert.equal(res.headers['set-cookie'], undefined);
+  }
+  assert.equal(request('/logout', { method: 'POST', headers: { 'sec-fetch-site': 'same-origin' } }).statusCode, 200);
+});
+
+test('production origin supports TLS termination without trusting forwarded headers', () => {
+  const options = { publicOrigin: 'https://coffee.example' };
+  const res = request('/logout', { method: 'POST', headers: { origin: 'https://coffee.example', cookie: '__Host-session=secret' }, options });
+  assert.equal(res.statusCode, 200);
+  assert.equal(res.headers['strict-transport-security'], 'max-age=31536000');
+  assert.ok(res.headers['set-cookie'].every(cookie => cookie.endsWith('; Secure')));
+  assert.equal(request('/', { headers: { 'x-forwarded-proto': 'https' } }).headers['strict-transport-security'], undefined);
+});
+
+test('report-only policy is opt-in and origin configuration fails closed', () => {
+  const res = request('/', { options: { reportOnly: true } });
+  assert.ok(res.headers['content-security-policy-report-only']);
+  assert.equal(res.headers['content-security-policy'], undefined);
+  for (const publicOrigin of ['javascript:alert(1)', 'https://user:pass@example.com', 'https://example.com/path']) {
+    assert.throws(() => createHandler({ publicOrigin }));
+  }
+});
+
+test('unknown/private paths, unsupported methods, malformed URLs and HEAD are handled', () => {
+  for (const url of ['/app.js', '/server.js', '/package.json', '/.git/config', '/%2e%2e/server.js', '/missing']) {
+    const res = request(url);
+    assert.equal(res.statusCode, 404, url);
+    assert.ok(res.headers['content-security-policy']);
+  }
+  assert.equal(request('//attacker.example').statusCode, 400);
+  assert.equal(request('/', { method: 'POST' }).statusCode, 405);
+  assert.equal(request('/logout', { method: 'DELETE' }).headers.allow, 'GET, HEAD, POST');
+  assert.equal(request('/', { method: 'HEAD' }).body, '');
+  assert.equal(request('/styles.css', { method: 'HEAD' }).body, '');
+});

