+// Page API: drink-title, description, action-href, action-label, and limited.
+// `limited` is boolean: remove the attribute to hide the badge.
+const drinkCardTemplate = document.createElement('template');
+drinkCardTemplate.innerHTML = `
+  <style>
+    :host {
+      display: block;
+      min-width: 0;
+    }
+
+    * {
+      box-sizing: border-box;
+      margin: 0;
+      padding: 0;
+    }
+
+    article {
+      height: 100%;
+      background: white;
+      padding: 20px;
+      border-radius: 8px;
+      box-shadow: 0 2px 5px rgba(0, 0, 0, 0.1);
+      text-align: center;
+      font: 16px/1.6 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
+      color: #3e2723;
+    }
+
+    h3 {
+      font-size: 1.17em;
+      margin-bottom: 10px;
+      color: #4e342e;
+    }
+
+    .badge {
+      display: inline-block;
+      margin-bottom: 10px;
+      padding: 2px 8px;
+      border-radius: 4px;
+      background: #ffab40;
+      font-size: 0.75rem;
+      font-weight: bold;
+    }
+
+    .badge[hidden] {
+      display: none;
+    }
+
+    a {
+      display: inline-block;
+      background: #4e342e;
+      color: white;
+      padding: 10px 20px;
+      text-decoration: none;
+      border-radius: 5px;
+      margin-top: 15px;
+      transition: background 0.3s;
+    }
+
+    a:hover {
+      background: #3e2723;
+    }
+  </style>
+  <article>
+    <span class="badge" hidden>Limited</span>
+    <h3></h3>
+    <p></p>
+    <a></a>
+  </article>
+`;
+
+class DrinkCard extends HTMLElement {
+  static get observedAttributes() {
+    return ['drink-title', 'description', 'action-href', 'action-label', 'limited'];
+  }
+
+  constructor() {
+    super();
+    this.attachShadow({ mode: 'open' }).append(drinkCardTemplate.content.cloneNode(true));
+  }
+
+  connectedCallback() {
+    this.render();
+  }
+
+  attributeChangedCallback() {
+    this.render();
+  }
+
+  render() {
+    const root = this.shadowRoot;
+    root.querySelector('h3').textContent = this.getAttribute('drink-title') ?? '';
+    root.querySelector('p').textContent = this.getAttribute('description') ?? '';
+    const action = root.querySelector('a');
+    action.textContent = this.getAttribute('action-label') ?? 'View Details';
+    const href = this.getAttribute('action-href');
+    if (href !== null) {
+      action.setAttribute('href', href);
+    } else {
+      action.removeAttribute('href');
+    }
+    root.querySelector('.badge').hidden = !this.hasAttribute('limited');
+  }
+}
+
+customElements.define('drink-card', DrinkCard);
