+(() => {
+  const form = document.getElementById('verification-form');
+  const phone = document.getElementById('phone');
+  const code = document.getElementById('otp');
+  const send = document.getElementById('send-code');
+  const verify = document.getElementById('verify-code');
+  const status = document.getElementById('verification-status');
+  let challenge = null;
+  let smsController = null;
+  let requestController = null;
+  let cooldownTimer = null;
+  let receivedCode = false;
+  let busy = false;
+
+  const purpose = () => form.elements.purpose.value;
+  const normalizedPhone = () => phone.value.replace(/[\s().-]/g, '');
+  function announce(message, error = false) {
+    status.textContent = message;
+    status.dataset.error = String(error);
+  }
+  function stopSms() {
+    smsController?.abort();
+    smsController = null;
+  }
+  function reset() {
+    stopSms();
+    requestController?.abort();
+    requestController = null;
+    clearInterval(cooldownTimer);
+    cooldownTimer = null;
+    challenge = null;
+    receivedCode = false;
+    code.value = '';
+    code.removeAttribute('aria-invalid');
+    send.textContent = 'Send code';
+    send.disabled = false;
+    verify.disabled = false;
+    busy = false;
+    form.removeAttribute('aria-busy');
+    announce('');
+  }
+  async function post(url, payload, controller) {
+    const timeout = setTimeout(() => controller.abort(), 15000);
+    try {
+      const response = await fetch(url, {
+        method: 'POST', credentials: 'same-origin',
+        headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' },
+        body: JSON.stringify(payload), signal: controller.signal,
+      });
+      if (response.status === 429) throw new Error('Too many attempts. Please wait a minute and try again.');
+      if (response.status >= 500 || response.status === 404 || response.status === 405) {
+        throw new Error('SMS sign in is currently unavailable. Please try again later.');
+      }
+      if (!response.ok) throw new Error(url.endsWith('/verify')
+        ? 'That code could not be verified. Check it or request a new code.'
+        : 'We couldn’t send a code. Check your mobile number and try again.');
+      try { return await response.json(); }
+      catch { throw new Error('SMS sign in is currently unavailable. Please try again later.'); }
+    } finally { clearTimeout(timeout); }
+  }
+  function listenForSms() {
+    stopSms();
+    if (!window.isSecureContext || !('OTPCredential' in window) || !navigator.credentials) return;
+    const controller = new AbortController();
+    smsController = controller;
+    const timeout = setTimeout(() => controller.abort(), 60000);
+    navigator.credentials.get({ otp: { transport: ['sms'] }, signal: controller.signal })
+      .then(credential => {
+        if (controller.signal.aborted || !credential || !/^[0-9]{6}$/.test(credential.code)) return;
+        code.value = credential.code;
+        code.removeAttribute('aria-invalid');
+        receivedCode = true;
+        if (challenge && !busy) form.requestSubmit();
+      })
+      .catch(() => { /* Autofill dismissal or unsupported policy: manual entry remains available. */ })
+      .finally(() => clearTimeout(timeout));
+  }
+  function cooldown(seconds) {
+    clearInterval(cooldownTimer);
+    const end = Date.now() + seconds * 1000;
+    function tick() {
+      const remaining = Math.ceil((end - Date.now()) / 1000);
+      send.disabled = remaining > 0;
+      send.textContent = remaining > 0 ? `Resend in ${remaining}s` : 'Resend code';
+      if (remaining <= 0) clearInterval(cooldownTimer);
+    }
+    tick();
+    cooldownTimer = setInterval(tick, 1000);
+  }
+  phone.addEventListener('input', () => {
+    phone.setCustomValidity('');
+    phone.removeAttribute('aria-invalid');
+    reset();
+  });
+  form.querySelectorAll('[name="purpose"]').forEach(radio => radio.addEventListener('change', reset));
+  code.addEventListener('input', () => {
+    code.setCustomValidity('');
+    code.removeAttribute('aria-invalid');
+    receivedCode = false;
+  });
+  code.addEventListener('invalid', () => {
+    stopSms();
+    code.setAttribute('aria-invalid', 'true');
+    announce('Enter the full 6-digit code from your text message.', true);
+  });
+  phone.addEventListener('invalid', () => phone.setAttribute('aria-invalid', 'true'));
