+  send.addEventListener('click', async () => {
+    if (busy) return;
+    const number = normalizedPhone();
+    phone.setCustomValidity(/^\+[1-9][0-9]{6,14}$/.test(number)
+      ? '' : 'Enter a mobile number with its country code, such as +1 202 555 0123.');
+    if (!phone.reportValidity()) return;
+    reset();
+    busy = true;
+    send.disabled = true;
+    verify.disabled = true;
+    form.setAttribute('aria-busy', 'true');
+    send.textContent = 'Sending…';
+    announce('Requesting your verification code…');
+    code.focus();
+    // Listen before requesting the SMS so a fast delivery is not missed.
+    listenForSms();
+    const controller = new AbortController();
+    requestController = controller;
+    try {
+      const result = await post('/api/auth/sms/request', { phone: number, purpose: purpose() }, controller);
+      if (requestController !== controller) return;
+      if (typeof result.challengeId !== 'string' || !result.challengeId) {
+        throw new Error('SMS sign in is currently unavailable. Please try again later.');
+      }
+      challenge = { id: result.challengeId, phone: number, purpose: purpose() };
+      announce(`Code sent to the mobile number ending in ${number.slice(-4)}. Enter it below to continue.`);
+      cooldown(60);
+    } catch (error) {
+      if (requestController !== controller) return;
+      stopSms();
+      send.disabled = false;
+      send.textContent = 'Send code';
+      announce(error.name === 'AbortError' ? 'The request timed out. Please try again.'
+        : error instanceof TypeError ? 'Couldn’t connect. Check your connection and try again.' : error.message, true);
