+  form.addEventListener('submit', async event => {
+    event.preventDefault();
+    stopSms();
+    if (busy) return;
+    if (!challenge) {
+      announce('Request a code with the Send code button first.', true);
+      send.focus();
+      return;
+    }
+    busy = true;
+    verify.disabled = true;
+    form.setAttribute('aria-busy', 'true');
+    announce('Verifying your code…');
+    const controller = new AbortController();
+    requestController = controller;
+    const destination = challenge.purpose === 'order' ? '/order-online' : '/rewards';
+    try {
+      const result = await post(form.action, {
+        challengeId: challenge.id, code: code.value, purpose: challenge.purpose,
+      }, controller);
+      if (requestController !== controller) return;
+      if (result.verified !== true) throw new Error('That code could not be verified. Request a new code and try again.');
+      announce('Verified. Taking you to your next stop…');
+      window.location.assign(destination);
+    } catch (error) {
+      if (requestController !== controller) return;
+      code.setAttribute('aria-invalid', 'true');
+      announce(error.name === 'AbortError' ? 'The request timed out. Please try again.'
+        : error instanceof TypeError ? 'Couldn’t connect. Check your connection and try again.' : error.message, true);
+      code.focus();
+    } finally {
+      if (requestController === controller) {
+        busy = false;
+        verify.disabled = false;
+        form.removeAttribute('aria-busy');
+      }
+    }
+  });
+  document.querySelectorAll('[data-purpose]').forEach(link => {
+    link.addEventListener('click', () => {
+      if (purpose() !== link.dataset.purpose) {
+        reset();
+        form.querySelector(`[name="purpose"][value="${link.dataset.purpose}"]`).checked = true;
+      }
+    });
+  });
