+(() => {
+  'use strict';
+  const $ = (id) => document.getElementById(id);
+  const phoneForm = $('phone-form');
+  const codeForm = $('code-form');
+  const phone = $('phone');
+  const code = $('code');
+  const status = $('form-status');
+  const resend = $('resend');
+  const tabs = [...document.querySelectorAll('.purpose-tabs button')];
+  const apiBase = window.DAILY_GRIND_AUTH?.apiBase?.replace(/\/$/, '');
+  const demo = !apiBase;
+  let purpose = 'rewards';
+  let number = '';
+  let challenge = null;
+  let expiresAt = 0;
+  let resendAt = 0;
+  let busy = false;
+  let stage = 'phone';
+  let otpController;
+  let otpTimer;
+  let cooldownTimer;
+  let demoAttempts = 0;
