+    $('auth-intro').textContent = stage === 'phone' ? 'Your next cup is just a little closer. Sign in or create an account to get started.' : stage === 'code' ? (demo ? `Try the preview with code 123456. No SMS was sent to ${number}.` : `Enter the code we sent to ${number}. It’s good for 5 minutes.`) : '';
+    $('step-label').textContent = stage === 'phone' ? '01 / YOUR DAILY GRIND STARTS HERE' : stage === 'code' ? '02 / A LITTLE SECURITY, THEN COFFEE' : '✓ / READY FOR YOUR NEXT CUP';
