+      if (demo) {
+        demoAttempts += 1;
+        if (demoAttempts > 5) throw new Error('Too many attempts. Request a new preview code.');
+        if (code.value !== '123456') throw new Error('That code doesn’t match. Use 123456 in this preview.');
+      } else {
+        const result = await request('verify', { challengeId: challenge, code: code.value, purpose });
+        if (result.verified !== true) throw new Error('We couldn’t verify that code. Please try again.');
+      }
+      clearInterval(cooldownTimer);
+      code.value = '';
+      challenge = null;
+      setStage('success');
+      renderHeading();
+      updateDestination();
+      announce();
