@@ -0,0 +1,112 @@
+const { test } = require('node:test');
+const assert = require('node:assert/strict');
+const fs = require('node:fs');
+const vm = require('node:vm');
+
+function setup({ live = false, fetch, credentials } = {}) {
+  const elements = new Map();
+  class Element {
+    constructor() { this.value = ''; this.dataset = {}; this.attrs = {}; this.handlers = {}; this.classList = { toggle() {} }; }
+    addEventListener(name, callback) { (this.handlers[name] ||= []).push(callback); }
+    async emit(name) { for (const handler of this.handlers[name] || []) await handler({ preventDefault() {} }); }
+    setAttribute(key, value) { this.attrs[key] = value; }
+    removeAttribute(key) { delete this.attrs[key]; }
+    setCustomValidity(value) { this.validation = value; }
+    reportValidity() { this.reported = true; }
+    focus() { this.focused = true; }
+    querySelector() { return this.span ||= new Element(); }
+    scrollIntoView() {}
+  }
+  const html = fs.readFileSync('index.html', 'utf8');
+  for (const [, id] of html.matchAll(/id="([^"]+)"/g)) {
+    assert.ok(!elements.has(id), `Duplicate id: ${id}`);
+    elements.set(id, new Element());
+  }
+  const $ = (id) => { assert.ok(elements.has(id), `Missing DOM element: ${id}`); return elements.get(id); };
+  const tabs = ['rewards', 'order'].map((purpose) => Object.assign(new Element(), { dataset: { purpose } }));
+  const links = ['rewards', 'order'].map((signIn) => Object.assign(new Element(), { dataset: { signIn } }));
+  let now = Date.now();
+  class TestDate extends Date { static now() { return now; } }
+  const window = { isSecureContext: true, addEventListener() {}, ...(live ? { DAILY_GRIND_AUTH: { apiBase: '/api/auth' }, OTPCredential: {} } : {}) };
+  vm.runInNewContext(fs.readFileSync('auth.js', 'utf8'), {
+    window, document: { getElementById: $, querySelectorAll: (selector) => selector === '.purpose-tabs button' ? tabs : selector === '[data-sign-in]' ? links : [] },
+    navigator: { credentials }, Date: TestDate, AbortController, fetch,
+    setTimeout: () => 1, clearTimeout() {}, setInterval: () => 1, clearInterval() {}, matchMedia: () => ({ matches: true }),
+  });
+  $('country').value = '+1';
+  return { $, tabs, links, advance: (ms) => { now += ms; }, async send() { $('phone').value = '5551234567'; await $('phone-form').emit('submit'); } };
+}
+
+test('preview validates phone, rejects incorrect code, then completes Rewards flow', async () => {
+  const { $, send } = setup();
+  $('phone').value = '123';
+  await $('phone-form').emit('submit');
+  assert.ok($('phone').validation);
+  await send();
+  assert.equal($('code-form').hidden, false);
+  assert.match($('form-status').textContent, /123456/);
+  assert.equal($('resend').disabled, true);
+  $('code').value = '999999';
+  await $('code-form').emit('submit');
+  assert.equal($('code').attrs['aria-invalid'], 'true');
+  $('code').value = '123456';
+  await $('code-form').emit('submit');
+  assert.equal($('success').hidden, false);
+  assert.equal($('continue').href, '/rewards');
+});
+
+test('online order navigation selects order and preserves that destination after verification', async () => {
+  const { $, links, send } = setup();
+  await links[1].emit('click');
+  await send();
+  $('code').value = '123456';
+  await $('code-form').emit('submit');
+  assert.equal($('continue').href, '/order');
+  await $('start-over').emit('click');
+  assert.equal($('phone-form').hidden, false);
+});
+
+test('expired preview cannot verify; resend renews challenge after cooldown', async () => {
+  const { $, send, advance } = setup();
+  await send();
+  advance(300001);
+  $('code').value = '123456';
+  await $('code-form').emit('submit');
+  assert.match($('form-status').textContent, /expired/);
+  await $('resend').emit('click');
+  assert.match($('form-status').textContent, /Preview code/);
+  assert.equal($('code').value, '');
+});
+
+test('live flow extracts SMS code and submits to server before completing sign-in', async () => {
+  const calls = [];
+  let resolveOtp;
+  let signal;
+  const { $, send } = setup({ live: true,
+    credentials: { get: (options) => { signal = options.signal; return new Promise((resolve) => { resolveOtp = resolve; }); } },
+    fetch: async (url, options) => {
+      calls.push({ url, payload: JSON.parse(options.body) });
+      return { ok: true, json: async () => url.endsWith('/send') ? { challengeId: 'challenge-1' } : { verified: true } };
+    },
+  });
+  await send();
+  resolveOtp({ code: '654321' });
+  await Promise.resolve();
+  await Promise.resolve();
+  assert.equal($('code').value, '654321');
+  assert.equal($('success').hidden, true);
+  await $('code-form').emit('submit');
+  assert.equal(signal.aborted, true);
+  assert.equal(calls[0].payload.phone, '+15551234567');
+  assert.equal(calls[1].payload.challengeId, 'challenge-1');
+  assert.equal(calls[1].payload.code, '654321');
+  assert.equal($('success').hidden, false);
+});
+
+test('live service failure stays on phone entry and allows retry', async () => {
+  const { $, send } = setup({ live: true, credentials: { get: async () => null }, fetch: async () => ({ ok: false, json: async () => ({ error: 'RATE_LIMITED' }) }) });
+  await send();
+  assert.match($('form-status').textContent, /Too many attempts/);
+  assert.notEqual($('phone-form').hidden, true);
+  assert.equal($('phone').disabled, false);
+});
