+import { createHash, randomInt, randomUUID, timingSafeEqual } from 'node:crypto';
+
+type Session = {
+  get(key: string): Promise<unknown>;
+  set(key: string, value: unknown): void;
+  delete(key: string): void;
+};
+type Challenge = {
+  phone: string;
+  digest: string;
+  expiresAt: number;
+  attempts: number;
+  verified: boolean;
+  busy: boolean;
+};
+const challenges = new Map<string, Challenge>();
+const limits = new Map<string, { count: number; resetAt: number; nextAt: number }>();
+const lifetime = 10 * 60 * 1000;
+const registerURL = 'https://us-central1-web-devrel-apps.cloudfunctions.net/times_cdn/api/register';
+const hash = (value: string) => createHash('sha256').update(value).digest('hex');
+const json = (body: object, status = 200) => new Response(JSON.stringify(body), {
+  status,
+  headers: { 'Content-Type': 'application/json', 'Cache-Control': 'no-store' },
+});
+
+// This store is atomic within the standalone Node process. See README for scaling.
+function prune(now: number) {
+  for (const [id, challenge] of challenges) if (challenge.expiresAt <= now && !challenge.busy) challenges.delete(id);
+  for (const [key, limit] of limits) if (limit.resetAt <= now) limits.delete(key);
+}
+
+export async function handleSignup(request: Request, session: Session | undefined, clientAddress: string): Promise<Response> {
+  const { TWILIO_ACCOUNT_SID: account, TWILIO_AUTH_TOKEN: token, TWILIO_MESSAGING_SERVICE_SID: service, SMS_ORIGIN: origin } = process.env;
+  if (!session || !account || !token || !service || !origin) {
+    return json({ error: 'SMS verification is unavailable. Please try again later.' }, 503);
+  }
+  let site: URL;
+  try { site = new URL(origin); } catch { return json({ error: 'SMS verification is unavailable.' }, 503); }
+  if ((site.protocol !== 'https:' && !(site.protocol === 'http:' && site.hostname === 'localhost')) || site.origin !== origin) {
+    return json({ error: 'SMS verification is unavailable.' }, 503);
+  }
+  // The project disables Astro's global origin check. Require same-origin JSON here.
+  if (request.headers.get('Origin') !== site.origin || !request.headers.get('Content-Type')?.startsWith('application/json')) {
+    return json({ error: 'Please submit this form from the sign-up page.' }, 403);
+  }
+  let body: Record<string, unknown>;
+  try {
+    const raw = await request.text();
+    if (raw.length > 8192) return json({ error: 'The form is too large.' }, 413);
+    body = JSON.parse(raw);
+    if (!body || typeof body !== 'object' || Array.isArray(body)) throw new Error();
+  } catch { return json({ error: 'Invalid form data.' }, 400); }
+  const phone = typeof body.phone === 'string' ? body.phone.replace(/[ ()-]/g, '') : '';
+  if (!/^\+[1-9][0-9]{6,14}$/.test(phone)) {
+    return json({ error: 'Enter a valid phone number with + and your country code.', field: 'phone' }, 400);
+  }
+  const now = Date.now();
+  prune(now);
+  const existingId = await session.get('signupChallenge');
+  const existing = typeof existingId === 'string' ? challenges.get(existingId) : undefined;
+  if (existing?.busy) return json({ error: 'A request is already in progress. Please wait.' }, 409);
+
+  if (body.action === 'send') {
+    const keys = [`phone:${hash(phone)}`, `ip:${hash(clientAddress)}`];
+    for (const key of keys) {
+      const limit = limits.get(key);
+      if (limit && (limit.nextAt > now || limit.count >= (key.startsWith('phone:') ? 5 : 20))) {
+        const retryAfter = Math.ceil(((limit.count >= (key.startsWith('phone:') ? 5 : 20) ? limit.resetAt : limit.nextAt) - now) / 1000);
+        return json({ error: 'Please wait before requesting another code.', retryAfter }, 429);
+      }
+    }
+    if (challenges.size >= 10000 || limits.size >= 20000) {
+      return json({ error: 'SMS verification is busy. Please try again later.' }, 503);
+    }
+    for (const key of keys) {
+      const previous = limits.get(key);
+      limits.set(key, {
+        count: (previous?.count ?? 0) + 1,
+        resetAt: previous?.resetAt ?? now + 60 * 60 * 1000,
+        nextAt: now + (key.startsWith('phone:') ? 60000 : 1000),
+      });
+    }
+    const id = randomUUID();
+    const code = randomInt(0, 1000000).toString().padStart(6, '0');
+    const challenge: Challenge = { phone, digest: hash(`${id}:${code}`), expiresAt: now + lifetime, attempts: 0, verified: false, busy: true };
+    if (typeof existingId === 'string') challenges.delete(existingId);
+    challenges.set(id, challenge);
+    session.set('signupChallenge', id);
+    try {
+      const response = await fetch(`https://api.twilio.com/2010-04-01/Accounts/${encodeURIComponent(account)}/Messages.json`, {
+        method: 'POST',
+        headers: {
+          Authorization: `Basic ${Buffer.from(`${account}:${token}`).toString('base64')}`,
+          'Content-Type': 'application/x-www-form-urlencoded',
+        },
+        body: new URLSearchParams({
+          To: phone,
+          MessagingServiceSid: service,
+          Body: `Your DevTools Times verification code is ${code}. It expires in 10 minutes.\n\n@${site.hostname} #${code}`,
+        }),
+        signal: AbortSignal.timeout(15000),
+      });
+      const delivery = await response.json();
+      if (!response.ok || delivery.status === 'failed' || delivery.status === 'undelivered') throw new Error();
+      challenge.busy = false;
+      return json({ phone, retryAfter: 60 });
+    } catch {
+      challenges.delete(id);
+      session.delete('signupChallenge');
+      return json({ error: 'We could not send your text message. Check your number and try again in a minute.', retryAfter: 60 }, 502);
+    }
+  }
+
+  if (body.action !== 'register') return json({ error: 'Invalid sign-up action.' }, 400);
+  const { username, password, code } = body;
+  if (typeof username !== 'string' || !username.trim() || username.length > 100 ||
+      typeof password !== 'string' || password.length < 8 || password.length > 1024 || !/[0-9]/.test(password)) {
+    return json({ error: 'Check your username and password. Use at least 8 password characters, including a number.' }, 400);
+  }
+  if (!existing || existing.phone !== phone || existing.expiresAt <= now) {
+    return json({ error: 'Your verification has expired or the phone number changed. Please request a new code.', field: 'code' }, 400);
+  }
+  if (!existing.verified) {
+    if (existing.attempts >= 5) return json({ error: 'Too many incorrect attempts. Please request a new code.', field: 'code' }, 429);
+    existing.attempts += 1;
+    if (typeof code !== 'string' || !/^[0-9]{6}$/.test(code) ||
+        !timingSafeEqual(Buffer.from(existing.digest, 'hex'), Buffer.from(hash(`${existingId}:${code}`), 'hex'))) {
+      return json({ error: 'That code is incorrect. Enter the 6-digit code from your latest text message.', field: 'code' }, 400);
+    }
+    // Consume the code once, retaining verification only for registration retries.
+    existing.verified = true;
+    existing.digest = '';
+  }
+  existing.busy = true;
+  try {
+    const response = await fetch(registerURL, {
+      method: 'POST',
+      headers: { 'Content-Type': 'application/json' },
+      body: JSON.stringify({ username: username.trim(), password, phoneNumber: existing.phone }),
+      signal: AbortSignal.timeout(15000),
+    });
+    if (!response.ok) {
+      return json({ error: 'Registration failed. Change your account details or try again.' }, response.status >= 500 ? 502 : 400);
+    }
+    challenges.delete(existingId as string);
+    session.delete('signupChallenge');
+    return json({ success: true });
+  } catch {
+    return json({ error: 'We could not create your account. Please try again.' }, 502);
+  } finally { existing.busy = false; }
+}
