+  const id = ++sequence;
+  const values = new Map();
+  const session = { get: async (key) => values.get(key), set: (key, value) => values.set(key, value), delete: (key) => values.delete(key) };
+  const phone = `+1202555${String(id).padStart(4, '0')}`;
+  const send = (body, headers = {}) => handleSignup(new Request('https://news.example/devtools-times/api/signup', {
+    method: 'POST', headers: { 'Content-Type': 'application/json', Origin: 'https://news.example', ...headers }, body: JSON.stringify(body),
+  }), session, `192.0.2.${id}`);
+  const register = (code, extra = {}) => send({ action: 'register', phone, username: 'reader', password: 'password1', code, ...extra });
+  return { session, phone, send, register };
+}
+async function withProvider(run) {
+  const original = globalThis.fetch;
+  const calls = [];
+  globalThis.fetch = async (url, options) => {
+    calls.push({ url: String(url), options });
+    return Response.json(String(url).includes('twilio.com') ? { status: 'queued' } : { success: true });
+  };
+  try { await run(calls); } finally { globalThis.fetch = original; }
