+  await withProvider(async (calls) => {
+    const f = fixture();
+    const response = await f.send({ action: 'send', phone: f.phone.replace('+1', '+1 ') });
+    assert.equal(response.status, 200);
+    assert.deepEqual(await response.json(), { phone: f.phone, retryAfter: 60 });
+    const payload = new URLSearchParams(calls[0].options.body);
+    assert.equal(payload.get('To'), f.phone);
+    assert.match(payload.get('Body'), /\n\n@news\.example #[0-9]{6}$/);
