--- /dev/null
+++ b/src/lib/phone-verification.ts
@@ -0,0 +1,60 @@
+const phonePattern = /^\+[1-9]\d{7,14}$/;
+
+export function normalizePhone(value: unknown): string | null {
+  if (typeof value !== 'string') return null;
+  const phone = value.replace(/[\s().-]/g, '');
+  return phonePattern.test(phone) ? phone : null;
+}
+
+export function validPassword(value: unknown): value is string {
+  return typeof value === 'string' && value.length >= 8 && /\d/.test(value);
+}
+
+export type SmsConfig = {
+  accountSid: string;
+  authToken: string;
+  serviceSid: string;
+};
+
+export class VerificationError extends Error {
+  status: number;
+  constructor(message: string, status = 400) {
+    super(message);
+    this.status = status;
+  }
+}
+
+export async function verifyRequest(
+  config: SmsConfig,
+  resource: 'Verifications' | 'VerificationCheck',
+  fields: Record<string, string>,
+  request: typeof fetch = fetch,
+) {
+  const response = await request(
+    `https://verify.twilio.com/v2/Services/${encodeURIComponent(config.serviceSid)}/${resource}`,
+    {
+      method: 'POST',
+      headers: {
+        Authorization: `Basic ${Buffer.from(`${config.accountSid}:${config.authToken}`).toString('base64')}`,
+        'Content-Type': 'application/x-www-form-urlencoded',
+      },
+      body: new URLSearchParams(fields),
+      signal: AbortSignal.timeout(15000),
+    },
+  );
+  if (response.status === 429) {
+    throw new VerificationError('Too many attempts. Please wait a few minutes before trying again.', 429);
+  }
+  if (response.status === 404 && resource === 'VerificationCheck') {
+    throw new VerificationError('This code has expired. Request another code.');
+  }
+  if (!response.ok) {
+    throw new VerificationError(
+      resource === 'Verifications'
+        ? 'We could not send a text to this number. Check the number or try again later.'
+        : 'We could not verify this code. Check it or request another code.',
+      response.status >= 500 || response.status === 401 ? 503 : 400,
+    );
+  }
+  return response.json() as Promise<{ status: string }>;
+}
