+  status,
+  headers: { 'Content-Type': 'application/json', 'Cache-Control': 'no-store' },
+});
+
+export const POST: APIRoute = async ({ request, url }) => {
+  // This endpoint sends paid SMS messages; do not allow cross-origin form posts.
+  if (request.headers.get('origin') !== url.origin) {
+    return reply({ error: 'Please submit the form from this website.' }, 403);
+  }
+  if (!request.headers.get('content-type')?.includes('application/json')) {
+    return reply({ error: 'Expected a JSON request.' }, 415);
+  }
+
+  let codeApproved = false;
+  try {
+    const body = await request.json();
+    const phoneNumber = normalizePhone(body?.phoneNumber);
+    if (!phoneNumber) {
+      return reply({ error: 'Enter a phone number with its country code, for example +1 202 555 0123.' }, 400);
+    }
+    if (body.action !== 'send' && body.action !== 'register') {
+      return reply({ error: 'Invalid sign-up action.' }, 400);
+    }
+    if (body.action === 'register' && (
+      typeof body.username !== 'string' || !body.username.trim() || body.username.length > 100 ||
+      !validPassword(body.password) || typeof body.code !== 'string' || !/^\d{6}$/.test(body.code)
+    )) {
+      return reply({ error: 'Enter a username, a password with at least 8 characters and a number, and a 6-digit code.' }, 400);
+    }
+
+    const config = {
+      accountSid: process.env.TWILIO_ACCOUNT_SID || '',
+      authToken: process.env.TWILIO_AUTH_TOKEN || '',
+      serviceSid: process.env.TWILIO_VERIFY_SERVICE_SID || '',
+    };
+    if (!config.accountSid || !config.authToken || !config.serviceSid) {
+      return reply({ error: 'SMS verification is currently unavailable. Please try again later.' }, 503);
+    }
+
+    if (body.action === 'send') {
+      const fields: Record<string, string> = { To: phoneNumber, Channel: 'sms' };
+      if (process.env.TWILIO_VERIFY_TEMPLATE_SID) fields.TemplateSid = process.env.TWILIO_VERIFY_TEMPLATE_SID;
+      const result = await verifyRequest(config, 'Verifications', fields);
+      if (result.status !== 'pending') throw new VerificationError('We could not send a code. Please try again.', 503);
+      return reply({ message: 'Verification code sent.' });
+    }
+
+    const result = await verifyRequest(config, 'VerificationCheck', { To: phoneNumber, Code: body.code });
+    if (result.status !== 'approved') {
+      return reply({ error: 'That code is incorrect or expired. Try again or request another code.' }, 400);
+    }
+    codeApproved = true;
+    // Never trust a client-side "verified" flag. Registration follows provider approval only.
+    const response = await fetch(registerUrl, {
+      method: 'POST',
+      headers: { 'Content-Type': 'application/json' },
+      body: JSON.stringify({ username: body.username.trim(), password: body.password, phoneNumber }),
+      signal: AbortSignal.timeout(15000),
+    });
+    if (!response.ok) {
+      return reply({
+        error: 'Registration could not be completed. Check your account details and request a new code before trying again.',
+        requiresNewCode: true,
+      }, response.status >= 500 ? 502 : 400);
+    }
+    return reply({ message: 'Your phone number is verified and your account has been created.' });
+  } catch (error) {
+    if (error instanceof SyntaxError) return reply({ error: 'Invalid request.' }, 400);
+    if (error instanceof VerificationError) return reply({ error: error.message }, error.status);
+    return reply({
+      error: codeApproved
+        ? 'Registration was interrupted. If your account was not created, request a new code before trying again.'
+        : 'The verification service could not be reached. Please try again.',
+      requiresNewCode: codeApproved,
+    }, 503);
+  }
+};
diff --git a/tests/signup.test.mjs b/tests/signup.test.mjs
new file mode 100644
