@@ -0,0 +1,145 @@
+import assert from 'node:assert/strict';
+import { test, afterEach } from 'node:test';
+import { POST } from '../src/pages/api/signup.ts';
+import { normalizePhone, validPassword } from '../src/lib/phone-verification.ts';
+
+const originalFetch = globalThis.fetch;
+const envKeys = ['TWILIO_ACCOUNT_SID', 'TWILIO_AUTH_TOKEN', 'TWILIO_VERIFY_SERVICE_SID', 'TWILIO_VERIFY_TEMPLATE_SID'];
+const originalEnv = Object.fromEntries(envKeys.map((key) => [key, process.env[key]]));
+afterEach(() => {
+  globalThis.fetch = originalFetch;
+  for (const key of envKeys) {
+    if (originalEnv[key] === undefined) delete process.env[key];
+    else process.env[key] = originalEnv[key];
+  }
+});
+
+function config() {
+  process.env.TWILIO_ACCOUNT_SID = 'ACtest';
+  process.env.TWILIO_AUTH_TOKEN = 'secret';
+  process.env.TWILIO_VERIFY_SERVICE_SID = 'VAtest';
+  delete process.env.TWILIO_VERIFY_TEMPLATE_SID;
+}
+const details = { action: 'register', username: 'reader', password: 'password1', phoneNumber: '+1 (202) 555-0123', code: '123456' };
+async function post(body, origin = 'https://example.com') {
+  const url = new URL('https://example.com/devtools-times/api/signup');
+  const request = new Request(url, {
+    method: 'POST', headers: { origin, 'Content-Type': 'application/json' },
+    body: typeof body === 'string' ? body : JSON.stringify(body),
+  });
+  const response = await POST({ request, url });
+  return { status: response.status, body: await response.json(), headers: response.headers };
+}
+function mockResponses(...responses) {
+  const calls = [];
+  globalThis.fetch = async (url, options) => {
+    calls.push({ url, options });
+    assert.ok(responses.length, 'Unexpected external request');
+    const response = responses.shift();
+    if (response instanceof Error) throw response;
+    return new Response(JSON.stringify(response.body), { status: response.status ?? 200 });
+  };
+  return calls;
+}
+
+test('normalizes international numbers and rejects missing country codes', () => {
+  assert.equal(normalizePhone('+1 (202) 555-0123'), '+12025550123');
+  for (const value of ['2025550123', '+0123456789', '+123', '+1234567890123456', '+1letters5550123', null]) {
+    assert.equal(normalizePhone(value), null);
+  }
+  assert.equal(validPassword('password1'), true);
+  assert.equal(validPassword('password'), false);
+  assert.equal(validPassword('short1'), false);
+});
+
+test('rejects cross-origin posts and malformed requests without external calls', async () => {
+  const calls = mockResponses();
+  assert.equal((await post(details, 'https://attacker.example')).status, 403);
+  assert.equal((await post('{')).status, 400);
+  assert.equal((await post(null)).status, 400);
+  assert.equal((await post({ ...details, action: 'other' })).status, 400);
+  assert.equal(calls.length, 0);
+});
+
+test('rejects invalid credentials and codes on the server', async () => {
+  config();
+  const calls = mockResponses();
+  for (const patch of [{ phoneNumber: '123' }, { username: ' ' }, { password: 'short' }, { code: '12345' }, { code: '12e456' }]) {
+    assert.equal((await post({ ...details, ...patch })).status, 400);
+  }
+  assert.equal(calls.length, 0);
+});
+
+test('missing configuration fails closed', async () => {
+  for (const key of envKeys) delete process.env[key];
+  const calls = mockResponses();
+  assert.equal((await post({ action: 'send', phoneNumber: details.phoneNumber })).status, 503);
+  assert.equal(calls.length, 0);
+});
+
+test('send uses SMS, normalized phone and optional origin-bound template', async () => {
+  config();
+  process.env.TWILIO_VERIFY_TEMPLATE_SID = 'HJtest';
+  const calls = mockResponses({ body: { status: 'pending' } });
+  const result = await post({ action: 'send', phoneNumber: details.phoneNumber });
+  assert.equal(result.status, 200);
+  assert.equal(result.headers.get('Cache-Control'), 'no-store');
+  assert.equal(calls.length, 1);
+  assert.match(calls[0].url, /\/Verifications$/);
+  assert.equal(calls[0].options.body.get('To'), '+12025550123');
+  assert.equal(calls[0].options.body.get('Channel'), 'sms');
+  assert.equal(calls[0].options.body.get('TemplateSid'), 'HJtest');
+  assert.equal(calls[0].options.headers.Authorization, `Basic ${Buffer.from('ACtest:secret').toString('base64')}`);
+});
+
+test('invalid and expired codes never reach registration', async () => {
+  config();
+  for (const response of [{ body: { status: 'pending' } }, { status: 404, body: {} }]) {
+    const calls = mockResponses(response);
+    const result = await post(details);
+    assert.equal(result.status, 400);
+    assert.equal(calls.length, 1);
+    assert.match(calls[0].url, /\/VerificationCheck$/);
+  }
+});
+
+test('approved code is checked before registering with the verified number', async () => {
+  config();
+  const calls = mockResponses({ body: { status: 'approved' } }, { body: {} });
+  const result = await post(details);
+  assert.equal(result.status, 200);
+  assert.equal(calls.length, 2);
+  assert.equal(calls[0].options.body.get('Code'), '123456');
+  assert.deepEqual(JSON.parse(calls[1].options.body), {
+    username: 'reader', password: 'password1', phoneNumber: '+12025550123',
+  });
+});
+
+test('rate limits and provider errors do not leak provider internals', async () => {
+  config();
+  for (const [status, expected] of [[429, 429], [401, 503], [500, 503]]) {
+    const calls = mockResponses({ status, body: { message: 'secret provider details' } });
+    const result = await post({ action: 'send', phoneNumber: details.phoneNumber });
+    assert.equal(result.status, expected);
+    assert.ok(!result.body.error.includes('secret'));
+    assert.equal(calls.length, 1);
+  }
+});
+
+test('registration failure after approval explicitly requires a fresh code', async () => {
+  config();
+  mockResponses({ body: { status: 'approved' } }, { status: 409, body: {} });
+  const result = await post(details);
+  assert.equal(result.status, 400);
+  assert.equal(result.body.requiresNewCode, true);
+});
+
+test('network errors fail safely before and after verification', async () => {
+  config();
+  mockResponses(new Error('network'));
+  assert.equal((await post(details)).status, 503);
+  mockResponses({ body: { status: 'approved' } }, new Error('network'));
+  const result = await post(details);
+  assert.equal(result.status, 503);
+  assert.equal(result.body.requiresNewCode, true);
+});

