index 0000000..1f3783e
--- /dev/null
+++ b/spatial-navigation.mjs
@@ -0,0 +1,86 @@
+const directions = {
+  ArrowRight: ['left', 'right', 'top', 'bottom'],
+  ArrowLeft: ['right', 'left', 'top', 'bottom'],
+  ArrowDown: ['top', 'bottom', 'left', 'right'],
+  ArrowUp: ['bottom', 'top', 'left', 'right'],
+};
+
+// Read geometry per keypress: column counts, flex order and RTL can all change.
+export function findSpatialTarget(current, candidates, key) {
+  const axes = directions[key];
+  if (!axes) return;
+  const [near, far, crossStart, crossEnd] = axes;
+  const sign = key === 'ArrowLeft' || key === 'ArrowUp' ? -1 : 1;
+  let best;
+  let bestRank;
+
+  for (const candidate of candidates) {
+    const rect = candidate.rect;
+    const gap = sign * (rect[near] - current[far]);
+    if (gap < -1) continue; // Allow subpixel rounding, never centre-based direction tests.
+    const overlap = Math.min(rect[crossEnd], current[crossEnd])
+      - Math.max(rect[crossStart], current[crossStart]);
+    const offset = Math.abs((rect[crossStart] + rect[crossEnd]
+      - current[crossStart] - current[crossEnd]) / 2);
+    const rank = overlap > 0
+      ? [0, Math.max(0, gap), offset]
+      : [1, Math.max(0, gap) + 2 * offset, offset];
+    if (!bestRank || rank[0] < bestRank[0]
+      || (rank[0] === bestRank[0] && (rank[1] < bestRank[1]
+        || (rank[1] === bestRank[1] && rank[2] < bestRank[2])))) {
+      best = candidate.element;
+      bestRank = rank;
+    }
+  }
+  return best;
+}
+
+export function setupSpatialGrid(grid) {
+  // Enhance progressively: all links remain normal Tab stops without JavaScript.
+  const links = [...grid.querySelectorAll('.card > a[href]')];
+  if (!links.length) return;
+  grid.setAttribute('role', 'grid');
+  grid.setAttribute('aria-labelledby', 'favorites-heading');
+  grid.setAttribute('aria-describedby', 'favorites-help');
+  grid.querySelector('.grid-row').setAttribute('role', 'row');
+  grid.querySelectorAll('.card').forEach((card) => card.setAttribute('role', 'gridcell'));
+  grid.ownerDocument.getElementById('favorites-help').hidden = false;
+
+  function setActive(active) {
+    links.forEach((link) => { link.tabIndex = link === active ? 0 : -1; });
+  }
+
+  setActive(links[0]);
+  grid.addEventListener('focusin', (event) => {
+    const target = event.composedPath()[0];
+    if (links.includes(target)) setActive(target);
+  });
+
+  grid.addEventListener('keydown', (event) => {
+    if (!Object.hasOwn(directions, event.key) || event.defaultPrevented
+      || event.isComposing || event.altKey || event.ctrlKey || event.metaKey || event.shiftKey) return;
+    const target = event.composedPath()[0];
+    if (!links.includes(target)
+      || target.matches(':read-write, select, input, textarea, [role="slider"], [role="spinbutton"], [role="combobox"]')) return;
+
+    const candidates = links.filter((link) => {
+      if (link.closest('[hidden], [inert], [aria-hidden="true"]') || link.matches(':disabled')) return false;
+      if (typeof link.checkVisibility === 'function') {
+        return link.checkVisibility({ visibilityProperty: true, opacityProperty: true });
+      }
+      // Fallback for browsers without checkVisibility().
+      const style = grid.ownerDocument.defaultView.getComputedStyle(link);
+      return link.getClientRects().length > 0 && style.visibility === 'visible' && style.opacity !== '0';
+    }).map((element) => ({ element, rect: element.getBoundingClientRect() }))
+      .filter(({ rect }) => rect.width > 0 && rect.height > 0);
+    const current = candidates.find(({ element }) => element === target);
+    if (!current) return;
+    const next = findSpatialTarget(current.rect, candidates.filter(({ element }) => element !== target), event.key);
+    if (!next) return; // Preserve native scrolling at the widget boundary.
+
+    event.preventDefault();
+    setActive(next);
+    next.focus({ preventScroll: true });
+    next.scrollIntoView({ block: 'nearest', inline: 'nearest' });
+  });
+}
