new file mode 100644
index 0000000..d3197d0
--- /dev/null
+++ b/spatial-navigation.test.mjs
@@ -0,0 +1,114 @@
+import assert from 'node:assert/strict';
+import { test } from 'node:test';
+import { findSpatialTarget, setupSpatialGrid } from './spatial-navigation.mjs';
+
+const rect = (left, top, width = 100, height = 60) => ({
+  left, top, right: left + width, bottom: top + height, width, height,
+});
+const candidate = (element, ...geometry) => ({ element, rect: rect(...geometry) });
+
+test('navigation follows physical positions in all four directions, independent of DOM order', () => {
+  const current = rect(120, 80);
+  const candidates = [candidate('below', 120, 160), candidate('left', 0, 80),
+    candidate('above', 120, 0), candidate('right', 240, 80)];
+  for (const [key, expected] of Object.entries({
+    ArrowLeft: 'left', ArrowRight: 'right', ArrowUp: 'above', ArrowDown: 'below',
+  })) assert.equal(findSpatialTarget(current, candidates, key), expected);
+});
+
+test('wrapped rows and single columns work without index arithmetic or edge wrapping', () => {
+  assert.equal(findSpatialTarget(rect(120, 0), [candidate('next-row', 0, 80)], 'ArrowRight'), undefined);
+  assert.equal(findSpatialTarget(rect(120, 0), [candidate('next-row', 0, 80)], 'ArrowDown'), 'next-row');
+  assert.equal(findSpatialTarget(rect(0, 0), [candidate('below', 0, 80)], 'ArrowDown'), 'below');
+  assert.equal(findSpatialTarget(rect(0, 0), [candidate('below', 0, 80)], 'ArrowRight'), undefined);
+});
+
+test('overlapping wide cards are excluded by edges even if their centres lie in the direction', () => {
+  assert.equal(findSpatialTarget(rect(100, 0), [candidate('overlap', 150, 0, 300),
+    candidate('right', 220, 0)], 'ArrowRight'), 'right');
+});
+
+test('aligned candidates win before diagonal scoring, then nearest gap and centre break ties', () => {
+  const current = rect(0, 0);
+  assert.equal(findSpatialTarget(current, [candidate('diagonal', 105, 70),
+    candidate('aligned', 250, 0)], 'ArrowRight'), 'aligned');
+  assert.equal(findSpatialTarget(current, [candidate('far', 250, 0),
+    candidate('offset', 120, 20), candidate('nearest', 120, 0)], 'ArrowRight'), 'nearest');
+  assert.equal(findSpatialTarget(current, [candidate('far-diagonal', 120, 240),
+    candidate('near-diagonal', 140, 80)], 'ArrowRight'), 'near-diagonal');
+});
+
+function fixture() {
+  const handlers = {};
+  const help = { hidden: true };
+  const links = [0, 120, 240].map((left) => ({
+    rect: rect(left, 0), visible: true, tabIndex: 0,
+    matches() { return false; },
+    closest() { return null; },
+    checkVisibility() { return this.visible; },
+    getBoundingClientRect() { return this.rect; },
+    focus(options) { this.focusOptions = options; this.focused = true; },
+    scrollIntoView(options) { this.scrollOptions = options; },
+  }));
+  const attributes = {};
+  const grid = {
+    ownerDocument: { getElementById: () => help },
+    setAttribute(name, value) { attributes[name] = value; },
+    querySelectorAll(selector) { return selector === '.card' ? links.map(() => ({ setAttribute() {} })) : links; },
+    querySelector() { return { setAttribute() {} }; },
+    addEventListener(name, handler) { handlers[name] = handler; },
+  };
+  setupSpatialGrid(grid);
+  const press = (target, key, extra = {}) => {
+    const event = { key, composedPath: () => [target],
+      preventDefault() { this.defaultPrevented = true; }, ...extra };
+    handlers.keydown(event);
+    return event;
+  };
+  return { links, handlers, attributes, help, press };
+}
+
+test('grid has one Tab stop, remembers pointer focus, and scrolls the arrow target into view', () => {
+  const { links, handlers, attributes, help, press } = fixture();
+  assert.equal(attributes.role, 'grid');
+  assert.equal(help.hidden, false);
+  assert.deepEqual(links.map((link) => link.tabIndex), [0, -1, -1]);
+  assert.equal(press(links[0], 'ArrowRight').defaultPrevented, true);
+  assert.deepEqual(links.map((link) => link.tabIndex), [-1, 0, -1]);
+  assert.equal(links[1].focused, true);
+  assert.deepEqual(links[1].focusOptions, { preventScroll: true });
+  assert.deepEqual(links[1].scrollOptions, { block: 'nearest', inline: 'nearest' });
+  handlers.focusin({ composedPath: () => [links[2]] });
+  assert.deepEqual(links.map((link) => link.tabIndex), [-1, -1, 0]);
+});
+
+test('keypress reads fresh geometry after reflow and skips hidden or zero-sized links', () => {
+  const { links, press } = fixture();
+  links[1].visible = false;
+  press(links[0], 'ArrowRight');
+  assert.equal(links[2].focused, true);
+  links[1].visible = true;
+  links[1].rect = rect(0, 80);
+  links[2].rect = rect(0, 160);
+  press(links[0], 'ArrowDown');
+  assert.equal(links[1].focused, true);
+  links[1].rect = rect(0, 80, 0, 0);
+  links[2].focused = false;
+  press(links[0], 'ArrowDown');
+  assert.equal(links[2].focused, true);
+});
+
+test('boundaries, Tab, activation, modifiers, nested controls and consumed events stay native', () => {
+  const { links, press } = fixture();
+  for (const key of ['ArrowLeft', 'ArrowUp', 'ArrowDown', 'Tab', 'Enter', ' ']) {
+    assert.equal(press(links[0], key).defaultPrevented, undefined);
+  }
+  for (const modifier of ['altKey', 'ctrlKey', 'metaKey', 'shiftKey', 'isComposing']) {
+    assert.equal(press(links[0], 'ArrowRight', { [modifier]: true }).defaultPrevented, undefined);
+  }
+  press(links[0], 'ArrowRight', { defaultPrevented: true });
+  press({}, 'ArrowRight');
+  links[0].matches = () => true;
+  assert.equal(press(links[0], 'ArrowRight').defaultPrevented, undefined);
+  assert.equal(links[1].focused, undefined);
+});

