@@ -0,0 +1,52 @@
+// Measure on every key press so responsive layouts, CSS ordering, and resizing
+// all use the positions currently visible to the user.
+document.querySelectorAll('.grid').forEach((grid) => {
+  grid.addEventListener('keydown', (event) => {
+    if (event.defaultPrevented || event.altKey || event.ctrlKey || event.metaKey || event.shiftKey) return;
+
+    const directions = {
+      ArrowLeft: ['left', 'right', 'top', 'bottom', -1],
+      ArrowRight: ['left', 'right', 'top', 'bottom', 1],
+      ArrowUp: ['top', 'bottom', 'left', 'right', -1],
+      ArrowDown: ['top', 'bottom', 'left', 'right', 1],
+    };
+    const direction = directions[event.key];
+    if (!direction) return;
+
+    const currentLink = event.target.closest('.card > a.btn');
+    if (!currentLink || currentLink !== event.target || currentLink.closest('.grid') !== grid) return;
+
+    const [start, end, crossStart, crossEnd, sign] = direction;
+    const current = currentLink.parentElement.getBoundingClientRect();
+    let nextLink = null;
+    let bestScore = [Infinity, Infinity];
+
+    grid.querySelectorAll('.card > a.btn').forEach((link) => {
+      if (link === currentLink || link.closest('.grid') !== grid || link.tabIndex < 0 ||
+          link.closest('[hidden], [inert]') || !link.getClientRects().length ||
+          getComputedStyle(link).visibility !== 'visible') return;
+
+      const rect = link.parentElement.getBoundingClientRect();
+      // Only consider cards beyond the facing edge; uneven heights in the same
+      // row must not make Up/Down jump sideways. Allow subpixel rounding.
+      const forwardGap = sign > 0 ? rect[start] - current[end] : current[start] - rect[end];
+      const forwardDistance = sign * ((rect[start] + rect[end] - current[start] - current[end]) / 2);
+      if (forwardGap < -1 || forwardDistance <= 0) return;
+
+      const crossGap = Math.max(0, rect[crossStart] - current[crossEnd], current[crossStart] - rect[crossEnd]);
+      const crossDistance = Math.abs((rect[crossStart] + rect[crossEnd] - current[crossStart] - current[crossEnd]) / 2);
+      // Prefer the same visual row/column, then the nearest center. At an edge
+      // keep focus in place instead of wrapping to an unrelated row.
+      const score = [crossGap === 0 ? 0 : 1, Math.hypot(forwardDistance, crossDistance)];
+      if (score[0] < bestScore[0] || (score[0] === bestScore[0] && score[1] < bestScore[1])) {
+        bestScore = score;
+        nextLink = link;
+      }
+    });
+
+    if (nextLink) {
+      event.preventDefault();
+      nextLink.focus();
+    }
+  });
+});
