@@ -0,0 +1,106 @@
+const { test } = require('node:test');
+const assert = require('node:assert/strict');
+const { readFileSync } = require('node:fs');
+const { runInNewContext } = require('node:vm');
+
+const source = readFileSync(`${__dirname}/card-navigation.js`, 'utf8');
+
+function setup(positions) {
+  let handler;
+  let focused = null;
+  const grid = {
+    addEventListener: (_, callback) => { handler = callback; },
+    querySelectorAll: () => links,
+  };
+  const links = positions.map(([left, top, width = 100, height = 100]) => ({
+    tabIndex: 0,
+    hidden: false,
+    visibility: 'visible',
+    parentElement: {
+      getBoundingClientRect: () => ({ left, top, right: left + width, bottom: top + height }),
+    },
+    closest(selector) {
+      if (selector === '.grid') return grid;
+      if (selector === '.card > a.btn') return this;
+      return this.hidden ? this : null;
+    },
+    getClientRects() { return this.hidden ? [] : [{}]; },
+    focus() { focused = this; },
+  }));
+  runInNewContext(source, {
+    document: { querySelectorAll: () => [grid] },
+    getComputedStyle: (link) => ({ visibility: link.visibility }),
+  });
+  return {
+    links,
+    press(index, key, modifiers = {}) {
+      focused = null;
+      let prevented = false;
+      handler({
+        target: links[index], key,
+        preventDefault() { prevented = true; },
+        ...modifiers,
+      });
+      return { focused: links.indexOf(focused), prevented };
+    },
+  };
+}
+
+test('moves in all four directions in a multi-column layout', () => {
+  const grid = setup([[0, 0], [120, 0], [0, 120], [120, 120]]);
+  for (const [from, key, to] of [
+    [0, 'ArrowRight', 1], [1, 'ArrowLeft', 0],
+    [0, 'ArrowDown', 2], [3, 'ArrowUp', 1],
+  ]) {
+    assert.deepEqual(grid.press(from, key), { focused: to, prevented: true });
+  }
+});
+
+test('single-column layouts use Up/Down and leave horizontal boundaries alone', () => {
+  const grid = setup([[0, 0], [0, 120], [0, 240]]);
+  assert.equal(grid.press(0, 'ArrowDown').focused, 1);
