+  <script>
+    (() => {
+      const list = document.querySelector('.SwipeableList');
+      const heading = document.querySelector('#cart-heading');
+      const status = document.querySelector('.SwipeableList-status');
+      const handles = new WeakMap();
+      const needsScrollWorkaround = !CSS.supports('scroll-initial-target', 'nearest');
+      const resizeObserver = needsScrollWorkaround && 'ResizeObserver' in window
+        ? new ResizeObserver(entries => {
+            for (const { target } of entries) target.scrollLeft = target.clientWidth;
+          })
+        : null;
+
+      function updateSummary() {
+        const rows = [...list.children].filter(row => !row.classList.contains('is-removing'));
+        document.querySelector('.cart-count').textContent = `${rows.length} item${rows.length === 1 ? '' : 's'}`;
+        const cents = rows.reduce((sum, row) => sum + Number(row.dataset.price), 0);
+        document.querySelector('.cart-total').textContent = new Intl.NumberFormat('en-US', {
+          style: 'currency', currency: 'USD'
+        }).format(cents / 100);
+        list.hidden = rows.length === 0 && !list.querySelector('.is-removing');
+        document.querySelector('.cart-empty').hidden = rows.length > 0;
+      }
+
+      async function removeItem(item, direction = 'left') {
+        if (item.classList.contains('is-removing')) return;
+        const track = item.querySelector('.SwipeableList-track');
+        const content = item.querySelector('.SwipeableList-content');
+        const rect = content.getBoundingClientRect();
+        const offset = rect.x - track.getBoundingClientRect().x;
+        const height = item.getBoundingClientRect().height;
+        const translate = direction === 'right' ? rect.width - offset : -(rect.width + offset);
+        // Stop observing before the height animation can trigger resize callbacks.
+        viewportObserver?.unobserve(item);
+        handles.get(item)?.observer.disconnect();
+        resizeObserver?.unobserve(track);
+        item.classList.add('is-removing');
+
+        if (item.contains(document.activeElement)) {
+          const rows = [...list.children];
+          const index = rows.indexOf(item);
+          const available = row => !row.classList.contains('is-removing');
+          const next = rows.slice(index + 1).find(available)
+            ?? rows.slice(0, index).reverse().find(available);
+          (next?.querySelector('button') ?? heading).focus({ preventScroll: true });
+        }
+        item.inert = true;
+        status.textContent = `${item.querySelector('.SwipeableList-label').textContent} removed from cart.`;
+        updateSummary();
+
+        const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
+        if (typeof item.animate === 'function') {
+          const options = { duration: reduce ? 120 : 300, easing: 'ease', fill: 'forwards' };
+          const animations = [item.animate([{ height: `${height}px` }, { height: '0px' }], options)];
+          if (!reduce) {
+            animations.push(content.animate([
+              { transform: 'translateX(0)' }, { transform: `translateX(${translate}px)` }
+            ], options));
+          }
+          await Promise.allSettled(animations.map(animation => animation.finished));
+        }
+        // Keep a collapsed shell briefly in Safari to avoid passing swipe momentum to the next row.
+        const finish = () => { item.remove(); updateSummary(); };
+        if ('GestureEvent' in window) {
+          item.style.height = '0px';
+          setTimeout(finish, 5000);
+        } else {
+          finish();
+        }
+      }
+
+      function setupItem(item) {
+        if (handles.has(item)) return handles.get(item);
+        const track = item.querySelector('.SwipeableList-track');
+        const content = item.querySelector('.SwipeableList-content');
+        item.classList.add('is-initialized');
+        // Center the content before observing, so initialization cannot count as a swipe.
+        if (needsScrollWorkaround) {
+          track.scrollLeft = track.clientWidth;
+          resizeObserver?.observe(track);
+        }
+        const observer = new IntersectionObserver(entries => {
+          const entry = entries[entries.length - 1];
+          if (!entry.rootBounds || item.classList.contains('is-removing')) return;
+          const offset = entry.boundingClientRect.x - entry.rootBounds.x;
+          const direction = offset > 0 ? 'right' : 'left';
+          item.classList.toggle('is-activating', entry.intersectionRatio < 0.8);
+          // Commit once more than 80% of the content has moved out of the track.
+          if (entry.intersectionRatio < 0.2) removeItem(item, direction);
+        }, { root: track, threshold: [0.2, 0.8] });
+        const handle = { observer, content };
+        handles.set(item, handle);
+        return handle;
+      }
+
+      // Leave plain rows and functional Remove buttons if native swipe APIs are unavailable.
+      const viewportObserver = 'IntersectionObserver' in window
+        ? new IntersectionObserver(entries => {
+            for (const entry of entries) {
+              const item = entry.target;
+              if (item.classList.contains('is-removing')) continue;
+              if (entry.isIntersecting) {
+                const handle = setupItem(item);
+                handle.observer.observe(handle.content);
+              } else {
+                handles.get(item)?.observer.unobserve(handles.get(item).content);
+              }
+            }
+          })
+        : null;
+      for (const item of list.children) viewportObserver?.observe(item);
+
+      list.addEventListener('click', event => {
+        const button = event.target.closest('.SwipeableList-action');
+        const item = button?.closest('.SwipeableList-item');
+        if (item) removeItem(item);
+      });
+    })();
+  </script>
