--- /dev/null
+++ b/translation.js
@@ -0,0 +1,129 @@
+(() => {
+  const selector = document.getElementById('language-selector');
+  const translateButton = document.getElementById('translate-button');
+  const restoreButton = document.getElementById('restore-button');
+  const status = document.getElementById('translation-status');
+  const passages = [...document.querySelectorAll('[data-translatable]')];
+  // Always translate from the original, never from an earlier translation.
+  const originals = passages.map((element) => element.textContent);
+  const cache = new Map([['en', originals]]);
+  let revision = 0;
+  let preparedOptions = null;
+  let busy = false;
+
+  function display(language, texts) {
+    passages.forEach((element, index) => {
+      element.textContent = texts[index];
+      element.lang = language;
+      element.dir = language === 'ar' ? 'rtl' : 'ltr';
+    });
+    restoreButton.disabled = language === 'en';
+  }
+
+  function restore() {
+    revision++;
+    busy = false;
+    preparedOptions = null;
+    selector.disabled = false;
+    selector.value = 'en';
+    translateButton.disabled = true;
+    translateButton.textContent = 'Translate';
+    display('en', originals);
+    status.textContent = 'Showing the original English menu and story.';
+  }
+
+  async function prepare() {
+    const current = ++revision;
+    const language = selector.value;
+    preparedOptions = null;
+    translateButton.disabled = true;
+    translateButton.textContent = 'Translate';
+    if (language === 'en') {
+      restore();
+      return;
+    }
+    if (cache.has(language)) {
+      display(language, cache.get(language));
+      status.textContent = 'Showing the saved on-device translation.';
+      return;
+    }
+    status.textContent = 'Checking this language on your device…';
+    const options = { sourceLanguage: 'en', targetLanguage: language };
+    try {
+      const availability = await window.Translator.availability(options);
+      if (current !== revision) return;
+      if (availability === 'unavailable') {
+        status.textContent = 'This language is unavailable on your device. Choose another language or restore English.';
+        return;
+      }
+      preparedOptions = options;
+      translateButton.disabled = false;
+      const needsDownload = availability !== 'available';
+      translateButton.textContent = needsDownload ? 'Download & translate' : 'Translate';
+      status.textContent = needsDownload
+        ? 'A language pack is needed. Choose Download & translate to start; an internet connection is required for the download.'
+        : 'Ready to translate on your device. Choose Translate to continue.';
+    } catch {
+      if (current === revision) {
+        status.textContent = 'Could not check this language. Select a language again to retry, or restore English.';
+      }
+    }
+  }
+
+  translateButton.addEventListener('click', async () => {
+    if (busy || !preparedOptions) return;
+    const options = preparedOptions;
+    const current = ++revision;
+    let translator;
+    busy = true;
+    selector.disabled = true;
+    translateButton.disabled = true;
+    restoreButton.disabled = false;
+    status.textContent = 'Preparing on-device translation…';
+    try {
+      // Call create directly from the click, preserving user activation for downloads.
+      translator = await window.Translator.create({
+        ...options,
+        monitor(monitor) {
+          monitor.addEventListener('downloadprogress', (event) => {
+            if (current !== revision) return;
+            const percent = Math.round(event.loaded * 100);
+            status.textContent = `Downloading language pack: ${percent}%`;
+          });
+        },
+      });
+      if (current !== revision) return;
+      status.textContent = 'Translating the menu descriptions and story on your device…';
+      const translated = [];
+      for (const text of originals) {
+        translated.push(await translator.translate(text));
+        if (current !== revision) return;
+      }
+      // Commit together so a failed translation leaves the existing content intact.
+      cache.set(options.targetLanguage, translated);
+      display(options.targetLanguage, translated);
+      status.textContent = 'Menu descriptions and story translated on your device using AI. You can restore English at any time.';
+    } catch {
+      if (current === revision) {
+        translateButton.disabled = false;
+        status.textContent = 'Translation could not finish. Your text has been kept. Try again, check your connection if a download is needed, or restore English.';
+      }
+    } finally {
+      translator?.destroy();
+      if (current === revision) {
+        busy = false;
+        selector.disabled = false;
+      }
+    }
+  });
+
+  selector.addEventListener('change', prepare);
+  restoreButton.addEventListener('click', restore);
+
+  if (!window.isSecureContext || !('Translator' in window)) {
+    status.textContent = 'On-device translation is unavailable in this browser. Try a supported desktop browser on a secure (HTTPS) connection. The original English text is shown below.';
+    return;
+  }
+  selector.disabled = false;
+  status.textContent = 'Choose a language to translate the menu descriptions and story on your device.';
+})();

