+++ b/src/scripts/article-translation.ts
@@ -0,0 +1,174 @@
+type LanguagePair = { sourceLanguage: string; targetLanguage: string };
+type Availability = 'available' | 'downloadable' | 'downloading' | 'unavailable';
+type LocalTranslator = {
+  translate(text: string, options?: { signal: AbortSignal }): Promise<string>;
+  destroy(): void;
+};
+type TranslatorAPI = {
+  availability(options: LanguagePair): Promise<Availability>;
+  create(options: LanguagePair & {
+    signal: AbortSignal;
+    monitor: (monitor: { addEventListener(type: 'downloadprogress', callback: (event: { loaded: number }) => void): void }) => void;
+  }): Promise<LocalTranslator>;
+};
+
+class ArticleTranslation extends HTMLElement {
+  private originals = new Map<Text, string>();
+  private roots: HTMLElement[] = [];
+  private task?: AbortController;
+  private generation = 0;
+  private appliedLanguage = 'en';
+  private api?: TranslatorAPI;
+  private select!: HTMLSelectElement;
+  private translateButton!: HTMLButtonElement;
+  private restoreButton!: HTMLButtonElement;
+  private status!: HTMLElement;
+  private listeners?: AbortController;
+
+  connectedCallback() {
+    this.select = this.querySelector('[data-language]')!;
+    this.translateButton = this.querySelector('[data-translate]')!;
+    this.restoreButton = this.querySelector('[data-restore]')!;
+    this.status = this.querySelector('[role="status"]')!;
+    this.api = (window as Window & { Translator?: TranslatorAPI }).Translator;
+    this.listeners = new AbortController();
+    const options = { signal: this.listeners.signal };
+    this.select.addEventListener('change', () => void this.checkAvailability(), options);
+    this.translateButton.addEventListener('click', () => void this.performTranslation(), options);
+    this.restoreButton.addEventListener('click', () => this.restore(), options);
+    this.select.disabled = !this.api;
+    void this.checkAvailability();
+  }
+
+  disconnectedCallback() {
+    this.generation++;
+    this.task?.abort();
+    this.listeners?.abort();
+    this.originals.clear();
+  }
+
+  private message(text: string) { this.status.textContent = text; }
+  private pair(): LanguagePair { return { sourceLanguage: 'en', targetLanguage: this.select.value }; }
+
+  private async checkAvailability() {
+    const generation = ++this.generation;
+    this.translateButton.disabled = true;
+    if (!this.api) {
+      this.message('On-device translation is unavailable in this browser. Try a supported desktop Chrome or Edge browser. Articles remain available in English.');
+      return;
+    }
+    if (this.select.value === 'en') {
+      this.translateButton.disabled = false;
+      this.translateButton.textContent = 'Show English';
+      this.message('Select Show English to restore the original articles.');
+      return;
+    }
+    this.translateButton.textContent = 'Translate';
+    this.message('Checking this language on your device…');
+    try {
+      const state = await this.api.availability(this.pair());
+      if (generation !== this.generation || !this.isConnected) return;
+      this.translateButton.disabled = state === 'unavailable';
+      this.message(state === 'unavailable'
+        ? 'This language pair is unavailable on your device. Choose another language.'
+        : state === 'available'
+          ? 'Ready to translate articles and teasers on this page.'
+          : 'Select Translate to download the language pack. An internet connection is needed for the download.');
+    } catch {
+      if (generation === this.generation) this.message('Could not check language support. Choose a language to try again.');
+    }
+  }
+
+  private capture() {
+    this.roots = Array.from(document.querySelectorAll<HTMLElement>('[data-article-text]'));
+    for (const root of this.roots) {
+      const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
+      let node: Node | null;
+      while ((node = walker.nextNode())) {
+        const text = node as Text;
+        if (text.textContent?.trim() && !text.parentElement?.closest('script, style, pre, code, [translate="no"]') && !this.originals.has(text)) {
+          this.originals.set(text, text.data);
+        }
+      }
+    }
+  }
+
+  private restore() {
+    this.generation++;
+    this.task?.abort();
+    this.task = undefined;
+    for (const [node, original] of this.originals) node.data = original;
+    this.setLanguage('en');
+    this.appliedLanguage = 'en';
+    this.select.disabled = !this.api;
+    this.translateButton.disabled = !this.api;
+    this.translateButton.textContent = this.select.value === 'en' ? 'Show English' : 'Translate';
+    this.restoreButton.disabled = true;
+    this.message('Original English articles restored.');
+  }
+
+  private setLanguage(language: string) {
+    for (const root of this.roots) {
+      root.lang = language;
+      root.dir = language === 'ar' ? 'rtl' : 'auto';
+    }
+  }
+
+  private async performTranslation() {
+    if (this.select.value === 'en') { this.restore(); return; }
+    if (!this.api || this.task) return;
+    const options = this.pair();
+    const generation = ++this.generation;
+    const controller = new AbortController();
+    this.task = controller;
+    this.select.disabled = true;
+    this.translateButton.disabled = true;
+    this.translateButton.textContent = 'Translating…';
+    this.restoreButton.disabled = false;
+    this.message('Preparing on-device translation…');
+    let translator: LocalTranslator | undefined;
+    try {
+      // Create directly in the click handler to retain user activation for downloads.
+      translator = await this.api.create({ ...options, signal: controller.signal, monitor: (monitor) => {
+        monitor.addEventListener('downloadprogress', (event) => {
+          if (!controller.signal.aborted) this.message(`Downloading language pack… ${Math.round(event.loaded * 100)}%`);
+        });
+      }});
+      if (controller.signal.aborted) return;
+      this.capture();
+      if (!this.originals.size) throw new Error('No articles');
+      const translated = new Map<string, string>();
+      const entries = Array.from(this.originals.entries());
+      for (const [, original] of entries) {
+        if (controller.signal.aborted) return;
+        if (!translated.has(original)) {
+          this.message(`Translating articles… ${translated.size + 1} text sections processed`);
+          const result = await translator.translate(original.trim(), { signal: controller.signal });
+          const leading = original.match(/^\s*/)?.[0] ?? '';
+          const trailing = original.match(/\s*$/)?.[0] ?? '';
+          translated.set(original, leading + result.trim() + trailing);
+        }
+      }
+      if (controller.signal.aborted || generation !== this.generation) return;
+      // Commit together, preserving links, markup and the previous language on failure.
+      for (const [node, original] of entries) node.data = translated.get(original)!;
+      this.setLanguage(options.targetLanguage);
+      this.appliedLanguage = options.targetLanguage;
+      const name = this.select.selectedOptions[0].textContent?.split(' · ')[0];
+      this.message(`Articles and teasers translated to ${name}. Machine translations may contain errors.`);
+    } catch {
+      if (!controller.signal.aborted) this.message('Translation could not complete. Your current text has been kept. Select Translate to retry, or choose another language.');
+    } finally {
+      translator?.destroy();
+      if (generation === this.generation && this.isConnected) {
+        this.task = undefined;
+        this.select.disabled = false;
+        this.translateButton.disabled = false;
+        this.translateButton.textContent = 'Translate';
+        this.restoreButton.disabled = this.appliedLanguage === 'en';
+      }
+    }
+  }
+}
