@@ -0,0 +1,152 @@
+type TranslatorSession = {
+  translate(text: string): Promise<string>;
+  destroy(): void;
+};
+type TranslatorAPI = {
+  create(options: {
+    sourceLanguage: string;
+    targetLanguage: string;
+    signal: AbortSignal;
+    monitor(monitor: EventTarget): void;
+  }): Promise<TranslatorSession>;
+};
+
+class EditionTranslator extends HTMLElement {
+  private originals = new Map<Text, string>();
+  private attributes = new Map<HTMLElement, { lang: string | null; dir: string | null }>();
+  private controller?: AbortController;
+  private session?: TranslatorSession;
+  private listeners?: AbortController;
+  private generation = 0;
+
+  private get select() { return this.querySelector('select')!; }
+  private get submit() { return this.querySelector<HTMLButtonElement>('[data-translate]')!; }
+  private get restoreButton() { return this.querySelector<HTMLButtonElement>('[data-restore]')!; }
+  private status(message: string) { this.querySelector('[data-status]')!.textContent = message; }
+  private get api() { return (window as unknown as { Translator?: TranslatorAPI }).Translator; }
+
+  connectedCallback() {
+    this.listeners?.abort();
+    this.listeners = new AbortController();
+    const { signal } = this.listeners;
+    this.querySelector('form')!.addEventListener('submit', (event) => {
+      event.preventDefault();
+      void this.translate();
+    }, { signal });
+    this.restoreButton.addEventListener('click', () => this.restore(), { signal });
+    const supported = window.isSecureContext && !!this.api;
+    this.select.disabled = this.submit.disabled = !supported;
+    this.status(supported
+      ? 'Headlines, teasers & articles · English originals · A language pack may download on first use.'
+      : 'On-device translation is unavailable in this browser. Try a supported desktop browser, such as Chrome, over HTTPS.');
+  }
+
+  disconnectedCallback() {
+    this.cancel();
+    this.listeners?.abort();
+  }
+
+  private cancel() {
+    this.generation++;
+    this.controller?.abort();
+    this.session?.destroy();
+    this.session = undefined;
+    this.removeAttribute('aria-busy');
+  }
+
+  private restore() {
+    this.cancel();
+    for (const [node, text] of this.originals) node.textContent = text;
+    for (const [element, attrs] of this.attributes) {
+      for (const key of ['lang', 'dir'] as const) {
+        if (attrs[key] === null) element.removeAttribute(key);
+        else element.setAttribute(key, attrs[key]);
+      }
+    }
+    this.select.disabled = this.submit.disabled = false;
+    this.submit.textContent = 'Translate';
+    this.restoreButton.hidden = true;
+    this.status('Showing the original English edition.');
+  }
+
+  private async translate() {
+    if (this.submit.disabled || !this.api) return;
+    const targetLanguage = this.select.value;
+    if (targetLanguage === 'en') { this.restore(); return; }
+    const roots = [...document.querySelectorAll<HTMLElement>('[data-translate-content]')];
+    if (!roots.length) { this.status('There are no news articles or teasers to translate on this page.'); return; }
+    this.cancel();
+    const generation = this.generation;
+    const active = () => this.isConnected && generation === this.generation;
+    this.controller = new AbortController();
+    this.select.disabled = this.submit.disabled = true;
+    this.submit.textContent = 'Translating…';
+    this.restoreButton.hidden = false;
+    this.setAttribute('aria-busy', 'true');
+    this.status('Preparing on-device translation…');
+    try {
+      // Start create directly in the submit gesture so language downloads can be authorized.
+      const session = await this.api.create({
+        sourceLanguage: 'en', targetLanguage, signal: this.controller.signal,
+        monitor: (monitor) => monitor.addEventListener('downloadprogress', (event) => {
+          if (!active()) return;
+          const loaded = (event as Event & { loaded: number }).loaded;
+          this.status(`Downloading language pack… ${Math.round(loaded * 100)}%`);
+        }),
+      });
+      if (!active()) { session.destroy(); return; }
+      this.session = session;
+      const nodes = new Set<Text>();
+      for (const root of roots) {
+        const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
+          acceptNode: (node) => node.textContent?.trim() && !node.parentElement?.closest('script, style, code, pre, [translate="no"]')
+            ? NodeFilter.FILTER_ACCEPT : NodeFilter.FILTER_REJECT,
+        });
+        while (walker.nextNode()) nodes.add(walker.currentNode as Text);
+      }
+      const results = new Map<Text, string>();
+      const cache = new Map<string, string>();
+      for (const node of nodes) {
+        if (!this.originals.has(node)) this.originals.set(node, node.textContent!);
+        const original = this.originals.get(node)!;
+        const text = original.trim();
+        let translated = cache.get(text);
+        if (translated === undefined) {
+          translated = await session.translate(text);
+          if (!active()) return;
+          cache.set(text, translated);
+        }
+        results.set(node, original.replace(/\S[\s\S]*\S|\S/, () => translated!));
+        this.status(`Translating articles… ${Math.round(results.size / nodes.size * 100)}%`);
+      }
+      if (!active()) return;
+      // Apply only once the whole edition succeeds; failures leave the current edition intact.
+      for (const [node, text] of results) node.textContent = text;
+      for (const root of roots) {
+        if (!this.attributes.has(root)) this.attributes.set(root, { lang: root.getAttribute('lang'), dir: root.getAttribute('dir') });
+        root.lang = targetLanguage;
+        root.dir = targetLanguage === 'ar' ? 'rtl' : 'ltr';
+      }
+      const language = this.select.selectedOptions[0].textContent;
+      this.status(`Reading in ${language} · Translated on your device. Machine translations may contain errors.`);
+    } catch (error) {
+      if (!active()) return;
+      const name = error instanceof DOMException ? error.name : '';
+      this.status(name === 'NotSupportedError'
+        ? 'This language is not supported on your device. Choose another language.'
+        : name === 'NotAllowedError'
+          ? 'The browser could not start translation. Press Translate to try again and allow any requested download.'
+          : 'Translation could not finish. Check your connection if a language pack is needed, then try again. Your current text is unchanged.');
+    } finally {
+      if (active()) {
+        this.session?.destroy();
+        this.session = undefined;
+        this.select.disabled = this.submit.disabled = false;
+        this.submit.textContent = 'Translate';
+        this.removeAttribute('aria-busy');
+      }
+    }
+  }
+}
+
+if (!customElements.get('edition-translator')) customElements.define('edition-translator', EditionTranslator);
