+import { test } from 'node:test';
+import assert from 'node:assert/strict';
+
+// A minimal DOM adapter exercises the controller without a browser or server.
+class Element extends EventTarget {
+  attrs = new Map();
+  isConnected = true;
+  disabled = false;
+  hidden = false;
+  textContent = '';
+  setAttribute(name, value) { this.attrs.set(name, value); }
+  getAttribute(name) { return this.attrs.get(name) ?? null; }
+  removeAttribute(name) { this.attrs.delete(name); }
+  set lang(value) { this.setAttribute('lang', value); }
+  set dir(value) { this.setAttribute('dir', value); }
+}
+let Controller;
+globalThis.HTMLElement = Element;
+globalThis.customElements = { get: () => undefined, define: (_, value) => { Controller = value; } };
+globalThis.NodeFilter = { SHOW_TEXT: 4, FILTER_ACCEPT: 1, FILTER_REJECT: 2 };
+await import('../src/scripts/translation-control.ts');
+
+function setup(api) {
+  const controls = Object.fromEntries(['select', 'form', '[data-translate]', '[data-restore]', '[data-status]'].map(key => [key, new Element()]));
+  controls.select.value = 'es';
+  controls.select.selectedOptions = [{ textContent: 'Español' }];
+  const root = new Element();
+  root.lang = 'en';
+  root.nodes = [' A headline ', 'A summary'].map(textContent => ({ textContent, parentElement: { closest: () => null } }));
+  globalThis.window = { isSecureContext: true, Translator: api };
+  globalThis.document = {
+    querySelectorAll: () => [root],
+    createTreeWalker: (element, _, filter) => {
+      const nodes = element.nodes.filter(node => filter.acceptNode(node) === 1);
+      let index = -1;
+      return { nextNode() { return ++index < nodes.length; }, get currentNode() { return nodes[index]; } };
+    },
+  };
+  const controller = new Controller();
+  controller.querySelector = key => controls[key];
+  controller.connectedCallback();
+  return { controller, controls, root };
+}
+
+const api = (translate = async text => `es:${text}`) => ({
+  create: async () => ({ translate, destroy() {} }),
+});
+
+test('unsupported browsers get a disabled control and an explanation', () => {
+  const { controls } = setup(undefined);
+  assert.equal(controls['[data-translate]'].disabled, true);
+  assert.match(controls['[data-status]'].textContent, /unavailable/);
+});
+
+test('translations preserve whitespace, switch language metadata, and restore originals', async () => {
+  const { controller, controls, root } = setup(api());
+  await controller.translate();
+  assert.equal(root.nodes[0].textContent, ' es:A headline ');
+  assert.equal(root.getAttribute('lang'), 'es');
+  assert.equal(controls['[data-restore]'].hidden, false);
+  controls['[data-restore]'].dispatchEvent(new Event('click'));
+  assert.equal(root.nodes[0].textContent, ' A headline ');
+  assert.equal(root.getAttribute('lang'), 'en');
+  assert.equal(root.getAttribute('dir'), null);
+});
+
+test('changing target languages always translates the original English text', async () => {
+  const inputs = [];
+  const { controller, controls, root } = setup(api(async text => { inputs.push(text); return `translated:${text}`; }));
+  await controller.translate();
+  controls.select.value = 'ar';
+  await controller.translate();
+  assert.deepEqual(inputs, ['A headline', 'A summary', 'A headline', 'A summary']);
+  assert.equal(root.getAttribute('dir'), 'rtl');
+});
+
+test('a mid-edition failure never leaves a partially translated page', async () => {
+  let calls = 0;
+  const { controller, controls, root } = setup(api(async text => {
+    if (++calls === 2) throw new Error('download failure');
+    return `es:${text}`;
+  }));
+  await controller.translate();
+  assert.deepEqual(root.nodes.map(node => node.textContent), [' A headline ', 'A summary']);
+  assert.match(controls['[data-status]'].textContent, /could not finish/);
+  assert.equal(controls['[data-translate]'].disabled, false);
+});
+
+test('restoring during a pending request prevents late results from changing content', async () => {
+  let resolve;
+  const { controller, controls, root } = setup(api(() => new Promise(done => { resolve = done; })));
+  const pending = controller.translate();
+  await Promise.resolve();
+  controls['[data-restore]'].dispatchEvent(new Event('click'));
+  resolve('late translation');
+  await pending;
+  assert.equal(root.nodes[0].textContent, ' A headline ');
+  assert.match(controls['[data-status]'].textContent, /original English/);
+});

