+import {
+  classifyLink,
+  createWidgetValidator,
+  isTrustedOrderingMessage,
+  sameSiteUrl,
+} from './origin-validation.mjs';
+
+const widget = document.querySelector('#ordering-widget');
+const status = document.querySelector('#order-status');
+const acceptsWidget = createWidgetValidator(() => widget.contentWindow);
+
+function redirect(candidate) {
+  const target = sameSiteUrl(candidate, window.location.href);
+  if (target) window.location.assign(target.href);
+}
+
+window.addEventListener('message', (event) => {
+  const data = event.data;
+  if (!data || typeof data !== 'object' || Array.isArray(data)) return;
+  if (!isTrustedOrderingMessage(event) && !acceptsWidget(event)) return;
+
+  if (data.type === 'redirect' && typeof data.url === 'string') {
+    redirect(data.url);
+  } else if (data.type === 'status' && typeof data.text === 'string' && data.text.length <= 300) {
+    status.textContent = data.text;
+  }
+});
+
+// Apply the same schemeful site policy to DOM links, including newly added links.
+function validateLink(link) {
+  const classification = classifyLink(link, window.location.href);
+  if (classification === 'external') link.relList.add('noopener', 'noreferrer');
+  return classification !== 'invalid';
+}
+
+document.querySelectorAll('a[href]').forEach(validateLink);
+document.addEventListener('click', (event) => {
+  const link = event.target.closest?.('a[href]');
+  if (link && !validateLink(link)) event.preventDefault();
+});
+document.addEventListener('auxclick', (event) => {
+  const link = event.target.closest?.('a[href]');
+  if (link && !validateLink(link)) event.preventDefault();
+});
+
+const returnTo = new URL(window.location.href).searchParams.get('returnTo');
+if (returnTo) {
+  const target = sameSiteUrl(returnTo, window.location.href);
+  if (target) document.querySelector('#order-now').href = target.href;
+}
+
+// Set src after installing the listener so an early init cannot be lost.
+widget.src = './ordering-widget.html';
