+    assert.equal(internal.relList.tokens.size, 0);
+    const send = (origin, data, source = {}) => listeners.get('message')({ origin, data, source });
+    send('https://orders.dailygrind.coffee.evil.example', { type: 'redirect', url: '/account' });
