--- /dev/null
+++ b/origin-validation.mjs
@@ -0,0 +1,94 @@
+// Deployment configuration: use the actual, independently trusted ordering origin.
+export const ORDERING_ORIGIN = 'https://orders.dailygrind.coffee';
+// Explicitly owned registrable domain for browsers without the Origin API.
+// Never derive this value by slicing a hostname (public suffixes have varying lengths).
+export const SITE_DOMAIN = 'dailygrind.coffee';
+
+function webUrl(candidate, base) {
+  const value = typeof candidate === 'string' ? candidate : candidate?.href;
+  if (typeof value !== 'string' || !value.trim()) throw new TypeError('Expected a URL');
+  const url = new URL(value, base);
+  if (!['https:', 'http:'].includes(url.protocol) || url.username || url.password) {
+    throw new TypeError('Expected an HTTP(S) URL without credentials');
+  }
+  return url;
+}
+
+function withinOwnedSite(hostname) {
+  return hostname === SITE_DOMAIN || hostname.endsWith(`.${SITE_DOMAIN}`);
+}
+
+export function isTrustedOrderingMessage(event) {
+  try {
+    const url = webUrl(event.origin);
+    if (typeof globalThis.Origin === 'function') {
+      let sender;
+      try {
+        sender = Origin.from(event);
+      } catch {
+        // Synthetic MessageEvents have no internal origin; opaque strings still fail.
+        sender = Origin.from(url);
+      }
+      return !sender.opaque && sender.isSameOrigin(Origin.from(ORDERING_ORIGIN));
+    }
+    return url.origin === new URL(ORDERING_ORIGIN).origin;
+  } catch {
+    return false;
+  }
+}
+
+// Return the parsed URL so callers navigate to exactly the URL that was checked.
+export function sameSiteUrl(candidate, pageUrl) {
+  try {
+    const page = webUrl(pageUrl);
+    const target = webUrl(candidate, page.href);
+    if (typeof globalThis.Origin === 'function') {
+      const origin = Origin.from(target);
+      return !origin.opaque && origin.isSameSite(Origin.from(page)) ? target : null;
+    }
+    // URL has no Public Suffix List. Permit known owned subdomains; on other
+    // deployments conservatively allow only the current origin.
+    const allowed = target.protocol === page.protocol && (
+      target.origin === page.origin ||
+      (withinOwnedSite(page.hostname) && withinOwnedSite(target.hostname))
+    );
+    return allowed ? target : null;
+  } catch {
+    return null;
+  }
+}
+
+export function classifyLink(candidate, pageUrl) {
+  try {
+    const target = webUrl(candidate, pageUrl);
+    return sameSiteUrl(target, pageUrl) ? 'internal' : 'external';
+  } catch {
+    return 'invalid';
+  }
+}
+
+export function createWidgetValidator(expectedWindow) {
+  const supportsOrigin = typeof globalThis.Origin === 'function';
+  let pinnedOrigin = supportsOrigin ? new Origin() : null;
+  let pinnedWindow = null;
+
+  return (event) => {
+    try {
+      const source = expectedWindow();
+      if (!source || event.source !== source || event.origin !== 'null') return false;
+      // Never parse the string "null": preserve the browser's opaque identity.
+      const sender = supportsOrigin ? Origin.from(event) : null;
+      if (supportsOrigin && !sender.opaque) return false;
+      if (!pinnedWindow) {
+        if (event.data?.type !== 'init') return false;
+        pinnedOrigin = sender;
+        pinnedWindow = source;
+      }
+      return event.source === pinnedWindow && (
+        !supportsOrigin || sender.isSameOrigin(pinnedOrigin)
+      );
+    } catch {
+      return false;
+    }
+  };
+}
