+import assert from 'node:assert/strict';
+import { afterEach, test } from 'node:test';
+import {
+  ORDERING_ORIGIN,
+  classifyLink,
+  createWidgetValidator,
+  isTrustedOrderingMessage,
+  sameSiteUrl,
+} from './origin-validation.mjs';
+
+const originalOrigin = globalThis.Origin;
+afterEach(() => {
+  if (originalOrigin === undefined) delete globalThis.Origin;
+  else globalThis.Origin = originalOrigin;
+});
+
+function withoutOrigin() {
+  delete globalThis.Origin;
+}
+
+test('ordering messages require the exact normalized trusted origin', () => {
+  withoutOrigin();
+  assert.equal(isTrustedOrderingMessage({ origin: ORDERING_ORIGIN }), true);
+  assert.equal(isTrustedOrderingMessage({ origin: `${ORDERING_ORIGIN}:443` }), true);
+  for (const origin of [
+    `${ORDERING_ORIGIN}.evil.example`, 'https://dailygrind.coffee',
+    'http://orders.dailygrind.coffee', `${ORDERING_ORIGIN}:8443`,
+    'https://orders.dailygrind.coffee@evil.example', 'null', '', 'not a URL',
+    'data:text/html,hello',
+  ]) assert.equal(isTrustedOrderingMessage({ origin }), false, origin);
+});
+
+test('same-site fallback resolves relative URLs and owned subdomains across ports', () => {
+  withoutOrigin();
+  const page = 'https://www.dailygrind.coffee/account';
+  for (const value of ['/menu', '?order=1', '#details', '//orders.dailygrind.coffee/menu',
+    'https://orders.dailygrind.coffee:8443/menu']) {
+    assert.equal(sameSiteUrl(value, page)?.href, new URL(value, page).href);
+  }
+  assert.equal(sameSiteUrl({ href: '/menu' }, page)?.pathname, '/menu');
+});
+
