+  withoutOrigin();
+  const page = 'https://www.dailygrind.coffee/';
+  for (const value of [
+    'https://dailygrind.coffee.evil.example', 'https://evildailygrind.coffee',
+    'https://dailygrind.coffee@evil.example', 'http://orders.dailygrind.coffee',
+    '//evil.example', '/\\evil.example', 'javascript:alert(1)',
+    'data:text/html,hello', 'blob:https://www.dailygrind.coffee/id',
+    'https://user:password@www.dailygrind.coffee', 'https://[', '', null, {}, 123,
+  ]) assert.equal(sameSiteUrl(value, page), null, String(value));
+});
+
+test('unknown domains fail closed rather than guessing public suffix boundaries', () => {
+  withoutOrigin();
+  for (const [page, other] of [
+    ['https://shop.alpha.co.uk', 'https://shop.beta.co.uk'],
+    ['https://alice.github.io', 'https://bob.github.io'],
+    ['https://dailygrind.coffee.evil.example', 'https://orders.dailygrind.coffee'],
+  ]) {
+    assert.equal(sameSiteUrl(other, page), null);
+    assert.equal(sameSiteUrl('/menu', page)?.href, `${page}/menu`);
+  }
+});
+
+test('links distinguish internal, external and invalid targets', () => {
+  withoutOrigin();
+  const page = 'https://dailygrind.coffee';
+  assert.equal(classifyLink({ href: 'https://orders.dailygrind.coffee/menu' }, page), 'internal');
+  assert.equal(classifyLink('https://dailygrind.coffee.evil.example', page), 'external');
+  assert.equal(classifyLink('http://dailygrind.coffee', page), 'external');
+  assert.equal(classifyLink('javascript:alert(1)', page), 'invalid');
+});
+
+test('fallback widget identity is pinned only by init from the expected window', () => {
+  withoutOrigin();
+  const expected = {};
+  const other = {};
+  let current = expected;
+  const accepts = createWidgetValidator(() => current);
+  const message = (source, type = 'status', origin = 'null') => ({ source, origin, data: { type } });
+  assert.equal(accepts(message(null, 'init')), false);
+  assert.equal(accepts(message(other, 'init')), false);
