+  assert.equal(accepts(message(expected, 'init', ORDERING_ORIGIN)), false);
+  assert.equal(accepts(message(expected, 'init')), true);
+  assert.equal(accepts(message(expected)), true);
+  assert.equal(accepts(message(other)), false);
+  current = other;
+  assert.equal(accepts(message(other, 'init')), false);
+});
+
+// Node does not implement the browser Origin API. This contract double checks
+// identity pinning and API wiring; it does not simulate the browser's PSL engine.
+function installOriginDouble() {
+  const eventOrigins = new WeakMap();
+  class TestOrigin {
+    constructor(url) {
+      this.url = url;
+      this.opaque = !url;
+    }
+    static from(value) {
+      if (eventOrigins.has(value)) return eventOrigins.get(value);
+      if (value instanceof TestOrigin) return value;
+      if (!(value instanceof URL) && typeof value !== 'string') throw new TypeError();
+      const url = new URL(value);
+      return new TestOrigin(url);
+    }
+    isSameOrigin(other) {
+      return this.opaque || other.opaque ? this === other : this.url.origin === other.url.origin;
+    }
+    isSameSite(other) {
+      assert.ok(other instanceof TestOrigin);
+      // Explicit fixtures exercise delegation to the native comparison.
+      return this.url.protocol === other.url.protocol &&
+        ['shop.example.co.uk', 'billing.example.co.uk'].includes(this.url.hostname) &&
+        ['shop.example.co.uk', 'billing.example.co.uk'].includes(other.url.hostname);
+    }
+  }
+  globalThis.Origin = TestOrigin;
+  return { eventOrigins, TestOrigin };
+}
+
+test('Origin API path normalizes tuple origins and supports synthetic test events', () => {
+  const { eventOrigins, TestOrigin } = installOriginDouble();
+  const event = { origin: ORDERING_ORIGIN };
+  assert.equal(isTrustedOrderingMessage(event), true);
+  eventOrigins.set(event, TestOrigin.from('https://evil.example'));
+  assert.equal(isTrustedOrderingMessage(event), false);
+  assert.equal(isTrustedOrderingMessage({ origin: 'null' }), false);
+});
+
+test('native same-site comparison receives parsed URL origins', () => {
+  installOriginDouble();
+  assert.ok(sameSiteUrl('https://billing.example.co.uk:8443/orders', 'https://shop.example.co.uk'));
+  assert.equal(sameSiteUrl('https://shop.evil.co.uk', 'https://shop.example.co.uk'), null);
+  assert.equal(sameSiteUrl('http://billing.example.co.uk', 'https://shop.example.co.uk'), null);
+});
+
+test('native widget pins the opaque origin and rejects a changed origin on the same WindowProxy', () => {
+  const { eventOrigins, TestOrigin } = installOriginDouble();
+  const source = {};
+  const accepts = createWidgetValidator(() => source);
+  const pinned = new TestOrigin();
+  const other = new TestOrigin();
+  function message(identity, type = 'status', sender = source) {
+    const event = { source: sender, origin: 'null', data: { type } };
+    eventOrigins.set(event, identity);
+    return event;
+  }
+  assert.equal(accepts(message(pinned)), false);
+  assert.equal(accepts(message(other, 'init', {})), false);
+  assert.equal(accepts(message(TestOrigin.from(ORDERING_ORIGIN), 'init')), false);
+  assert.equal(accepts(message(pinned, 'init')), true);
+  assert.equal(accepts(message(pinned)), true);
+  assert.equal(accepts(message(other, 'init')), false);
+  assert.equal(accepts(message(other)), false);
+  assert.equal(accepts({ source, origin: 'null', data: { type: 'init' } }), false);
+  assert.equal(accepts(message(pinned)), true);
+});
