+(() => {
+  'use strict';
+
+  // Deployment configuration: keep this an exact origin, including any port.
+  const ORDERING_ORIGIN = 'https://orders.thedailygrind.com';
+  const EXTERNAL_ORIGINS = new Set([ORDERING_ORIGIN]);
+  const pageURL = new URL(window.location.href);
+  const widget = document.getElementById('order-widget');
+  const status = document.getElementById('order-status');
+  let widgetSender = null;
+
+  function parseNavigationURL(value) {
+    if (typeof value !== 'string' || !value.trim()) return null;
+    try {
+      // Resolve against the page URL, independent of any document <base>.
+      const url = new URL(value, pageURL);
+      if (!['http:', 'https:'].includes(url.protocol)) return null;
+      if (url.username || url.password) return null;
+      return url;
+    } catch {
+      return null;
+    }
+  }
+
+  function sameSiteURL(value) {
+    const url = parseNavigationURL(value);
+    return url && url.origin === pageURL.origin ? url : null;
+  }
+
+  function externalURL(value) {
+    const url = parseNavigationURL(value);
+    return url && url.protocol === 'https:' && EXTERNAL_ORIGINS.has(url.origin)
+      ? url : null;
+  }
+
+  function updateStatus(value) {
+    if (typeof value === 'string' && value.length <= 500) {
+      status.textContent = value;
+    }
+  }
+
+  window.addEventListener('message', (event) => {
+    const data = event.data;
+    if (!data || typeof data !== 'object' || Array.isArray(data)) return;
+
+    // Sandboxed frames have an opaque origin ("null"). Origin alone cannot
+    // distinguish them: initialization must come from this particular frame.
+    if (event.origin === 'null') {
+      if (!widgetSender) {
+        if (data.type !== 'widget:init' || !event.source ||
+            event.source !== widget.contentWindow) return;
+        widgetSender = event.source;
+        return;
+      }
+      if (event.source !== widgetSender) return;
+      if (data.type === 'widget:status') updateStatus(data.status);
+      return;
+    }
+
+    if (event.origin !== ORDERING_ORIGIN) return;
+    switch (data.type) {
+      case 'order-status':
+        updateStatus(data.status);
+        break;
+      case 'redirect': {
+        const url = sameSiteURL(data.url);
+        if (url) window.location.assign(url.href);
+        break;
+      }
+      case 'external-link': {
+        const url = externalURL(data.url);
+        if (url) window.open(url.href, '_blank', 'noopener,noreferrer');
+        break;
+      }
+    }
+  });
+
+  // Validate links at activation time as well, including dynamically added links.
+  function validateLink(event) {
+    const link = event.target.closest?.('a[href]');
+    if (!link) return;
+    const value = link.getAttribute('href');
+    const url = sameSiteURL(value) || externalURL(value);
+    if (!url) {
+      event.preventDefault();
+      return;
+    }
+    link.href = url.href;
+    if (link.target === '_blank') {
+      link.relList.add('noopener', 'noreferrer');
+    }
+  }
+  document.addEventListener('click', validateLink);
+  document.addEventListener('auxclick', validateLink);
+
+  // Install the listener before loading the widget so its init cannot race it.
+  // Target the parent's origin; the receiver also checks the child's source.
+  widget.srcdoc = `<!doctype html><html lang="en"><meta charset="utf-8">
+    <title>Coffee order updates</title><p>Order updates will appear above.</p>
+    <script>parent.postMessage({type: 'widget:init'}, ${JSON.stringify(pageURL.origin)});</script></html>`;
+})();
