new file mode 100644
index 0000000..46488f3
--- /dev/null
+++ b/security.test.cjs
@@ -0,0 +1,135 @@
+const { test } = require('node:test');
+const assert = require('node:assert/strict');
+const { readFileSync } = require('node:fs');
+const { runInNewContext } = require('node:vm');
+
+const script = readFileSync(`${__dirname}/security.js`, 'utf8');
+const orderingOrigin = 'https://orders.thedailygrind.com';
+
+function setup() {
+  const listeners = {};
+  const documentListeners = {};
+  const redirects = [];
+  const opened = [];
+  const widget = { contentWindow: {} };
+  const status = { textContent: 'initial' };
+  runInNewContext(script, {
+    URL,
+    window: {
+      location: {
+        href: 'https://www.thedailygrind.com/menu',
+        assign: (url) => redirects.push(url),
+      },
+      open: (...args) => opened.push(args),
+      addEventListener: (type, handler) => { listeners[type] = handler; },
+    },
+    document: {
+      getElementById: (id) => id === 'order-widget' ? widget : status,
+      addEventListener: (type, handler) => { documentListeners[type] = handler; },
+    },
+  });
+  return {
+    widget, status, redirects, opened,
+    message: (data, origin = orderingOrigin, source = {}) =>
+      listeners.message({ data, origin, source }),
+    click(value, type = 'click') {
+      let prevented = false;
+      const rel = new Set();
+      const link = {
+        getAttribute: () => value, target: '_blank',
+        relList: { add: (...values) => values.forEach((value) => rel.add(value)) },
+      };
+      documentListeners[type]({
+        target: { closest: () => link },
+        preventDefault: () => { prevented = true; },
+      });
+      return { prevented, link, rel };
+    },
+  };
+}
+
+test('ordering messages require an exact trusted origin and valid payload', () => {
+  const app = setup();
+  for (const origin of [
+    'https://orders.thedailygrind.com.attacker.test',
+    'http://orders.thedailygrind.com',
+    'https://orders.thedailygrind.com:444',
+    'null', '',
+  ]) {
+    app.message({ type: 'order-status', status: 'spoofed' }, origin);
+  }
+  for (const data of [null, [], 'order-status', {}, { type: 'order-status', status: {} }]) {
+    app.message(data);
+  }
+  assert.equal(app.status.textContent, 'initial');
+  app.message({ type: 'order-status', status: '<b>Brewing</b>' });
+  assert.equal(app.status.textContent, '<b>Brewing</b>');
+});
+
+test('redirects use parsed same-origin URLs and reject deceptive destinations', () => {
+  const app = setup();
+  for (const url of [
+    '//attacker.test/path', 'https://www.thedailygrind.com.attacker.test/',
+    'https://www.thedailygrind.com@attacker.test/',
+    'https://attacker.test/?next=https://www.thedailygrind.com',
+    'https://www.thedailygrind.com:444/', 'http://www.thedailygrind.com/',
+    'https://user:pass@www.thedailygrind.com/',
+    'javascript:alert(1)', 'data:text/html,test', 'https://[', '', null,
+    '/\\attacker.test/',
+  ]) app.message({ type: 'redirect', url });
+  assert.deepEqual(app.redirects, []);
+  app.message({ type: 'redirect', url: '/account?next=a%2Fb#orders' });
+  app.message({ type: 'redirect', url: 'https://WWW.THEDAILYGRIND.COM:443/rewards' });
+  assert.deepEqual(app.redirects, [
+    'https://www.thedailygrind.com/account?next=a%2Fb#orders',
+    'https://www.thedailygrind.com/rewards',
+  ]);
+});
+
+test('external links require an allowlisted HTTPS origin', () => {
+  const app = setup();
+  for (const url of [
+    'https://orders.thedailygrind.com.attacker.test/',
+    'https://orders.thedailygrind.com@attacker.test/',
+    'https://orders.thedailygrind.com:444/',
+    'https://user@orders.thedailygrind.com/',
+    'http://orders.thedailygrind.com/', 'javascript:alert(1)',
+  ]) app.message({ type: 'external-link', url });
+  assert.deepEqual(app.opened, []);
+  app.message({ type: 'external-link', url: `${orderingOrigin}/checkout` });
+  assert.deepEqual(app.opened, [[`${orderingOrigin}/checkout`, '_blank', 'noopener,noreferrer']]);
+});
+
+test('widget initialization pins only the intended iframe and requires init first', () => {
+  const app = setup();
+  const otherFrame = {};
+  app.message({ type: 'widget:init' }, 'null', otherFrame);
+  app.message({ type: 'widget:init' }, 'null', null);
+  app.message({ type: 'widget:status', status: 'too early' }, 'null', app.widget.contentWindow);
+  assert.equal(app.status.textContent, 'initial');
+  app.message({ type: 'widget:init' }, 'null', app.widget.contentWindow);
+  app.message({ type: 'widget:status', status: 'Ready' }, 'null', app.widget.contentWindow);
+  assert.equal(app.status.textContent, 'Ready');
+  app.message({ type: 'widget:init' }, 'null', otherFrame);
+  app.message({ type: 'widget:status', status: 'spoofed' }, 'null', otherFrame);
+  app.message({ type: 'redirect', url: '/logout' }, 'null', app.widget.contentWindow);
+  assert.equal(app.status.textContent, 'Ready');
+  assert.deepEqual(app.redirects, []);
+  app.message({ type: 'widget:status', status: 'Brewing' }, 'null', app.widget.contentWindow);
+  assert.equal(app.status.textContent, 'Brewing');
+});
+
+test('normal and middle-click links share URL validation and safe new-tab relations', () => {
+  const app = setup();
+  for (const type of ['click', 'auxclick']) {
+    for (const url of ['javascript:alert(1)', '//attacker.test/', 'https://orders.thedailygrind.com.attacker.test/']) {
+      assert.equal(app.click(url, type).prevented, true);
+    }
+    const local = app.click('/rewards', type);
+    assert.equal(local.prevented, false);
+    assert.equal(local.link.href, 'https://www.thedailygrind.com/rewards');
+    const external = app.click(`${orderingOrigin}/checkout`, type);
+    assert.equal(external.prevented, false);
+    assert.deepEqual([...external.rel], ['noopener', 'noreferrer']);
+  }
+});

