+++ b/server.mjs
@@ -0,0 +1,39 @@
+import { createServer } from 'node:http';
+import { readFile, mkdir } from 'node:fs/promises';
+import { resolve } from 'node:path';
+import { Readable } from 'node:stream';
+import { createApplication } from './server/app.mjs';
+import { createAccountStore } from './server/store.mjs';
+import { createEmailVerifier } from './server/verify-email.mjs';
+
+const port = Number(process.env.PORT || 11222);
+const origin = new URL(process.env.PUBLIC_ORIGIN || `http://localhost:${port}`).origin;
+if (process.env.NODE_ENV === 'production' && !origin.startsWith('https://')) throw new Error('Set PUBLIC_ORIGIN to the public HTTPS origin');
+const dataDirectory = resolve(process.env.DATA_DIR || './data');
+await mkdir(dataDirectory, { recursive: true, mode: 0o700 });
+const store = createAccountStore(resolve(dataDirectory, 'rewards.sqlite'));
+const verifyEmail = createEmailVerifier({
+  ...(process.env.TRUSTED_ISSUER_ORIGINS && { trustedOrigins: process.env.TRUSTED_ISSUER_ORIGINS.split(',').map((value) => value.trim()) }),
+});
+const handle = createApplication({
+  template: await readFile(new URL('./index.html', import.meta.url), 'utf8'),
+  origin, trialToken: process.env.EMAIL_VERIFICATION_ORIGIN_TRIAL_TOKEN || '', store, verifyEmail,
+});
+
+const server = createServer(async (incoming, outgoing) => {
+  try {
+    const request = new Request(new URL(incoming.url, origin), {
+      method: incoming.method, headers: incoming.headers,
+      ...(!['GET', 'HEAD'].includes(incoming.method) && { body: Readable.toWeb(incoming), duplex: 'half' }),
+    });
+    const response = await handle(request);
+    outgoing.writeHead(response.status, Object.fromEntries(response.headers));
+    outgoing.end(Buffer.from(await response.arrayBuffer()));
+  } catch {
+    outgoing.writeHead(500, { 'Content-Type': 'text/plain', 'Cache-Control': 'no-store' });
+    outgoing.end('Something went wrong. Please return to the homepage and try again.');
+  }
+});
+server.requestTimeout = 15000;
+server.listen(port, () => console.log(`Daily Grind listening on port ${port}`));
+for (const signal of ['SIGTERM', 'SIGINT']) process.on(signal, () => server.close(() => { store.close(); process.exit(0); }));
diff --git a/server/app.mjs b/server/app.mjs
new file mode 100644
index 0000000..5eeaa7d
--- /dev/null
+++ b/server/app.mjs
@@ -0,0 +1,81 @@
+import { randomBytes } from 'node:crypto';
+
+const random = () => randomBytes(32).toString('base64url');
+const escapeHtml = (value) => String(value).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
+const maxBody = 32768;
+
+export function createApplication({ template, origin, trialToken = '', store, verifyEmail, now = Date.now }) {
+  const sessions = new Map();
+  const secure = new URL(origin).protocol === 'https:';
+  const cookieName = secure ? '__Host-dg_signup' : 'dg_signup';
+  function page({ status = 200, message = '', name = '', email = '', success = false } = {}) {
+    for (const [id, session] of sessions) if (session.expires <= now()) sessions.delete(id);
+    if (sessions.size >= 10000) return new Response('Please try again shortly.', { status: 503 });
+    const id = random();
+    const session = { nonce: random(), csrf: random(), expires: now() + 10 * 60 * 1000 };
+    sessions.set(id, session);
+    const values = {
+      STATUS: message, NAME: name, EMAIL: email, NONCE: session.nonce, CSRF: session.csrf,
+      SUCCESS_HIDDEN: success ? '' : 'hidden', FORM_HIDDEN: success ? 'hidden' : '',
+    };
+    const html = template.replace(/__(STATUS|NAME|EMAIL|NONCE|CSRF|SUCCESS_HIDDEN|FORM_HIDDEN)__/g, (_, key) => escapeHtml(values[key]));
+    const headers = new Headers({
+      'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-store',
+      'Set-Cookie': `${cookieName}=${id}; HttpOnly; SameSite=Lax; Path=/; Max-Age=600${secure ? '; Secure' : ''}`,
+      'X-Content-Type-Options': 'nosniff', 'Referrer-Policy': 'same-origin',
+      'Content-Security-Policy': "default-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' https://images.unsplash.com; form-action 'self'; frame-ancestors 'none'; base-uri 'none'",
+    });
+    if (trialToken) headers.set('Origin-Trial', trialToken);
+    return new Response(html, { status, headers });
+  }
+
+  return async function handle(request) {
+    const path = new URL(request.url).pathname;
+    if (path === '/' && request.method === 'GET') return page();
+    if (path !== '/api/verify-email') return new Response('Not found', { status: 404 });
+    if (request.method !== 'POST') return new Response('Method not allowed', { status: 405, headers: { Allow: 'POST' } });
+    if (request.headers.get('origin') !== origin) return new Response('Invalid request origin', { status: 403 });
+    const cookie = request.headers.get('cookie') || '';
+    const id = cookie.split(';').map((part) => part.trim()).find((part) => part.startsWith(`${cookieName}=`))?.slice(cookieName.length + 1);
+    const session = sessions.get(id);
+    sessions.delete(id); // Consume before awaiting I/O; concurrent replays cannot reuse the nonce.
+    if (!session || session.expires <= now()) return page({ status: 409, message: 'Your sign-up form expired or was already submitted. Please try again with this fresh form.' });
+    if (!request.headers.get('content-type')?.startsWith('application/x-www-form-urlencoded')) {
+      return page({ status: 415, message: 'Please submit the sign-up form below.' });
+    }
+    let body = '';
+    let size = 0;
+    const reader = request.body?.getReader();
+    if (reader) {
+      const chunks = [];
+      while (true) {
+        const { done, value } = await reader.read();
+        if (done) break;
+        size += value.length;
+        if (size > maxBody) { await reader.cancel(); return page({ status: 413, message: 'The form was too large. Please try again.' }); }
+        chunks.push(value);
+      }
+      body = Buffer.concat(chunks).toString('utf8');
+    }
+    const form = new URLSearchParams(body);
+    if (form.get('csrf') !== session.csrf) return page({ status: 403, message: 'We couldn’t confirm this form. Please try again.' });
+    const name = (form.get('name') || '').trim();
+    const email = (form.get('email') || '').trim();
+    if (!name || name.length > 100 || email.length > 254 || !/^[^\s@]+@[a-z0-9](?:[a-z0-9.-]*[a-z0-9])?\.[a-z]{2,}$/i.test(email)) {
+      return page({ status: 422, name: name.slice(0, 100), email: email.slice(0, 254), message: 'Please enter your full name and a valid email address.' });
+    }
+    const rawToken = (form.get('token') || '').trim();
+    if (!rawToken) return page({ status: 422, name, email, message: 'Your browser didn’t provide email verification. Use a supported browser, sign in to your email provider in the same browser, then reselect or re-enter your address and allow verification. No email was sent and no account was created.' });
+    try {
+      await verifyEmail({ rawToken, submittedEmail: email, expectedNonce: session.nonce, expectedAudience: origin });
+    } catch {
+      return page({ status: 422, name, email, message: 'We couldn’t verify your email. Please reselect or re-enter your address, allow browser verification, and try again. No email was sent and no account was created.' });
+    }
+    try {
+      const created = store.create({ name, email });
+      return page({ success: true, message: created ? '' : 'This email already has a rewards account. Your existing account has been kept.' });
+    } catch {
+      return page({ status: 503, name, email, message: 'We couldn’t save your account right now. Please try again shortly.' });
+    }
+  };
+}
