new file mode 100644
index 0000000..c631281
--- /dev/null
+++ b/server/store.mjs
@@ -0,0 +1,20 @@
+import { DatabaseSync } from 'node:sqlite';
+import { randomUUID } from 'node:crypto';
+
+export function createAccountStore(path) {
+  const db = new DatabaseSync(path);
+  db.exec(`PRAGMA journal_mode = WAL;
+    CREATE TABLE IF NOT EXISTS rewards_accounts (
+      id TEXT PRIMARY KEY, email TEXT NOT NULL, email_key TEXT NOT NULL UNIQUE,
+      name TEXT NOT NULL, email_verified_at TEXT NOT NULL, points INTEGER NOT NULL DEFAULT 0
+    );`);
+  const insert = db.prepare(`INSERT INTO rewards_accounts
+    (id, email, email_key, name, email_verified_at) VALUES (?, ?, ?, ?, ?)
+    ON CONFLICT(email_key) DO NOTHING`);
+  return {
+    create({ email, name }) {
+      return insert.run(randomUUID(), email, email.toLowerCase(), name, new Date().toISOString()).changes === 1;
+    },
+    close: () => db.close(),
+  };
+}
diff --git a/server/verify-email.mjs b/server/verify-email.mjs
new file mode 100644
index 0000000..ef62d33
--- /dev/null
+++ b/server/verify-email.mjs
@@ -0,0 +1,93 @@
+import { createHash } from 'node:crypto';
+import { resolveTxt } from 'node:dns/promises';
+import { decodeSdJwtSync, SdJwtInstance } from '@sd-jwt/core';
+import { createRemoteJWKSet, importJWK, jwtVerify } from 'jose';
+
+const algorithms = ['Ed25519', 'EdDSA', 'ES256'];
+const normalize = (alg) => alg === 'Ed25519' ? 'EdDSA' : alg;
+const hasher = (data, alg) => {
+  if (alg !== 'sha-256') throw new Error('Unsupported digest');
+  return createHash('sha256').update(data).digest();
+};
+
+// Only administrator-configured HTTPS origins may receive discovery/key requests.
+// DNS delegation alone must not allow user-controlled tokens to probe internal URLs.
+export function createEmailVerifier({
+  trustedOrigins = ['https://accounts.google.com', 'https://www.googleapis.com', 'https://oauth2.googleapis.com'],
+  lookupTxt = resolveTxt,
+  fetchMetadata = fetch,
+  loadKeys = (url) => createRemoteJWKSet(url, { timeoutDuration: 5000 }),
+} = {}) {
+  const trusted = new Set(trustedOrigins);
+  function trustedUrl(value) {
+    const url = new URL(value);
+    if (url.protocol !== 'https:' || url.username || url.password || url.hash || !trusted.has(url.origin)) {
+      throw new Error('Untrusted issuer or key URL');
+    }
+    return url;
+  }
+
+  return async function verifyEmail({ rawToken, submittedEmail, expectedNonce, expectedAudience }) {
+    if (!expectedNonce || !rawToken || rawToken.length > 24000) throw new Error('Missing or oversized proof');
+    const decoded = decodeSdJwtSync(rawToken, hasher);
+    const claims = decoded.jwt.payload;
+    if (!decoded.kbJwt || typeof claims.iss !== 'string' || claims.email_verified !== true ||
+        typeof claims.email !== 'string' || claims.email.toLowerCase() !== submittedEmail.toLowerCase()) {
+      throw new Error('Invalid email claims');
+    }
+    const issuer = trustedUrl(claims.iss);
+    if (issuer.origin !== claims.iss) throw new Error('Issuer must be a canonical HTTPS origin');
+    const domain = submittedEmail.slice(submittedEmail.lastIndexOf('@') + 1).toLowerCase();
+    const records = await lookupTxt(`_email-verification.${domain}`);
+    if (!records.some((parts) => `https://${parts.join('').slice(4).trim()}` === claims.iss && parts.join('').startsWith('iss='))) {
+      throw new Error('Issuer is not delegated by the email domain');
+    }
+    const response = await fetchMetadata(new URL('/.well-known/email-verification', issuer), {
+      redirect: 'error', signal: AbortSignal.timeout(5000),
+    });
+    if (!response.ok) throw new Error('Issuer discovery failed');
+    const metadata = await response.json();
+    if (metadata.issuer !== claims.iss || typeof metadata.jwks_uri !== 'string') throw new Error('Invalid discovery metadata');
+    const keys = loadKeys(trustedUrl(metadata.jwks_uri));
+    const evtOptions = {
+      typ: 'ev+sd-jwt', issuer: claims.iss, algorithms,
+      requiredClaims: ['iss', 'iat', 'exp', 'email', 'email_verified', 'cnf'],
+      maxTokenAge: '5m', clockTolerance: 60,
+    };
+    const instance = new SdJwtInstance({
+      hasher,
+      verifier: async (data, signature) => {
+        const jwt = `${data}.${signature}`;
+        try {
+          await jwtVerify(jwt, keys, evtOptions);
+        } catch (error) {
+          if (error.code !== 'ERR_JWKS_MULTIPLE_MATCHING_KEYS') throw error;
+          let verified = false;
+          for await (const key of error) {
+            try { await jwtVerify(jwt, key, evtOptions); verified = true; break; } catch {}
+          }
+          if (!verified) throw error;
+        }
+        return true;
+      },
+      kbVerifier: async (data, signature) => {
+        const jwk = claims.cnf?.jwk;
+        const alg = decoded.kbJwt.header.alg;
+        if (!jwk || jwk.d || !algorithms.includes(jwk.alg) || !algorithms.includes(alg) || normalize(jwk.alg) !== normalize(alg)) {
+          throw new Error('Invalid browser binding key');
+        }
+        const key = await importJWK(jwk, alg);
+        await jwtVerify(`${data}.${signature}`, key, {
+          typ: 'kb+jwt', audience: expectedAudience, algorithms: [alg],
+          requiredClaims: ['aud', 'nonce', 'iat', 'sd_hash'], maxTokenAge: '5m', clockTolerance: 60,
+        });
+        return true;
+      },
+    });
+    await instance.verify(rawToken, {
+      requiredClaimKeys: ['email', 'email_verified'], keyBindingNonce: expectedNonce,
+      expectedKeyBindingAudience: expectedAudience, keyBindingMaxAgeSeconds: 300, skewSeconds: 60,
+    });
+    return { email: claims.email };
+  };
+}
diff --git a/tests/rewards.test.mjs b/tests/rewards.test.mjs
new file mode 100644
index 0000000..2042aa8
--- /dev/null
+++ b/tests/rewards.test.mjs
@@ -0,0 +1,167 @@
+import test from 'node:test';
+import assert from 'node:assert/strict';
+import { readFile, mkdtemp, rm } from 'node:fs/promises';
+import { tmpdir } from 'node:os';
+import { join } from 'node:path';
+import { createHash } from 'node:crypto';
+import { SignJWT, createLocalJWKSet, exportJWK, generateKeyPair } from 'jose';
+import { createEmailVerifier } from '../server/verify-email.mjs';
+import { createApplication } from '../server/app.mjs';
+import { createAccountStore } from '../server/store.mjs';
+
+const origin = 'https://coffee.example';
+const issuer = 'https://issuer.example';
+const email = 'coffee@example.com';
+const issuerKey = await generateKeyPair('ES256');
+const holderKey = await generateKeyPair('ES256');
+const otherKey = await generateKeyPair('ES256');
+const attackerKey = await generateKeyPair('ES256');
+const publicIssuer = { ...await exportJWK(issuerKey.publicKey), alg: 'ES256' };
+const publicHolder = { ...await exportJWK(holderKey.publicKey), alg: 'ES256' };
+const publicOther = { ...await exportJWK(otherKey.publicKey), alg: 'ES256' };
+
+async function proof({ claims = {}, binding = {}, signingKey = issuerKey.privateKey, holderSigningKey = holderKey.privateKey } = {}) {
+  const now = Math.floor(Date.now() / 1000);
+  const evt = await new SignJWT({ iss: issuer, iat: now, exp: now + 180, email, email_verified: true, cnf: { jwk: publicHolder }, ...claims })
+    .setProtectedHeader({ alg: 'ES256', typ: 'ev+sd-jwt' }).sign(signingKey);
+  const hash = createHash('sha256').update(`${evt}~`).digest('base64url');
+  const kb = await new SignJWT({ aud: origin, nonce: 'session-nonce', iat: now, sd_hash: hash, ...binding })
+    .setProtectedHeader({ alg: 'ES256', typ: 'kb+jwt' }).sign(holderSigningKey);
+  return `${evt}~${kb}`;
+}
+
+function verifier(overrides = {}) {
+  return createEmailVerifier({
+    trustedOrigins: [issuer], lookupTxt: async () => [['iss=issuer.', 'example']],
+    fetchMetadata: async () => Response.json({ issuer, jwks_uri: `${issuer}/keys` }),
+    // Multiple matching keys deliberately omit kid, matching major providers.
+    loadKeys: () => createLocalJWKSet({ keys: [publicOther, publicIssuer] }), ...overrides,
+  });
+}
+const verifyArgs = { submittedEmail: 'COFFEE@EXAMPLE.COM', expectedNonce: 'session-nonce', expectedAudience: origin };
+
+test('verifies both signatures, case-insensitive email, and an issuer JWKS without kid', async () => {
+  assert.deepEqual(await verifier()({ ...verifyArgs, rawToken: await proof() }), { email });
+});
+
+for (const [name, changes] of [
+  ['different email', { claims: { email: 'someone@example.com' } }],
+  ['unverified email', { claims: { email_verified: false } }],
+  ['expired proof', { claims: { exp: 1 } }],
+  ['missing expiry', { claims: { exp: undefined } }],
+  ['stale proof', { claims: { iat: 1 } }],
+  ['future issuance', { claims: { iat: Math.floor(Date.now() / 1000) + 600 } }],
+  ['wrong nonce', { binding: { nonce: 'wrong' } }],
+  ['wrong origin', { binding: { aud: 'https://evil.example' } }],
+  ['stale browser binding', { binding: { iat: 1 } }],
+  ['wrong token hash', { binding: { sd_hash: 'wrong' } }],
+  ['forged issuer signature', { signingKey: attackerKey.privateKey }],
+  ['forged holder signature', { holderSigningKey: otherKey.privateKey }],
+]) test(`rejects ${name}`, async () => {
+  await assert.rejects(verifier()({ ...verifyArgs, rawToken: await proof(changes) }));
+});
+
+test('rejects absent key binding, malformed tokens, and missing server nonce', async () => {
+  const token = await proof();
+  for (const rawToken of ['', 'invalid', `${token.split('~')[0]}~`]) {
+    await assert.rejects(verifier()({ ...verifyArgs, rawToken }));
+  }
+  await assert.rejects(verifier()({ ...verifyArgs, rawToken: token, expectedNonce: '' }));
+});
+
+test('requires DNS delegation before any issuer fetch', async () => {
+  let fetched = false;
+  const verify = verifier({ lookupTxt: async () => [['iss=evil.example']], fetchMetadata: async () => { fetched = true; } });
+  await assert.rejects(verify({ ...verifyArgs, rawToken: await proof() }));
+  assert.equal(fetched, false);
+});
+
+test('rejects mismatched metadata and untrusted JWKS URLs', async () => {
+  for (const metadata of [{ issuer: 'https://evil.example', jwks_uri: `${issuer}/keys` }, { issuer, jwks_uri: 'http://127.0.0.1/keys' }, { issuer, jwks_uri: 'https://internal.example/keys' }]) {
+    await assert.rejects(verifier({ fetchMetadata: async () => Response.json(metadata) })({ ...verifyArgs, rawToken: await proof() }));
+  }
+});
+
+const template = await readFile(new URL('../index.html', import.meta.url), 'utf8');
+function application({ verifyEmail = async () => ({ email }), ...options } = {}) {
+  const accounts = [];
+  const handle = createApplication({ template, origin, verifyEmail, store: { create: (account) => { accounts.push(account); return true; } }, ...options });
+  return { handle, accounts };
+}
+async function formSession(handle) {
+  const page = await handle(new Request(origin));
+  const html = await page.text();
+  return { page, html, cookie: page.headers.get('set-cookie').split(';')[0], csrf: html.match(/name="csrf" value="([^"]+)"/)[1], nonce: html.match(/nonce="([^"]+)"/)[1] };
+}
+function submit(handle, session, fields = {}, headers = {}) {
+  return handle(new Request(`${origin}/api/verify-email`, {
+    method: 'POST', headers: { origin, cookie: session.cookie, 'content-type': 'application/x-www-form-urlencoded', ...headers },
+    body: new URLSearchParams({ name: 'Café Customer', email, csrf: session.csrf, token: 'proof', ...fields }),
+  }));
+}
+
+test('renders unique server nonces, secure session cookies, and trial header', async () => {
+  const { handle } = application({ trialToken: 'deployment-token' });
+  const first = await formSession(handle);
+  const second = await formSession(handle);
+  assert.notEqual(first.nonce, second.nonce);
+  assert.match(first.page.headers.get('set-cookie'), /HttpOnly; SameSite=Lax; Path=\/; Max-Age=600; Secure/);
+  assert.equal(first.page.headers.get('cache-control'), 'no-store');
+  assert.equal(first.page.headers.get('origin-trial'), 'deployment-token');
+  assert.doesNotMatch(first.html, /__(NONCE|CSRF|STATUS)__/);
+});
+
+test('passes server-held nonce and origin to verifier and creates account only once', async () => {
+  let received;
+  const { handle, accounts } = application({ verifyEmail: async (args) => { received = args; } });
+  const session = await formSession(handle);
+  const responses = await Promise.all([submit(handle, session), submit(handle, session)]);
+  assert.deepEqual(responses.map((r) => r.status), [200, 409]);
+  assert.equal(accounts.length, 1);
+  assert.equal(received.expectedNonce, session.nonce);
+  assert.equal(received.expectedAudience, origin);
+  assert.match(await responses[0].text(), /Your email is verified and your rewards account is ready/);
+});
+
+test('missing/invalid verification proofs do not create accounts and render fresh retry forms', async () => {
+  for (const missing of [true, false]) {
+    const { handle, accounts } = application({ verifyEmail: async () => { throw new Error('bad proof'); } });
+    const session = await formSession(handle);
+    const response = await submit(handle, session, { token: missing ? '' : 'invalid' });
+    assert.equal(response.status, 422);
+    assert.equal(accounts.length, 0);
+    const html = await response.text();
+    assert.match(html, /No email was sent and no account was created/);
+    assert.match(html, /value="Café Customer"/);
+    assert.notEqual(html.match(/nonce="([^"]+)"/)[1], session.nonce);
+  }
+});
+
+test('rejects CSRF, invalid fields, stale sessions, and escaped name injection', async () => {
+  const { handle, accounts } = application();
+  assert.equal((await submit(handle, await formSession(handle), {}, { origin: 'https://evil.example' })).status, 403);
+  assert.equal((await submit(handle, await formSession(handle), { csrf: 'wrong' })).status, 403);
+  assert.equal((await submit(handle, await formSession(handle), { email: 'bad', name: '"><script>alert(1)</script>' })).status, 422);
+  const response = await submit(handle, await formSession(handle), { email: 'bad', name: '<script>' });
+  const html = await response.text();
+  assert.match(html, /value="&lt;script&gt;"/);
+  assert.doesNotMatch(html, /value="<script>/);
+  let current = 0;
+  const expiring = application({ now: () => current });
+  const old = await formSession(expiring.handle);
+  current = 601000;
+  assert.equal((await submit(expiring.handle, old)).status, 409);
+  assert.equal(accounts.length, 0);
+});
+
+test('durably stores verified accounts and prevents case-insensitive duplicate registrations', async () => {
+  const dir = await mkdtemp(join(tmpdir(), 'dg-test-'));
+  const path = join(dir, 'accounts.sqlite');
+  let store = createAccountStore(path);
+  try {
+    assert.equal(store.create({ email, name: 'Coffee Customer' }), true);
+    store.close();
+    store = createAccountStore(path);
+    assert.equal(store.create({ email: email.toUpperCase(), name: 'Changed' }), false);
+  } finally { store.close(); await rm(dir, { recursive: true, force: true }); }
+});

