+const form = document.querySelector('#rewards-form');
+const status = document.querySelector('#form-status');
+let state = {};
+try { state = JSON.parse(document.querySelector('#page-state').textContent); } catch { /* Static source preview has no server state. */ }
+if (state.draft) {
+  for (const key of ['firstName', 'lastName', 'email']) form.elements[key].value = state.draft[key] || '';
+  form.elements.marketing.checked = Boolean(state.draft.marketing);
+}
+if (state.error) {
+  status.textContent = state.error;
+  form.elements.email.setAttribute('aria-describedby', 'form-status');
+}
+if (state.ok) {
+  form.hidden = true;
+  document.querySelector('.welcome-perk').hidden = true;
+  document.querySelector('.secure-note').hidden = true;
+  document.querySelector('#success-panel').hidden = false;
+  document.querySelector('#success-copy').textContent = `Welcome, ${state.account.firstName}! Your email is verified and your rewards account is ready. Your next coffee just got a little sweeter.`;
+}
+// Keep native submission: the browser populates the EVP field during submission.
+form.addEventListener('submit', (event) => {
+  if (form.elements.csrf.value === '__EVP_NONCE__') {
+    event.preventDefault();
+    status.textContent = 'Registration needs the Daily Grind server. Please open the hosted site to securely verify your email.';
+    return;
+  }
+  const button = form.querySelector('[type="submit"]');
+  button.querySelector('span').textContent = 'Verifying your email…';
+  button.disabled = true;
+});
+window.addEventListener('pageshow', () => {
+  const button = form.querySelector('[type="submit"]');
+  button.disabled = false;
+  button.querySelector('span').textContent = 'Create my rewards account';
+});
+const policies = {
+  terms: { title: 'Rewards Terms', copy: ['Membership is free. Receive 50 welcome points once per verified email address. Earn 1 point per $1 on eligible purchases and redeem 100 points for a standard handcrafted drink at participating Daily Grind locations.', 'Points have no cash value and cannot be transferred. Offers may vary by location. Email verification is required to create a membership. Optional marketing consent is never required to join.'] },
+  privacy: { title: 'Your privacy matters.', copy: ['We store your name, verified email address, rewards balance, registration date, and consent choices to manage your rewards membership. A secure browser session keeps your registration connected to you.', 'Your browser shares a signed verification token from your email provider. We validate it securely; we do not read your inbox, send verification emails, or retain the token. If you opt in to offers, you can unsubscribe at any time.'] },
+};
+const dialog = document.querySelector('#policy-dialog');
+document.querySelectorAll('[data-policy]').forEach(button => button.addEventListener('click', () => {
+  const policy = policies[button.dataset.policy];
+  document.querySelector('#policy-title').textContent = policy.title;
+  document.querySelector('#policy-copy').replaceChildren(...policy.copy.map(text => { const p = document.createElement('p'); p.textContent = text; return p; }));
+  dialog.showModal();
+}));
+dialog.querySelector('.dialog-close').addEventListener('click', () => dialog.close());
+dialog.addEventListener('click', event => { if (event.target === dialog) { const rect = dialog.getBoundingClientRect(); if (event.clientX < rect.left || event.clientX > rect.right || event.clientY < rect.top || event.clientY > rect.bottom) dialog.close(); } });
