+const hash = value => createHash('sha256').update(value).digest('hex');
+export function createStore(path) {
+  if (path !== ':memory:') mkdirSync(dirname(path), { recursive: true });
+  const db = new DatabaseSync(path);
+  db.exec(`PRAGMA journal_mode=WAL; PRAGMA busy_timeout=5000;
+    CREATE TABLE IF NOT EXISTS accounts (id TEXT PRIMARY KEY, email TEXT UNIQUE NOT NULL COLLATE NOCASE, first_name TEXT NOT NULL, last_name TEXT NOT NULL, marketing INTEGER NOT NULL, points INTEGER NOT NULL DEFAULT 50, verified_at INTEGER NOT NULL, terms_version TEXT NOT NULL);
+    CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY, nonce TEXT, nonce_at INTEGER, expires INTEGER NOT NULL, account_id TEXT, flash TEXT);
+    CREATE TABLE IF NOT EXISTS rate_limits (key TEXT PRIMARY KEY, attempts INTEGER NOT NULL, expires INTEGER NOT NULL);`);
+  return {
+    session(cookie) {
+      const now = Date.now();
+      db.prepare('DELETE FROM sessions WHERE expires < ?').run(now);
+      db.prepare('DELETE FROM rate_limits WHERE expires < ?').run(now);
+      let row = cookie && /^[a-f0-9]{64}$/.test(cookie) ? db.prepare('SELECT * FROM sessions WHERE id = ?').get(hash(cookie)) : null;
+      let secret = cookie;
+      if (!row) {
+        secret = randomBytes(32).toString('hex');
+        const id = hash(secret);
+        db.prepare('INSERT INTO sessions(id, expires) VALUES (?, ?)').run(id, now + 3600000);
+        row = db.prepare('SELECT * FROM sessions WHERE id = ?').get(id);
+      }
+      return { ...row, secret };
+    },
+    challenge(session) {
+      const nonce = randomBytes(32).toString('base64url');
+      db.prepare('UPDATE sessions SET nonce = ?, nonce_at = ? WHERE id = ?').run(nonce, Date.now(), session.id);
+      return nonce;
+    },
+    consume(session, csrf) {
+      if (typeof csrf !== 'string') return null;
+      const result = db.prepare('UPDATE sessions SET nonce = NULL WHERE id = ? AND nonce = ? AND nonce_at > ? RETURNING nonce_at').get(session.id, csrf, Date.now() - 600000);
+      return result ? csrf : null;
+    },
+    rateLimit(ip) {
+      const key = hash(ip);
+      db.prepare('INSERT INTO rate_limits VALUES (?, 1, ?) ON CONFLICT(key) DO UPDATE SET attempts = attempts + 1').run(key, Date.now() + 600000);
+      return db.prepare('SELECT attempts FROM rate_limits WHERE key = ?').get(key).attempts <= 15;
+    },
+    flash(session, state) { db.prepare('UPDATE sessions SET flash = ? WHERE id = ?').run(JSON.stringify(state), session.id); },
+    takeFlash(session) {
+      db.prepare('UPDATE sessions SET flash = NULL WHERE id = ?').run(session.id);
+      return session.flash ? JSON.parse(session.flash) : {};
+    },
+    createAccount(session, { email, firstName, lastName, marketing }) {
+      const account = { id: randomUUID(), email: email.toLowerCase(), firstName, lastName, points: 50 };
+      // UNIQUE email is enforced by SQLite, including concurrent registrations.
+      db.prepare('INSERT INTO accounts(id,email,first_name,last_name,marketing,verified_at,terms_version) VALUES (?,?,?,?,?,?,?)').run(account.id, account.email, firstName, lastName, marketing ? 1 : 0, Date.now(), '2026-11-19');
+      db.prepare('UPDATE sessions SET account_id = ? WHERE id = ?').run(account.id, session.id);
+      return account;
+    },
+    close() { db.close(); },
+  };
+}
