new file mode 100644
index 0000000..06fb98d
--- /dev/null
+++ b/lib/verify-email.mjs
@@ -0,0 +1,99 @@
+import { createHash } from 'node:crypto';
+import { resolveTxt } from 'node:dns/promises';
+import { decodeSdJwtSync, SdJwtInstance } from '@sd-jwt/core';
+import { importJWK, compactVerify } from 'jose';
+
+// Explicitly trusted network destinations: never fetch a URL supplied by a token.
+// Add a provider here only after reviewing its HTTPS discovery and JWKS origins.
+const providers = {
+  'https://accounts.google.com': {
+    discovery: 'https://accounts.google.com/.well-known/email-verification',
+    jwks: 'https://verifiablecredentials-pa.googleapis.com/.well-known/vc-public-jwks',
+  },
+};
+const algorithms = ['EdDSA', 'Ed25519', 'ES256'];
+const hasher = (data, alg) => {
+  if (alg !== 'sha-256') throw new Error('Unsupported digest');
+  return createHash('sha256').update(data).digest();
+};
+const cache = new Map();
+async function fetchJson(url) {
+  const cached = cache.get(url);
+  if (cached && cached.expires > Date.now()) return cached.value;
+  const response = await fetch(url, { redirect: 'error', signal: AbortSignal.timeout(5000), headers: { Accept: 'application/json' } });
+  if (!response.ok) throw new Error('Provider unavailable');
+  const reader = response.body.getReader();
+  const chunks = []; let size = 0;
+  try {
+    while (true) {
+      const { done, value } = await reader.read();
+      if (done) break;
+      size += value.length;
+      if (size > 100_000) throw new Error('Provider response too large');
+      chunks.push(Buffer.from(value));
+    }
+  } finally { await reader.cancel(); }
+  const value = JSON.parse(Buffer.concat(chunks).toString('utf8'));
+  cache.set(url, { value, expires: Date.now() + 300_000 });
+  return value;
+}
+
+export async function verifyEmailToken({ token, email, nonce, origin }, dependencies = {}) {
+  const dns = dependencies.resolveTxt ?? resolveTxt;
+  const getJson = dependencies.fetchJson ?? fetchJson;
+  const now = dependencies.now ?? Math.floor(Date.now() / 1000);
+  if (typeof token !== 'string' || !token || token.length > 18000 || !nonce) throw new Error('Missing verification');
+  const decoded = decodeSdJwtSync(token, hasher);
+  const evt = decoded.jwt?.payload;
+  const kb = decoded.kbJwt?.payload;
+  const issuer = evt?.iss;
+  const provider = providers[issuer];
+  if (!provider || decoded.jwt.header.typ !== 'evt+jwt' || !kb || !algorithms.includes(decoded.jwt.header.alg) || !algorithms.includes(decoded.kbJwt.header.alg)) throw new Error('Unsupported verification');
+  const validTime = (payload, requireExpiry) => Number.isInteger(payload?.iat) && payload.iat <= now + 30 && payload.iat >= now - 600 && (!requireExpiry || (Number.isInteger(payload.exp) && payload.exp > now && payload.exp > payload.iat));
+  if (!validTime(evt, true) || !validTime(kb, false) || (kb.exp !== undefined && (!Number.isInteger(kb.exp) || kb.exp <= now))) throw new Error('Expired verification');
+  if (kb.aud !== origin || kb.nonce !== nonce) throw new Error('Verification binding mismatch');
+  const domain = email.split('@')[1]?.toLowerCase();
+  if (!domain || !/^(?:[a-z0-9](?:[a-z0-9-]*[a-z0-9])?\.)+[a-z]{2,63}$/.test(domain)) throw new Error('Invalid email domain');
+  const records = await dns(`_email-verification.${domain}`);
+  const delegated = records.some(parts => parts.join('').trim() === `iss=${new URL(issuer).host}`);
+  if (!delegated) throw new Error('Provider not delegated');
+  const metadata = await getJson(provider.discovery);
+  if ((metadata.issuer !== undefined && metadata.issuer !== issuer) || metadata.jwks_uri !== provider.jwks) throw new Error('Untrusted provider metadata');
+  const jwks = await getJson(provider.jwks);
+  if (!Array.isArray(jwks.keys) || jwks.keys.length > 50) throw new Error('Invalid provider keys');
+  const sdJwt = new SdJwtInstance({
+    hasher,
+    verifier: async (data, sig) => {
+      const header = decoded.jwt.header;
+      for (const jwk of jwks.keys.filter(key => !header.kid || key.kid === header.kid)) {
+        if (jwk.d || (jwk.use && jwk.use !== 'sig') || (jwk.alg && jwk.alg !== header.alg)) continue;
+        try {
+          const key = await importJWK(jwk, header.alg);
+          await compactVerify(`${data}.${sig}`, key, { algorithms });
+          return true;
+        } catch { /* Other keys may match when the issuer omits kid. */ }
+      }
+      return false;
+    },
+    kbVerifier: async (data, sig, payload) => {
+      try {
+        if (!payload.cnf?.jwk || payload.cnf.jwk.d) return false;
+        const key = await importJWK(payload.cnf.jwk, decoded.kbJwt.header.alg);
+        await compactVerify(`${data}.${sig}`, key, { algorithms });
+        return true;
+      } catch { return false; }
+    },
+  });
+  const verified = await sdJwt.verify(token, {
+    keyBindingNonce: nonce,
+    expectedKeyBindingAudience: origin,
+    keyBindingMaxAgeSeconds: 600,
+    maxAgeSeconds: 600,
+    currentDate: now,
+    skewSeconds: 0,
+    allowedIssuerAlgorithms: algorithms,
+    allowedKeyBindingAlgorithms: algorithms,
+  });
+  if (verified.payload.email_verified !== true || typeof verified.payload.email !== 'string' || verified.payload.email.toLowerCase() !== email.toLowerCase()) throw new Error('Email mismatch');
+  return { email: verified.payload.email, issuer };
+}
