--- /dev/null
+++ b/server.mjs
@@ -0,0 +1,85 @@
+import { createServer } from 'node:http';
+import { readFile } from 'node:fs/promises';
+import { resolve } from 'node:path';
+import { createStore } from './lib/store.mjs';
+import { verifyEmailToken } from './lib/verify-email.mjs';
+
+const root = new URL('.', import.meta.url);
+const store = createStore(process.env.DATABASE_PATH || resolve('data/rewards.sqlite'));
+const configuredOrigin = process.env.APP_ORIGIN ? new URL(process.env.APP_ORIGIN).origin : null;
+if (process.env.NODE_ENV === 'production' && (!configuredOrigin || !configuredOrigin.startsWith('https://'))) throw new Error('Set APP_ORIGIN to the public HTTPS origin in production.');
+const staticFiles = { '/styles.css': ['styles.css', 'text/css'], '/app.js': ['app.js', 'text/javascript'] };
+const errors = {
+  unsupported: 'Your browser or email provider couldn’t verify this address. Try a supported Chrome browser with your email provider signed in, then submit again. We haven’t created an account or sent an email.',
+  expired: 'This form has expired or was already submitted. Please try again with the refreshed form below.',
+  invalid: 'Please enter your first name, last name, and a valid email, and agree to the Rewards Terms.',
+  verification: 'We couldn’t confirm your email securely. Check the address and try again. Your account hasn’t been created.',
+  duplicate: 'A rewards account already uses this email address. Your existing account and points are unchanged.',
+  limited: 'A few too many attempts. Please wait 10 minutes before trying again.',
+};
+const html = await readFile(new URL('index.html', root), 'utf8');
+const server = createServer(async (req, res) => {
+  res.setHeader('X-Content-Type-Options', 'nosniff');
+  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
+  res.setHeader('X-Frame-Options', 'DENY');
+  res.setHeader('Cache-Control', 'no-store');
+  const origin = configuredOrigin || `http://${req.headers.host}`;
+  const secure = origin.startsWith('https://');
+  if (secure) res.setHeader('Strict-Transport-Security', 'max-age=31536000');
+  const send = (status, body, type = 'text/plain; charset=utf-8') => { res.writeHead(status, { 'Content-Type': type }); res.end(body); };
+  try {
+    const url = new URL(req.url, origin);
+    if (req.method === 'GET' && staticFiles[url.pathname]) {
+      const [file, type] = staticFiles[url.pathname];
+      return send(200, await readFile(new URL(file, root)), `${type}; charset=utf-8`);
+    }
+    if (!['/', '/api/rewards/signup'].includes(url.pathname)) return send(404, 'Not found');
+    if ((url.pathname === '/' && req.method !== 'GET') || (url.pathname !== '/' && req.method !== 'POST')) { res.setHeader('Allow', url.pathname === '/' ? 'GET' : 'POST'); return send(405, 'Method not allowed'); }
+    const cookie = req.headers.cookie?.split(';').map(x => x.trim()).find(x => x.startsWith('dg_session='))?.slice(11);
+    const session = store.session(cookie);
+    res.setHeader('Set-Cookie', `dg_session=${session.secret}; Path=/; HttpOnly; SameSite=Lax; Max-Age=3600${secure ? '; Secure' : ''}`);
+    if (req.method === 'GET') {
+      const nonce = store.challenge(session);
+      const state = JSON.stringify(store.takeFlash(session)).replace(/</g, '\\u003c').replace(/>/g, '\\u003e').replace(/&/g, '\\u0026');
+      if (process.env.EVP_ORIGIN_TRIAL_TOKEN) res.setHeader('Origin-Trial', process.env.EVP_ORIGIN_TRIAL_TOKEN);
+      return send(200, html.replaceAll('__EVP_NONCE__', nonce).replace('__PAGE_STATE__', () => state), 'text/html; charset=utf-8');
+    }
+    const isJson = req.headers['content-type']?.split(';')[0] === 'application/json';
+    const fail = (key, status = 400, draft = {}) => {
+      if (isJson) return send(status, JSON.stringify({ ok: false, error: key, message: errors[key] }), 'application/json');
+      store.flash(session, { error: errors[key], draft });
+      res.writeHead(303, { Location: '/#signup' }); res.end();
+    };
+    if (req.headers.origin !== origin || req.headers['sec-fetch-site'] === 'cross-site') return send(403, 'Invalid request origin');
+    if (!store.rateLimit(req.socket.remoteAddress || 'unknown')) return fail('limited', 429);
+    if (!isJson && req.headers['content-type']?.split(';')[0] !== 'application/x-www-form-urlencoded') return send(415, 'Unsupported content type');
+    const chunks = []; let size = 0;
+    for await (const chunk of req) { size += chunk.length; if (size > 22000) return send(413, 'Request too large'); chunks.push(chunk); }
+    let data;
+    try { const body = Buffer.concat(chunks).toString('utf8'); data = isJson ? JSON.parse(body) : Object.fromEntries(new URLSearchParams(body)); } catch { return send(400, 'Invalid request body'); }
+    if (!data || typeof data !== 'object') return fail('invalid');
+    const firstName = typeof data.firstName === 'string' ? data.firstName.trim() : '';
+    const lastName = typeof data.lastName === 'string' ? data.lastName.trim() : '';
+    const email = typeof data.email === 'string' ? data.email.trim() : '';
+    const draft = { firstName: firstName.slice(0, 60), lastName: lastName.slice(0, 60), email: email.slice(0, 254), marketing: data.marketing === 'yes' };
+    // Consume before async verification: concurrent requests cannot reuse this challenge.
+    const nonce = store.consume(session, data.csrf);
+    if (!nonce) return fail('expired', 409, draft);
+    if (!firstName || !lastName || firstName.length > 60 || lastName.length > 60 || email.length > 254 || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email) || data.terms !== 'yes') return fail('invalid', 422, draft);
+    if (typeof data.token !== 'string' || !data.token) return fail('unsupported', 422, draft);
+    try { await verifyEmailToken({ token: data.token, email, nonce, origin }); } catch { return fail('verification', 422, draft); }
+    let account;
+    try { account = store.createAccount(session, draft); } catch (error) { if (error.code === 'ERR_SQLITE_ERROR' && error.message.includes('UNIQUE constraint')) return fail('duplicate', 409, draft); throw error; }
+    const success = { ok: true, account: { firstName: account.firstName, email: account.email, points: account.points } };
+    if (isJson) return send(201, JSON.stringify(success), 'application/json');
+    store.flash(session, success);
+    res.writeHead(303, { Location: '/#signup' }); res.end();
+  } catch {
+    // Do not log tokens, customer data, or provider response bodies.
+    if (!res.headersSent) send(500, 'Something went wrong. Please refresh and try again.');
+    else res.end();
+  }
+});
+server.requestTimeout = 15000;
+server.headersTimeout = 10000;
+server.listen(Number(process.env.PORT) || 11222, '0.0.0.0');
