index 0000000..6d799a9
--- /dev/null
+++ b/test/verification.test.mjs
@@ -0,0 +1,80 @@
+import { test } from 'node:test';
+import assert from 'node:assert/strict';
+import { createHash } from 'node:crypto';
+import { exportJWK, generateKeyPair, SignJWT } from 'jose';
+import { verifyEmailToken } from '../lib/verify-email.mjs';
+import { createStore } from '../lib/store.mjs';
+
+const issuer = 'https://accounts.google.com';
+const origin = 'https://coffee.example';
+const now = Math.floor(Date.now() / 1000);
+const nonce = 'test-session-bound-nonce';
+const email = 'regular@gmail.com';
+const issuerKeys = await generateKeyPair('ES256');
+const browserKeys = await generateKeyPair('ES256');
+const publicIssuer = await exportJWK(issuerKeys.publicKey);
+const publicBrowser = await exportJWK(browserKeys.publicKey);
+const dependencies = {
+  now,
+  resolveTxt: async () => [['iss=accounts.', 'google.com']],
+  fetchJson: async url => url.endsWith('/.well-known/email-verification')
+    ? { issuer, jwks_uri: 'https://verifiablecredentials-pa.googleapis.com/.well-known/vc-public-jwks' }
+    : { keys: [await exportJWK((await generateKeyPair('ES256')).publicKey), publicIssuer] },
+};
+async function proof({ evt = {}, kb = {}, digest, signingKey = issuerKeys.privateKey, bindingKey = browserKeys.privateKey } = {}) {
+  const signed = await new SignJWT({ iss: issuer, email, email_verified: true, iat: now, exp: now + 300, cnf: { jwk: publicBrowser }, ...evt })
+    .setProtectedHeader({ typ: 'evt+jwt', alg: 'ES256' }).sign(signingKey);
+  const sd_hash = digest ?? createHash('sha256').update(`${signed}~`).digest('base64url');
+  const binding = await new SignJWT({ aud: origin, iat: now, nonce, sd_hash, ...kb }).setProtectedHeader({ typ: 'kb+jwt', alg: 'ES256' }).sign(bindingKey);
+  return `${signed}~${binding}`;
+}
+const verify = async (options = {}, deps = dependencies) => verifyEmailToken({ token: await proof(), email, nonce, origin, ...options }, deps);
+
+test('accepts a signed email proof and searches keys when kid is absent', async () => {
+  assert.deepEqual(await verify(), { email, issuer });
+});
+test('requires a proof; email syntax alone is never verification', async () => {
+  await assert.rejects(verify({ token: '' }));
+});
+test('rejects another email, origin, session nonce, or unverified claim', async () => {
+  await assert.rejects(verify({ email: 'someone@gmail.com' }));
+  await assert.rejects(verify({ origin: 'https://attacker.example' }));
+  await assert.rejects(verify({ nonce: 'other-session' }));
+  await assert.rejects(verify({ token: await proof({ evt: { email_verified: false } }) }));
+});
+test('rejects expired or future proofs and stale key bindings', async () => {
+  for (const changes of [{ evt: { exp: now - 1 } }, { evt: { iat: now + 100 } }, { kb: { iat: now - 1000 } }]) {
+    await assert.rejects(verify({ token: await proof(changes) }));
+  }
+});
+test('rejects altered issuer signatures and digest binding', async () => {
+  const attacker = await generateKeyPair('ES256');
+  await assert.rejects(verify({ token: await proof({ signingKey: attacker.privateKey }) }));
+  await assert.rejects(verify({ token: await proof({ digest: 'incorrect-hash' }) }));
+  await assert.rejects(verify({ token: await proof({ bindingKey: attacker.privateKey }) }));
+});
+test('requires DNS delegation, pins discovery and JWKS URLs', async () => {
+  await assert.rejects(verify({}, { ...dependencies, resolveTxt: async () => [['iss=attacker.example']] }));
+  await assert.rejects(verify({}, { ...dependencies, fetchJson: async () => ({ issuer, jwks_uri: 'http://127.0.0.1/keys' }) }));
+  let networkCalls = 0;
+  await assert.rejects(verify({ token: await proof({ evt: { iss: 'https://127.0.0.1' } }) }, { ...dependencies, fetchJson: async () => { networkCalls++; } }));
+  assert.equal(networkCalls, 0);
+});
+test('store consumes a nonce once and persists consent and welcome points', () => {
+  const store = createStore(':memory:');
+  try {
+    const session = store.session();
+    const challenge = store.challenge(session);
+    assert.equal(store.consume(session, 'incorrect'), null);
+    assert.equal(store.consume(session, challenge), challenge);
+    assert.equal(store.consume(session, challenge), null);
+    const account = store.createAccount(session, { email, firstName: 'Jamie', lastName: 'Morgan', marketing: false });
+    assert.equal(account.points, 50);
+    assert.throws(() => store.createAccount(session, { email: email.toUpperCase(), firstName: 'J', lastName: 'M', marketing: false }), /UNIQUE/);
+    store.flash(session, { ok: true });
+    assert.deepEqual(store.takeFlash(store.session(session.secret)), { ok: true });
+    assert.deepEqual(store.takeFlash(store.session(session.secret)), {});
+    for (let attempt = 0; attempt < 15; attempt++) assert.equal(store.rateLimit('127.0.0.1'), true);
+    assert.equal(store.rateLimit('127.0.0.1'), false);
+  } finally { store.close(); }
+});

