+// Templates contain only trusted, static markup. Consumer content stays in slots.
+const focusStyles = `
+  ::slotted(a:focus-visible), button:focus-visible {
+    outline: 3px solid var(--focus-ring, #4e342e);
+    outline-offset: 4px;
+  }
+`;
+
+const buttonStyles = `
+  ::slotted(a) {
+    display: inline-block;
+    background: var(--primary, #4e342e);
+    color: white;
+    padding: 10px 20px;
+    text-decoration: none;
+    border-radius: 5px;
+    margin-top: 15px;
+  }
+  ::slotted(a:hover) { background: #3e2723; }
+  ${focusStyles}
+`;
+
+function componentTemplate(markup) {
+  const template = document.createElement('template');
+  template.innerHTML = markup;
+  return template;
+}
+
+const cardTemplate = componentTemplate(`
+  <style>
+    :host { display: block; height: 100%; }
+    article {
+      box-sizing: border-box;
+      height: 100%;
+      background: var(--card-background, white);
+      padding: 20px;
+      border-radius: 8px;
+      box-shadow: 0 2px 5px rgb(0 0 0 / 10%);
+      text-align: center;
+    }
+    ::slotted(h3) { margin: 0 0 10px; color: var(--primary, #4e342e); }
+    ::slotted(p) { margin: 0; }
+    ${buttonStyles}
+  </style>
+  <article part="card">
+    <slot name="heading"></slot>
+    <slot></slot>
+    <slot name="action"></slot>
+  </article>
+`);
+
+export class CoffeeCard extends HTMLElement {
+  constructor() {
+    super();
+    this.attachShadow({ mode: 'open', delegatesFocus: true })
+      .append(cardTemplate.content.cloneNode(true));
+  }
+}
+
+const heroTemplate = componentTemplate(`
+  <style>
+    :host { display: block; }
+    header {
+      box-sizing: border-box;
+      min-height: 60vh;
+      background: linear-gradient(rgb(0 0 0 / 50%), rgb(0 0 0 / 50%)),
+        var(--hero-image, url('https://images.unsplash.com/photo-1495474472287-4d71bcdd2085?auto=format&fit=crop&w=1350&q=80'));
+      background-size: cover;
+      background-position: center;
+      display: flex;
+      flex-direction: column;
+      justify-content: center;
+      align-items: center;
+      color: white;
+      text-align: center;
+      padding: 40px 20px;
+    }
+    ::slotted(h1) { font-size: clamp(2rem, 6vw, 3rem); margin: 0 0 1rem; }
+    ::slotted(p) { margin: 0; }
+    ${buttonStyles}
+    ::slotted(a:focus-visible) { outline-color: var(--focus-ring, #ffab40); }
+  </style>
+  <header part="hero">
+    <slot name="heading"></slot>
+    <slot></slot>
+    <slot name="action"></slot>
+  </header>
+`);
+
+export class GrindHero extends HTMLElement {
+  constructor() {
+    super();
+    this.attachShadow({ mode: 'open', delegatesFocus: true })
+      .append(heroTemplate.content.cloneNode(true));
+  }
+}
+
+const navigationTemplate = componentTemplate(`
+  <style>
+    :host { display: block; background: var(--primary, #4e342e); color: white; }
+    nav { padding: 1rem 5%; display: flex; gap: 20px; align-items: center; justify-content: space-between; }
+    #links { display: flex; gap: 20px; align-items: center; flex-wrap: wrap; }
+    #links[hidden], button[hidden] { display: none; }
+    ::slotted(a) { color: white; text-decoration: none; font-size: .9rem; }
+    ::slotted(a:hover) { color: var(--accent, #ffab40); }
+    ::slotted([slot="brand"]) { font-size: 1.5rem; font-weight: bold; letter-spacing: 1px; }
+    ::slotted([data-outlined]) { border: 1px solid var(--accent, #ffab40); padding: 5px 12px; border-radius: 4px; }
+    button { font: inherit; color: inherit; background: transparent; border: 1px solid var(--accent, #ffab40); border-radius: 4px; padding: 8px 12px; cursor: pointer; }
+    ${focusStyles}
+    ::slotted(a:focus-visible), button:focus-visible { outline-color: var(--focus-ring, #ffab40); }
+    @media (max-width: 700px) {
+      nav { flex-wrap: wrap; }
+      #links { width: 100%; align-items: stretch; flex-direction: column; gap: 8px; }
+      ::slotted(a:not([slot="brand"])) { padding: 8px 12px; }
+      ::slotted([slot="brand"]) { font-size: 1.1rem; }
+    }
