+import assert from 'node:assert/strict';
+import { readFile } from 'node:fs/promises';
+import { test } from 'node:test';
+import { Window } from 'happy-dom';
+
+const window = new Window({
+  settings: { disableCSSFileLoading: true, disableJavaScriptFileLoading: true },
+});
+for (const name of ['window', 'document', 'HTMLElement', 'HTMLAnchorElement', 'customElements']) {
+  globalThis[name] = name === 'window' ? window : window[name];
+}
+const viewport = new window.EventTarget();
+viewport.matches = true;
+window.matchMedia = () => viewport;
+await import('../components/daily-grind.js');
+
+test('mobile menu toggles, closes with Escape, and restores focus', () => {
+  const nav = document.createElement('grind-navigation');
+  nav.innerHTML = '<a href="/menu">Menu</a>';
+  document.body.append(nav);
+  const button = nav.shadowRoot.querySelector('button');
+  const links = nav.shadowRoot.querySelector('#links');
+  assert.equal(button.getAttribute('aria-controls'), links.id);
+  assert.equal(links.hidden, true);
+  button.click();
+  assert.equal(button.getAttribute('aria-expanded'), 'true');
+  assert.equal(links.hidden, false);
+  nav.querySelector('a').focus();
+  nav.dispatchEvent(new window.KeyboardEvent('keydown', { key: 'Escape', bubbles: true }));
+  assert.equal(links.hidden, true);
+  assert.equal(button.getAttribute('aria-expanded'), 'false');
+  assert.equal(nav.shadowRoot.activeElement, button);
+  nav.remove();
+});
+
+test('viewport changes and reconnection reset the mobile menu without duplicate handlers', () => {
+  const nav = document.createElement('grind-navigation');
+  document.body.append(nav);
+  const button = nav.shadowRoot.querySelector('button');
+  const links = nav.shadowRoot.querySelector('#links');
+  button.click();
+  viewport.matches = false;
+  viewport.dispatchEvent(new window.Event('change'));
+  assert.equal(links.hidden, false);
+  viewport.matches = true;
+  viewport.dispatchEvent(new window.Event('change'));
+  assert.equal(links.hidden, true);
+  nav.remove();
+  document.body.append(nav);
+  button.click();
+  assert.equal(links.hidden, false);
+  nav.remove();
+});
+
+test('following a mobile navigation link closes the menu', () => {
+  const nav = document.createElement('grind-navigation');
+  nav.innerHTML = '<a href="#main-content">Main content</a>';
+  document.body.append(nav);
+  nav.shadowRoot.querySelector('button').click();
+  nav.querySelector('a').dispatchEvent(new window.MouseEvent('click', { bubbles: true, composed: true }));
+  assert.equal(nav.shadowRoot.querySelector('#links').hidden, true);
+  nav.remove();
+});
+
+test('navigation instances keep their state independent and detach viewport listeners', () => {
+  const first = document.createElement('grind-navigation');
+  const second = document.createElement('grind-navigation');
+  document.body.append(first, second);
+  first.shadowRoot.querySelector('button').click();
+  assert.equal(first.shadowRoot.querySelector('#links').hidden, false);
+  assert.equal(second.shadowRoot.querySelector('#links').hidden, true);
+  first.remove();
+  viewport.dispatchEvent(new window.Event('change'));
+  assert.equal(first.shadowRoot.querySelector('#links').hidden, false);
+  second.remove();
+});
+
+test('homepage components retain semantic content, destinations, and independent shadow roots', async () => {
+  document.body.innerHTML = await readFile(new URL('../index.html', import.meta.url), 'utf8');
+  const cards = [...document.querySelectorAll('coffee-card')];
+  assert.equal(cards.length, 3);
+  assert.notEqual(cards[0].shadowRoot, cards[1].shadowRoot);
+  for (const card of cards) {
+    assert.ok(card.shadowRoot.querySelector('article'));
+    assert.ok(card.shadowRoot.querySelector('style'));
+    const title = card.querySelector('h3');
+    const link = card.querySelector('a');
+    assert.ok(link.getAttribute('aria-label').includes(title.textContent));
+    assert.equal(card.shadowRoot.querySelector('slot[name="title"]').assignedElements()[0], title);
+    assert.equal(card.shadowRoot.querySelector('slot[name="action"]').assignedElements()[0], link);
+  }
+  assert.deepEqual(cards.map(card => card.querySelector('a').getAttribute('href')),
+    ['/menu/seasonal', '/menu/espresso', '/menu/cold-brew']);
+  const hero = document.querySelector('coffee-hero');
+  assert.ok(hero.shadowRoot.querySelector('header'));
+  assert.equal(hero.querySelector('a').getAttribute('href'), '/order-online');
+  assert.equal(document.querySelectorAll('h1').length, 1);
+  assert.ok(document.querySelector(document.querySelector('.skip-link').getAttribute('href')));
+  await window.happyDOM.close();
+});

