--- /dev/null
+++ b/src/scripts/browser-tools.ts
@@ -0,0 +1,123 @@
+import { apiUrl, filterArticles, getArticles, getReadingList, toggleReadingList } from '../utils/article-client';
+
+const emptySchema = { type: 'object', properties: {}, additionalProperties: false };
+const slugSchema = {
+  type: 'object',
+  properties: { slug: { type: 'string', minLength: 1, description: 'The article identifier returned by list_articles.' } },
+  required: ['slug'],
+  additionalProperties: false,
+};
+
+// This Astro-owned module lives outside React islands and follows page navigation.
+export function createArticleTools(): WebMCP.ModelContextTool[] {
+  return [
+    {
+      name: 'list_articles',
+      description: 'List articles with their titles, summaries, and identifiers.',
+      inputSchema: emptySchema,
+      execute: (_, { signal }) => getArticles(signal),
+      annotations: { readOnlyHint: true },
+    },
+    {
+      name: 'search_articles',
+      description: 'Find articles by words in their title or summary.',
+      inputSchema: {
+        type: 'object',
+        properties: { query: { type: 'string', minLength: 1, description: 'Words to look for in article titles and summaries.' } },
+        required: ['query'],
+        additionalProperties: false,
+      },
+      async execute({ query }, { signal }) {
+        if (typeof query !== 'string' || !query.trim()) return { error: 'Provide a non-empty search query.' };
+        return { articles: filterArticles(await getArticles(signal), query) };
+      },
+      annotations: { readOnlyHint: true },
+    },
+    {
+      name: 'get_reading_list',
+      description: 'Retrieve the articles saved in the current browser session.',
+      inputSchema: emptySchema,
+      execute: (_, { signal }) => getReadingList(signal),
+      annotations: { readOnlyHint: true },
+    },
+    {
+      name: 'toggle_reading_list',
+      description: 'Save an article to the reading list, or remove it if already saved.',
+      inputSchema: slugSchema,
+      async execute({ slug }, { signal }) {
+        if (typeof slug !== 'string' || !slug.trim()) return { error: 'Provide an article slug from list_articles.' };
+        const articles = await getArticles(signal);
+        if (!articles.some(article => article.slug === slug)) return { error: 'Article not found. Use list_articles to find its slug.' };
+        return toggleReadingList(slug, signal);
+      },
+      annotations: { readOnlyHint: false },
+    },
+    ...[
+      ['get_tide_levels', 'Fetch tide levels for the coastal article.', 'tide-levels'],
+      ['get_coffee_brew', 'Fetch brewing information for the coffee article.', 'coffee-brew'],
+      ['get_plant_stats', 'Fetch plant statistics for the plants article.', 'plant-stats'],
+    ].map(([name, description, path]): WebMCP.ModelContextTool => ({
+      name, description, inputSchema: emptySchema,
+      execute: (_, { signal }) => fetchUtility(path, signal),
+      annotations: { readOnlyHint: true },
+    })),
+    {
+      name: 'get_article_popularity',
+      description: 'Fetch view counts and trending status for an article.',
+      inputSchema: slugSchema,
+      execute({ slug }, { signal }) {
+        if (typeof slug !== 'string' || !slug.trim()) return { error: 'Provide an article slug.' };
+        return fetchUtility(`article-popularity?id=${encodeURIComponent(slug)}`, signal);
+      },
+      annotations: { readOnlyHint: true },
+    },
+  ];
+}
+
+async function fetchUtility(path: string, signal: AbortSignal) {
+  const response = await fetch(apiUrl(path), { signal });
+  const body = await response.text();
+  let data: unknown = body;
+  try { data = JSON.parse(body); } catch { /* Error pages may be HTML or empty. */ }
+  return {
+    status: response.status, url: response.url, redirected: response.redirected,
+    ...(response.ok ? { data } : { error: `Request failed: ${response.status} ${response.statusText}`, data }),
+  };
+}
+
+let registration: AbortController | undefined;
+async function registerTools() {
+  registration?.abort();
+  if (!document.modelContext?.registerTool) return;
+  const controller = new AbortController();
+  registration = controller;
+  for (const tool of createArticleTools()) {
+    if (controller.signal.aborted) return;
+    const execute = tool.execute;
+    try {
+      await document.modelContext.registerTool({
+        ...tool,
+        async execute(input, { signal }) {
+          // Both navigation and agent cancellation stop requests in progress.
+          const executionSignal = AbortSignal.any([signal, controller.signal]);
+          try {
+            return await execute(input, { signal: executionSignal });
+          } catch (error) {
+            if (executionSignal.aborted) throw error;
+            return { error: error instanceof Error ? error.message : String(error) };
+          }
+        },
+      }, { signal: controller.signal });
+    } catch (error) {
+      if (!controller.signal.aborted) console.warn(`Could not register browser tool ${tool.name}`, error);
+    }
+  }
+}
+
+if (typeof document !== 'undefined') {
+  document.addEventListener('astro:page-load', registerTools);
+  document.addEventListener('astro:before-swap', () => registration?.abort());
+  window.addEventListener('pagehide', () => registration?.abort());
+  window.addEventListener('pageshow', event => { if (event.persisted) void registerTools(); });
+  void registerTools();
+}
