--- /dev/null
+++ b/src/utils/article-client.ts
@@ -0,0 +1,44 @@
+/** Shared browser operations used by the UI and WebMCP tools. */
+export interface Article {
+  slug: string;
+  title: string;
+  summary: string;
+  image?: string;
+}
+
+export const apiUrl = (path: string) => `${import.meta.env.BASE_URL}api/${path}`;
+
+export async function requestJSON<T>(path: string, options: RequestInit = {}): Promise<T> {
+  const response = await fetch(apiUrl(path), options);
+  if (!response.ok) throw new Error(`Request failed: ${response.status} ${response.statusText}`);
+  return response.json();
+}
+
+export const getArticles = (signal?: AbortSignal) => requestJSON<Article[]>('articles.json', { signal });
+export const getReadingList = (signal?: AbortSignal) => requestJSON<{ readingList: string[] }>('reading-list.json', { signal });
+export const filterArticles = (articles: Article[], query: string) => {
+  const term = query.trim().toLowerCase();
+  return term ? articles.filter(article => `${article.title}\n${article.summary}`.toLowerCase().includes(term)) : [];
+};
+
+export async function toggleReadingList(slug: string, signal?: AbortSignal, action: 'toggle' | 'remove' = 'toggle') {
+  const result = await requestJSON<{ readingList: string[] }>('reading-list.json', {
+    method: 'POST',
+    headers: { 'Content-Type': 'application/json' },
+    body: JSON.stringify({ slug, action }),
+    signal,
+  });
+  window.dispatchEvent(new CustomEvent('reading-list-updated', { detail: result.readingList }));
+  return result;
+}
+
+// Declarative WebMCP extensions are not included in the imperative API types.
+export type AgentSubmitEvent = SubmitEvent & {
+  agentInvoked?: boolean;
+  respondWith?: (result: Promise<unknown>) => void;
+};
+
+export function respondToAgent(event: Event, result: Promise<unknown>) {
+  const submission = event as AgentSubmitEvent;
+  if (submission.agentInvoked && submission.respondWith) submission.respondWith(result);
+}
