+import assert from 'node:assert/strict';
+import { readFile } from 'node:fs/promises';
+import { test } from 'node:test';
+import { stripTypeScriptTypes } from 'node:module';
+
+// Compile only client modules; never load the Astro server or start a server.
+const asModule = source => 'data:text/javascript;base64,' + Buffer.from(stripTypeScriptTypes(source)).toString('base64');
+const clientSource = (await readFile(new URL('../src/utils/article-client.ts', import.meta.url), 'utf8'))
+  .replaceAll('import.meta.env.BASE_URL', "'/devtools-times/'");
+const clientURL = asModule(clientSource);
+const toolsSource = (await readFile(new URL('../src/scripts/browser-tools.ts', import.meta.url), 'utf8'))
+  .replace("'../utils/article-client'", JSON.stringify(clientURL));
+
+const documentMock = new EventTarget();
+const windowMock = new EventTarget();
+globalThis.document = documentMock;
+globalThis.window = windowMock;
+const { createArticleTools } = await import(asModule(toolsSource));
+const client = await import(clientURL);
+const tools = createArticleTools();
+const signal = new AbortController().signal;
+const call = (name, input = {}, options = { signal }) => tools.find(tool => tool.name === name).execute(input, options);
+const articles = [{ slug: 'coffee', title: 'Coffee Alchemy', summary: 'Roasting science' }];
+
+await test('registers safely without WebMCP and exposes distinct tools with schemas', () => {
+  assert.equal(tools.length, 8);
+  assert.equal(new Set(tools.map(tool => tool.name)).size, 8);
+  for (const tool of tools) assert.equal(tool.inputSchema.type, 'object');
+});
+
+await test('search shares UI filtering and rejects invalid input', async () => {
+  globalThis.fetch = async (url, options) => {
+    assert.equal(url, '/devtools-times/api/articles.json');
+    assert.equal(options.signal, signal);
+    return Response.json(articles);
+  };
+  assert.deepEqual(await call('search_articles', { query: ' SCIENCE ' }), { articles });
+  assert.deepEqual(client.filterArticles(articles, 'coffee'), articles);
+  assert.ok((await call('search_articles', { query: 42 })).error);
+  assert.ok((await call('toggle_reading_list', { slug: 'missing' })).error);
+});
+
+await test('reading-list mutation uses the session API and announces updated state', async () => {
+  let updated;
+  windowMock.addEventListener('reading-list-updated', event => { updated = event.detail; }, { once: true });
+  globalThis.fetch = async (url, options) => {
+    assert.equal(url, '/devtools-times/api/reading-list.json');
+    assert.deepEqual(JSON.parse(options.body), { slug: 'coffee', action: 'remove' });
+    return Response.json({ readingList: [] });
+  };
+  assert.deepEqual(await client.toggleReadingList('coffee', signal, 'remove'), { readingList: [] });
+  assert.deepEqual(updated, []);
+});
+
+await test('utility tools preserve HTTP failures and encode article identifiers', async () => {
+  globalThis.fetch = async url => {
+    assert.equal(url, '/devtools-times/api/article-popularity?id=coffee%20%26%20tea');
+    return Response.json({ error: 'Unavailable' }, { status: 500 });
+  };
+  const result = await call('get_article_popularity', { slug: 'coffee & tea' });
+  assert.equal(result.status, 500);
+  assert.ok(result.error);
+  assert.deepEqual(result.data, { error: 'Unavailable' });
+});
+
+await test('declarative submissions respond only when agent invoked', async () => {
+  let received;
+  client.respondToAgent({ agentInvoked: true, respondWith: result => { received = result; } }, Promise.resolve({ articles }));
+  assert.deepEqual(await received, { articles });
+  client.respondToAgent({}, Promise.resolve('ordinary submission'));
+});
+
+await test('navigation cleans up registrations, returns actionable errors and cancels requests', async () => {
+  const registered = [];
+  documentMock.modelContext = { registerTool: async (tool, options) => registered.push({ tool, options }) };
+  documentMock.dispatchEvent(new Event('astro:page-load'));
+  await new Promise(resolve => setImmediate(resolve));
+  assert.equal(registered.length, 8);
+  const list = registered.find(({ tool }) => tool.name === 'list_articles');
+  globalThis.fetch = async () => { throw new Error('Connection unavailable'); };
+  assert.deepEqual(await list.tool.execute({}, { signal }), { error: 'Connection unavailable' });
+  globalThis.fetch = (_, { signal: executionSignal }) => new Promise((resolve, reject) => {
+    executionSignal.addEventListener('abort', () => reject(executionSignal.reason), { once: true });
+  });
+  const pending = list.tool.execute({}, { signal });
+  documentMock.dispatchEvent(new Event('astro:before-swap'));
+  await assert.rejects(pending, { name: 'AbortError' });
+  assert.ok(registered.every(({ options }) => options.signal.aborted));
+  documentMock.dispatchEvent(new Event('astro:page-load'));
+  await new Promise(resolve => setImmediate(resolve));
+  assert.equal(registered.length, 16);
+  windowMock.dispatchEvent(new Event('pagehide'));
+  assert.ok(registered.every(({ options }) => options.signal.aborted));
+});
+
+await test('reading-list removal is idempotent and old toggle callers still work', async () => {
+  const source = await readFile(new URL('../src/pages/api/reading-list.json.ts', import.meta.url), 'utf8');
+  const { POST } = await import(asModule(source));
+  let saved = ['coffee'];
+  const session = { get: async () => saved, set: async (_, value) => { saved = value; } };
+  const submit = body => POST({ request: new Request('https://example.test/api/reading-list.json', {
+    method: 'POST', body: JSON.stringify(body), headers: { 'Content-Type': 'application/json' },
+  }), session });
+  await submit({ slug: 'coffee', action: 'remove' });
+  await submit({ slug: 'coffee', action: 'remove' });
+  assert.deepEqual(saved, []);
+  await submit({ slug: 'coffee' });
+  assert.deepEqual(saved, ['coffee']);
+  assert.equal((await submit({ slug: 123 })).status, 400);
+});
