+export interface BrowserTool {
+  name: string;
+  description: string;
+  inputSchema: Record<string, unknown>;
+  annotations: { readOnlyHint: boolean };
+  execute: (input: Record<string, unknown>, context?: { signal?: AbortSignal }) => Promise<unknown>;
+}
+
+// Keep HTTP failures and redirects visible: these APIs are intentionally used
+// as network debugging examples. Tool calls must not disguise them as success.
+export function createArticleTools(baseURL: string): BrowserTool[] {
+  const request = async (path: string, signal?: AbortSignal) => {
+    const response = await fetch(`${baseURL}api/${path}`, { signal });
+    const body = await response.text();
+    let data: unknown = body;
+    try { data = JSON.parse(body); } catch { /* Redirect targets can return HTML. */ }
+    return {
+      isError: !response.ok,
+      content: [{ type: 'text', text: JSON.stringify({
+        status: response.status, url: response.url, redirected: response.redirected, data,
+      }) }],
+    };
+  };
+
+  const definitions = [
+    ['get_plant_stats', 'Fetch plant statistics for The Silent Architects of Earth. Reports HTTP failures, including oversized cookie headers.', 'plant-stats'],
+    ['get_tide_levels', 'Fetch tide levels for The Coastal Pulse. Reports the final HTTP status and whether the request was redirected.', 'tide-levels'],
+    ['brew_coffee', 'Fetch coffee brewing statistics for The Global Alchemy of Coffee. Reports service errors.', 'coffee-brew'],
+  ];
+  const tools: BrowserTool[] = definitions.map(([name, description, path]) => ({
+    name, description,
+    inputSchema: { type: 'object', properties: {}, additionalProperties: false },
+    annotations: { readOnlyHint: true },
+    execute: async (_input, context) => request(path, context?.signal),
+  }));
+
+  tools.push({
+    name: 'get_article_popularity',
+    description: 'Fetch article views and trending status by article ID (slug), including Super Bowl LX.',
+    inputSchema: {
+      type: 'object',
+      properties: { id: { type: 'string', minLength: 1, description: 'Article slug, for example super-bowl-lx.' } },
+      required: ['id'],
+      additionalProperties: false,
+    },
+    annotations: { readOnlyHint: true },
+    execute: async ({ id }, context) => {
+      if (typeof id !== 'string' || !id.trim()) throw new Error('A non-empty article id is required.');
+      return request(`article-popularity?${new URLSearchParams({ id: id.trim() })}`, context?.signal);
+    },
+  });
+  return tools;
+}
+
+export interface ModelContext {
+  registerTool: (tool: BrowserTool, options?: { signal: AbortSignal }) => void | Promise<void>;
+}
+
+export async function registerArticleTools(context: ModelContext | undefined, baseURL: string, signal: AbortSignal) {
+  if (!context) return;
+  for (const tool of createArticleTools(baseURL)) {
+    if (signal.aborted) return;
+    await context.registerTool(tool, { signal });
+  }
+}
