+import type { FormEvent } from 'react';
+
+// Read FormData on submit: an agent can populate native fields without firing
+// the React change events that normally update controlled input state.
+export function respondToAgent(event: FormEvent<HTMLFormElement>, result: Promise<unknown>) {
+  const submit = event.nativeEvent as SubmitEvent & {
+    agentInvoked?: boolean;
+    respondWith?: (result: Promise<unknown>) => void;
+  };
+  if (submit.agentInvoked && submit.respondWith) submit.respondWith(result);
+}
+
+export interface Article {
+  slug: string;
+  title: string;
+  summary: string;
+  image?: string;
+}
+
+export async function fetchJSON<T>(url: string, options?: RequestInit): Promise<T> {
+  const response = await fetch(url, options);
+  if (!response.ok) throw new Error(`Request failed (${response.status})`);
+  return response.json();
+}
+
+export function filterArticles(articles: Article[], query: string) {
+  const term = query.trim().toLowerCase();
+  return term ? articles.filter(article =>
+    article.title.toLowerCase().includes(term) || article.summary.toLowerCase().includes(term)
+  ) : [];
+}
+
+export async function toggleReadingList(slug: string) {
+  const data = await fetchJSON<{ readingList: string[] }>(`${import.meta.env.BASE_URL}api/reading-list.json`, {
+    method: 'POST',
+    headers: { 'Content-Type': 'application/json' },
+    body: JSON.stringify({ slug }),
+  });
+  window.dispatchEvent(new CustomEvent('reading-list-change', { detail: data.readingList }));
+  return data;
+}
