--- /dev/null
+++ b/src/scripts/browser-tools.ts
@@ -0,0 +1,13 @@
+import { registerArticleTools, type ModelContext } from '../lib/article-tools';
+
+// Layout scripts execute once with Astro's ClientRouter. These site-wide tools
+// deliberately persist across page swaps, without duplicate registrations.
+const context = (document as Document & { modelContext?: ModelContext }).modelContext
+  ?? (navigator as Navigator & { modelContext?: ModelContext }).modelContext;
+const controller = new AbortController();
+void registerArticleTools(context, import.meta.env.BASE_URL, controller.signal).catch(error => {
+  controller.abort();
+  console.error('Unable to register article browser tools:', error);
+});
+
+if (import.meta.hot) import.meta.hot.dispose(() => controller.abort());
