+import assert from 'node:assert/strict';
+import { test } from 'node:test';
+import { createArticleTools, registerArticleTools } from '../src/lib/article-tools.ts';
+import { filterArticles, respondToAgent } from '../src/lib/browser-tools.ts';
+
+test('search handles case, whitespace, title and summary matches', () => {
+  const articles = [
+    { slug: 'coffee', title: 'Coffee Alchemy', summary: 'Roasting beans' },
+    { slug: 'shore', title: 'Coastal Pulse', summary: 'Coffee by the sea' },
+  ];
+  assert.deepEqual(filterArticles(articles, ' COFFEE '), articles);
+  assert.deepEqual(filterArticles(articles, 'beans'), [articles[0]]);
+  assert.deepEqual(filterArticles(articles, 'unknown'), []);
+  assert.deepEqual(filterArticles(articles, '  '), []);
+});
+
+test('form response uses the native agent SubmitEvent and leaves human submits alone', async () => {
+  const result = Promise.resolve({ readingList: ['coffee'] });
+  let response: Promise<unknown> | undefined;
+  respondToAgent({ nativeEvent: { agentInvoked: true, respondWith(value) { response = value; } } } as never, result);
+  assert.equal(response, result);
+  assert.deepEqual(await response, { readingList: ['coffee'] });
+  respondToAgent({ nativeEvent: {} } as never, result);
+  respondToAgent({ nativeEvent: { agentInvoked: false, respondWith() { assert.fail('Human submission responded to agent'); } } } as never, result);
+});
+
+test('article tools respect the deployment base, return HTTP failures and forward cancellation', async () => {
+  const originalFetch = globalThis.fetch;
+  const calls: { url: string; signal?: AbortSignal | null }[] = [];
+  const controller = new AbortController();
+  globalThis.fetch = async (url, options) => {
+    calls.push({ url: String(url), signal: options?.signal });
+    const status = String(url).includes('plant-stats') ? 431 : 500;
+    return new Response(JSON.stringify({ error: 'Intentional example failure' }), { status });
+  };
+  try {
+    const tools = createArticleTools('/devtools-times/');
+    for (const name of ['get_plant_stats', 'brew_coffee']) {
+      const result = await tools.find(tool => tool.name === name)!.execute({}, { signal: controller.signal }) as any;
+      assert.equal(result.isError, true);
+      assert.equal(JSON.parse(result.content[0].text).data.error, 'Intentional example failure');
+    }
+    assert.deepEqual(calls.map(call => call.url), ['/devtools-times/api/plant-stats', '/devtools-times/api/coffee-brew']);
+    assert.ok(calls.every(call => call.signal === controller.signal));
+  } finally { globalThis.fetch = originalFetch; }
+});
+
+test('popularity requires an id, encodes it, and returns success data', async () => {
+  const originalFetch = globalThis.fetch;
+  const tool = createArticleTools('/news/').find(tool => tool.name === 'get_article_popularity')!;
+  let requested = '';
+  globalThis.fetch = async url => {
+    requested = String(url);
+    return new Response(JSON.stringify({ views: 42, trending: true }));
+  };
+  try {
+    await assert.rejects(tool.execute({}), /article id/);
+    await assert.rejects(tool.execute({ id: ' ' }), /article id/);
+    const result = await tool.execute({ id: ' a&b ' }) as any;
+    assert.equal(requested, '/news/api/article-popularity?id=a%26b');
+    assert.equal(result.isError, false);
+    assert.equal(JSON.parse(result.content[0].text).data.views, 42);
+  } finally { globalThis.fetch = originalFetch; }
+});
+
+test('tides report redirects and non-JSON error bodies', async () => {
+  const originalFetch = globalThis.fetch;
+  globalThis.fetch = async () => {
+    const response = new Response('<h1>Not found</h1>', { status: 404 });
+    Object.defineProperties(response, { redirected: { value: true }, url: { value: 'https://example.com/api/tide-levels-v2' } });
+    return response;
+  };
+  try {
+    const result = await createArticleTools('/').find(tool => tool.name === 'get_tide_levels')!.execute({}) as any;
+    const data = JSON.parse(result.content[0].text);
+    assert.equal(result.isError, true);
+    assert.equal(data.redirected, true);
+    assert.equal(data.status, 404);
+    assert.equal(data.data, '<h1>Not found</h1>');
+  } finally { globalThis.fetch = originalFetch; }
+});
+
+test('registration supports absent APIs and uses an abort signal for lifecycle cleanup', async () => {
+  const controller = new AbortController();
+  await registerArticleTools(undefined, '/', controller.signal);
+  const names: string[] = [];
+  await registerArticleTools({ registerTool(tool, options) {
+    names.push(tool.name);
+    assert.equal(options?.signal, controller.signal);
+  } }, '/', controller.signal);
+  assert.equal(new Set(names).size, 4);
+  controller.abort();
+  await registerArticleTools({ registerTool() { assert.fail('Registered after disposal'); } }, '/', controller.signal);
+});
